/* Déclic — Analyse I */
(()=>{
/* ---------- helpers locaux ---------- */
// tableau (1re ligne = en-tête) : sert aux tableaux de signes et de variations
const tab=rows=>`<table style="border-collapse:collapse;margin:6px auto;font-size:.95em">${rows.map((r,i)=>`<tr>${r.map(c=>`<${i?'td':'th'} style="border:1px solid var(--line);padding:4px 9px;text-align:center">${c}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</table>`;
// droite numérique avec un intervalle [a ; b], lo/ro = bord gauche/droit ouvert
function iline(a,b,lo,ro,col='var(--accent)'){
  const P=plane({x:[-5.6,5.6],y:[-1.1,1.1],grid:false,axes:false});
  P.seg(-5.5,0,5.5,0,{c:'var(--muted)',w:1.5});
  for(let k=-5;k<=5;k++){ P.seg(k,-.12,k,.12,{c:'var(--muted)',w:1.2}); P.text(k,0,fmt(k),{a:'middle',dy:24,s:11,c:'var(--muted)'}); }
  P.seg(a,0,b,0,{c:col,w:6});
  P.text(a,0,lo?']':'[',{a:'middle',dy:8,s:24,c:col}).text(b,0,ro?'[':']',{a:'middle',dy:8,s:24,c:col});
  return P.svg();
}
const iv=(a,b,lo,ro)=>`${lo?']':'['}${fmt(a)} ; ${fmt(b)}${ro?'[':']'}`;
const fact=n=>n<2?1:n*fact(n-1);

COURS.push(
/* ===================== CALCUL DIFFÉRENTIEL ===================== */
{subj:'an1', sem:'aut', id:'an1-nombres', h:'Nombres et (in)équations', p:'Les ensembles de nombres, les intervalles et la résolution d’inéquations avec un tableau de signes.', steps:[
 {kind:'Théorie',h:'Des ensembles emboîtés',p:'<p>Compter des moutons, noter une température négative, partager un gâteau en trois, mesurer la diagonale d’un carré : chaque besoin a fait naître une nouvelle famille de nombres. On les range en quatre ensembles emboîtés.</p><div class="def"><p>Les <b>naturels</b> ℕ = {0, 1, 2, 3, …} servent à compter. Les <b>entiers</b> ℤ = {…, −2, −1, 0, 1, 2, …} ajoutent les négatifs. Les <b>rationnels</b> ℚ sont les quotients <i>p</i>/<i>q</i> avec <i>p</i> ∈ ℤ, <i>q</i> ∈ ℕ et <i>q</i> ≠ 0. Les <b>réels</b> ℝ sont tous les points de la droite numérique. On a <b>ℕ ⊂ ℤ ⊂ ℚ ⊂ ℝ</b> ; le symbole ⊂ se lit « est inclus dans » et ∈ « appartient à ».</p></div><div class="idea"><p>Chaque ensemble répond à une question que le précédent ne sait pas résoudre : 3 − 5 n’a pas de sens dans ℕ mais vaut −2 dans ℤ ; 2/3 n’existe pas dans ℤ mais existe dans ℚ ; aucune fraction n’a pour carré 2, alors que √2 est un réel, la diagonale du carré de côté 1.</p></div><div class="ex"><p>Pour placer 0,75 : ce n’est ni un naturel ni un entier, mais 0,75 = 3/4 ∈ ℚ. Pour −12/4 : la fraction se simplifie en −3, donc le nombre est dans ℤ, pas dans ℕ. Le plus petit ensemble qui le contient est ℤ.</p></div><div class="warn"><p>Un nombre dont l’écriture décimale est finie ou périodique est rationnel : 0,125 = 1/8 et 0,333… = 1/3. √2 = 1,41421… et π = 3,14159… n’ont aucune période : ce sont des <b>irrationnels</b>, dans ℝ mais pas dans ℚ.</p></div>',
  fig:(()=>{ const P=plane({x:[0,10],y:[0,6],grid:false,axes:false});
    P.rect(.2,.2,9.6,5.6,{fill:'var(--sci)',fo:.12,c:'var(--ink)',w:1.5}).rect(.6,.6,7,4.5,{fill:'var(--math)',fo:.15,c:'var(--ink)',w:1.5})
     .rect(1,1,4.4,3.4,{fill:'var(--spark)',fo:.2,c:'var(--ink)',w:1.5}).rect(1.4,1.4,2,2.2,{fill:'var(--accent)',fo:.25,c:'var(--ink)',w:1.5});
    P.text(.4,5.8,'ℝ',{dy:18,s:15}).text(.8,5.1,'ℚ',{dy:18,s:15}).text(1.2,4.4,'ℤ',{dy:18,s:15}).text(1.6,3.6,'ℕ',{dy:18,s:15});
    P.text(1.9,2,'0',{a:'middle'}).text(2.8,2.6,'7',{a:'middle'}).text(4.4,2.4,'−3',{a:'middle'}).text(6.5,3,'−2/5',{a:'middle'}).text(6.5,1.6,'0,3̅',{a:'middle'})
     .text(8.8,3.2,'√2',{a:'middle'}).text(8.8,1.8,'π',{a:'middle'});
    return P.svg(); })(),
  note:'Pour prouver qu’un nombre est rationnel, il suffit de l’écrire comme une fraction d’entiers. Prouver qu’il est irrationnel est plus difficile : il faut montrer qu’aucune fraction ne convient.'},
 {h:'Le plus petit ensemble',p:`Quel est le plus petit ensemble qui contient le nombre ${F('−12','4')}&nbsp;?`,opts:['ℕ','ℤ','ℚ','ℝ'],ans:1,
  why:'−12/4 = −3. C’est un entier négatif : il est dans ℤ mais pas dans ℕ.'},
 {kind:'Théorie',h:'Intervalles',p:'<p>« Tous les réels entre −2 et 3 » : impossible de les lister, il y en a une infinité. On décrit cet ensemble d’une seule écriture, l’intervalle.</p><div class="def"><p>Pour <i>a</i> &lt; <i>b</i>, l’<b>intervalle fermé</b> <b>[<i>a</i> ; <i>b</i>]</b> est l’ensemble {<i>x</i> ∈ ℝ : <i>a</i> ≤ <i>x</i> ≤ <i>b</i>} et l’<b>intervalle ouvert</b> <b>]<i>a</i> ; <i>b</i>[</b> est {<i>x</i> ∈ ℝ : <i>a</i> &lt; <i>x</i> &lt; <i>b</i>}. Un crochet tourné vers le nombre l’<b>inclut</b>, un crochet tourné vers l’extérieur l’<b>exclut</b>. Les intervalles mixtes [<i>a</i> ; <i>b</i>[ et ]<i>a</i> ; <i>b</i>] existent aussi.</p></div><div class="idea"><p>Un intervalle est un morceau de la droite réelle sans trou : si deux nombres y sont, tout ce qui est entre eux y est aussi. Les bornes <i>a</i> et <i>b</i> sont les seuls points où il faut décider : dedans ou dehors ? Règle les curseurs : la légende traduit le dessin en inégalités.</p></div><div class="ex"><p>]−2 ; 3] contient 3, 0 et −1,999, mais pas −2 (crochet ouvert) ni 3,01. L’ensemble {<i>x</i> : <i>x</i> ≥ 2} s’écrit <b>[2 ; +∞[</b> : fermé en 2, il file vers l’infini.</p></div><div class="warn"><p>Du côté de l’infini, le crochet est <b>toujours ouvert</b> : ∞ n’est pas un nombre, on ne peut pas l’atteindre. ℝ lui-même s’écrit ]−∞ ; +∞[.</p></div>',
  params:[{id:'a',l:'a',min:-5,max:0,step:.5,v:-2},{id:'b',l:'b',min:.5,max:5,step:.5,v:3},{id:'lo',l:'Bord gauche (0 fermé, 1 ouvert)',min:0,max:1,v:0},{id:'ro',l:'Bord droit (0 fermé, 1 ouvert)',min:0,max:1,v:1}],
  draw:v=>iline(v.a,v.b,v.lo,v.ro),
  info:v=>`${iv(v.a,v.b,v.lo,v.ro)} = {<i>x</i> ∈ ℝ : ${fmt(v.a)} ${v.lo?'&lt;':'≤'} <i>x</i> ${v.ro?'&lt;':'≤'} ${fmt(v.b)}}`,
  note:'Un seul nombre s’écrit entre accolades : {3}. L’ensemble vide, sans aucun élément, se note ∅.'},
 {kind:'Pratique',h:'Représente l’ensemble',p:'Règle les curseurs pour représenter {<i>x</i> ∈ ℝ : −2 &lt; <i>x</i> ≤ 3}.',
  params:[{id:'a',l:'a',min:-5,max:0,step:.5,v:-1},{id:'b',l:'b',min:.5,max:5,step:.5,v:2},{id:'lo',l:'Bord gauche (0 fermé, 1 ouvert)',min:0,max:1,v:0},{id:'ro',l:'Bord droit (0 fermé, 1 ouvert)',min:0,max:1,v:0}],
  draw:v=>iline(v.a,v.b,v.lo,v.ro), info:v=>iv(v.a,v.b,v.lo,v.ro),
  ok:v=>v.a===-2&&v.b===3&&v.lo===1&&v.ro===0,why:'−2 est exclu (inégalité stricte) et 3 est inclus : c’est ]−2 ; 3].'},
 {kind:'Théorie',h:'Réunion et intersection d’intervalles',p:'<p>La solution d’une inéquation est souvent en plusieurs morceaux : « <i>x</i> &lt; −1 ou <i>x</i> &gt; 3 ». Il faut un symbole pour coller des intervalles, et un autre pour ne garder que ce qu’ils ont en commun.</p><div class="def"><p>La <b>réunion</b> A ∪ B (lire « A union B ») est l’ensemble des nombres qui sont dans A <b>ou</b> dans B, c’est-à-dire dans au moins l’un des deux. L’<b>intersection</b> A ∩ B (« A inter B ») est l’ensemble des nombres qui sont dans A <b>et</b> dans B à la fois. Si rien n’est commun, l’intersection est l’ensemble vide ∅.</p></div><div class="idea"><p>Dessine chaque intervalle sur une droite numérique, l’un au-dessus de l’autre. La réunion est tout ce qui est colorié au moins une fois ; l’intersection, ce qui est colorié deux fois. Une double inégalité comme −1 ≤ <i>x</i> &lt; 4 est une intersection : <i>x</i> ≥ −1 et <i>x</i> &lt; 4.</p></div><div class="ex"><p>Avec A = ]−∞ ; 2] et B = [0 ; 5[ (la figure) : A ∩ B = [0 ; 2], les nombres à la fois ≥ 0 et ≤ 2, et A ∪ B = ]−∞ ; 5[. Avec A = ]−∞ ; −1[ et B = ]3 ; +∞[, l’intersection est vide et la réunion ]−∞ ; −1[ ∪ ]3 ; +∞[ ne se simplifie pas : on la laisse écrite avec ∪.</p></div><div class="warn"><p>« <i>x</i> &lt; −1 ou <i>x</i> &gt; 3 » ne s’écrit jamais ]3 ; −1[ : un intervalle a toujours sa petite borne à gauche. Quand les morceaux sont séparés, le symbole ∪ est obligatoire.</p></div>',
  fig:(()=>{ const P=plane({x:[-5.6,5.6],y:[-1.4,2.3],h:150,grid:false,axes:false});
    P.seg(-5.5,0,5.5,0,{c:'var(--muted)',w:1.5}); for(let k=-5;k<=5;k++){ P.seg(k,-.12,k,.12,{c:'var(--muted)',w:1.2}); P.text(k,0,fmt(k),{a:'middle',dy:24,s:11,c:'var(--muted)'}); }
    P.seg(-5.5,1.6,2,1.6,{c:'var(--accent)',w:6}).text(2,1.6,']',{a:'middle',dy:8,s:24,c:'var(--accent)'}).text(-5.3,1.6,'A',{dy:-10,c:'var(--accent)'});
    P.seg(0,.9,5,.9,{c:'var(--math)',w:6}).text(0,.9,'[',{a:'middle',dy:8,s:24,c:'var(--math)'}).text(5,.9,'[',{a:'middle',dy:8,s:24,c:'var(--math)'}).text(4.3,.9,'B',{dy:-10,c:'var(--math)'});
    P.seg(0,0,2,0,{c:'var(--spark)',w:6}).text(0,0,'[',{a:'middle',dy:8,s:24,c:'var(--spark)'}).text(2,0,']',{a:'middle',dy:8,s:24,c:'var(--spark)'}).text(1,0,'A ∩ B',{a:'middle',dy:-12,c:'var(--spark)'});
    return P.svg(); })()},
 {kind:'Théorie',h:'Résoudre une inéquation',p:'<p>Une inéquation comme 3 − 4<i>x</i> &gt; 2<i>x</i> + 15 demande tous les <i>x</i> qui la rendent vraie : en général une infinité, donc un intervalle. On ne peut pas les tester un par un ; on transforme l’inéquation sans changer ses solutions.</p><div class="prop"><p>Deux inéquations sont <b>équivalentes</b> (symbole ⇔) si elles ont exactement les mêmes solutions. On obtient une inéquation équivalente en : 1) ajoutant ou retranchant un même nombre (ou une même expression) des deux côtés ; 2) multipliant ou divisant les deux côtés par un même nombre <b>strictement positif</b> ; 3) multipliant ou divisant par un nombre <b>strictement négatif, à condition de renverser le sens</b> de l’inégalité.</p></div><div class="why"><p>Ajouter un nombre décale les deux membres de la même quantité : l’ordre ne change pas. Multiplier par un positif étire la droite numérique sans la retourner. Multiplier par un négatif la retourne comme un miroir : 2 &lt; 5, mais −2 &gt; −5. Voilà pourquoi le sens s’inverse.</p></div><div class="ex"><p>−3<i>x</i> &gt; −6. On divise par −3 &lt; 0 et on renverse : <i>x</i> &lt; 2. Contrôle : <i>x</i> = 0 donne 0 &gt; −6, vrai ; <i>x</i> = 3 donne −9 &gt; −6, faux. S = ]−∞ ; 2[.</p></div><div class="warn"><p>Ne multiplie jamais par une expression dont tu ne connais pas le signe, comme (<i>x</i> − 1) : elle est positive pour certains <i>x</i>, négative pour d’autres, et le sens dépendrait de <i>x</i>. Dans ce cas, on compare à 0 et on fait un tableau de signes.</p></div>',
  note:'Écris toujours la réponse sous forme d’intervalle, puis vérifie-la avec une valeur prise dedans et une prise dehors.'},
 {kind:'Méthode',h:'Résoudre une inéquation du premier degré',p:'<b>Quand :</b> l’inconnue <i>x</i> n’apparaît qu’à la puissance 1, sans dénominateur. <b>Pourquoi ça marche :</b> chaque geste (ajouter, multiplier par un nombre non nul) donne une inéquation qui a exactement les mêmes solutions. <b>Comment :</b> regroupe les <i>x</i> d’un côté et les nombres de l’autre, puis divise par le coefficient de <i>x</i>, en renversant le sens s’il est négatif. Écris enfin la réponse sous forme d’intervalle.',
  demo:{enonce:'Résoudre 3 − 4<i>x</i> &gt; 2<i>x</i> + 15.',
   etapes:[
    {f:'3 − 4<i>x</i> − 2<i>x</i> &gt; 15, soit 3 − 6<i>x</i> &gt; 15',w:'On retire 2<i>x</i> des deux côtés pour regrouper les <i>x</i> à gauche.'},
    {f:'−6<i>x</i> &gt; 12',w:'On retire 3 des deux côtés : il ne reste que le terme en <i>x</i> à gauche.'},
    {f:'<i>x</i> &lt; 12/(−6), soit <i>x</i> &lt; −2',w:'On divise par −6, un nombre négatif : le sens de l’inégalité se renverse.'},
    {f:'Contrôle avec <i>x</i> = −3 : 3 + 12 = 15 &gt; 2 · (−3) + 15 = 9 ✓',w:'Un nombre de l’ensemble trouvé doit vérifier l’inéquation de départ.'}],
   conclusion:'S = ]−∞ ; −2[. Le crochet est ouvert car l’inégalité est stricte.'}},
 {h:'À toi',p:'Résous 2<i>x</i> − 5 ≤ 7<i>x</i> + 10. L’ensemble des solutions s’écrit [<i>a</i> ; +∞[. Donne <i>a</i>.',lab:'a =',ans:-3,
  why:'On regroupe : −5 − 10 ≤ 7x − 2x, soit −15 ≤ 5x, donc x ≥ −3. S = [−3 ; +∞[.'},
 {kind:'Théorie',h:'Le signe d’une expression affine',p:'<p>Pour résoudre (<i>x</i> − 1)(<i>x</i> + 2) ≤ 0, il faut connaître le signe de chaque facteur selon la valeur de <i>x</i>. Le cas de base est l’expression <i>ax</i> + <i>b</i>.</p><div class="prop"><p>Pour <i>a</i> ≠ 0, l’expression <b><i>ax</i> + <i>b</i></b> s’annule en un seul point, sa <b>racine</b> <i>x</i>₀ = −<i>b</i>/<i>a</i>. Elle a le <b>signe de <i>a</i></b> pour <i>x</i> &gt; <i>x</i>₀ et le <b>signe opposé</b> pour <i>x</i> &lt; <i>x</i>₀.</p></div><div class="why"><p>On écrit <i>ax</i> + <i>b</i> = <i>a</i>(<i>x</i> − <i>x</i>₀). Le facteur <i>x</i> − <i>x</i>₀ est positif à droite de <i>x</i>₀ et négatif à gauche ; multiplié par <i>a</i>, il garde le signe de <i>a</i> à droite et prend le signe opposé à gauche. Sur la figure, la droite <i>y</i> = <i>ax</i> + <i>b</i> traverse l’axe une seule fois : en montant si <i>a</i> &gt; 0, en descendant si <i>a</i> &lt; 0.</p></div><div class="ex"><p>5 − 2<i>x</i> : ici <i>a</i> = −2 et la racine vaut 5/2. Pour <i>x</i> &gt; 2,5, l’expression a le signe de <i>a</i>, donc elle est négative (en <i>x</i> = 3 : 5 − 6 = −1). Pour <i>x</i> &lt; 2,5, elle est positive (en <i>x</i> = 0 : 5).</p></div><div class="idea"><p>Un produit ou un quotient de telles expressions ne peut changer de signe qu’en une racine de l’un des facteurs. Entre deux racines consécutives, son signe est constant : il suffit de le calculer facteur par facteur. C’est tout le principe du tableau de signes.</p></div>',
  fig:(()=>{ const P=plane({x:[-2,5],y:[-4,6],w:300,lab:1}); P.fn(x=>5-2*x,{from:-2,to:5}).fn(x=>2*x+1,{from:-2,to:5,c:'var(--spark)'});
    P.dot(2.5,0,{r:5,c:'var(--accent)',l:'5/2'}).dot(-.5,0,{r:5,c:'var(--spark)',l:'−1/2',dx:-44}); P.text(3.3,-1.6,'5 − 2x',{c:'var(--accent)'}).text(1.5,4.8,'2x + 1',{c:'var(--spark)'}); return P.svg(); })()},
 {kind:'Méthode',h:'Le tableau de signes',p:`<b>Quand :</b> on compare à 0 un produit ou un quotient de facteurs simples. <b>Pourquoi ça marche :</b> un facteur affine <i>ax</i> + <i>b</i> ne change de signe qu’en sa racine −<i>b</i>/<i>a</i> ; il a le signe de <i>a</i> à droite de sa racine et le signe opposé à gauche. Entre deux racines consécutives, le produit garde donc un signe constant. <b>Comment :</b> on étudie le signe de chaque facteur, puis on applique la règle des signes colonne par colonne. Exemple : ${F('<i>x</i> − 1','<i>x</i> + 2')} ≤ 0.`,
  demo:{enonce:`Résoudre ${F('<i>x</i> − 1','<i>x</i> + 2')} ≤ 0.`,
   etapes:[
    {f:'<i>x</i> − 1 = 0 ⇔ <i>x</i> = 1 ; <i>x</i> + 2 = 0 ⇔ <i>x</i> = −2 (valeur interdite)',w:'On cherche où chaque facteur s’annule : ce sont les seuls endroits où un signe peut changer. Le dénominateur ne doit jamais valoir 0.'},
    {f:'On range les valeurs dans l’ordre : −∞, −2, 1, +∞',w:'Elles découpent la droite en trois intervalles, une colonne chacun.'},
    {f:'<i>x</i> − 1 : − puis − puis + ; <i>x</i> + 2 : − puis + puis +',w:'Le coefficient de <i>x</i> vaut 1 &gt; 0 dans les deux cas : chaque facteur est négatif à gauche de sa racine, positif à droite.'},
    {f:'Quotient : + sur ]−∞ ; −2[, − sur ]−2 ; 1[, + sur ]1 ; +∞[',w:'Règle des signes : deux signes égaux donnent +, deux signes différents donnent −.'},
    {f:'Le quotient vaut 0 en 1 (inclus) et n’existe pas en −2 (exclu)',w:'L’inégalité est large (≤) : les zéros du numérateur sont solutions. Une valeur interdite ne l’est jamais.'}],
   conclusion:'S = ]−2 ; 1]. Quand la solution a plusieurs morceaux, on les réunit avec le symbole ∪ (« ou »).'},
  fig:tab([['<i>x</i>','−∞','','−2','','1','','+∞'],['<i>x</i> − 1','','−','|','−','0','+',''],['<i>x</i> + 2','','−','0','+','|','+',''],['quotient','','+','‖','−','0','+','']]),
  note:'La double barre ‖ marque une <b>valeur interdite</b> : on l’exclut toujours. Ici S = ]−2 ; 1] (1 est inclus car le quotient y vaut 0).'},
 {kind:'Défi',h:'Produit et quotient',p:`Résous ${F('(<i>x</i> + 1)(3 − <i>x</i>)','<i>x</i>')} &gt; 0.`,
  opts:[']−1 ; 0[ ∪ ]3 ; +∞[',']−1 ; 3[',']−∞ ; −1[ ∪ ]0 ; 3[',']−∞ ; −1] ∪ ]0 ; 3]'],ans:2,
  why:'Zéros : −1 et 3, valeur interdite 0. Signes de gauche à droite : + (x &lt; −1), − (entre −1 et 0), + (entre 0 et 3), − (x &gt; 3). Inégalité stricte : S = ]−∞ ; −1[ ∪ ]0 ; 3[.'},
 {kind:'Méthode',h:'Factoriser avant d’étudier un signe',p:'<b>Quand :</b> l’expression est une somme, comme <i>x</i>³ − 4<i>x</i>, et le tableau de signes demande des facteurs. <b>Pourquoi ça marche :</b> le signe d’une somme ne se lit pas directement, celui d’un produit oui. <b>Comment :</b> mets d’abord en facteur ce qui est commun à tous les termes, puis cherche une identité remarquable : <b><i>a</i>² − <i>b</i>² = (<i>a</i> − <i>b</i>)(<i>a</i> + <i>b</i>)</b>, <b><i>a</i>² ± 2<i>ab</i> + <i>b</i>² = (<i>a</i> ± <i>b</i>)²</b>.',
  demo:{enonce:'Résoudre <i>x</i>³ − 4<i>x</i> &lt; 0.',
   etapes:[
    {f:'<i>x</i>³ − 4<i>x</i> = <i>x</i>(<i>x</i>² − 4)',w:'Les deux termes contiennent <i>x</i> : on le met en facteur.'},
    {f:'<i>x</i>² − 4 = <i>x</i>² − 2² = (<i>x</i> − 2)(<i>x</i> + 2)',w:'On reconnaît une différence de deux carrés.'},
    {f:'Racines : −2, 0, 2. Signes de <i>x</i>, <i>x</i> − 2, <i>x</i> + 2 dans chaque colonne',w:'Trois facteurs affines, donc trois lignes dans le tableau de signes.'},
    {f:'Produit : − sur ]−∞ ; −2[, + sur ]−2 ; 0[, − sur ]0 ; 2[, + sur ]2 ; +∞[',w:'Règle des signes : un nombre impair de facteurs négatifs donne un produit négatif.'}],
   conclusion:'S = ]−∞ ; −2[ ∪ ]0 ; 2[. Les racines sont exclues car l’inégalité est stricte.'},
  note:'Un carré (<i>x</i> − 3)² est toujours ≥ 0 et ne s’annule qu’en 3 : il ne change pas le signe du reste.'},
 {h:'Factorise, puis conclus',p:'Résous <i>x</i>³ − 6<i>x</i>² + 9<i>x</i> ≤ 0.',opts:[']−∞ ; 0]','[0 ; 3]',']−∞ ; 0] ∪ {3}',']−∞ ; 3]'],ans:2,
  why:'x³ − 6x² + 9x = x(x² − 6x + 9) = x(x − 3)². Le carré est positif sauf en 3 où il est nul. Donc le produit est ≤ 0 pour x ≤ 0, et aussi en x = 3 : S = ]−∞ ; 0] ∪ {3}.'},
 {kind:'Méthode',h:'Inéquation avec un quotient : tout ramener à 0',p:'<b>Quand :</b> l’inconnue est au dénominateur et l’autre membre n’est pas 0, comme 3/(<i>x</i> − 1) ≤ 1. <b>Pourquoi :</b> on ne peut pas multiplier par le dénominateur, dont le signe dépend de <i>x</i>. Comparer à 0 un seul quotient, lui, se fait avec un tableau de signes. <b>Comment :</b> passe tout du même côté, réduis au même dénominateur, simplifie le numérateur, puis fais le tableau de signes.',
  demo:{enonce:`Résoudre ${F('<i>x</i> + 1','<i>x</i> − 2')} ≥ 2.`,
   etapes:[
    {f:`${F('<i>x</i> + 1','<i>x</i> − 2')} − 2 ≥ 0`,w:'On soustrait 2 des deux côtés pour comparer à 0.'},
    {f:`${F('<i>x</i> + 1 − 2(<i>x</i> − 2)','<i>x</i> − 2')} ≥ 0`,w:'On écrit 2 = 2(<i>x</i> − 2)/(<i>x</i> − 2) pour n’avoir qu’une seule fraction.'},
    {f:`${F('−<i>x</i> + 5','<i>x</i> − 2')} ≥ 0`,w:'On développe et on réduit le numérateur : <i>x</i> + 1 − 2<i>x</i> + 4 = −<i>x</i> + 5.'},
    {f:'−<i>x</i> + 5 : + avant 5, − après. <i>x</i> − 2 : − avant 2, + après',w:'Le coefficient de <i>x</i> au numérateur vaut −1 : ce facteur est négatif à droite de sa racine.'},
    {f:'Quotient : − sur ]−∞ ; 2[, + sur ]2 ; 5[, − sur ]5 ; +∞[ ; nul en 5, interdit en 2',w:'Règle des signes, puis on regarde les bornes.'}],
   conclusion:'S = ]2 ; 5]. Contrôle avec <i>x</i> = 3 : 4/1 = 4 ≥ 2 ✓.'}},
 {h:'À toi',p:`Résous ${F('3','<i>x</i> − 1')} ≤ 1.`,opts:[']−∞ ; 4]',']1 ; 4]',']−∞ ; 1[ ∪ [4 ; +∞[','[4 ; +∞['],ans:2,
  why:'3/(x − 1) − 1 = (3 − x + 1)/(x − 1) = (4 − x)/(x − 1). Le quotient est négatif pour x &lt; 1, positif entre 1 et 4, négatif après 4, nul en 4 et interdit en 1. S = ]−∞ ; 1[ ∪ [4 ; +∞[.'},
 {kind:'Récapitulatif',h:'Ce qu’il faut retenir : nombres et inéquations',p:'<div class="keep"><ul><li><b>Ensembles de nombres</b> : ℕ ⊂ ℤ ⊂ ℚ ⊂ ℝ. Un rationnel s’écrit <i>p</i>/<i>q</i> ; une écriture décimale finie ou périodique est rationnelle ; √2 et π sont irrationnels.</li><li><b>Intervalles</b> : crochet vers le nombre = inclus, vers l’extérieur = exclu ; toujours ouvert du côté de ∞. ∪ pour « ou » (réunion), ∩ pour « et » (intersection).</li><li><b>Transformer une inéquation</b> : ajouter un nombre, multiplier par un positif ; multiplier par un négatif <b>renverse le sens</b>. Jamais de multiplication par une expression de signe inconnu.</li><li><b>Signe de <i>ax</i> + <i>b</i></b> : signe de <i>a</i> à droite de la racine −<i>b</i>/<i>a</i>, signe opposé à gauche.</li><li><b>Tableau de signes</b> : racines de chaque facteur dans l’ordre, une ligne par facteur, règle des signes colonne par colonne. Double barre ‖ pour une valeur interdite, 0 pour un zéro du numérateur ; inégalité large = zéros inclus.</li><li><b>Quotient comparé à un nombre</b> : tout passer du même côté, réduire au même dénominateur, puis tableau de signes.</li><li><b>Factoriser</b> d’abord : facteur commun, <i>a</i>² − <i>b</i>² = (<i>a</i> − <i>b</i>)(<i>a</i> + <i>b</i>), carrés parfaits (<i>a</i> ± <i>b</i>)².</li><li>Toujours <b>contrôler</b> avec une valeur prise dans la solution.</li></ul></div>'},
 {kind:'Problème',h:'Quelle agence de location&nbsp;?',
  p:'Pour louer une camionnette une journée, l’agence A facture 30 CHF plus 0,50 CHF par kilomètre. L’agence B facture 18 CHF plus 0,80 CHF par kilomètre. On note <i>x</i> ≥ 0 la distance parcourue, en km. On cherche quand chaque agence est la plus avantageuse.',
  parts:[
   {q:'a) Pour quelle distance les deux agences coûtent-elles le même prix&nbsp;?',lab:'x =',unit:'km',ans:40,hint:'Écris les deux prix, 30 + 0,5<i>x</i> et 18 + 0,8<i>x</i>, puis résous leur égalité.',why:'30 + 0,5x = 18 + 0,8x ⇔ 12 = 0,3x ⇔ x = 40 km. Les deux coûtent alors 50 CHF.'},
   {q:'b) Pour quelles distances l’agence A est-elle strictement moins chère&nbsp;?',opts:['[0 ; 40[','[40 ; +∞[',']40 ; +∞[',']0 ; 40]'],ans:2,hint:'Résous 30 + 0,5<i>x</i> &lt; 18 + 0,8<i>x</i>. Diviser par un nombre positif garde le sens.',why:'30 + 0,5x &lt; 18 + 0,8x ⇔ 12 &lt; 0,3x ⇔ x &gt; 40. L’inégalité est stricte : 40 est exclu.'},
   {q:'c) Tu as 45 CHF. En choisissant la meilleure agence, quelle distance maximale peux-tu parcourir&nbsp;?',lab:'x =',unit:'km',ans:33.75,tol:1e-6,hint:'Résous 30 + 0,5<i>x</i> ≤ 45 et 18 + 0,8<i>x</i> ≤ 45, puis compare.',why:'Chez A : 0,5x ≤ 15, soit x ≤ 30. Chez B : 0,8x ≤ 27, soit x ≤ 33,75. B permet d’aller jusqu’à 33,75 km.'},
  ],
  sol:'Les prix sont A(x) = 30 + 0,5x et B(x) = 18 + 0,8x.<br>A(x) − B(x) = 12 − 0,3x : nul en x = 40, positif pour x &lt; 40, négatif pour x &gt; 40.<br>Donc B est moins chère sous 40 km, A au-delà, et les deux coûtent 50 CHF à 40 km.<br>Avec 45 CHF, on reste sous 50 CHF, donc dans la zone où B est la moins chère : 18 + 0,8x ≤ 45 ⇔ x ≤ 33,75. On peut parcourir au plus 33,75 km (contre 30 km chez A).'},
 {kind:'Problème',h:'L’erreur du camarade',
  p:`Un camarade veut résoudre ${F('2<i>x</i> − 1','<i>x</i> + 3')} ≤ 1. Il multiplie les deux membres par <i>x</i> + 3, obtient 2<i>x</i> − 1 ≤ <i>x</i> + 3, et conclut <i>x</i> ≤ 4. Sa réponse est fausse. On cherche la bonne solution, puis on localise l’erreur.`,
  parts:[
   {q:`a) En passant tout du même côté, l’inéquation devient ${F('<i>x</i> − <i>a</i>','<i>x</i> + 3')} ≤ 0. Que vaut <i>a</i>&nbsp;?`,lab:'a =',ans:4,hint:'Soustrais 1 et mets tout sur le dénominateur <i>x</i> + 3.',why:'(2x − 1)/(x + 3) − 1 = (2x − 1 − x − 3)/(x + 3) = (x − 4)/(x + 3).'},
   {q:'b) Quel est l’ensemble des solutions&nbsp;?',opts:[']−∞ ; 4]',']−3 ; 4]','[−3 ; 4]',']−∞ ; −3[ ∪ [4 ; +∞['],ans:1,hint:'Fais un tableau de signes avec les zéros 4 et −3. N’oublie pas la valeur interdite.',why:'Le quotient est négatif entre −3 et 4, nul en 4, interdit en −3 : S = ]−3 ; 4].'},
   {q:'c) Où est l’erreur du camarade&nbsp;?',opts:['Il aurait dû remplacer 1 par 0 avant de multiplier','On n’a pas le droit de multiplier une inéquation','Pour <i>x</i> &lt; −3, <i>x</i> + 3 est négatif : multiplier par <i>x</i> + 3 renverse alors le sens','Il a oublié que 4 est exclu'],ans:2,hint:'Le sens d’une inéquation dépend du signe du nombre par lequel on multiplie.',why:'Le signe de x + 3 n’est pas connu. Pour x &lt; −3 il est négatif et le sens s’inverse : sa réponse garde à tort ]−∞ ; −3].'},
   {q:'d) Combien de nombres entiers vérifient l’inéquation&nbsp;?',ans:7,hint:'Liste les entiers de ]−3 ; 4].',why:'−2, −1, 0, 1, 2, 3, 4 : sept entiers. −3 est exclu.'},
  ],
  sol:'On ne multiplie pas par x + 3, dont le signe est inconnu. On écrit plutôt (2x − 1)/(x + 3) − 1 ≤ 0, soit (x − 4)/(x + 3) ≤ 0.<br>Tableau de signes : x − 4 s’annule en 4, x + 3 en −3 (valeur interdite).<br>Le quotient est positif pour x &lt; −3, négatif entre −3 et 4, positif pour x &gt; 4, et nul en 4.<br>Donc S = ]−3 ; 4]. Le camarade a inclus à tort ]−∞ ; −3] : pour ces x, multiplier par x + 3 &lt; 0 aurait dû renverser le sens (et −3 est interdit).<br>Les entiers solutions sont −2, −1, 0, 1, 2, 3, 4 : il y en a 7.'},
]},

{subj:'an1', sem:'aut', id:'an1-trinome', h:'Valeurs absolues et trinôme', p:'La valeur absolue comme distance, puis le trinôme du second degré : discriminant, racines, signe et factorisation.', steps:[
 {kind:'Théorie',h:'La valeur absolue est une distance',p:'<p>Sur une droite graduée, quelle est la distance entre 3 et −2 ? Cinq unités, qu’on parte de l’un ou de l’autre. Il faut un outil qui « oublie le signe » d’une différence : la valeur absolue.</p><div class="def"><p>La <b>valeur absolue</b> d’un réel <i>x</i> est <b>|<i>x</i>| = <i>x</i></b> si <i>x</i> ≥ 0 et <b>|<i>x</i>| = −<i>x</i></b> si <i>x</i> &lt; 0. C’est toujours un nombre positif ou nul : |5| = 5 et |−5| = −(−5) = 5. Pour deux réels <i>a</i> et <i>b</i>, le nombre <b>|<i>a</i> − <i>b</i>|</b> est la <b>distance</b> entre <i>a</i> et <i>b</i> sur la droite réelle.</p></div><div class="idea"><p>|<i>x</i>| est la distance de <i>x</i> à 0. Comme une distance ne dépend pas du sens du trajet, |<i>a</i> − <i>b</i>| = |<i>b</i> − <i>a</i>| : déplace les deux points de la figure, le segment jaune garde la même longueur dans un sens comme dans l’autre. Cette lecture géométrique rend les équations et inéquations avec valeur absolue presque évidentes.</p></div><div class="ex"><p>|3 − (−2)| = |5| = 5 et |−2 − 3| = |−5| = 5 : la distance entre 3 et −2 vaut 5. Autre lecture : |<i>x</i> − 4| = 1 signifie « <i>x</i> est à distance 1 de 4 », donc <i>x</i> = 3 ou <i>x</i> = 5.</p></div><div class="warn"><p>−<i>x</i> n’est pas forcément négatif : si <i>x</i> = −7, alors −<i>x</i> = 7. Écrire |<i>x</i>| = −<i>x</i> pour <i>x</i> &lt; 0 donne bien un résultat positif.</p></div>',
  params:[{id:'a',l:'a',min:-5,max:5,step:.5,v:-2},{id:'b',l:'b',min:-5,max:5,step:.5,v:3}],
  draw:v=>{ const P=plane({x:[-5.6,5.6],y:[-1.1,1.6],grid:false,axes:false}); P.seg(-5.5,0,5.5,0,{c:'var(--muted)',w:1.5});
    for(let k=-5;k<=5;k++){ P.seg(k,-.12,k,.12,{c:'var(--muted)',w:1.2}); P.text(k,0,fmt(k),{a:'middle',dy:24,s:11,c:'var(--muted)'}); }
    if(v.a!==v.b) P.seg(v.a,.6,v.b,.6,{c:'var(--spark)',w:3}).text((v.a+v.b)/2,.6,`${fmt(Math.abs(v.a-v.b),1)}`,{a:'middle',dy:-8});
    P.dot(v.a,0,{l:'a',c:'var(--accent)'}).dot(v.b,0,{l:'b',c:'var(--math)'}); return P.svg(); },
  info:v=>`|a − b| = |${fmt(v.a,1)} − (${fmt(v.b,1)})| = ${fmt(Math.abs(v.a-v.b),1)} = |b − a|`,
  note:'√(x²) = |x|, et pas x : √((−3)²) = 3.'},
 {kind:'Théorie',h:'Calculer avec les valeurs absolues',p:'<p>Avant de résoudre des équations, il faut savoir ce qu’on a le droit de faire avec le symbole | |. Il se comporte bien avec la multiplication, beaucoup moins bien avec l’addition.</p><div class="prop"><p>Pour tous réels <i>a</i>, <i>b</i> : <b>|<i>ab</i>| = |<i>a</i>| · |<i>b</i>|</b>, <b>|<i>a</i>/<i>b</i>| = |<i>a</i>|/|<i>b</i>|</b> (<i>b</i> ≠ 0), <b>|<i>a</i>|² = <i>a</i>²</b> et <b>√(<i>a</i>²) = |<i>a</i>|</b>. De plus, |<i>a</i>| = |<i>b</i>| ⇔ <i>a</i> = <i>b</i> ou <i>a</i> = −<i>b</i>. Pour l’addition, on a seulement l’<b>inégalité triangulaire</b> <b>|<i>a</i> + <i>b</i>| ≤ |<i>a</i>| + |<i>b</i>|</b>.</p></div><div class="why"><p>Le signe d’un produit est le produit des signes, et la valeur absolue ne retient que la grandeur : |(−3) · 4| = 12 = 3 · 4. Pour la racine : <i>a</i>² est le même nombre pour <i>a</i> et pour −<i>a</i>, et la racine carrée renvoie la version positive, donc |<i>a</i>|. Pour l’addition, deux nombres de signes contraires se compensent en partie : |5 + (−3)| = 2 &lt; 8 ; l’égalité n’a lieu que s’ils ont le même signe.</p></div><div class="ex"><p>Simplifions |2<i>x</i> − 6| : c’est |2(<i>x</i> − 3)| = 2|<i>x</i> − 3|, le double de la distance de <i>x</i> à 3. Et √((<i>x</i> − 1)²) vaut |<i>x</i> − 1|, pas <i>x</i> − 1 : pour <i>x</i> = 0, √1 = 1 = |−1|.</p></div><div class="warn"><p>|<i>a</i> + <i>b</i>| n’est pas |<i>a</i>| + |<i>b</i>| en général, et |<i>a</i> − <i>b</i>| n’est pas |<i>a</i>| − |<i>b</i>| : |2 − 5| = 3 alors que 2 − 5 = −3. On ne « distribue » jamais une valeur absolue sur une somme.</p></div>'},
 {kind:'Méthode',h:'Résoudre |A| = k',p:'<b>Quand :</b> une valeur absolue est égale à un nombre <i>k</i>. <b>Pourquoi ça marche :</b> deux nombres seulement ont pour valeur absolue <i>k</i> &gt; 0, à savoir <i>k</i> et −<i>k</i>. <b>Comment :</b> si <i>k</i> &lt; 0, il n’y a aucune solution ; si <i>k</i> = 0, on résout A = 0 ; si <i>k</i> &gt; 0, on résout séparément <b>A = <i>k</i></b> et <b>A = −<i>k</i></b>.',
  demo:{enonce:'Résoudre |3<i>x</i> + 1| = 5.',
   etapes:[
    {f:'5 &gt; 0, donc 3<i>x</i> + 1 = 5 ou 3<i>x</i> + 1 = −5',w:'L’expression dans la valeur absolue vaut 5 ou −5 : deux cas.'},
    {f:'3<i>x</i> + 1 = 5 ⇔ <i>x</i> = 4/3',w:'Premier cas : équation du premier degré.'},
    {f:'3<i>x</i> + 1 = −5 ⇔ 3<i>x</i> = −6 ⇔ <i>x</i> = −2',w:'Second cas.'},
    {f:'Contrôle : |3 · (−2) + 1| = |−5| = 5 ✓',w:'On vérifie au moins une solution dans l’équation de départ.'}],
   conclusion:'S = {−2 ; 4/3}.'},
  note:'|<i>x</i> − 4| = −1 n’a aucune solution : une valeur absolue n’est jamais négative.'},
 {h:'Équation avec valeur absolue',p:'Résous |2<i>x</i> − 3| = 7. Donne la plus petite solution.',lab:'x =',ans:-2,
  why:'|A| = 7 ⇔ A = 7 ou A = −7. Donc 2x − 3 = 7 (x = 5) ou 2x − 3 = −7 (x = −2). La plus petite est −2.'},
 {kind:'Théorie',h:'Inéquations : penser distance',p:'<p>Résoudre |<i>x</i> − 1| ≤ 3 en séparant les cas <i>x</i> − 1 ≥ 0 et <i>x</i> − 1 &lt; 0 marche, mais c’est long et source d’erreurs. Lire l’inéquation comme une distance donne la réponse d’un coup d’œil.</p><div class="prop"><p>Pour <i>r</i> &gt; 0 : <b>|<i>x</i> − <i>a</i>| &lt; <i>r</i> ⇔ <i>a</i> − <i>r</i> &lt; <i>x</i> &lt; <i>a</i> + <i>r</i></b>, c’est-à-dire <i>x</i> ∈ ]<i>a</i> − <i>r</i> ; <i>a</i> + <i>r</i>[. À l’inverse, <b>|<i>x</i> − <i>a</i>| &gt; <i>r</i> ⇔ <i>x</i> &lt; <i>a</i> − <i>r</i> ou <i>x</i> &gt; <i>a</i> + <i>r</i></b>. Avec ≤ et ≥, les bornes sont incluses.</p></div><div class="idea"><p>|<i>x</i> − <i>a</i>| &lt; <i>r</i> dit « <i>x</i> est à moins de <i>r</i> du centre <i>a</i> » : les solutions forment un intervalle centré en <i>a</i>, de rayon <i>r</i>. |<i>x</i> − <i>a</i>| &gt; <i>r</i> dit « <i>x</i> est à plus de <i>r</i> de <i>a</i> » : c’est l’extérieur de cet intervalle, en deux morceaux. Le centre est la valeur qui annule l’intérieur, le rayon est le nombre de droite.</p></div><div class="ex"><p>|<i>x</i> − 1| ≤ 3 (la figure) : les points à distance au plus 3 de 1, soit [1 − 3 ; 1 + 3] = [−2 ; 4]. Pour |<i>x</i> + 2| &gt; 3, on écrit <i>x</i> + 2 = <i>x</i> − (−2) : distance à −2 supérieure à 3, donc <i>x</i> &lt; −5 ou <i>x</i> &gt; 1.</p></div><div class="warn"><p>Si <i>r</i> est négatif, |A| &lt; <i>r</i> n’a aucune solution et |A| &gt; <i>r</i> est vraie pour tout <i>x</i> : une distance n’est jamais négative. Regarde le signe du membre de droite avant de commencer.</p></div>',
  fig:iline(-2,4,0,0),note:'Ci-dessus : |<i>x</i> − 1| ≤ 3, les points à distance au plus 3 de 1, soit [−2 ; 4].'},
 {kind:'Méthode',h:'Inéquations |A| ≤ r et |A| ≥ r',p:'<b>Quand :</b> une valeur absolue est comparée à un nombre <i>r</i> &gt; 0. <b>Pourquoi ça marche :</b> |A| ≤ <i>r</i> dit que A est à distance au plus <i>r</i> de 0, donc entre −<i>r</i> et <i>r</i>. <b>Comment :</b> |A| ≤ <i>r</i> ⇔ <b>−<i>r</i> ≤ A ≤ <i>r</i></b>, puis on isole <i>x</i> au milieu de l’encadrement. |A| ≥ <i>r</i> ⇔ <b>A ≤ −<i>r</i> ou A ≥ <i>r</i></b>, deux inéquations séparées.',
  demo:{enonce:'Résoudre |2<i>x</i> − 1| ≤ 5.',
   etapes:[
    {f:'−5 ≤ 2<i>x</i> − 1 ≤ 5',w:'La quantité 2<i>x</i> − 1 est à distance au plus 5 de 0.'},
    {f:'−4 ≤ 2<i>x</i> ≤ 6',w:'On ajoute 1 aux trois membres de l’encadrement.'},
    {f:'−2 ≤ <i>x</i> ≤ 3',w:'On divise les trois membres par 2 &gt; 0 : le sens ne change pas.'}],
   conclusion:'S = [−2 ; 3]. Pour |2<i>x</i> − 1| &gt; 5 on obtiendrait le complémentaire : ]−∞ ; −2[ ∪ ]3 ; +∞[.'},
  note:'Astuce : |<i>x</i> + 2| = |<i>x</i> − (−2)| est la distance de <i>x</i> à −2.'},
 {h:'À toi',p:'Quel est l’ensemble des solutions de |<i>x</i> + 2| &gt; 3&nbsp;?',opts:[']−5 ; 1[',']−∞ ; −5[ ∪ ]1 ; +∞[',']−∞ ; −1[ ∪ ]5 ; +∞[',']−∞ ; 1['],ans:1,
  why:'|x + 2| = |x − (−2)| est la distance à −2. Elle dépasse 3 si x &lt; −5 ou x &gt; 1.'},
 {kind:'Théorie',h:'Le trinôme et son discriminant',p:'<p>Une parabole <i>y</i> = <i>ax</i>² + <i>bx</i> + <i>c</i> peut couper l’axe des abscisses deux fois, le toucher une seule fois ou ne jamais le rencontrer. Un seul nombre, calculé avec les coefficients, dit dans quel cas on est.</p><div class="def"><p>Un <b>trinôme du second degré</b> est une expression <i>ax</i>² + <i>bx</i> + <i>c</i> avec <i>a</i> ≠ 0. Son <b>discriminant</b> est <b>Δ = <i>b</i>² − 4<i>ac</i></b> (lire « delta »). Ses <b>racines</b> sont les solutions de <i>ax</i>² + <i>bx</i> + <i>c</i> = 0 : si Δ &gt; 0, deux racines <b><i>x</i> = (−<i>b</i> ± √Δ)/(2<i>a</i>)</b> ; si Δ = 0, une <b>racine double</b> <i>x</i> = −<i>b</i>/(2<i>a</i>) ; si Δ &lt; 0, aucune racine réelle.</p></div><div class="idea"><p>Le graphe est une parabole tournée vers le haut si <i>a</i> &gt; 0, vers le bas si <i>a</i> &lt; 0, symétrique par rapport à la droite verticale <i>x</i> = −<i>b</i>/(2<i>a</i>). Les racines sont les abscisses où elle traverse l’axe, les points marqués sur la figure. Fais varier <i>c</i> : la parabole monte ou descend, et Δ change de signe exactement quand elle décolle de l’axe.</p></div><div class="ex"><p>Pour <i>x</i>² − 2<i>x</i> − 3 (position de départ) : Δ = (−2)² − 4 · 1 · (−3) = 4 + 12 = 16 &gt; 0, √Δ = 4, racines (2 − 4)/2 = −1 et (2 + 4)/2 = 3. Contrôle : 3² − 2 · 3 − 3 = 0 ✓.</p></div><div class="warn"><p>Repère <i>b</i> et <i>c</i> avec leur signe : dans <i>x</i>² − 2<i>x</i> − 3, <i>b</i> = −2 et <i>c</i> = −3, donc −4<i>ac</i> = +12. L’oubli du signe de <i>c</i> est l’erreur la plus fréquente.</p></div>',
  params:[{id:'a',l:'a',min:-2,max:2,step:.5,v:1},{id:'b',l:'b',min:-4,max:4,v:-2},{id:'c',l:'c',min:-4,max:4,v:-3}],
  draw:v=>{ const P=plane({x:[-6,6],y:[-6,6],lab:2}); P.fn(x=>v.a*x*x+v.b*x+v.c);
    const D=v.b*v.b-4*v.a*v.c; if(v.a!==0&&D>=0){ const s=Math.sqrt(D); [(-v.b-s)/(2*v.a),(-v.b+s)/(2*v.a)].forEach(r=>P.dot(r,0,{r:5})); } return P.svg(); },
  info:v=>{ if(v.a===0) return '<i>a</i> = 0 : ce n’est plus un trinôme, mais une fonction affine.'; const D=v.b*v.b-4*v.a*v.c;
    if(D<0) return `Δ = ${fmt(D)} &lt; 0 : aucune racine réelle, la parabole ne coupe pas l’axe.`;
    if(D===0) return `Δ = 0 : racine double x = ${fmt(-v.b/(2*v.a))}`;
    const s=Math.sqrt(D); return `Δ = ${fmt(D)} &gt; 0 : x₁ ≈ ${fmt((-v.b-s)/(2*v.a))}, x₂ ≈ ${fmt((-v.b+s)/(2*v.a))}`; }},
 {kind:'Théorie',h:'D’où vient la formule des racines',p:'<p>La formule (−<i>b</i> ± √Δ)/(2<i>a</i>) n’est pas tombée du ciel. Elle vient d’une seule idée : transformer le trinôme pour n’avoir qu’un seul <i>x</i>, enfermé dans un carré.</p><div class="why"><p>On met <i>a</i> en facteur : <i>ax</i>² + <i>bx</i> + <i>c</i> = <i>a</i>[<i>x</i>² + (<i>b</i>/<i>a</i>)<i>x</i>] + <i>c</i>. Or (<i>x</i> + <i>b</i>/(2<i>a</i>))² = <i>x</i>² + (<i>b</i>/<i>a</i>)<i>x</i> + <i>b</i>²/(4<i>a</i>²) : le crochet est ce carré, moins <i>b</i>²/(4<i>a</i>²). Donc <i>ax</i>² + <i>bx</i> + <i>c</i> = <i>a</i>(<i>x</i> + <i>b</i>/(2<i>a</i>))² − <i>b</i>²/(4<i>a</i>) + <i>c</i> = <i>a</i>(<i>x</i> + <i>b</i>/(2<i>a</i>))² − Δ/(4<i>a</i>). Annuler le trinôme revient à <b>(<i>x</i> + <i>b</i>/(2<i>a</i>))² = Δ/(4<i>a</i>²)</b>.</p></div><div class="idea"><p>Un carré égale un nombre. Si ce nombre est négatif (Δ &lt; 0), c’est impossible : aucune racine. S’il est nul (Δ = 0), <i>x</i> + <i>b</i>/(2<i>a</i>) = 0 : une seule racine, −<i>b</i>/(2<i>a</i>). S’il est positif (Δ &gt; 0), <i>x</i> + <i>b</i>/(2<i>a</i>) = ±√Δ/(2<i>a</i>), d’où les deux racines. Les trois cas du discriminant ne sont que les trois cas de l’équation « carré = nombre ».</p></div><div class="ex"><p><i>x</i>² − 2<i>x</i> − 3 = (<i>x</i> − 1)² − 1 − 3 = (<i>x</i> − 1)² − 4. Annuler : (<i>x</i> − 1)² = 4, donc <i>x</i> − 1 = ±2, soit <i>x</i> = 3 ou <i>x</i> = −1. On retrouve les racines, et on lit en plus le sommet de la parabole : (1 ; −4).</p></div><div class="warn"><p>Le signe ± ne donne deux racines que si √Δ ≠ 0. Avec Δ = 0, les deux « racines » sont le même nombre : on dit que la racine est double, et la parabole touche l’axe sans le traverser.</p></div>'},
 {kind:'Méthode',h:'Résoudre une équation du second degré',p:'<b>Quand :</b> l’équation s’écrit <i>ax²</i> + <i>bx</i> + <i>c</i> = 0 avec <i>a</i> ≠ 0 (au besoin, passe tout du même côté et développe). <b>Pourquoi ça marche :</b> en complétant le carré, <i>ax²</i> + <i>bx</i> + <i>c</i> = <i>a</i>[(<i>x</i> + <i>b</i>/(2<i>a</i>))² − Δ/(4<i>a</i>²)] : on se ramène à « un carré égale Δ/(4<i>a</i>²) », qui a deux, une ou zéro solution selon le signe de Δ. <b>Comment :</b> repère <i>a</i>, <i>b</i>, <i>c</i> avec leurs signes, calcule Δ, puis applique la formule.',
  demo:{enonce:'Résoudre 2<i>x</i>² + <i>x</i> − 3 = 0.',
   etapes:[
    {f:'<i>a</i> = 2, <i>b</i> = 1, <i>c</i> = −3',w:'On lit les coefficients, sans oublier le signe de <i>c</i>.'},
    {f:'Δ = 1² − 4 · 2 · (−3) = 1 + 24 = 25',w:'Δ &gt; 0 : il y a deux racines distinctes.'},
    {f:'<i>x</i> = (−1 ± 5)/4',w:'√25 = 5 et 2<i>a</i> = 4.'},
    {f:'<i>x</i>₁ = −6/4 = −3/2 et <i>x</i>₂ = 4/4 = 1',w:'On calcule chaque racine séparément.'},
    {f:'Contrôle : 2 · 1 + 1 − 3 = 0 ✓',w:'Remplacer une racine dans l’équation détecte une erreur de signe.'}],
   conclusion:'S = {−3/2 ; 1}, et 2<i>x</i>² + <i>x</i> − 3 = 2(<i>x</i> − 1)(<i>x</i> + 3/2) = (<i>x</i> − 1)(2<i>x</i> + 3).'},
  note:'Si <i>b</i> = 0 ou <i>c</i> = 0, pas besoin de Δ : <i>x</i>² − 9 = (<i>x</i> − 3)(<i>x</i> + 3) et <i>x</i>² − 5<i>x</i> = <i>x</i>(<i>x</i> − 5).'},
 {h:'À toi',p:'Résous 3<i>x</i>² − 5<i>x</i> − 2 = 0. Donne la plus grande solution.',lab:'x =',ans:2,
  why:'Δ = 25 + 24 = 49, donc x = (5 ± 7)/6 : x = 2 ou x = −1/3. La plus grande est 2.'},
 {kind:'Méthode',h:'La racine évidente',p:'<b>Quand :</b> les coefficients sont des entiers simples. On teste <i>x</i> = 1 (la somme <i>a</i> + <i>b</i> + <i>c</i> vaut 0) ou <i>x</i> = −1 (<i>a</i> − <i>b</i> + <i>c</i> = 0). <b>Pourquoi ça marche :</b> en développant <i>a</i>(<i>x</i> − <i>x</i>₁)(<i>x</i> − <i>x</i>₂), on trouve <b><i>x</i>₁ · <i>x</i>₂ = <i>c</i>/<i>a</i></b> et <b><i>x</i>₁ + <i>x</i>₂ = −<i>b</i>/<i>a</i></b>. Une racine connue donne l’autre sans Δ.',
  demo:{enonce:'Résoudre <i>x</i>² + 4<i>x</i> − 5 = 0 sans discriminant.',
   etapes:[
    {f:'1 + 4 − 5 = 0, donc <i>x</i>₁ = 1 est racine',w:'Pour <i>x</i> = 1, le trinôme vaut <i>a</i> + <i>b</i> + <i>c</i>.'},
    {f:'<i>x</i>₁ · <i>x</i>₂ = <i>c</i>/<i>a</i> = −5',w:'Le produit des racines se lit sur les coefficients.'},
    {f:'<i>x</i>₂ = −5/1 = −5',w:'On divise par la racine connue.'}],
   conclusion:'S = {−5 ; 1}, et <i>x</i>² + 4<i>x</i> − 5 = (<i>x</i> − 1)(<i>x</i> + 5).'}},
 {h:'Avec une racine évidente',p:'3<i>x</i>² − 7<i>x</i> + 4 = 0 a une racine évidente. Donne l’autre racine (fraction acceptée).',lab:'x =',ans:4/3,tol:1e-6,
  why:'3 − 7 + 4 = 0 : x = 1 est racine. Le produit des racines vaut c/a = 4/3, donc l’autre racine est 4/3.'},
 {kind:'Pratique',h:'Une racine double',p:'Règle <i>c</i> pour que <i>x² + 2x + c</i> ait une racine double.',
  params:[{id:'c',l:'c',min:-4,max:4,step:.5,v:-2}],
  draw:v=>{ const P=plane({x:[-6,6],y:[-6,6],lab:2}); P.fn(x=>x*x+2*x+v.c); return P.svg(); },
  info:v=>`Δ = 4 − 4·${fmt(v.c)} = ${fmt(4-4*v.c)}`,
  ok:v=>v.c===1,why:'Δ = 2² − 4·1·c = 4 − 4c = 0 donne c = 1. Alors x² + 2x + 1 = (x + 1)² : la parabole touche l’axe en −1.'},
 {kind:'Théorie',h:'Signe et factorisation',p:'<p>Pour résoudre <i>ax</i>² + <i>bx</i> + <i>c</i> ≥ 0, on pourrait dresser un tableau de signes à deux lignes. Mais le résultat est toujours le même, et il se retient en une phrase.</p><div class="prop"><p>Si Δ &gt; 0, avec les racines <i>x</i>₁ &lt; <i>x</i>₂ : <b><i>ax</i>² + <i>bx</i> + <i>c</i> = <i>a</i>(<i>x</i> − <i>x</i>₁)(<i>x</i> − <i>x</i>₂)</b>, et le trinôme a <b>le signe de <i>a</i> à l’extérieur des racines</b>, le signe opposé entre elles. Si Δ = 0, il vaut <i>a</i>(<i>x</i> − <i>x</i>₀)² : signe de <i>a</i> partout, nul en <i>x</i>₀. Si Δ &lt; 0, il garde <b>partout le signe de <i>a</i></b> et ne s’annule jamais.</p></div><div class="why"><p>La factorisation vient de la forme <i>a</i>(<i>x</i> + <i>b</i>/(2<i>a</i>))² − Δ/(4<i>a</i>) : c’est <i>a</i> fois une différence de deux carrés, qui se factorise en (<i>x</i> − <i>x</i>₁)(<i>x</i> − <i>x</i>₂). Entre les racines, <i>x</i> − <i>x</i>₁ &gt; 0 et <i>x</i> − <i>x</i>₂ &lt; 0 : le produit est négatif, et <i>a</i> le multiplie. À l’extérieur, les deux facteurs ont le même signe et leur produit est positif. Si Δ &lt; 0, un carré moins un nombre négatif est strictement positif, et <i>a</i> impose son signe.</p></div><div class="ex"><p>−<i>x</i>² + <i>x</i> + 6 : Δ = 1 + 24 = 25, racines (−1 ± 5)/(−2), soit −2 et 3. Comme <i>a</i> = −1 &lt; 0, le trinôme est négatif pour <i>x</i> &lt; −2 et pour <i>x</i> &gt; 3, positif sur ]−2 ; 3[. Contrôle en <i>x</i> = 0 : 6 &gt; 0 ✓. Factorisation : −(<i>x</i> + 2)(<i>x</i> − 3).</p></div><div class="warn"><p>N’oublie pas le facteur <i>a</i> devant la factorisation : 2<i>x</i>² − 2<i>x</i> − 12 = 2(<i>x</i> − 3)(<i>x</i> + 2), et pas (<i>x</i> − 3)(<i>x</i> + 2). Développe pour vérifier le coefficient de <i>x</i>².</p></div>',
  fig:tab([['<i>x</i>','−∞','','<i>x</i>₁','','<i>x</i>₂','','+∞'],['<i>ax² + bx + c</i>','','signe de <i>a</i>','0','signe de −<i>a</i>','0','signe de <i>a</i>','']])},
 {kind:'Méthode',h:'Inéquation du second degré',p:'<b>Quand :</b> on compare un trinôme à 0, comme −<i>x</i>² + <i>x</i> + 6 ≥ 0. <b>Pourquoi ça marche :</b> la factorisation <i>a</i>(<i>x</i> − <i>x</i>₁)(<i>x</i> − <i>x</i>₂) montre que le signe ne change qu’aux racines ; entre elles, les deux facteurs sont de signes opposés. <b>Comment :</b> mets tout du même côté, calcule Δ et les racines, puis applique « signe de <i>a</i> à l’extérieur des racines ».',
  demo:{enonce:'Résoudre −<i>x</i>² + <i>x</i> + 6 ≥ 0.',
   etapes:[
    {f:'<i>a</i> = −1, <i>b</i> = 1, <i>c</i> = 6 ; Δ = 1 + 24 = 25',w:'On commence par les racines, qui sont les frontières des zones de signe.'},
    {f:'<i>x</i> = (−1 ± 5)/(−2) : <i>x</i>₁ = −2 et <i>x</i>₂ = 3',w:'Attention : 2<i>a</i> = −2.'},
    {f:'<i>a</i> = −1 &lt; 0 : le trinôme est négatif à l’extérieur de [−2 ; 3], positif entre −2 et 3',w:'Règle du signe de <i>a</i>. La parabole est tournée vers le bas.'},
    {f:'Il vaut 0 en −2 et en 3, qui sont donc solutions',w:'L’inégalité est large.'}],
   conclusion:'S = [−2 ; 3].'}},
 {h:'À toi',p:'Résous 2<i>x</i>² − 3<i>x</i> − 2 &gt; 0.',opts:[']−1/2 ; 2[',']−∞ ; −1/2[ ∪ ]2 ; +∞[',']−∞ ; −2[ ∪ ]1/2 ; +∞[','[−1/2 ; 2]'],ans:1,
  why:'Δ = 9 + 16 = 25, racines (3 ± 5)/4, soit 2 et −1/2. Comme a = 2 &gt; 0, le trinôme est positif à l’extérieur des racines, qui sont exclues (inégalité stricte).'},
 {h:'Factorise',p:'Quelle est la factorisation de 2<i>x</i>² − 2<i>x</i> − 12&nbsp;?',opts:['(2x − 6)(x − 2)','2(x + 3)(x − 2)','2(x − 6)(x + 1)','2(x − 3)(x + 2)'],ans:3,
  why:'2x² − 2x − 12 = 2(x² − x − 6). Δ = 1 + 24 = 25, racines (1 ± 5)/2, soit 3 et −2. Donc 2(x − 3)(x + 2).'},
 {kind:'Méthode',h:'Changement de variable : se ramener à un trinôme',p:'<b>Quand :</b> l’inconnue n’apparaît qu’à travers une même quantité <i>t</i> et son carré, comme <i>x</i>⁴ et <i>x</i>², ou |<i>x</i>| et <i>x</i>² = |<i>x</i>|². <b>Pourquoi ça marche :</b> en posant <i>t</i> = cette quantité, l’équation devient un trinôme en <i>t</i>, qu’on sait résoudre. <b>Comment :</b> pose <i>t</i>, note sa contrainte (<i>t</i> ≥ 0 pour un carré ou une valeur absolue), résous en <i>t</i>, garde les valeurs permises, puis reviens à <i>x</i>.',
  demo:{enonce:'Résoudre <i>x</i>⁴ − 5<i>x</i>² + 4 = 0.',
   etapes:[
    {f:'On pose <i>t</i> = <i>x</i>², avec <i>t</i> ≥ 0 : <i>t</i>² − 5<i>t</i> + 4 = 0',w:'<i>x</i>⁴ = (<i>x</i>²)² = <i>t</i>².'},
    {f:'1 − 5 + 4 = 0, donc <i>t</i> = 1, et le produit des racines vaut 4 : <i>t</i> = 4',w:'Racine évidente, puis produit des racines.'},
    {f:'Les deux valeurs sont ≥ 0, on les garde',w:'Une valeur négative de <i>t</i> serait rejetée : un carré ne peut pas être négatif.'},
    {f:'<i>x</i>² = 1 ⇔ <i>x</i> = ±1 ; <i>x</i>² = 4 ⇔ <i>x</i> = ±2',w:'On revient à l’inconnue de départ.'}],
   conclusion:'S = {−2 ; −1 ; 1 ; 2}.'}},
 {kind:'Défi',h:'Les deux à la fois',p:'Résous <i>x</i>² − 2|<i>x</i>| − 3 &lt; 0. L’ensemble des solutions est un intervalle : quelle est sa longueur&nbsp;?',ans:6,
  why:'Avec t = |x| ≥ 0 (et x² = t²) : t² − 2t − 3 = (t − 3)(t + 1) &lt; 0 ⇔ −1 &lt; t &lt; 3. Donc |x| &lt; 3, S = ]−3 ; 3[, de longueur 6.'},
 {kind:'Méthode',h:'La forme canonique',p:'<b>Quand :</b> on cherche le minimum ou le maximum d’un trinôme, ou on veut l’écrire avec un seul <i>x</i>. <b>Pourquoi ça marche :</b> (<i>x</i> + <i>p</i>)² = <i>x</i>² + 2<i>px</i> + <i>p</i>² : le début <i>x</i>² + 2<i>px</i> est un carré « presque complet », il ne manque que <i>p</i>². <b>Comment :</b> pour <i>x</i>² + <i>bx</i> + <i>c</i>, écris <b><i>x</i>² + <i>bx</i> = (<i>x</i> + <i>b</i>/2)² − (<i>b</i>/2)²</b>, puis regroupe les constantes. Un carré étant ≥ 0, on lit l’extremum.',
  demo:{enonce:'Écrire <i>x</i>² − 6<i>x</i> + 11 sous forme canonique et trouver son minimum.',
   etapes:[
    {f:'<i>x</i>² − 6<i>x</i> = (<i>x</i> − 3)² − 9',w:'La moitié de −6 est −3, et (<i>x</i> − 3)² = <i>x</i>² − 6<i>x</i> + 9 : on retire le 9 en trop.'},
    {f:'<i>x</i>² − 6<i>x</i> + 11 = (<i>x</i> − 3)² − 9 + 11 = (<i>x</i> − 3)² + 2',w:'On regroupe les constantes.'},
    {f:'(<i>x</i> − 3)² ≥ 0, donc <i>x</i>² − 6<i>x</i> + 11 ≥ 2, avec égalité pour <i>x</i> = 3',w:'Un carré est toujours positif et ne s’annule qu’en un point.'}],
   conclusion:'Le minimum vaut 2, atteint en <i>x</i> = 3 : c’est le sommet (3 ; 2) de la parabole.'},
  note:'Si <i>a</i> ≠ 1, mets d’abord <i>a</i> en facteur : 2<i>x</i>² + 8<i>x</i> + 1 = 2(<i>x</i>² + 4<i>x</i>) + 1 = 2(<i>x</i> + 2)² − 7.'},
 {h:'À toi',p:'Quel est le minimum de <i>x</i>² + 4<i>x</i> + 9 sur ℝ&nbsp;?',lab:'min =',ans:5,
  why:'x² + 4x = (x + 2)² − 4, donc x² + 4x + 9 = (x + 2)² + 5 ≥ 5, avec égalité en x = −2.'},
 {kind:'Récapitulatif',h:'Ce qu’il faut retenir : valeur absolue et trinôme',p:'<div class="keep"><ul><li><b>|<i>x</i>|</b> = <i>x</i> si <i>x</i> ≥ 0, −<i>x</i> sinon ; <b>|<i>a</i> − <i>b</i>|</b> est la distance entre <i>a</i> et <i>b</i>. |<i>ab</i>| = |<i>a</i>||<i>b</i>|, √(<i>a</i>²) = |<i>a</i>|, mais seulement |<i>a</i> + <i>b</i>| ≤ |<i>a</i>| + |<i>b</i>|.</li><li><b>|A| = <i>k</i></b> (<i>k</i> &gt; 0) ⇔ A = <i>k</i> ou A = −<i>k</i> ; aucune solution si <i>k</i> &lt; 0.</li><li><b>|<i>x</i> − <i>a</i>| ≤ <i>r</i></b> ⇔ <i>a</i> − <i>r</i> ≤ <i>x</i> ≤ <i>a</i> + <i>r</i> (intervalle centré en <i>a</i>) ; <b>|<i>x</i> − <i>a</i>| ≥ <i>r</i></b> ⇔ <i>x</i> ≤ <i>a</i> − <i>r</i> ou <i>x</i> ≥ <i>a</i> + <i>r</i>.</li><li><b>Δ = <i>b</i>² − 4<i>ac</i></b> : deux racines (−<i>b</i> ± √Δ)/(2<i>a</i>) si Δ &gt; 0, racine double −<i>b</i>/(2<i>a</i>) si Δ = 0, aucune si Δ &lt; 0. Tout vient de <i>ax</i>² + <i>bx</i> + <i>c</i> = <i>a</i>(<i>x</i> + <i>b</i>/(2<i>a</i>))² − Δ/(4<i>a</i>).</li><li><b>Somme et produit</b> : <i>x</i>₁ + <i>x</i>₂ = −<i>b</i>/<i>a</i>, <i>x</i>₁<i>x</i>₂ = <i>c</i>/<i>a</i>. Racine évidente 1 si <i>a</i> + <i>b</i> + <i>c</i> = 0, −1 si <i>a</i> − <i>b</i> + <i>c</i> = 0.</li><li><b>Signe</b> : signe de <i>a</i> à l’extérieur des racines, opposé entre elles ; signe de <i>a</i> partout si Δ &lt; 0. Factorisation <i>a</i>(<i>x</i> − <i>x</i>₁)(<i>x</i> − <i>x</i>₂).</li><li><b>Forme canonique</b> : <i>x</i>² + <i>bx</i> = (<i>x</i> + <i>b</i>/2)² − (<i>b</i>/2)² ; elle donne le sommet et l’extremum.</li><li><b>Changement de variable</b> <i>t</i> = <i>x</i>² ou <i>t</i> = |<i>x</i>| (avec <i>t</i> ≥ 0) pour se ramener à un trinôme.</li></ul></div>'},
 {kind:'Problème',h:'Une tolérance de fabrication',
  p:'Une tige d’acier doit mesurer 50 mm, avec une tolérance de 0,2 mm : elle est acceptée si |<i>L</i> − 50| ≤ 0,2. Sa longueur dépend de la température <i>T</i> de l’atelier (en °C) : <i>L</i>(<i>T</i>) = 49,9 + 0,004 <i>T</i>. On cherche les températures pour lesquelles la tige est acceptée.',
  parts:[
   {q:'a) Quelle est la plus petite longueur acceptée&nbsp;?',lab:'L =',unit:'mm',ans:49.8,tol:1e-6,hint:'|<i>L</i> − 50| ≤ 0,2 veut dire que <i>L</i> est à au plus 0,2 de 50.',why:'|L − 50| ≤ 0,2 ⇔ 49,8 ≤ L ≤ 50,2. La plus petite longueur acceptée est 49,8 mm.'},
   {q:'b) La condition s’écrit |0,004 <i>T</i> − <i>c</i>| ≤ 0,2. Que vaut <i>c</i>&nbsp;?',lab:'c =',ans:.1,tol:1e-9,hint:'Remplace <i>L</i> par 49,9 + 0,004 <i>T</i> dans <i>L</i> − 50.',why:'L − 50 = 49,9 + 0,004T − 50 = 0,004T − 0,1. Donc c = 0,1.'},
   {q:'c) Quelle est la température maximale admise&nbsp;?',lab:'T =',unit:'°C',ans:75,hint:'Écris −0,2 ≤ 0,004 <i>T</i> − 0,1 ≤ 0,2 et isole <i>T</i>.',why:'0,004T − 0,1 ≤ 0,2 ⇔ 0,004T ≤ 0,3 ⇔ T ≤ 75 °C.'},
   {q:'d) Et la température minimale&nbsp;?',lab:'T =',unit:'°C',ans:-25,hint:'Utilise l’autre moitié de l’encadrement.',why:'−0,2 ≤ 0,004T − 0,1 ⇔ −0,1 ≤ 0,004T ⇔ T ≥ −25 °C.'},
  ],
  sol:'La tige est acceptée si |L − 50| ≤ 0,2, c’est-à-dire 49,8 ≤ L ≤ 50,2.<br>Avec L = 49,9 + 0,004T, on a L − 50 = 0,004T − 0,1, d’où |0,004T − 0,1| ≤ 0,2.<br>Penser distance : −0,2 ≤ 0,004T − 0,1 ≤ 0,2, soit −0,1 ≤ 0,004T ≤ 0,3.<br>On divise par 0,004 &gt; 0, le sens ne change pas : −25 ≤ T ≤ 75.<br>La tige est acceptée pour T ∈ [−25 ; 75] °C.'},
 {kind:'Problème',h:'Le jardin clôturé',
  p:'Avec 40 m de clôture, tu entoures un jardin rectangulaire. On note <i>x</i> sa largeur en m, avec 0 &lt; <i>x</i> &lt; 20 : la longueur vaut alors 20 − <i>x</i> et l’aire A(<i>x</i>) = <i>x</i>(20 − <i>x</i>). Tu veux savoir quelles largeurs donnent une aire suffisante.',
  parts:[
   {q:'a) A(<i>x</i>) ≥ 96 équivaut à <i>x</i>² − 20<i>x</i> + 96 ≤ 0. Que vaut le discriminant de ce trinôme&nbsp;?',lab:'Δ =',ans:16,hint:'Δ = b² − 4ac avec a = 1, b = −20, c = 96.',why:'Δ = 400 − 384 = 16. Les racines sont (20 ± 4)/2, soit 8 et 12.'},
   {q:'b) Quelles largeurs donnent une aire d’au moins 96 m²&nbsp;?',opts:[']−∞ ; 8] ∪ [12 ; +∞[',']8 ; 12[','[8 ; 12]','[6 ; 14]'],ans:2,hint:'Le trinôme a le signe de a = 1 à l’extérieur des racines.',why:'x² − 20x + 96 = (x − 8)(x − 12) ≤ 0 entre les racines, bornes comprises : x ∈ [8 ; 12].'},
   {q:'c) On vérifie que A(<i>x</i>) = 100 − (<i>x</i> − 10)². Une aire d’au moins 91 m² s’écrit alors |<i>x</i> − 10| ≤ <i>r</i>. Que vaut <i>r</i>&nbsp;?',lab:'r =',unit:'m',ans:3,hint:'100 − (<i>x</i> − 10)² ≥ 91 ⇔ (<i>x</i> − 10)² ≤ 9. Et √(<i>u</i>²) = |<i>u</i>|.',why:'(x − 10)² ≤ 9 ⇔ |x − 10| ≤ 3, soit x ∈ [7 ; 13].'},
   {q:'d) Quelle est la plus grande aire possible&nbsp;?',lab:'A =',unit:'m²',ans:100,hint:'Un carré n’est jamais négatif.',why:'(x − 10)² ≥ 0 donne A(x) ≤ 100, avec égalité pour x = 10 : le carré de 10 m de côté.'},
  ],
  sol:'A(x) = x(20 − x) = 20x − x² = 100 − (x − 10)².<br>A(x) ≥ 96 ⇔ x² − 20x + 96 ≤ 0. Δ = 16, racines 8 et 12, donc (x − 8)(x − 12) ≤ 0 ⇔ x ∈ [8 ; 12].<br>Même résultat avec la forme canonique : (x − 10)² ≤ 4 ⇔ |x − 10| ≤ 2.<br>De même, A(x) ≥ 91 ⇔ |x − 10| ≤ 3, soit x ∈ [7 ; 13].<br>Enfin A(x) ≤ 100 pour tout x, avec égalité seulement en x = 10 : à périmètre fixé, le carré a la plus grande aire.'},
]},

{subj:'an1', sem:'aut', id:'an1-suites', h:'Suites et limites', p:'Suites bornées et monotones, la définition ε–N de la limite, les limites infinies et les formes indéterminées.', steps:[
 {kind:'Théorie',h:'Une suite, une liste infinie',p:'<p>Un capital qui grossit chaque année, la hauteur d’une balle à chaque rebond, les décimales successives de π : on rencontre partout des listes infinies de nombres, numérotées 0, 1, 2, … L’analyse les appelle des suites.</p><div class="def"><p>Une <b>suite</b> (<i>uₙ</i>) associe à chaque entier naturel <i>n</i> un réel <i>uₙ</i>, son <b>terme de rang <i>n</i></b> (lire « u indice n »). Elle est <b>majorée</b> s’il existe <i>M</i> avec <i>uₙ</i> ≤ <i>M</i> pour tout <i>n</i>, <b>minorée</b> s’il existe <i>m</i> avec <i>uₙ</i> ≥ <i>m</i>, <b>bornée</b> si elle est les deux, ce qui revient à |<i>uₙ</i>| ≤ <i>M</i>. Elle est <b>croissante</b> si <i>uₙ₊₁</i> ≥ <i>uₙ</i> pour tout <i>n</i>, <b>décroissante</b> si <i>uₙ₊₁</i> ≤ <i>uₙ</i>, <b>monotone</b> si elle est l’un ou l’autre.</p></div><div class="idea"><p>Une suite se donne soit par une formule explicite (<i>uₙ</i> = 1/<i>n</i>), soit par récurrence (<i>u</i>₀ = 1 et <i>uₙ₊₁</i> = 0,5<i>uₙ</i> + 2 : chaque terme se calcule à partir du précédent). Sur le graphique, on place les points (<i>n</i> ; <i>uₙ</i>) : bornée veut dire que tous les points tiennent dans une bande horizontale ; croissante, que chaque point est au moins aussi haut que le précédent.</p></div><div class="ex"><p><i>uₙ</i> = (2<i>n</i> + 1)/(<i>n</i> + 1) : <i>u</i>₀ = 1, <i>u</i>₁ = 1,5, <i>u</i>₂ ≈ 1,667, <i>u</i>₁₀ ≈ 1,909. Elle est croissante, et majorée par 2 car 2<i>n</i> + 1 &lt; 2(<i>n</i> + 1). Parcours les quatre suites de la figure : bornée ou pas, monotone ou pas, et vers quoi elle semble aller.</p></div><div class="warn"><p>« Bornée » ne veut pas dire « monotone » : (−1)ⁿ oscille entre −1 et 1 sans jamais se calmer. Et « croissante » ne veut pas dire « non bornée » : (2<i>n</i> + 1)/(<i>n</i> + 1) monte sans jamais dépasser 2.</p></div>',
  params:[{id:'k',l:'Suite',min:0,max:3,v:0}],
  draw:v=>{ const u=[n=>1/n,n=>(-1)**n,n=>Math.sqrt(n),n=>(2*n+1)/(n+1)][v.k], P=plane({x:[-1,21],y:[-1.6,5],h:220,grid:false,lx:5,ly:1});
    for(let n=1;n<=20;n++) P.dot(n,u(n),{r:4,c:'var(--accent)'}); return P.svg(); },
  info:v=>['<i>uₙ</i> = 1/<i>n</i> : décroissante, bornée, tend vers 0.','<i>uₙ</i> = (−1)ⁿ : bornée, pas monotone, n’a pas de limite.','<i>uₙ</i> = √<i>n</i> : croissante, non bornée, tend vers +∞.','<i>uₙ</i> = (2<i>n</i> + 1)/(<i>n</i> + 1) : croissante, bornée par 2, tend vers 2.'][v.k]},
 {h:'Classe la suite',p:'La suite <i>uₙ</i> = (−1)ⁿ/<i>n</i> (pour <i>n</i> ≥ 1) est…',opts:['croissante et bornée','monotone et non bornée','bornée et non monotone','ni bornée, ni convergente'],ans:2,
  why:'|uₙ| = 1/n ≤ 1, donc elle est bornée. Ses termes changent de signe (−1, 1/2, −1/3, …) : elle n’est pas monotone. Elle tend tout de même vers 0.'},
 {kind:'Méthode',h:'Étudier le sens de variation d’une suite',p:'<b>Quand :</b> on demande si (<i>uₙ</i>) est croissante ou décroissante. <b>Pourquoi ça marche :</b> croissante veut dire <i>uₙ₊₁</i> ≥ <i>uₙ</i>, c’est-à-dire <i>uₙ₊₁</i> − <i>uₙ</i> ≥ 0 : tout se ramène à un signe. <b>Comment :</b> calcule <b><i>uₙ₊₁</i> − <i>uₙ</i></b>, réduis au même dénominateur, et étudie son signe pour <i>n</i> ≥ 0. Si tous les termes sont positifs, on peut aussi comparer le quotient <i>uₙ₊₁</i>/<i>uₙ</i> à 1.',
  demo:{enonce:`Étudier le sens de variation de <i>uₙ</i> = ${F('<i>n</i>','<i>n</i> + 1')}.`,
   etapes:[
    {f:`<i>uₙ₊₁</i> = ${F('<i>n</i> + 1','<i>n</i> + 2')}`,w:'On remplace <i>n</i> par <i>n</i> + 1 partout.'},
    {f:`<i>uₙ₊₁</i> − <i>uₙ</i> = ${F('(<i>n</i> + 1)² − <i>n</i>(<i>n</i> + 2)','(<i>n</i> + 1)(<i>n</i> + 2)')}`,w:'Même dénominateur pour soustraire les deux fractions.'},
    {f:`= ${F('<i>n</i>² + 2<i>n</i> + 1 − <i>n</i>² − 2<i>n</i>','(<i>n</i> + 1)(<i>n</i> + 2)')} = ${F('1','(<i>n</i> + 1)(<i>n</i> + 2)')}`,w:'On développe : presque tout se simplifie.'},
    {f:'Numérateur et dénominateur sont positifs, donc <i>uₙ₊₁</i> − <i>uₙ</i> &gt; 0',w:'Le signe se lit directement pour <i>n</i> ≥ 0.'}],
   conclusion:'(<i>uₙ</i>) est strictement croissante.'}},
 {h:'Croissante ou décroissante&nbsp;?',p:`Pour <i>uₙ</i> = ${F('<i>n</i> + 3','<i>n</i> + 1')}, que vaut le signe de <i>uₙ₊₁</i> − <i>uₙ</i>, et qu’en conclut-on&nbsp;?`,opts:['Positif : la suite est croissante','Négatif : la suite est décroissante','Il change de signe : la suite n’est pas monotone','Nul : la suite est constante'],ans:1,
  why:'uₙ₊₁ − uₙ = (n + 4)/(n + 2) − (n + 3)/(n + 1) = ((n + 4)(n + 1) − (n + 3)(n + 2))/((n + 1)(n + 2)) = −2/((n + 1)(n + 2)) &lt; 0. La suite est décroissante.'},
 {kind:'Théorie',h:'L’idée de limite : se rapprocher d’une valeur',p:'<p>Les termes de <i>uₙ</i> = (2<i>n</i> + 1)/(<i>n</i> + 1) valent 1 ; 1,5 ; 1,667 ; 1,75 ; … Ils ne valent jamais 2, mais ils s’en approchent sans fin. Comment dire cela avec précision ? C’est la question centrale de toute l’analyse.</p><div class="def"><p>On dit que (<i>uₙ</i>) <b>converge</b> vers le réel <i>L</i>, ou <b>tend vers <i>L</i></b>, noté <b><i>uₙ</i> → <i>L</i></b> ou lim <i>uₙ</i> = <i>L</i>, si l’écart |<i>uₙ</i> − <i>L</i>| devient aussi petit qu’on veut et le reste, pourvu que <i>n</i> soit assez grand. <i>L</i> est la <b>limite</b> de la suite. Une suite qui ne converge vers aucun réel <b>diverge</b>.</p></div><div class="idea"><p>Quelqu’un te lance un défi : « je veux tous les termes à moins de 0,01 de 2 ». Tu réponds : « à partir du rang 100, c’est garanti ». Il resserre : « à moins de 0,001 ». Tu réponds : « à partir du rang 1000 ». Converger, c’est pouvoir gagner ce jeu <b>quel que soit</b> l’écart demandé. Le rang à partir duquel ça marche dépend de l’écart exigé : plus il est petit, plus il faut attendre.</p></div><div class="ex"><p>Pour <i>uₙ</i> = (2<i>n</i> + 1)/(<i>n</i> + 1), l’écart vaut |<i>uₙ</i> − 2| = |(2<i>n</i> + 1 − 2<i>n</i> − 2)/(<i>n</i> + 1)| = 1/(<i>n</i> + 1). Pour qu’il soit inférieur à 0,01, il faut <i>n</i> + 1 &gt; 100, soit <i>n</i> ≥ 100. Quel que soit l’écart demandé, un rang suffit : <i>uₙ</i> → 2.</p></div><div class="warn"><p>Une suite peut converger vers <i>L</i> sans jamais valoir <i>L</i> (c’est le cas ici). Et une suite qui « se rapproche » sans se stabiliser ne converge pas : (−1)ⁿ vaut 1 une fois sur deux, mais son écart à 1 revaut 2 une fois sur deux. Une suite a <b>au plus une</b> limite.</p></div>',
  fig:(()=>{ const P=plane({x:[-.5,21],y:[.8,2.3],h:200,grid:false,lx:5,ly:.5}); P.seg(0,2,21,2,{c:'var(--ok)',w:1.5,dash:true}).text(20,2,'L = 2',{a:'end',dy:-6,c:'var(--ok)'});
    for(let n=0;n<=20;n++) P.dot(n,(2*n+1)/(n+1),{r:4,c:'var(--accent)'}); P.seg(10,2,10,21/11,{c:'var(--bad)',w:2}).text(10,1.95,'|uₙ − L|',{dx:6,dy:4,c:'var(--bad)'}); return P.svg(); })()},
 {kind:'Théorie',h:'La définition ε–N',p:'<p>« Aussi petit qu’on veut » et « assez grand » sont des mots. Pour démontrer des théorèmes, il faut une définition où tout est un nombre : l’écart toléré s’appelle ε (epsilon), le rang à partir duquel ça marche s’appelle <i>N</i>.</p><div class="def"><p><b><i>uₙ</i> → <i>L</i></b> signifie : <b>pour tout ε &gt; 0, il existe un rang <i>N</i> tel que <i>n</i> ≥ <i>N</i> ⇒ |<i>uₙ</i> − <i>L</i>| &lt; ε</b>. En mots : quelle que soit la largeur ε de la bande autour de <i>L</i>, tous les termes à partir d’un certain rang sont dans la bande.</p></div><div class="idea"><p>La figure montre la bande ]<i>L</i> − ε ; <i>L</i> + ε[ en vert et le rang <i>N</i> par un trait vertical. Les termes avant <i>N</i> sont grisés : la définition ne s’occupe pas d’eux, ils ont le droit d’être loin. Les termes après <i>N</i> doivent tous être dans la bande ; s’il en reste un en rouge, ce <i>N</i> est trop petit. L’ordre des mots compte : on fixe ε d’abord, puis on cherche <i>N</i>, qui a le droit de dépendre de ε.</p></div><div class="ex"><p>Ici <i>uₙ</i> = (2<i>n</i> + 1)/(<i>n</i> + 1), <i>L</i> = 2 et |<i>uₙ</i> − 2| = 1/(<i>n</i> + 1). Avec ε = 0,2 : 1/(<i>n</i> + 1) &lt; 0,2 ⇔ <i>n</i> + 1 &gt; 5 ⇔ <i>n</i> ≥ 5. Le rang <i>N</i> = 5 convient (et tout rang plus grand aussi). Avec ε = 0,05, il faut <i>N</i> = 20. Fais glisser ε vers 0 : le <i>N</i> nécessaire grandit.</p></div><div class="warn"><p>Il ne suffit pas qu’un terme entre dans la bande : il faut que <b>tous</b> les suivants y restent. Et <i>N</i> n’est pas unique : si 5 convient, 6, 7 et 100 conviennent aussi. On demande parfois le plus petit, mais la définition n’exige que l’existence d’un rang.</p></div>',
  params:[{id:'e',l:'ε',min:.05,max:.5,step:.05,v:.2},{id:'N',l:'N',min:1,max:30,v:2}],
  draw:v=>{ const P=plane({x:[-.5,31],y:[1.3,2.6],h:220,grid:false,lx:5});
    P.rect(0,2-v.e,31,2*v.e,{fill:'var(--ok)',fo:.15,c:null}).seg(0,2,31,2,{c:'var(--ok)',w:1.5,dash:true}).seg(v.N,1.3,v.N,2.6,{c:'var(--muted)',w:1.5});
    for(let n=1;n<=30;n++){ const u=(2*n+1)/(n+1); P.dot(n,u,{r:3.5,c:n<v.N?'var(--muted)':Math.abs(u-2)<v.e-1e-12?'var(--accent)':'var(--bad)'}); }
    P.text(v.N,2.6,'N',{dx:4,dy:14}); return P.svg(); },
  info:v=>{ const ok=1/(v.N+1)<v.e-1e-12; return `|<i>uₙ</i> − 2| = 1/(<i>n</i> + 1). ${ok?'Tous les termes à partir du rang N sont dans la bande.':'Certains termes après N sortent encore de la bande.'}`; }},
 {kind:'Méthode',h:'Trouver le rang N pour un ε donné',p:'<b>Quand :</b> on demande à partir de quel rang <i>uₙ</i> est à moins de ε de sa limite <i>L</i>. <b>Pourquoi ça marche :</b> la définition demande |<i>uₙ</i> − <i>L</i>| &lt; ε ; si cette distance diminue avec <i>n</i>, le premier rang qui convient convient aussi pour tous les suivants. <b>Comment :</b> calcule et simplifie |<i>uₙ</i> − <i>L</i>|, résous l’inéquation en <i>n</i>, puis prends le plus petit entier qui la vérifie.',
  demo:{enonce:`Pour <i>uₙ</i> = ${F('3<i>n</i> − 1','<i>n</i>')} et <i>L</i> = 3, trouver le plus petit <i>N</i> tel que |<i>uₙ</i> − 3| &lt; 0,01 pour tout <i>n</i> ≥ <i>N</i>.`,
   etapes:[
    {f:`<i>uₙ</i> − 3 = ${F('3<i>n</i> − 1 − 3<i>n</i>','<i>n</i>')} = −${F('1','<i>n</i>')}, donc |<i>uₙ</i> − 3| = 1/<i>n</i>`,w:'On réduit au même dénominateur pour voir l’écart à la limite.'},
    {f:'1/<i>n</i> &lt; 0,01 ⇔ <i>n</i> &gt; 100',w:'On inverse les deux membres positifs, ce qui renverse le sens.'},
    {f:'Pour <i>n</i> = 100, l’écart vaut exactement 0,01 : pas assez',w:'L’inégalité est stricte, on vérifie le cas limite.'},
    {f:'1/<i>n</i> décroît, donc tout <i>n</i> ≥ 101 convient',w:'C’est ce qui permet de prendre le premier rang qui marche.'}],
   conclusion:'<i>N</i> = 101.'}},
 {kind:'Pratique',h:'Trouve le rang',p:'Avec ε = 0,1 : trouve le <b>plus petit</b> <i>N</i> tel que |<i>uₙ</i> − 2| &lt; 0,1 pour tout <i>n</i> ≥ <i>N</i>.',
  params:[{id:'N',l:'N',min:1,max:30,v:3}],
  draw:v=>{ const P=plane({x:[-.5,31],y:[1.3,2.6],h:220,grid:false,lx:5});
    P.rect(0,1.9,31,.2,{fill:'var(--ok)',fo:.15,c:null}).seg(0,2,31,2,{c:'var(--ok)',w:1.5,dash:true}).seg(v.N,1.3,v.N,2.6,{c:'var(--muted)',w:1.5});
    for(let n=1;n<=30;n++){ const u=(2*n+1)/(n+1); P.dot(n,u,{r:3.5,c:n<v.N?'var(--muted)':Math.abs(u-2)<.1-1e-12?'var(--accent)':'var(--bad)'}); } return P.svg(); },
  info:v=>`Pour n = N = ${v.N} : |u − 2| = 1/${v.N+1} ≈ ${fmt(1/(v.N+1),3)}`,
  ok:v=>v.N===10,why:'1/(n + 1) &lt; 0,1 ⇔ n + 1 &gt; 10 ⇔ n &gt; 9. Le premier rang qui marche est N = 10 (pour n = 9 on a exactement 0,1, pas strictement moins).'},
 {kind:'Théorie',h:'Le théorème de la limite monotone',p:'<p>Souvent on ne connaît pas la limite d’une suite, par exemple quand elle est définie par récurrence. Comment prouver qu’elle converge sans savoir vers quoi ? Un théorème le permet dans un cas très fréquent.</p><div class="thm"><p><b>Toute suite croissante et majorée converge.</b> De même, toute suite décroissante et minorée converge. La limite est alors le plus petit des majorants (respectivement le plus grand des minorants).</p></div><div class="why"><p>Idée de la preuve : les termes montent sans jamais dépasser <i>M</i>. Ils ne peuvent pas monter indéfiniment, puisqu’ils sont bloqués ; ils ne peuvent pas redescendre, puisque la suite est croissante. Ils s’entassent donc sous une valeur <i>L</i>, la plus petite qui les domine tous, et s’en rapprochent autant qu’on veut : c’est la convergence. La preuve complète utilise une propriété profonde de ℝ, l’existence de cette borne supérieure, qui est fausse dans ℚ.</p></div><div class="ex"><p><i>uₙ</i> = (2<i>n</i> + 1)/(<i>n</i> + 1) est croissante (on l’a montré avec <i>uₙ₊₁</i> − <i>uₙ</i> &gt; 0) et majorée par 2 : elle converge, avant même qu’on calcule sa limite. Autre exemple : la suite de Héron <i>u</i>₀ = 2, <i>uₙ₊₁</i> = (<i>uₙ</i> + 2/<i>uₙ</i>)/2 est décroissante et minorée par √2, donc elle converge ; on identifie ensuite sa limite en passant à la limite dans la relation.</p></div><div class="warn"><p>Les deux hypothèses sont nécessaires. <i>uₙ</i> = <i>n</i> est croissante mais pas majorée : elle tend vers +∞. <i>uₙ</i> = (−1)ⁿ est bornée mais pas monotone : elle ne converge pas. Attention aussi : la limite d’une suite croissante majorée par <i>M</i> est ≤ <i>M</i>, pas forcément égale à <i>M</i> : (2<i>n</i> + 1)/(<i>n</i> + 1) est aussi majorée par 10, et sa limite est 2.</p></div>'},
 {kind:'Théorie',h:'Limites infinies et règles de calcul',p:'<p>Les termes de <i>uₙ</i> = <i>n</i>² ne se rapprochent d’aucun réel : ils dépassent n’importe quel seuil. On dit qu’ils tendent vers l’infini. Il faut aussi savoir combiner des limites, finies ou non.</p><div class="def"><p><b><i>uₙ</i> → +∞</b> signifie : pour tout réel <i>A</i>, il existe un rang <i>N</i> tel que <i>n</i> ≥ <i>N</i> ⇒ <i>uₙ</i> &gt; <i>A</i>. Si grand que soit le seuil <i>A</i>, la suite finit par rester au-dessus. De même <i>uₙ</i> → −∞ si elle finit par rester sous tout seuil. Une suite qui tend vers ±∞ diverge : +∞ n’est pas un nombre.</p></div><div class="prop"><p>Si <i>uₙ</i> → <i>L</i> et <i>vₙ</i> → <i>L</i>′ (réels), alors <i>uₙ</i> + <i>vₙ</i> → <i>L</i> + <i>L</i>′, <i>uₙ</i><i>vₙ</i> → <i>LL</i>′ et <i>uₙ</i>/<i>vₙ</i> → <i>L</i>/<i>L</i>′ si <i>L</i>′ ≠ 0. Avec l’infini, les conventions naturelles s’appliquent : <i>L</i> + ∞ = ∞, <i>L</i> · ∞ = ±∞ si <i>L</i> ≠ 0 (signe par la règle des signes), ∞ · ∞ = ∞, <i>L</i>/∞ = 0, et <i>L</i>/0⁺ = +∞ si <i>L</i> &gt; 0.</p></div><div class="why"><p>Pour la somme : si <i>uₙ</i> est à moins de ε/2 de <i>L</i> et <i>vₙ</i> à moins de ε/2 de <i>L</i>′, leur somme est à moins de ε de <i>L</i> + <i>L</i>′. Pour <i>L</i>/∞ = 0 : un nombre fixé divisé par quelque chose d’énorme donne quelque chose de minuscule. Les autres règles se démontrent de la même façon, en revenant aux définitions.</p></div><div class="ex"><p><i>uₙ</i> = 3 + 1/<i>n</i> → 3 et <i>vₙ</i> = <i>n</i>² → +∞. Alors <i>uₙ</i> + <i>vₙ</i> → +∞ (3 + ∞), <i>uₙ</i><i>vₙ</i> → +∞ (3 · ∞) et <i>uₙ</i>/<i>vₙ</i> → 0 (3/∞). Vérifie avec <i>n</i> = 1000 : 3,001 + 10⁶, environ 3 · 10⁶, et 0,000003.</p></div>',
  note:'Les règles ne couvrent pas tout : ∞ − ∞, 0 · ∞, ∞/∞ et 0/0 demandent un traitement à part, c’est l’étape suivante.'},
 {kind:'Théorie',h:'Pourquoi quatre formes sont indéterminées',p:'<p>Que vaut « ∞ − ∞ » ? On aimerait répondre 0. Pourtant <i>n</i>² − <i>n</i> → +∞, <i>n</i> − <i>n</i> → 0 et <i>n</i> − <i>n</i>² → −∞ : trois différences de deux suites qui tendent vers +∞, trois résultats différents. Le symbole ne contient pas assez d’information pour décider.</p><div class="def"><p>Une <b>forme indéterminée</b> est une combinaison de limites dont le résultat n’est pas fixé d’avance : il dépend des suites précises, pas seulement de leurs limites. Il y en a quatre : <b>∞ − ∞</b>, <b>0 · ∞</b>, <b>∞/∞</b> et <b>0/0</b>.</p></div><div class="why"><p>Chaque forme est une course entre deux suites. Dans ∞/∞, tout dépend de celle qui grandit le plus vite : <i>n</i>²/<i>n</i> → ∞, <i>n</i>/<i>n</i>² → 0, 2<i>n</i>/<i>n</i> → 2. Dans 0 · ∞, l’un écrase vers 0 pendant que l’autre explose : (1/<i>n</i>) · <i>n</i> = 1, mais (1/<i>n</i>) · <i>n</i>² = <i>n</i> → ∞ et (1/<i>n</i>²) · <i>n</i> → 0. Les formes 0/0 et ∞/∞ se ramènent l’une à l’autre en inversant.</p></div><div class="idea"><p>« Indéterminée » ne veut pas dire « sans limite » : cela veut dire que la règle de calcul ne s’applique pas et qu’il faut <b>transformer l’expression</b> pour faire apparaître une forme décidable. Les méthodes qui suivent (terme dominant, conjugué, gendarmes) sont exactement ces transformations.</p></div><div class="ex"><p>√(<i>n</i>² + <i>n</i>) − <i>n</i> est une forme ∞ − ∞. Multipliée et divisée par √(<i>n</i>² + <i>n</i>) + <i>n</i>, elle devient <i>n</i>/(√(<i>n</i>² + <i>n</i>) + <i>n</i>), puis 1/(√(1 + 1/<i>n</i>) + 1) → 1/2. La limite existe bel et bien, mais seul le calcul pouvait la révéler.</p></div><div class="warn"><p>Ne confonds pas avec <i>L</i>/0 où <i>L</i> ≠ 0, qui n’est <b>pas</b> indéterminée : la limite est ±∞, il suffit de trouver le signe. Et <i>L</i>/∞ vaut toujours 0. Avant de chercher une astuce, vérifie que tu es vraiment dans l’un des quatre cas.</p></div>'},
 {h:'Reconnais la forme',p:'Laquelle de ces situations est une forme indéterminée&nbsp;?',opts:['uₙ → +∞ et vₙ → +∞, on cherche lim (uₙ + vₙ)','uₙ → 3 et vₙ → +∞, on cherche lim uₙ/vₙ','uₙ → 0 et vₙ → +∞, on cherche lim uₙ·vₙ','uₙ → +∞ et vₙ → +∞, on cherche lim uₙ·vₙ'],ans:2,
  why:'0 · ∞ est indéterminé : 1/n · n → 1 mais 1/n · n² → +∞. Les autres cas donnent +∞, 0 et +∞.'},
 {kind:'Méthode',h:'Mettre en facteur le terme dominant',p:'<b>Quand :</b> forme ∞/∞ ou ∞ − ∞ avec des polynômes en <i>n</i> (ou en <i>x</i> → ±∞). <b>Pourquoi ça marche :</b> en mettant en facteur la plus grande puissance, tous les autres termes deviennent des 1/<i>n</i>, 1/<i>n</i>², … qui tendent vers 0. <b>Comment :</b> en haut et en bas, factorise le terme de plus haut degré, simplifie, puis passe à la limite.',
  demo:{enonce:`Calculer lim ${F('2<i>n</i>³ − <i>n</i> + 4','5<i>n</i>³ + <i>n</i>²')} quand <i>n</i> → ∞.`,
   etapes:[
    {f:'Forme ∞/∞',w:'Numérateur et dénominateur tendent vers +∞ : on ne peut pas conclure directement.'},
    {f:`= ${F('<i>n</i>³(2 − 1/<i>n</i>² + 4/<i>n</i>³)','<i>n</i>³(5 + 1/<i>n</i>)')}`,w:'On factorise <i>n</i>³, la plus grande puissance, en haut et en bas.'},
    {f:`= ${F('2 − 1/<i>n</i>² + 4/<i>n</i>³','5 + 1/<i>n</i>')}`,w:'On simplifie par <i>n</i>³ ≠ 0.'},
    {f:'→ 2/5',w:'Chaque terme en 1/<i>n</i>ᵏ tend vers 0.'}],
   conclusion:'La limite vaut 2/5 : c’est le quotient des coefficients dominants.'},
  note:'Règle qui en découle : même degré en haut et en bas, la limite est le quotient des coefficients dominants ; degré du haut plus petit, la limite est 0 ; degré du haut plus grand, la limite est ±∞ (le signe se lit sur les coefficients dominants).'},
 {h:'Lever l’indétermination',p:`Calcule lim ${F('3<i>n</i>² − <i>n</i> + 1','2<i>n</i>² + 5')} quand <i>n</i> → ∞.`,lab:'L =',ans:1.5,tol:1e-9,
  why:'On factorise n² en haut et en bas : (3 − 1/n + 1/n²)/(2 + 5/n²) → 3/2 = 1,5.'},
 {h:'Degrés différents',p:`Que vaut lim ${F('4<i>n</i> − <i>n</i>³','2<i>n</i>² + 1')} quand <i>n</i> → ∞&nbsp;?`,opts:['0','−1/2','+∞','−∞'],ans:3,
  why:'On factorise : n³(4/n² − 1)/(n²(2 + 1/n²)) = n · (4/n² − 1)/(2 + 1/n²). Le quotient tend vers −1/2 et n → +∞ : la limite vaut −∞.'},
 {kind:'Méthode',h:'Multiplier par la quantité conjuguée',p:'<b>Quand :</b> une différence avec une racine carrée donne une forme indéterminée : ∞ − ∞ comme √(<i>n</i>² + <i>n</i>) − <i>n</i>, ou 0/0 comme (√(1 + <i>x</i>) − 1)/<i>x</i>. <b>Pourquoi ça marche :</b> <b>(<i>a</i> − <i>b</i>)(<i>a</i> + <i>b</i>) = <i>a</i>² − <i>b</i>²</b>. Le carré fait disparaître la racine, et la somme <i>a</i> + <i>b</i>, elle, n’est plus indéterminée. <b>Comment :</b> multiplie en haut et en bas par le conjugué <i>a</i> + <i>b</i>, développe le haut avec l’identité, puis mets en facteur le terme dominant.',
  demo:{enonce:'Calculer lim (√(<i>n</i>² + <i>n</i>) − <i>n</i>) quand <i>n</i> → ∞.',
   etapes:[
    {f:'Forme ∞ − ∞',w:'√(<i>n</i>² + <i>n</i>) et <i>n</i> tendent tous deux vers +∞.'},
    {f:`= ${F('(√(<i>n</i>² + <i>n</i>) − <i>n</i>)(√(<i>n</i>² + <i>n</i>) + <i>n</i>)','√(<i>n</i>² + <i>n</i>) + <i>n</i>')}`,w:'On multiplie et on divise par le conjugué : la valeur ne change pas.'},
    {f:`= ${F('<i>n</i>² + <i>n</i> − <i>n</i>²','√(<i>n</i>² + <i>n</i>) + <i>n</i>')} = ${F('<i>n</i>','√(<i>n</i>² + <i>n</i>) + <i>n</i>')}`,w:'En haut, (<i>a</i> − <i>b</i>)(<i>a</i> + <i>b</i>) = <i>a</i>² − <i>b</i>² : la racine a disparu.'},
    {f:`= ${F('<i>n</i>','<i>n</i>(√(1 + 1/<i>n</i>) + 1)')} = ${F('1','√(1 + 1/<i>n</i>) + 1')}`,w:'Sous la racine, on factorise <i>n</i>² : √(<i>n</i>²(1 + 1/<i>n</i>)) = <i>n</i>√(1 + 1/<i>n</i>) car <i>n</i> &gt; 0.'},
    {f:'→ 1/(1 + 1) = 1/2',w:'Il ne reste plus d’indétermination.'}],
   conclusion:'La limite vaut 1/2. On n’aurait rien pu conclure de « ∞ − ∞ » sans transformer l’expression.'}},
 {kind:'Défi',h:'Avec le conjugué',p:'Calcule lim (√(<i>n</i>² + 4<i>n</i>) − <i>n</i>) quand <i>n</i> → ∞.',lab:'L =',ans:2,
  why:'Forme ∞ − ∞. On multiplie par le conjugué : (n² + 4n − n²)/(√(n² + 4n) + n) = 4n/(n(√(1 + 4/n) + 1)) → 4/2 = 2.'},
 {kind:'Méthode',h:'Le théorème des gendarmes',p:'<b>Quand :</b> la suite contient un terme qui oscille sans limite, comme sin <i>n</i>, cos <i>n</i> ou (−1)ⁿ, mais qui reste borné. <b>Pourquoi ça marche :</b> si <b><i>aₙ</i> ≤ <i>uₙ</i> ≤ <i>bₙ</i></b> et si <i>aₙ</i> et <i>bₙ</i> tendent vers la même limite <i>L</i>, alors <i>uₙ</i>, coincée entre les deux, tend aussi vers <i>L</i>. <b>Comment :</b> encadre le terme gênant (−1 ≤ sin <i>n</i> ≤ 1), reporte l’encadrement dans l’expression, puis calcule les limites des deux bornes.',
  demo:{enonce:`Calculer lim ${F('<i>n</i> + cos <i>n</i>','<i>n</i>')} quand <i>n</i> → ∞.`,
   etapes:[
    {f:'−1 ≤ cos <i>n</i> ≤ 1',w:'cos <i>n</i> n’a pas de limite, mais il est borné.'},
    {f:`${F('<i>n</i> − 1','<i>n</i>')} ≤ ${F('<i>n</i> + cos <i>n</i>','<i>n</i>')} ≤ ${F('<i>n</i> + 1','<i>n</i>')}`,w:'On ajoute <i>n</i> puis on divise par <i>n</i> &gt; 0 : le sens est conservé.'},
    {f:'1 − 1/<i>n</i> → 1 et 1 + 1/<i>n</i> → 1',w:'Les deux gendarmes ont la même limite.'}],
   conclusion:'La suite tend vers 1. Variante : si <i>uₙ</i> ≥ <i>aₙ</i> et <i>aₙ</i> → +∞, alors <i>uₙ</i> → +∞ (un seul gendarme suffit).'}},
 {h:'Coince la suite',p:`Calcule lim ${F('2<i>n</i> + sin <i>n</i>','<i>n</i> + 1')} quand <i>n</i> → ∞.`,lab:'L =',ans:2,
  why:'−1 ≤ sin n ≤ 1 donne (2n − 1)/(n + 1) ≤ uₙ ≤ (2n + 1)/(n + 1). Les deux bornes tendent vers 2, donc uₙ → 2.'},
 {kind:'Méthode',h:'La limite de qⁿ',p:'<b>Quand :</b> la suite contient des puissances <i>n</i>-ièmes, comme 0,8ⁿ ou 3ⁿ. <b>Le résultat :</b> si <b><i>q</i> &gt; 1</b>, <i>qⁿ</i> → +∞ ; si <b>|<i>q</i>| &lt; 1</b>, <i>qⁿ</i> → 0 ; si <i>q</i> = 1, <i>qⁿ</i> = 1 ; si <i>q</i> ≤ −1, pas de limite. <b>Pourquoi :</b> pour <i>q</i> = 1 + <i>h</i> avec <i>h</i> &gt; 0, on a (1 + <i>h</i>)ⁿ ≥ 1 + <i>nh</i> → +∞ ; et si 0 &lt; |<i>q</i>| &lt; 1, |<i>q</i>|ⁿ = 1/(1/|<i>q</i>|)ⁿ avec 1/|<i>q</i>| &gt; 1. <b>Comment :</b> avec plusieurs puissances, mets en facteur celle de plus grande base, comme un terme dominant.',
  demo:{enonce:`Calculer lim ${F('2ⁿ + 3ⁿ','3ⁿ + 1')} quand <i>n</i> → ∞.`,
   etapes:[
    {f:'Forme ∞/∞',w:'2ⁿ, 3ⁿ → +∞ car 2 &gt; 1 et 3 &gt; 1.'},
    {f:`= ${F('3ⁿ((2/3)ⁿ + 1)','3ⁿ(1 + (1/3)ⁿ)')}`,w:'3ⁿ est le terme dominant : on le met en facteur, car 2ⁿ/3ⁿ = (2/3)ⁿ.'},
    {f:`= ${F('(2/3)ⁿ + 1','1 + (1/3)ⁿ')}`,w:'On simplifie par 3ⁿ.'},
    {f:'(2/3)ⁿ → 0 et (1/3)ⁿ → 0',w:'Les raisons 2/3 et 1/3 sont entre −1 et 1.'}],
   conclusion:'La limite vaut 1.'}},
 {h:'À toi',p:`Calcule lim ${F('5 · 4ⁿ − 3ⁿ','4ⁿ⁺¹ + 2ⁿ')} quand <i>n</i> → ∞.`,lab:'L =',ans:1.25,tol:1e-9,
  why:'4ⁿ⁺¹ = 4 · 4ⁿ. On factorise 4ⁿ : (5 − (3/4)ⁿ)/(4 + (1/2)ⁿ) → 5/4 = 1,25.'},
 {kind:'Méthode',h:'Suite récurrente uₙ₊₁ = a uₙ + b',p:'<b>Quand :</b> chaque terme se calcule à partir du précédent par une relation affine, avec <i>a</i> ≠ 1. <b>Pourquoi ça marche :</b> si la suite converge vers <i>L</i>, alors <i>uₙ₊₁</i> → <i>L</i> aussi, et la relation devient <b><i>L</i> = <i>aL</i> + <i>b</i></b> (le <b>point fixe</b>). En soustrayant les deux égalités, <i>vₙ</i> = <i>uₙ</i> − <i>L</i> vérifie <i>vₙ₊₁</i> = <i>a vₙ</i> : c’est une suite géométrique, <i>vₙ</i> = <i>v</i>₀ <i>a</i>ⁿ. <b>Comment :</b> trouve <i>L</i>, pose <i>vₙ</i> = <i>uₙ</i> − <i>L</i>, écris <i>uₙ</i> = <i>L</i> + (<i>u</i>₀ − <i>L</i>)<i>a</i>ⁿ et conclus avec la limite de <i>a</i>ⁿ.',
  demo:{enonce:'<i>u</i>₀ = 1 et <i>uₙ₊₁</i> = 0,5 <i>uₙ</i> + 2. Étudier la limite de (<i>uₙ</i>).',
   etapes:[
    {f:'<i>L</i> = 0,5<i>L</i> + 2 ⇔ 0,5<i>L</i> = 2 ⇔ <i>L</i> = 4',w:'Le seul candidat possible pour la limite est le point fixe.'},
    {f:'<i>vₙ₊₁</i> = <i>uₙ₊₁</i> − 4 = 0,5<i>uₙ</i> − 2 = 0,5(<i>uₙ</i> − 4) = 0,5 <i>vₙ</i>',w:'On vérifie que l’écart au point fixe est multiplié par 0,5 à chaque étape.'},
    {f:'<i>vₙ</i> = <i>v</i>₀ · 0,5ⁿ = −3 · 0,5ⁿ, donc <i>uₙ</i> = 4 − 3 · 0,5ⁿ',w:'<i>v</i>₀ = 1 − 4 = −3. On a une formule explicite.'},
    {f:'0,5ⁿ → 0, donc <i>uₙ</i> → 4',w:'|0,5| &lt; 1.'}],
   conclusion:'(<i>uₙ</i>) converge vers 4. Si |<i>a</i>| &gt; 1 et <i>u</i>₀ ≠ <i>L</i>, l’écart <i>vₙ</i> explose : la suite diverge.'},
  note:'Passer à la limite dans la relation ne prouve pas que la suite converge : cela donne seulement le candidat. La convergence vient de la formule <i>uₙ</i> = <i>L</i> + <i>v</i>₀<i>a</i>ⁿ, ou d’un autre argument (par exemple suite monotone et bornée).'},
 {h:'Le point fixe',p:'<i>u</i>₀ = 2 et <i>uₙ₊₁</i> = 0,5 <i>uₙ</i> + 3. Vers quelle limite tend (<i>uₙ</i>)&nbsp;?',lab:'L =',ans:6,
  why:'L = 0,5L + 3 donne L = 6. Avec vₙ = uₙ − 6 : vₙ₊₁ = 0,5vₙ, donc uₙ = 6 − 4 · 0,5ⁿ → 6.'},
 {kind:'Récapitulatif',h:'Ce qu’il faut retenir : suites et limites',p:'<div class="keep"><ul><li><b>Suite</b> (<i>uₙ</i>) : un réel par entier <i>n</i>. Bornée : |<i>uₙ</i>| ≤ <i>M</i>. Croissante : <i>uₙ₊₁</i> − <i>uₙ</i> ≥ 0 (ou <i>uₙ₊₁</i>/<i>uₙ</i> ≥ 1 si les termes sont positifs).</li><li><b><i>uₙ</i> → <i>L</i></b> : pour tout ε &gt; 0, il existe <i>N</i> tel que <i>n</i> ≥ <i>N</i> ⇒ |<i>uₙ</i> − <i>L</i>| &lt; ε. Pour trouver <i>N</i> : simplifier |<i>uₙ</i> − <i>L</i>|, résoudre l’inéquation en <i>n</i>, prendre le premier entier qui convient.</li><li><b>Limite monotone</b> : croissante et majorée (ou décroissante et minorée) ⇒ convergente.</li><li><b><i>uₙ</i> → +∞</b> : dépasse tout seuil <i>A</i> à partir d’un rang. Règles : <i>L</i> + ∞ = ∞, <i>L</i>/∞ = 0, <i>L</i>/0⁺ = +∞ si <i>L</i> &gt; 0.</li><li><b>Formes indéterminées</b> : ∞ − ∞, 0 · ∞, ∞/∞, 0/0. Il faut transformer : <b>terme dominant</b> en facteur (quotient de polynômes : comparer les degrés), <b>conjugué</b> pour une racine, <b>gendarmes</b> <i>aₙ</i> ≤ <i>uₙ</i> ≤ <i>bₙ</i> pour un terme borné qui oscille.</li><li><b><i>q</i>ⁿ</b> : → 0 si |<i>q</i>| &lt; 1, → +∞ si <i>q</i> &gt; 1, = 1 si <i>q</i> = 1, pas de limite si <i>q</i> ≤ −1. Avec plusieurs puissances, factoriser celle de plus grande base.</li><li><b><i>uₙ₊₁</i> = <i>a</i> <i>uₙ</i> + <i>b</i></b> : point fixe <i>L</i> = <i>aL</i> + <i>b</i>, puis <i>uₙ</i> − <i>L</i> = (<i>u</i>₀ − <i>L</i>)<i>a</i>ⁿ ; convergence vers <i>L</i> si |<i>a</i>| &lt; 1. Passer à la limite dans la relation donne un candidat, pas une preuve de convergence.</li></ul></div>'},
 {kind:'Problème',h:'Le stock de poissons',
  p:'Un lac contient 100 tonnes de poissons. Chaque année, la pêche prélève 20 % du stock, puis on relâche 10 tonnes d’alevins. On note <i>uₙ</i> le stock (en tonnes) après <i>n</i> années : <i>u</i>₀ = 100 et <b><i>uₙ</i>₊₁ = 0,8 <i>uₙ</i> + 10</b>. On veut savoir vers quoi tend le stock, et à partir de quand il en est proche.',
  fig:(()=>{ const P=plane({x:[-1,25],y:[40,105],h:200,grid:false,lx:5,ly:10}); P.seg(0,50,25,50,{c:'var(--ok)',w:1.5,dash:true}).text(24,50,'50',{dy:-6,c:'var(--ok)'});
    let u=100; for(let n=0;n<=24;n++){ P.dot(n,u,{r:3.5,c:'var(--accent)'}); u=.8*u+10; } return P.svg(); })(),
  parts:[
   {q:'a) Que vaut <i>u</i>₁&nbsp;?',lab:'u₁ =',unit:'t',ans:90,hint:'Applique la relation avec <i>u</i>₀ = 100.',why:'u₁ = 0,8 · 100 + 10 = 90 t.'},
   {q:'b) Si (<i>uₙ</i>) converge vers <i>L</i>, alors <i>L</i> = 0,8<i>L</i> + 10. Que vaut <i>L</i>&nbsp;?',lab:'L =',unit:'t',ans:50,hint:'Passe à la limite des deux côtés de la relation, puis résous.',why:'L = 0,8L + 10 ⇔ 0,2L = 10 ⇔ L = 50 t.'},
   {q:'c) On pose <i>vₙ</i> = <i>uₙ</i> − 50. Que peut-on dire de (<i>vₙ</i>)&nbsp;?',opts:['<i>vₙ</i>₊₁ = <i>vₙ</i> − 10 : elle perd 10 par an','<i>vₙ</i>₊₁ = 0,8 <i>vₙ</i> + 10 : même relation que (<i>uₙ</i>)','<i>vₙ</i> est constante, égale à 50','<i>vₙ</i>₊₁ = 0,8 <i>vₙ</i> : elle est multipliée par 0,8 chaque année et tend vers 0'],ans:3,hint:'Calcule <i>vₙ</i>₊₁ = <i>uₙ</i>₊₁ − 50 et fais apparaître <i>uₙ</i> − 50.',why:'vₙ₊₁ = 0,8uₙ + 10 − 50 = 0,8uₙ − 40 = 0,8(uₙ − 50) = 0,8vₙ. Donc vₙ = 50 · 0,8ⁿ → 0, et uₙ → 50.'},
   {q:'d) À partir de quel rang <i>N</i> a-t-on |<i>uₙ</i> − 50| &lt; 1 pour tout <i>n</i> ≥ <i>N</i>&nbsp;?',lab:'N =',ans:18,hint:'|<i>uₙ</i> − 50| = 50 · 0,8ⁿ diminue avec <i>n</i>. Teste quelques valeurs à la calculatrice.',why:'50 · 0,8¹⁷ ≈ 1,13 et 50 · 0,8¹⁸ ≈ 0,90. Comme la suite 50 · 0,8ⁿ décroît, N = 18.'},
  ],
  sol:'u₁ = 0,8 · 100 + 10 = 90.<br>Le seul candidat limite vérifie L = 0,8L + 10, donc L = 50.<br>Avec vₙ = uₙ − 50 : vₙ₊₁ = 0,8uₙ − 40 = 0,8vₙ, donc vₙ = v₀ · 0,8ⁿ = 50 · 0,8ⁿ.<br>Comme 0 &lt; 0,8 &lt; 1, 0,8ⁿ → 0 et uₙ = 50 + 50 · 0,8ⁿ → 50. Le stock décroît vers 50 t.<br>|uₙ − 50| = 50 · 0,8ⁿ &lt; 1 dès n = 18 (50 · 0,8¹⁷ ≈ 1,13 ; 50 · 0,8¹⁸ ≈ 0,90). C’est le N de la définition ε–N avec ε = 1.'},
 {kind:'Problème',h:'La méthode de Héron',
  p:'Pour approcher √2, on calcule <i>u</i>₀ = 2 et <b><i>uₙ</i>₊₁ = (<i>uₙ</i> + 2/<i>uₙ</i>)/2</b>. Chaque terme est la moyenne de <i>uₙ</i> et de 2/<i>uₙ</i>, deux nombres dont le produit vaut 2 : l’un est au-dessus de √2, l’autre en dessous. On admet que (<i>uₙ</i>) est décroissante et minorée par √2, donc qu’elle converge vers un réel <i>L</i> &gt; 0.',
  parts:[
   {q:'a) Que vaut <i>u</i>₁&nbsp;?',lab:'u₁ =',ans:1.5,tol:1e-9,hint:'Remplace <i>uₙ</i> par 2.',why:'u₁ = (2 + 2/2)/2 = 3/2 = 1,5.'},
   {q:'b) Que vaut <i>u</i>₂&nbsp;? Donne une fraction ou un arrondi à 10⁻⁵.',lab:'u₂ =',ans:17/12,tol:1e-5,hint:'2/(3/2) = 4/3.',why:'u₂ = (3/2 + 4/3)/2 = (17/6)/2 = 17/12 ≈ 1,41667.'},
   {q:'c) Pourquoi la limite <i>L</i> vaut-elle √2&nbsp;?',opts:['Parce que <i>u</i>₂ est déjà très proche de √2','Parce que la suite est décroissante','En passant à la limite dans la relation : <i>L</i> = (<i>L</i> + 2/<i>L</i>)/2, donc <i>L</i>² = 2, et <i>L</i> &gt; 0','Parce que 2/<i>uₙ</i> tend vers 0'],ans:2,hint:'Si <i>uₙ</i> → <i>L</i>, alors <i>uₙ</i>₊₁ → <i>L</i> aussi.',why:'L = (L + 2/L)/2 ⇔ 2L = L + 2/L ⇔ L = 2/L ⇔ L² = 2. Comme L ≥ √2 &gt; 0, L = √2. Être proche ou décroissante ne suffit pas à identifier la limite.'},
   {q:'d) On trouve <i>u</i>₃ = 577/408. Combien de décimales de √2 = 1,4142135… sont exactes dans <i>u</i>₃&nbsp;?',ans:5,hint:'Calcule 577/408 avec 7 décimales et compare chiffre par chiffre.',why:'577/408 ≈ 1,4142157 : les décimales 4, 1, 4, 2, 1 sont justes, la 6e (5 au lieu de 3) ne l’est pas.'},
  ],
  sol:'u₁ = (2 + 1)/2 = 3/2, puis u₂ = (3/2 + 4/3)/2 = 17/12 ≈ 1,41667, et u₃ = 577/408 ≈ 1,4142157.<br>La suite est décroissante et minorée par √2, donc elle converge vers un réel L ≥ √2.<br>En passant à la limite dans uₙ₊₁ = (uₙ + 2/uₙ)/2, on obtient L = (L + 2/L)/2, soit L² = 2, donc L = √2.<br>La convergence est très rapide : l’erreur passe de 0,086 (u₁) à 0,0025 (u₂) puis à 0,000002 (u₃). Elle est à peu près élevée au carré à chaque étape, ce qui double le nombre de décimales exactes.'},
]},

{subj:'an1', sem:'aut', id:'an1-geometrique', h:'Série géométrique et nombre d’Euler', p:'Sommer une infinité de termes : la série géométrique, puis le nombre e vu de deux façons.', steps:[
 {kind:'Théorie',h:'Additionner une infinité de termes',p:'<p>Pour traverser une pièce, tu parcours d’abord la moitié, puis la moitié du reste, puis encore la moitié… Une infinité d’étapes, et pourtant tu arrives au mur. Comment une somme infinie 1/2 + 1/4 + 1/8 + … peut-elle valoir un nombre fini ?</p><div class="def"><p>Étant donné une suite (<i>uₖ</i>), la <b>somme partielle</b> de rang <i>n</i> est <b>Sₙ = <i>u</i>₀ + <i>u</i>₁ + … + <i>uₙ</i> = Σ<sub>k=0</sub><sup>n</sup> <i>uₖ</i></b> (lire « somme des <i>uₖ</i> pour <i>k</i> de 0 à <i>n</i> »). La <b>série</b> Σ <i>uₖ</i> <b>converge</b> si la suite (Sₙ) a une limite finie S ; on écrit alors <b>Σ<sub>k=0</sub><sup>∞</sup> <i>uₖ</i> = S</b>. Sinon la série <b>diverge</b>.</p></div><div class="idea"><p>On ne « fait » jamais une addition infinie : on additionne un nombre fini de termes, de plus en plus, et on regarde si le total se stabilise. La somme infinie est la <b>limite</b> des sommes partielles, exactement au sens du chapitre précédent. Une série est une suite déguisée : (Sₙ) est la suite des totaux cumulés.</p></div><div class="ex"><p>Pour <i>uₖ</i> = 1/2ᵏ (<i>k</i> ≥ 1) : S₁ = 0,5, S₂ = 0,75, S₃ = 0,875, S₄ = 0,9375, et en général Sₙ = 1 − 1/2ⁿ (la figure). Comme 1/2ⁿ → 0, Sₙ → 1 : la série converge et 1/2 + 1/4 + 1/8 + … = 1. Il manque toujours un petit morceau, mais il devient aussi petit qu’on veut.</p></div><div class="warn"><p>Si les termes ne tendent pas vers 0, la série diverge : 1 + 1 + 1 + … explose. Mais la réciproque est fausse : 1 + 1/2 + 1/3 + 1/4 + … a des termes qui tendent vers 0 et diverge quand même, lentement (S₁₀₀₀ ≈ 7,49, S₁₀₀₀₀₀₀ ≈ 14,39, sans jamais s’arrêter).</p></div>',
  fig:(()=>{ const P=plane({x:[-.5,12.5],y:[-.1,1.15],h:190,grid:false,lx:2,ly:.5}); P.seg(0,1,12.5,1,{c:'var(--ok)',w:1.5,dash:true}).text(12,1,'S = 1',{a:'end',dy:-6,c:'var(--ok)'});
    let s=0; for(let n=1;n<=12;n++){ s+=1/2**n; P.dot(n,s,{r:4,c:'var(--accent)'}); } P.text(1,.5,'S₁ = 0,5',{dx:8,dy:4}); return P.svg(); })()},
 {kind:'Théorie',h:'Sommes partielles',p:'<p>Pour une raison <i>q</i> quelconque, on veut savoir si 1 + <i>q</i> + <i>q</i>² + … converge, et combien ça vaut. Tout repose sur une formule qui donne la somme partielle d’un coup.</p><div class="prop"><p>Pour <i>q</i> ≠ 1 : <b>Sₙ = 1 + <i>q</i> + <i>q</i>² + … + <i>q</i>ⁿ = (1 − <i>q</i>ⁿ⁺¹)/(1 − <i>q</i>)</b>. Si |<i>q</i>| &lt; 1, alors <i>q</i>ⁿ⁺¹ → 0 et la <b>série géométrique</b> converge : <b>Σ<sub>k=0</sub><sup>∞</sup> <i>q</i>ᵏ = 1/(1 − <i>q</i>)</b>. Si |<i>q</i>| ≥ 1, elle diverge.</p></div><div class="why"><p>Multiplions Sₙ par <i>q</i> : <i>q</i>Sₙ = <i>q</i> + <i>q</i>² + … + <i>q</i>ⁿ⁺¹, la même somme décalée d’un cran. En soustrayant, tous les termes du milieu se compensent : Sₙ − <i>q</i>Sₙ = 1 − <i>q</i>ⁿ⁺¹, donc (1 − <i>q</i>)Sₙ = 1 − <i>q</i>ⁿ⁺¹. Pour la limite : si |<i>q</i>| &lt; 1, <i>q</i>ⁿ⁺¹ → 0 et il reste 1/(1 − <i>q</i>). Si |<i>q</i>| ≥ 1, les termes <i>q</i>ᵏ ne tendent pas vers 0, et une série dont les termes ne tendent pas vers 0 ne peut pas converger.</p></div><div class="ex"><p><i>q</i> = 1/2 : S₅ = (1 − 1/64)/(1/2) = 2 − 1/32 = 1,96875, et la limite vaut 1/(1 − 1/2) = 2. Sur la figure, les points s’empilent sous la ligne verte. <i>q</i> = −0,5 : la somme vaut 1/1,5 = 2/3 ≈ 0,667, et les points l’approchent en zigzag, alternativement au-dessus et en dessous.</p></div><div class="warn"><p>Règle <i>q</i> sur 1 ou −1 : la formule n’a plus de sens (division par 0), et les sommes partielles valent <i>n</i> + 1 ou oscillent entre 1 et 0. Au-delà de 1, elles explosent. La condition |<i>q</i>| &lt; 1 n’est pas un détail.</p></div>',
  params:[{id:'q',l:'q',min:-1.2,max:1.2,step:.1,v:.5},{id:'n',l:'n',min:0,max:20,v:5}],
  draw:v=>{ const P=plane({x:[-1,21],y:[-2,6],h:240,grid:false,lx:5,ly:1}); let s=0;
    if(Math.abs(v.q)<1-1e-9) P.seg(0,1/(1-v.q),21,1/(1-v.q),{c:'var(--ok)',w:1.5,dash:true});
    for(let k=0;k<=20;k++){ s+=v.q**k; if(s>-2&&s<6) P.dot(k,s,{r:k===v.n?6:3.5,c:k===v.n?'var(--spark)':'var(--accent)'}); } return P.svg(); },
  info:v=>{ let s=0; for(let k=0;k<=v.n;k++) s+=v.q**k; return `S<sub>${v.n}</sub> ≈ ${fmt(s,4)} · `+(Math.abs(v.q)<1-1e-9?`limite 1/(1 − q) ≈ ${fmt(1/(1-v.q),4)}`:'|q| ≥ 1 : la série diverge'); },
  note:'Si |<i>q</i>| ≥ 1, le terme <i>qⁿ</i> ne tend pas vers 0, la série ne peut pas converger.'},
 {kind:'Méthode',h:'Somme finie de termes géométriques',p:'<b>Quand :</b> chaque terme s’obtient en multipliant le précédent par un même nombre <i>q</i> ≠ 1 (la raison). <b>Pourquoi ça marche :</b> si S = <i>a</i> + <i>aq</i> + … + <i>aq</i><sup><i>N</i>−1</sup>, alors <i>q</i>S décale tout d’un cran et S − <i>q</i>S = <i>a</i> − <i>aq</i><sup><i>N</i></sup> : tous les termes du milieu se compensent. <b>Comment :</b> repère le premier terme <i>a</i>, la raison <i>q</i> et le <b>nombre de termes</b> <i>N</i>, puis <b>S = <i>a</i> · (1 − <i>q</i><sup><i>N</i></sup>)/(1 − <i>q</i>)</b>.',
  demo:{enonce:'Calculer S = 3 + 6 + 12 + … + 384.',
   etapes:[
    {f:'Premier terme <i>a</i> = 3, raison <i>q</i> = 2',w:'Chaque terme est le double du précédent.'},
    {f:'384 = 3 · 128 = 3 · 2⁷ : les termes sont 3 · 2⁰, …, 3 · 2⁷, soit <i>N</i> = 8 termes',w:'On compte les termes avec les exposants de 0 à 7 : l’erreur classique est d’en oublier un.'},
    {f:'S = 3 · (1 − 2⁸)/(1 − 2) = 3 · (−255)/(−1) = 765',w:'On applique la formule avec <i>N</i> = 8.'}],
   conclusion:'S = 765.'}},
 {h:'Compte les termes',p:'Calcule 1 + 3 + 9 + 27 + … + 3⁶.',ans:1093,
  why:'Premier terme 1, raison 3, et 7 termes (exposants 0 à 6) : S = (1 − 3⁷)/(1 − 3) = (3⁷ − 1)/2 = 2186/2 = 1093.'},
 {kind:'Méthode',h:'Sommer une série géométrique',p:'<b>Quand :</b> on additionne une infinité de termes géométriques de raison |<i>q</i>| &lt; 1, qui ne commence pas forcément à 1. <b>Pourquoi ça marche :</b> la somme finie vaut <i>a</i>(1 − <i>q</i><sup><i>N</i></sup>)/(1 − <i>q</i>), et <i>q</i><sup><i>N</i></sup> → 0. <b>Comment :</b> la somme vaut <b>premier terme / (1 − raison)</b>. Écris le premier terme en remplaçant <i>k</i> par sa valeur de départ.',
  demo:{enonce:'Calculer Σ<sub>k=2</sub><sup>∞</sup> 3 · (1/2)<sup>k</sup>.',
   etapes:[
    {f:'Raison <i>q</i> = 1/2, et |1/2| &lt; 1',w:'Condition de convergence : sans elle, la formule est fausse.'},
    {f:'Premier terme (pour <i>k</i> = 2) : 3 · (1/2)² = 3/4',w:'On ne prend pas 3 : la somme commence à <i>k</i> = 2.'},
    {f:'S = (3/4)/(1 − 1/2) = (3/4)/(1/2) = 3/2',w:'Premier terme divisé par 1 − raison.'}],
   conclusion:'La série converge et sa somme vaut 3/2.'},
  note:'Même méthode pour un nombre périodique : 0,555… = 5/10 + 5/100 + … = (5/10)/(1 − 1/10) = 5/9.'},
 {h:'Somme à partir de k = 1',p:'Calcule la somme Σ<sub>k=1</sub><sup>∞</sup> (2/3)<sup>k</sup>.',lab:'S =',ans:2,
  why:'Le premier terme est 2/3 et la raison 2/3 : S = (2/3)/(1 − 2/3) = (2/3)/(1/3) = 2.'},
 {h:'Convergente ou pas&nbsp;?',p:'Laquelle de ces séries converge&nbsp;?',opts:['Σ (1,1)ⁿ','Σ (−1)ⁿ','Σ (−1,5)ⁿ','Σ (−0,9)ⁿ'],ans:3,
  why:'Seule |−0,9| &lt; 1. Sa somme vaut 1/(1 + 0,9) = 1/1,9 ≈ 0,526. Pour (−1)ⁿ, les sommes partielles oscillent entre 1 et 0.'},
 {h:'Un nombre périodique',p:'0,272727… = 27/100 + 27/100² + … Écris ce nombre comme une fraction (par exemple 3/7).',lab:'x =',ans:3/11,tol:1e-6,
  why:'Série géométrique de premier terme 27/100 et de raison 1/100 : (27/100)/(1 − 1/100) = 27/99 = 3/11.'},
 {kind:'Théorie',h:'Les intérêts composés et le nombre e',p:'<p>Une banque offre 100 % par an. Avec 1 CHF, tu as 2 CHF au bout d’un an. Si elle verse 50 % tous les six mois, tu as 1,5² = 2,25 CHF. Et si elle verse 100/<i>n</i> % <i>n</i> fois par an ? Plus on fractionne, plus on gagne : mais est-ce sans limite ?</p><div class="def"><p>Avec <i>n</i> versements par an, le capital devient (1 + 1/<i>n</i>)ⁿ. Cette suite est croissante et majorée (par 3), donc elle converge d’après le théorème de la limite monotone. Sa limite est le <b>nombre d’Euler</b> <b>e = lim (1 + 1/<i>n</i>)ⁿ ≈ 2,71828</b>. C’est un irrationnel, comme π.</p></div><div class="why"><p>Pourquoi c’est majoré : en développant (1 + 1/<i>n</i>)ⁿ avec la formule du binôme, le terme numéro <i>k</i> vaut au plus 1/<i>k</i>!, et comme <i>k</i>! ≥ 2ᵏ⁻¹, la somme 1 + 1 + 1/2! + 1/3! + … est majorée par 1 + 1 + 1/2 + 1/4 + 1/8 + … = 3. Le même développement montre que la limite est aussi Σ 1/<i>k</i>! : c’est la seconde définition de e, à l’étape suivante.</p></div><div class="ex"><p><i>n</i> = 1 : 2. <i>n</i> = 2 : 2,25. <i>n</i> = 12 (mensuel) : (1 + 1/12)¹² ≈ 2,613. <i>n</i> = 365 (quotidien) : ≈ 2,7146. <i>n</i> = 10⁶ : ≈ 2,71828. Fractionner à l’infini ne rend pas infiniment riche : on plafonne à e fois le capital.</p></div><div class="idea"><p>Plus généralement, un taux <i>x</i> versé en <i>n</i> fois donne (1 + <i>x</i>/<i>n</i>)ⁿ, qui tend vers <b>eˣ</b> : c’est la croissance <b>continue</b> au taux <i>x</i>. Cette limite est l’outil de toutes les formes 1<sup>∞</sup>, et eˣ est la fonction exponentielle, dont on verra plus tard qu’elle est sa propre dérivée.</p></div>'},
 {kind:'Théorie',h:'Le nombre e, deux fois',p:'<p>Deux suites très différentes mènent au même nombre : une puissance dont la base se rapproche de 1 pendant que l’exposant explose, et une somme de fractions de plus en plus petites. Compare-les sur la figure.</p><div class="thm"><p>Les suites <b><i>aₙ</i> = (1 + 1/<i>n</i>)ⁿ</b> et <b><i>bₙ</i> = Σ<sub>k=0</sub><sup>n</sup> 1/<i>k</i>! = 1 + 1 + 1/2 + 1/6 + 1/24 + …</b> convergent vers la même limite <b>e ≈ 2,718281828</b>. Ici <i>k</i>! = 1 · 2 · … · <i>k</i> (lire « factorielle k »), avec 0! = 1.</p></div><div class="why"><p>Le développement de (1 + 1/<i>n</i>)ⁿ par la formule du binôme donne une somme de termes de la forme (1/<i>k</i>!)(1 − 1/<i>n</i>)(1 − 2/<i>n</i>)…, chacun un peu plus petit que 1/<i>k</i>!. Donc <i>aₙ</i> ≤ <i>bₙ</i>, et quand <i>n</i> grandit, les facteurs (1 − <i>j</i>/<i>n</i>) tendent vers 1 : les deux suites se rejoignent.</p></div><div class="ex"><p>Pour <i>n</i> = 3 : <i>a</i>₃ = (4/3)³ = 64/27 ≈ 2,370, alors que <i>b</i>₃ = 1 + 1 + 1/2 + 1/6 = 8/3 ≈ 2,667, déjà à 0,05 de e. Pour <i>n</i> = 10 : <i>a</i>₁₀ ≈ 2,594 et <i>b</i>₁₀ ≈ 2,7182818, exact à sept décimales. La somme des factorielles converge incomparablement plus vite : c’est elle que les calculatrices utilisent.</p></div><div class="warn"><p>1<sup>∞</sup> est une forme indéterminée : la base 1 + 1/<i>n</i> tend vers 1, l’exposant <i>n</i> vers l’infini, et le résultat n’est ni 1 ni ∞, mais e. Plus généralement <b>(1 + <i>x</i>/<i>n</i>)ⁿ → eˣ</b>, donc (1 − 1/<i>n</i>)ⁿ → e⁻¹ ≈ 0,368, pas 1.</p></div>',
  params:[{id:'n',l:'n',min:1,max:40,v:3}],
  draw:v=>{ const P=plane({x:[-1,41],y:[1.8,3],h:220,grid:false,lx:10}); P.seg(0,Math.E,41,Math.E,{c:'var(--ok)',w:1.5,dash:true}).text(40,Math.E,'e',{dy:-6});
    let s=0; for(let n=1;n<=40;n++){ P.dot(n,(1+1/n)**n,{r:n===v.n?6:3,c:'var(--accent)'}); }
    for(let n=0;n<=40;n++){ s+=1/fact(n); if(n>=1) P.dot(n,s,{r:n===v.n?6:3,c:'var(--spark)'}); } return P.svg(); },
  info:v=>{ let s=0; for(let k=0;k<=v.n;k++) s+=1/fact(k); return `(1 + 1/${v.n})<sup>${v.n}</sup> ≈ ${fmt((1+1/v.n)**v.n,5)} (bleu) · Σ 1/k! jusqu’à ${v.n} ≈ ${fmt(s,5)} (jaune)`; },
  note:'En bleu, (1 + 1/n)ⁿ ; en jaune, la somme des 1/k!. Observe à quelle vitesse chacune rejoint la ligne e.'},
 {h:'Quatre termes',p:'Calcule 1 + 1/1! + 1/2! + 1/3!, arrondi au millième.',lab:'S ≈',ans:8/3,tol:6e-4,
  why:'1 + 1 + 1/2 + 1/6 = 8/3 ≈ 2,667. On est déjà à 0,05 de e.'},
 {kind:'Méthode',h:'Forme 1<sup>∞</sup> : se ramener à (1 + x/n)ⁿ',p:'<b>Quand :</b> une base qui tend vers 1 est élevée à une puissance qui tend vers l’infini. <b>Pourquoi ça marche :</b> on connaît une seule limite de ce type, <b>(1 + <i>x</i>/<i>n</i>)ⁿ → eˣ</b>, valable pour tout réel <i>x</i> (donc aussi (1 − 1/<i>n</i>)ⁿ → e⁻¹). Il suffit de faire apparaître cette forme. <b>Comment :</b> écris la base sous la forme 1 + <i>x</i>/<i>n</i> (ou un quotient de telles bases), ajuste l’exposant avec (<i>A</i>ⁿ)ᵏ = <i>A</i><sup><i>kn</i></sup>, puis passe à la limite.',
  demo:{enonce:'Calculer lim (1 + 3/<i>n</i>)<sup>2<i>n</i></sup> quand <i>n</i> → ∞.',
   etapes:[
    {f:'Forme 1<sup>∞</sup>',w:'1 + 3/<i>n</i> → 1 et 2<i>n</i> → ∞ : on ne peut pas dire « 1 puissance quelque chose vaut 1 ».'},
    {f:'(1 + 3/<i>n</i>)<sup>2<i>n</i></sup> = [(1 + 3/<i>n</i>)ⁿ]²',w:'On isole la forme connue, avec l’exposant <i>n</i>.'},
    {f:'(1 + 3/<i>n</i>)ⁿ → e³',w:'C’est (1 + <i>x</i>/<i>n</i>)ⁿ avec <i>x</i> = 3.'},
    {f:'[(1 + 3/<i>n</i>)ⁿ]² → (e³)² = e⁶',w:'La fonction carré est continue : on passe à la limite à l’intérieur.'}],
   conclusion:'La limite vaut e⁶ ≈ 403,4.'}},
 {kind:'Défi',h:'Une limite en 1<sup>∞</sup>',p:`Calcule lim (${F('<i>n</i> + 1','<i>n</i> − 1')})<sup><i>n</i></sup> quand <i>n</i> → ∞, arrondi au centième.`,lab:'L ≈',ans:Math.E**2,tol:.006,
  why:'(n + 1)/(n − 1) = (1 + 1/n)/(1 − 1/n). Donc la puissance n vaut (1 + 1/n)ⁿ/(1 − 1/n)ⁿ → e/e⁻¹ = e² ≈ 7,39.'},
 {kind:'Récapitulatif',h:'Ce qu’il faut retenir : séries géométriques et nombre e',p:'<div class="keep"><ul><li><b>Série</b> Σ <i>uₖ</i> : limite des sommes partielles Sₙ = <i>u</i>₀ + … + <i>uₙ</i>. Si les termes ne tendent pas vers 0, elle diverge (la réciproque est fausse).</li><li><b>Somme géométrique finie</b> : <i>a</i> + <i>aq</i> + … + <i>aq</i><sup>N−1</sup> = <i>a</i>(1 − <i>q</i><sup>N</sup>)/(1 − <i>q</i>), avec <i>N</i> le nombre de termes (compte-les avec les exposants).</li><li><b>Série géométrique</b> : converge si et seulement si |<i>q</i>| &lt; 1, et vaut <b>premier terme/(1 − raison)</b>. Un nombre périodique est une série géométrique de raison 1/10, 1/100, …</li><li><b>e</b> = lim (1 + 1/<i>n</i>)ⁿ = Σ 1/<i>k</i>! ≈ 2,71828 ; la seconde forme converge très vite.</li><li><b>(1 + <i>x</i>/<i>n</i>)ⁿ → eˣ</b> pour tout réel <i>x</i> : c’est la croissance continue au taux <i>x</i>.</li><li><b>Forme 1<sup>∞</sup></b> : écrire la base comme 1 + <i>x</i>/<i>n</i> (ou un quotient de telles bases), ajuster l’exposant avec (Aⁿ)ᵏ = A<sup>kn</sup>, conclure avec eˣ.</li></ul></div>'},
 {kind:'Problème',h:'La balle qui rebondit',
  p:'Tu lâches une balle d’une hauteur de 2 m. À chaque rebond, elle remonte aux 3/4 de la hauteur précédente. On suppose qu’elle rebondit indéfiniment. On veut la hauteur des rebonds et la distance totale parcourue.',
  fig:(()=>{ const P=plane({x:[-.3,8],y:[-.2,2.2],h:160,grid:false,lx:1,ly:.5}); let h=2,x=0;
    P.seg(0,2,0,0,{c:'var(--accent)',w:2});
    for(let k=1;k<=7;k++){ h*=.75; const H=h,x0=x; P.curve(t=>x0+t,t=>4*H*t*(1-t),0,1,{c:'var(--accent)',w:2}); x+=1; }
    P.text(.1,2,'2 m',{dx:6,dy:4}); return P.svg(); })(),
  parts:[
   {q:'a) Quelle hauteur atteint-elle après le 3e rebond&nbsp;? Arrondis au centième.',lab:'h₃ ≈',unit:'m',ans:.84375,tol:.006,hint:'Chaque rebond multiplie la hauteur par 3/4.',why:'h₃ = 2 · (3/4)³ = 2 · 27/64 = 0,84375 ≈ 0,84 m.'},
   {q:'b) Quelle distance verticale totale parcourt-elle&nbsp;?',lab:'D =',unit:'m',ans:14,hint:'Une descente de 2 m, puis pour chaque rebond <i>k</i> ≥ 1 une montée et une descente de hₖ = 2 · (3/4)ᵏ.',why:'D = 2 + 2 · Σ<sub>k≥1</sub> 2 · (3/4)ᵏ = 2 + 4 · (3/4)/(1 − 3/4) = 2 + 4 · 3 = 14 m.'},
   {q:'c) Après combien de rebonds la hauteur passe-t-elle pour la première fois sous 1 cm&nbsp;?',ans:19,hint:'Cherche le plus petit <i>n</i> avec 2 · 0,75ⁿ &lt; 0,01, en testant à la calculatrice.',why:'2 · 0,75¹⁸ ≈ 0,0113 m et 2 · 0,75¹⁹ ≈ 0,0085 m : c’est au 19e rebond.'},
  ],
  sol:'Après le k-ième rebond, la hauteur vaut hₖ = 2 · (3/4)ᵏ : c’est une suite géométrique de raison 3/4. Donc h₃ = 54/64 ≈ 0,84 m.<br>Distance : la première chute (2 m), puis chaque rebond se parcourt deux fois (montée et descente).<br>D = 2 + 2 Σ<sub>k=1</sub><sup>∞</sup> 2(3/4)ᵏ. La série a pour premier terme 3/2 et raison 3/4, sa somme vaut (3/2)/(1/4) = 6.<br>D = 2 + 2 · 6 = 14 m : une infinité de rebonds, mais une distance finie.<br>Enfin 2 · 0,75ⁿ &lt; 0,01 ⇔ 0,75ⁿ &lt; 0,005, vrai pour la première fois en n = 19.'},
 {kind:'Problème',h:'Rembourser un emprunt',
  p:'Tu empruntes 10 000 CHF au taux de 1 % par mois. Tu rembourses en 12 mensualités égales <i>M</i>, la première un mois après l’emprunt. Le principe : au bout de 12 mois, la valeur de tes versements (avec leurs intérêts) doit égaler la dette (avec ses intérêts). On compare ensuite avec des intérêts calculés en continu.',
  parts:[
   {q:'a) Sans aucun versement, combien devrais-tu au bout de 12 mois&nbsp;? Arrondis au centime.',lab:'D =',unit:'CHF',ans:10000*1.01**12,tol:.006,hint:'Chaque mois, la dette est multipliée par 1,01.',why:'10 000 · 1,01¹² ≈ 11 268,25 CHF.'},
   {q:'b) Le versement du mois <i>k</i> rapporte des intérêts pendant 12 − <i>k</i> mois. La valeur finale des versements vaut <i>M</i>(1 + 1,01 + 1,01² + … + 1,01¹¹) = <i>M</i> · <i>S</i>. Que vaut <i>S</i>&nbsp;? Arrondis au millième.',lab:'S ≈',ans:(1.01**12-1)/.01,tol:6e-4,hint:'Somme géométrique de raison <i>q</i> = 1,01 : (1 − <i>q</i>¹²)/(1 − <i>q</i>).',why:'S = (1,01¹² − 1)/0,01 ≈ 12,683.'},
   {q:'c) Que vaut la mensualité <i>M</i>&nbsp;? Arrondis au centime.',lab:'M =',unit:'CHF',ans:10000*1.01**12*.01/(1.01**12-1),tol:.006,hint:'Écris l’égalité <i>M</i> · <i>S</i> = 10 000 · 1,01¹².',why:'M = 11 268,25/12,6825 ≈ 888,49 CHF. Tu paies au total 12M ≈ 10 661,85 CHF, soit 661,85 CHF d’intérêts.'},
   {q:'d) Une banque qui capitaliserait en continu au taux annuel de 12 % ferait passer la dette, en un an, à lim 10 000 (1 + 0,12/<i>n</i>)ⁿ. Combien vaut cette dette&nbsp;? Arrondis au centime.',lab:'D =',unit:'CHF',ans:10000*Math.exp(.12),tol:.006,hint:'(1 + <i>x</i>/<i>n</i>)ⁿ → eˣ.',why:'10 000 · e<sup>0,12</sup> ≈ 11 274,97 CHF, à peine plus que les 11 268,25 CHF de la capitalisation mensuelle.'},
  ],
  sol:'Sans versement, la dette vaut 10 000 · 1,01¹² ≈ 11 268,25 CHF après un an.<br>Le versement du mois k vaut M · 1,01¹²⁻ᵏ au mois 12. En sommant de k = 1 à 12 : M(1 + 1,01 + … + 1,01¹¹) = M · (1,01¹² − 1)/0,01 ≈ 12,6825 M.<br>On égale : 12,6825 M = 11 268,25, d’où M ≈ 888,49 CHF.<br>Total payé : 12M ≈ 10 661,85 CHF, dont 661,85 CHF d’intérêts.<br>En continu, (1 + 0,12/n)ⁿ → e<sup>0,12</sup> ≈ 1,1275 : la dette deviendrait 11 274,97 CHF. Capitaliser plus souvent coûte un peu plus, mais la limite reste finie : c’est le rôle du nombre e.'},
]},

{subj:'an1', sem:'aut', id:'an1-limfonctions', h:'Limites de fonctions', p:'Limites en un point, à gauche et à droite, à l’infini, et les infiniment petits équivalents.', steps:[
 {kind:'Théorie',h:'La limite d’une fonction en un point',p:'<p>f(x) = (<i>x</i>² − 1)/(<i>x</i> − 1) n’est pas définie en 1 : on y diviserait par 0. Pourtant f(0,99) = 1,99 et f(1,001) = 2,001 : les valeurs se serrent autour de 2. La limite rend précise cette idée de « valeur vers laquelle on tend », même là où la fonction n’existe pas.</p><div class="def"><p>On dit que <b>f(x) tend vers <i>L</i> quand <i>x</i> tend vers <i>a</i></b>, noté <b>lim<sub>x→a</sub> f(x) = <i>L</i></b>, si f(x) est aussi proche de <i>L</i> qu’on veut pourvu que <i>x</i> soit assez proche de <i>a</i>, <b>sans être égal à <i>a</i></b>. En symboles : pour tout ε &gt; 0, il existe δ &gt; 0 tel que 0 &lt; |<i>x</i> − <i>a</i>| &lt; δ ⇒ |f(x) − <i>L</i>| &lt; ε.</p></div><div class="idea"><p>C’est la définition ε–N des suites, avec un changement : au lieu de « <i>n</i> assez grand », on demande « <i>x</i> assez proche de <i>a</i> », mesuré par δ (delta). La valeur f(<i>a</i>) elle-même ne compte pas : elle peut ne pas exister, ou être différente de <i>L</i>. On regarde ce qui se passe <b>autour</b> de <i>a</i>, jamais <b>en</b> <i>a</i>.</p></div><div class="ex"><p>Pour <i>x</i> ≠ 1, (<i>x</i>² − 1)/(<i>x</i> − 1) = (<i>x</i> − 1)(<i>x</i> + 1)/(<i>x</i> − 1) = <i>x</i> + 1. Quand <i>x</i> → 1, <i>x</i> + 1 → 2 : lim<sub>x→1</sub> f(x) = 2, bien que f(1) n’existe pas. Sur la figure, la courbe est la droite <i>y</i> = <i>x</i> + 1 avec un trou en (1 ; 2).</p></div><div class="warn"><p>Pour les fonctions usuelles (polynômes, racines, sin, cos, exp, ln) en un point où elles sont définies, la limite vaut simplement la valeur : lim<sub>x→2</sub> <i>x</i>² = 4. Le travail commence quand remplacer <i>x</i> par <i>a</i> donne un calcul impossible, comme 0/0.</p></div>',
  fig:(()=>{ const P=plane({x:[-2,4],y:[-1.5,5],h:240,lab:1}); P.fn(x=>x+1,{from:-2,to:4}); P.circ(1,2,.1,{c:'var(--accent)',w:2,fill:'var(--surface)',fo:1}); P.seg(1,-1.5,1,2,{c:'var(--muted)',w:1.2,dash:true}).seg(-2,2,1,2,{c:'var(--muted)',w:1.2,dash:true}).text(1,2,'L = 2',{dx:10,dy:-8}); return P.svg(); })()},
 {kind:'Théorie',h:'À gauche, à droite',p:'<p>Certaines fonctions se comportent différemment selon le côté par lequel on approche. Ici f(x) = (<i>x</i>² − 1)/|<i>x</i> − 1| : à droite de 1, |<i>x</i> − 1| = <i>x</i> − 1 et f(x) = <i>x</i> + 1 ; à gauche, |<i>x</i> − 1| = 1 − <i>x</i> et f(x) = −(<i>x</i> + 1). Deux formules, deux comportements.</p><div class="def"><p>La <b>limite à droite</b> <b>lim<sub>x→a⁺</sub> f(x)</b> ne regarde que les <i>x</i> &gt; <i>a</i> ; la <b>limite à gauche</b> <b>lim<sub>x→a⁻</sub> f(x)</b> que les <i>x</i> &lt; <i>a</i>. La limite lim<sub>x→a</sub> f(x) <b>existe si et seulement si</b> les deux limites latérales existent <b>et sont égales</b> ; elle vaut alors leur valeur commune.</p></div><div class="idea"><p>Approcher <i>a</i> « de n’importe quelle manière » revient à l’approcher par la droite ou par la gauche. Si les deux côtés ne sont pas d’accord, aucun nombre ne peut être « la » limite. Réduis la distance <i>h</i> avec le curseur : le point violet (gauche) descend vers −2, le point jaune (droite) monte vers 2.</p></div><div class="ex"><p>f(1 + <i>h</i>) = 2 + <i>h</i> → 2 quand <i>h</i> → 0⁺ ; f(1 − <i>h</i>) = −(2 − <i>h</i>) → −2. Limite à droite 2, limite à gauche −2 : <i>f</i> n’a pas de limite en 1. En revanche, pour g(x) = |<i>x</i>|, les deux limites en 0 valent 0 : la limite existe et vaut 0.</p></div><div class="warn"><p>Les limites latérales servent aussi quand la fonction n’est définie que d’un côté : √<i>x</i> en 0 n’a qu’une limite à droite. Et elles sont indispensables pour les formes « nombre/0 », où le signe du dénominateur change d’un côté à l’autre.</p></div>',
  params:[{id:'h',l:'Distance h à 1',min:.05,max:1,step:.05,v:.8}],
  draw:v=>{ const P=plane({x:[-1,3],y:[-3,3.4],lab:1}); P.fn(x=>-(x+1),{from:-1,to:.995}).fn(x=>x+1,{from:1.005,to:3});
    P.circ(1,-2,.07,{c:'var(--accent)',w:2,fill:'var(--surface)',fo:1}).circ(1,2,.07,{c:'var(--accent)',w:2,fill:'var(--surface)',fo:1});
    P.dot(1-v.h,-(2-v.h),{c:'var(--math)',l:'gauche',dx:-50}).dot(1+v.h,2+v.h,{c:'var(--spark)',l:'droite'}); return P.svg(); },
  info:v=>`f(1 − ${fmt(v.h)}) = ${fmt(-(2-v.h))} · f(1 + ${fmt(v.h)}) = ${fmt(2+v.h)}. Limite à gauche −2, à droite 2 : pas de limite en 1.`,
  note:'Une fonction définie par morceaux se raccorde en un point exactement quand ses deux limites latérales y coïncident.'},
 {kind:'Théorie',h:'Règles de calcul et formes indéterminées',p:'<p>On connaît les limites de <i>x</i>², de sin <i>x</i>, de 1/<i>x</i>. Comment obtenir celle d’une expression qui les combine ? Les mêmes règles que pour les suites s’appliquent, avec les mêmes exceptions.</p><div class="prop"><p>Si f(x) → <i>L</i> et g(x) → <i>L</i>′ (quand <i>x</i> → <i>a</i>, <i>a</i>⁺, <i>a</i>⁻ ou ±∞), alors f + g → <i>L</i> + <i>L</i>′, f · g → <i>LL</i>′, f/g → <i>L</i>/<i>L</i>′ si <i>L</i>′ ≠ 0, et h(f(x)) → h(<i>L</i>) si h est continue en <i>L</i> (par exemple √, exp, sin). Avec l’infini : <i>L</i> + ∞ = ∞, <i>L</i>/∞ = 0, <i>L</i>/0⁺ = +∞ si <i>L</i> &gt; 0. Les <b>formes indéterminées</b> restent <b>0/0</b>, <b>∞/∞</b>, <b>0 · ∞</b> et <b>∞ − ∞</b>, auxquelles s’ajoute <b>1<sup>∞</sup></b> pour les puissances.</p></div><div class="idea"><p>Première chose à faire devant une limite : <b>remplacer</b>. Si on obtient un nombre, c’est fini. Si on obtient <i>k</i>/0 avec <i>k</i> ≠ 0, la limite est infinie et il reste à trouver le signe. Si on obtient une forme indéterminée, il faut transformer l’expression : factoriser, conjuguer, mettre le terme dominant en facteur, utiliser un équivalent. Chaque méthode de ce chapitre correspond à l’une de ces situations.</p></div><div class="ex"><p>lim<sub>x→2</sub> (<i>x</i>² + 3)/(<i>x</i> − 1) : on remplace, 7/1 = 7, terminé. lim<sub>x→2</sub> (<i>x</i>² − 4)/(<i>x</i> − 2) : on remplace, 0/0, forme indéterminée ; en factorisant, (<i>x</i> − 2)(<i>x</i> + 2)/(<i>x</i> − 2) = <i>x</i> + 2 → 4. Même apparence au départ, deux traitements différents.</p></div><div class="warn"><p>« Indéterminé » ne signifie pas « la limite n’existe pas » : (<i>x</i>² − 4)/(<i>x</i> − 2) a bien une limite, 4. Cela signifie seulement que la règle de calcul ne suffit pas et qu’il faut travailler.</p></div>'},
 {kind:'Méthode',h:'Forme 0/0 en un point : factoriser par (x − a)',p:'<b>Quand :</b> une fraction de polynômes vaut 0/0 en <i>x</i> = <i>a</i>. <b>Pourquoi ça marche :</b> si un polynôme s’annule en <i>a</i>, il se factorise par (<i>x</i> − <i>a</i>). Ce facteur commun, responsable du 0/0, se simplifie, car on regarde <i>x</i> ≠ <i>a</i>. <b>Comment :</b> factorise le haut et le bas (identités remarquables, racines du trinôme), simplifie par (<i>x</i> − <i>a</i>), puis remplace <i>x</i> par <i>a</i>.',
  demo:{enonce:`Calculer lim<sub>x→2</sub> ${F('<i>x</i>² + <i>x</i> − 6','<i>x</i>² − 4')}.`,
   etapes:[
    {f:'En 2 : 4 + 2 − 6 = 0 et 4 − 4 = 0, forme 0/0',w:'On remplace d’abord : si ce n’était pas 0/0, la limite serait directe.'},
    {f:'<i>x</i>² + <i>x</i> − 6 = (<i>x</i> − 2)(<i>x</i> + 3) et <i>x</i>² − 4 = (<i>x</i> − 2)(<i>x</i> + 2)',w:'2 est racine des deux : le trinôme a pour autre racine −3 (produit des racines −6), et le bas est une différence de carrés.'},
    {f:`Pour <i>x</i> ≠ 2 : ${F('<i>x</i> + 3','<i>x</i> + 2')}`,w:'On simplifie par <i>x</i> − 2, qui n’est pas nul puisque <i>x</i> ≠ 2.'},
    {f:'→ 5/4',w:'Plus d’indétermination : on remplace <i>x</i> par 2.'}],
   conclusion:'La limite vaut 5/4.'}},
 {h:'Une forme 0/0',p:`Calcule lim<sub>x→2</sub> ${F('<i>x</i>² − 4','<i>x</i> − 2')}.`,lab:'L =',ans:4,
  why:'Pour x ≠ 2, (x² − 4)/(x − 2) = (x − 2)(x + 2)/(x − 2) = x + 2, qui tend vers 4.'},
 {kind:'Méthode',h:'0/0 avec une racine : le conjugué',p:'<b>Quand :</b> la forme 0/0 vient d’une différence comme √<i>x</i> − 2 ou √(1 + <i>x</i>) − 1 : on ne peut pas factoriser par (<i>x</i> − <i>a</i>) directement. <b>Pourquoi ça marche :</b> (√<i>A</i> − <i>B</i>)(√<i>A</i> + <i>B</i>) = <i>A</i> − <i>B</i>², sans racine ; le facteur (<i>x</i> − <i>a</i>) apparaît alors et se simplifie. <b>Comment :</b> multiplie en haut et en bas par le conjugué, développe le côté qui le contient, simplifie, puis remplace.',
  demo:{enonce:`Calculer lim<sub>x→0</sub> ${F('√(1 + <i>x</i>) − 1','<i>x</i>')}.`,
   etapes:[
    {f:'En 0 : (1 − 1)/0, forme 0/0',w:'Le numérateur contient une racine : on pense au conjugué.'},
    {f:`= ${F('(√(1 + <i>x</i>) − 1)(√(1 + <i>x</i>) + 1)','<i>x</i>(√(1 + <i>x</i>) + 1)')}`,w:'On multiplie en haut et en bas par √(1 + <i>x</i>) + 1.'},
    {f:`= ${F('1 + <i>x</i> − 1','<i>x</i>(√(1 + <i>x</i>) + 1)')} = ${F('1','√(1 + <i>x</i>) + 1')}`,w:'(<i>a</i> − <i>b</i>)(<i>a</i> + <i>b</i>) = <i>a</i>² − <i>b</i>², puis on simplifie par <i>x</i> ≠ 0.'},
    {f:'→ 1/(1 + 1) = 1/2',w:'On remplace <i>x</i> par 0.'}],
   conclusion:'La limite vaut 1/2.'}},
 {h:'À toi',p:`Calcule lim<sub>x→4</sub> ${F('√<i>x</i> − 2','<i>x</i> − 4')}.`,lab:'L =',ans:.25,tol:1e-9,
  why:'Avec le conjugué : (√x − 2)(√x + 2) = x − 4. Donc le quotient vaut 1/(√x + 2) pour x ≠ 4, qui tend vers 1/4.'},
 {kind:'Méthode',h:'Forme « nombre / 0 » : regarder le signe',p:'<b>Quand :</b> le numérateur tend vers un nombre <i>k</i> ≠ 0 et le dénominateur vers 0. Ce n’est <b>pas</b> une forme indéterminée. <b>Pourquoi :</b> diviser par un nombre de plus en plus petit donne un résultat de plus en plus grand en valeur absolue : la limite est +∞ ou −∞. <b>Comment :</b> cherche le signe du dénominateur près du point (0⁺ s’il est positif, 0⁻ s’il est négatif), puis applique la règle des signes. Souvent il faut séparer la gauche et la droite.',
  demo:{enonce:`Étudier lim ${F('<i>x</i> + 2','<i>x</i> − 1')} quand <i>x</i> → 1⁺ et quand <i>x</i> → 1⁻.`,
   etapes:[
    {f:'<i>x</i> + 2 → 3 et <i>x</i> − 1 → 0',w:'Forme 3/0 : la limite sera infinie, reste à trouver le signe.'},
    {f:'Si <i>x</i> &gt; 1, <i>x</i> − 1 &gt; 0 : le dénominateur tend vers 0⁺',w:'À droite de 1, <i>x</i> − 1 est positif.'},
    {f:'3/0⁺ : lim<sub>x→1⁺</sub> = +∞',w:'Positif divisé par un petit positif.'},
    {f:'Si <i>x</i> &lt; 1, <i>x</i> − 1 → 0⁻ : lim<sub>x→1⁻</sub> = −∞',w:'Positif divisé par un petit négatif.'}],
   conclusion:'La droite <i>x</i> = 1 est une asymptote verticale ; la courbe part vers +∞ à droite et vers −∞ à gauche.'}},
 {h:'Le signe du zéro',p:`Que vaut lim ${F('2<i>x</i>','<i>x</i> − 3')} quand <i>x</i> → 3⁻&nbsp;?`,opts:['+∞','−∞','2/3','0'],ans:1,
  why:'Le numérateur tend vers 6 &gt; 0. Pour x &lt; 3, x − 3 &lt; 0 tend vers 0⁻. 6/0⁻ donne −∞.'},
 {kind:'Théorie',h:'Limites à l’infini',p:'<p>Que devient (2<i>x</i> + 1)/(<i>x</i> − 3) quand <i>x</i> devient immense ? En <i>x</i> = 1000 : 2001/997 ≈ 2,007. En <i>x</i> = 10⁶ : ≈ 2,000007. La courbe se colle à une droite horizontale.</p><div class="def"><p><b>lim<sub>x→+∞</sub> f(x) = <i>L</i></b> signifie que f(x) est aussi proche de <i>L</i> qu’on veut dès que <i>x</i> est assez grand (pour tout ε &gt; 0, il existe <i>A</i> tel que <i>x</i> &gt; <i>A</i> ⇒ |f(x) − <i>L</i>| &lt; ε). Si cette limite <i>L</i> est finie, la droite <b><i>y</i> = <i>L</i></b> est une <b>asymptote horizontale</b> de la courbe en +∞. Même définition en −∞, avec <i>x</i> &lt; −<i>A</i>.</p></div><div class="prop"><p>Pour un quotient de polynômes en ±∞, <b>seuls les termes de plus haut degré comptent</b> : on met le terme dominant en facteur en haut et en bas, exactement comme pour les suites. Même degré : la limite est le quotient des coefficients dominants. Degré du haut plus petit : limite 0. Degré du haut plus grand : limite ±∞.</p></div><div class="why"><p>(2<i>x</i> + 1)/(<i>x</i> − 3) = <i>x</i>(2 + 1/<i>x</i>)/(<i>x</i>(1 − 3/<i>x</i>)) = (2 + 1/<i>x</i>)/(1 − 3/<i>x</i>). Quand <i>x</i> → ±∞, 1/<i>x</i> et 3/<i>x</i> tendent vers 0 : il reste 2/1 = 2. Les termes de bas degré deviennent négligeables devant <i>x</i>.</p></div><div class="ex"><p>Sur la figure, la courbe de (2<i>x</i> + 1)/(<i>x</i> − 3) se rapproche de <i>y</i> = 2 des deux côtés : par au-dessus en +∞, car f(x) − 2 = 7/(<i>x</i> − 3) &gt; 0, et par en dessous en −∞. La droite verticale <i>x</i> = 3 est une autre asymptote, verticale, liée à la forme 7/0.</p></div><div class="warn"><p>En −∞, attention aux signes des puissances impaires : <i>x</i>³ → −∞ alors que <i>x</i>² → +∞. Et une courbe peut traverser son asymptote horizontale : elle s’en rapproche à l’infini, rien ne l’empêche de la couper avant.</p></div>',
  fig:(()=>{ const P=plane({x:[-6,10],y:[-5,9],w:300,lab:2}); P.seg(-6,2,10,2,{c:'var(--ok)',w:1.5,dash:true}).seg(3,-5,3,9,{c:'var(--muted)',w:1.5,dash:true});
    P.fn(x=>(2*x+1)/(x-3),{from:-6,to:2.9}).fn(x=>(2*x+1)/(x-3),{from:3.1,to:10}).text(9.5,2,'y = 2',{a:'end',dy:-8,c:'var(--ok)'}); return P.svg(); })()},
 {h:'À l’infini',p:`Que vaut lim<sub>x→−∞</sub> ${F('<i>x</i>³ − 2<i>x</i>','1 − 4<i>x</i>³')}&nbsp;?`,opts:['1/4','−∞','0','−1/4'],ans:3,
  why:'Les termes dominants sont x³ et −4x³ : le quotient tend vers 1/(−4) = −1/4, en +∞ comme en −∞.'},
 {kind:'Méthode',h:'Croissances comparées',p:'<b>Quand :</b> une forme indéterminée mélange exponentielle, puissance et logarithme, comme <i>x</i>³/eˣ ou (ln <i>x</i>)/<i>x</i>. <b>Le résultat :</b> en +∞, <b>l’exponentielle l’emporte sur toute puissance</b>, et <b>toute puissance l’emporte sur le logarithme</b> : <i>x</i>ⁿ/eˣ → 0, eˣ/<i>x</i>ⁿ → +∞, (ln <i>x</i>)/<i>x</i>ᵃ → 0 pour <i>a</i> &gt; 0. En 0⁺, <i>x</i> ln <i>x</i> → 0. <b>Comment :</b> repère le terme le plus fort, mets-le en facteur, et fais apparaître ces quotients connus.',
  demo:{enonce:`Calculer lim<sub>x→+∞</sub> ${F('<i>x</i>³ + eˣ','2eˣ − <i>x</i>')}.`,
   etapes:[
    {f:'Forme ∞/∞',w:'Haut et bas tendent vers +∞.'},
    {f:'Le terme le plus fort est eˣ, en haut comme en bas',w:'L’exponentielle domine <i>x</i>³ et <i>x</i>.'},
    {f:`= ${F('eˣ(<i>x</i>³/eˣ + 1)','eˣ(2 − <i>x</i>/eˣ)')} = ${F('<i>x</i>³/eˣ + 1','2 − <i>x</i>/eˣ')}`,w:'On factorise eˣ et on simplifie.'},
    {f:'<i>x</i>³/eˣ → 0 et <i>x</i>/eˣ → 0',w:'Croissances comparées.'}],
   conclusion:'La limite vaut 1/2.'}},
 {h:'Qui domine&nbsp;?',p:`Calcule lim<sub>x→+∞</sub> ${F('ln <i>x</i> + 3<i>x</i>','<i>x</i> + 1')}.`,lab:'L =',ans:3,
  why:'On factorise x : (ln x/x + 3)/(1 + 1/x). Or ln x/x → 0 par croissances comparées, donc la limite vaut 3.'},
 {kind:'Théorie',h:'Infiniment petits équivalents',p:'<p>Près de 0, sin <i>x</i> et <i>x</i> sont presque indiscernables : sin 0,1 ≈ 0,09983. Cette ressemblance est un outil de calcul puissant, à condition de dire exactement ce que « presque » veut dire.</p><div class="def"><p>Deux fonctions f et g sont <b>équivalentes en 0</b>, noté <b>f ~ g</b>, si <b>f(x)/g(x) → 1</b> quand <i>x</i> → 0. Quand de plus f et g tendent vers 0, on parle d’<b>infiniment petits équivalents</b>. Les quatre à connaître : <b>sin <i>x</i> ~ <i>x</i></b>, <b>ln(1 + <i>x</i>) ~ <i>x</i></b>, <b>eˣ − 1 ~ <i>x</i></b>, <b>1 − cos <i>x</i> ~ <i>x</i>²/2</b>.</p></div><div class="idea"><p>f ~ g ne dit pas que f − g est petit (deux quantités qui tendent vers 0 ont toujours une différence petite), mais que leur <b>rapport</b> tend vers 1 : f vaut g à 1 % près, puis à 0,1 % près, … Sur la figure, la courbe en trait plein et celle en pointillé se confondent près de 0 ; choisis une autre paire et rapproche <i>x</i> de 0 pour voir le quotient tendre vers 1.</p></div><div class="ex"><p>En <i>x</i> = 0,1 : sin(0,1)/0,1 ≈ 0,9983 ; en <i>x</i> = 0,01 : ≈ 0,99998. Pour 1 − cos <i>x</i> en <i>x</i> = 0,1 : 1 − cos 0,1 ≈ 0,0049958 et <i>x</i>²/2 = 0,005, rapport ≈ 0,9992. Ces quatre équivalents sont les plus utiles parce que sin, ln, exp et cos apparaissent partout dans les formes 0/0.</p></div><div class="warn"><p>Les équivalents ne valent qu’<b>au point considéré</b> : sin <i>x</i> ~ <i>x</i> en 0, pas en π. Et ils se composent : si u(x) → 0, alors sin(u(x)) ~ u(x). Avec u = 3<i>x</i> : sin(3<i>x</i>) ~ 3<i>x</i>.</p></div>',
  params:[{id:'k',l:'Équivalent',min:0,max:3,v:0},{id:'x',l:'x',min:-.9,max:1.5,step:.1,v:1.2}],
  draw:v=>{ const f=[Math.sin,x=>Math.log(1+x),x=>Math.exp(x)-1,x=>1-Math.cos(x)][v.k], g=v.k===3?x=>x*x/2:x=>x;
    const P=plane({x:[-1,2],y:[-1.2,1.8],w:320,step:.5,lab:1}); P.fn(g,{c:'var(--muted)',w:2.5,dash:true}).fn(f,{from:v.k===1?-.95:-1});
    P.dot(v.x,f(v.x),{r:5}).dot(v.x,g(v.x),{r:5,c:'var(--muted)'}); return P.svg(); },
  info:v=>{ const n=['sin x','ln(1 + x)','eˣ − 1','1 − cos x'][v.k], m=v.k===3?'x²/2':'x', f=[Math.sin,x=>Math.log(1+x),x=>Math.exp(x)-1,x=>1-Math.cos(x)][v.k], g=v.k===3?x=>x*x/2:x=>x;
    return Math.abs(v.x)<1e-9?`${n} ~ ${m} : en x = 0 le quotient n’est pas défini, sa limite vaut 1.`:`${n} ~ ${m} · quotient en x = ${fmt(v.x,1)} : ${fmt(f(v.x)/g(v.x),4)}`; }},
 {kind:'Théorie',h:'D’où viennent les quatre équivalents',p:'<p>Pourquoi sin <i>x</i> ressemble-t-il à <i>x</i>, et 1 − cos <i>x</i> à <i>x</i>²/2 plutôt qu’à <i>x</i> ? Les quatre équivalents ne sont pas des formules magiques : chacun a une raison géométrique ou algébrique.</p><div class="why"><p><b>sin <i>x</i> ~ <i>x</i></b> : sur le cercle de rayon 1, un arc d’angle <i>x</i> (en radians) a pour longueur <i>x</i>, et sin <i>x</i> est la hauteur de son extrémité. Pour 0 &lt; <i>x</i> &lt; π/2, en comparant les aires du petit triangle, du secteur et du grand triangle, on obtient sin <i>x</i> &lt; <i>x</i> &lt; tan <i>x</i>, donc cos <i>x</i> &lt; (sin <i>x</i>)/<i>x</i> &lt; 1 ; les gendarmes concluent puisque cos <i>x</i> → 1. <b>1 − cos <i>x</i> ~ <i>x</i>²/2</b> : la formule 1 − cos <i>x</i> = 2 sin²(<i>x</i>/2) et sin(<i>x</i>/2) ~ <i>x</i>/2 donnent 2(<i>x</i>/2)² = <i>x</i>²/2.</p></div><div class="why"><p><b>eˣ − 1 ~ <i>x</i></b> : eˣ = lim (1 + <i>x</i>/<i>n</i>)ⁿ, et pour <i>x</i> petit, eˣ ≈ 1 + <i>x</i> au premier ordre ; c’est dire que la tangente à l’exponentielle en 0 a pour pente 1. <b>ln(1 + <i>x</i>) ~ <i>x</i></b> : si l’on pose <i>y</i> = ln(1 + <i>x</i>), alors <i>x</i> = e<sup>y</sup> − 1 ~ <i>y</i>, et <i>y</i> → 0 quand <i>x</i> → 0 ; les deux équivalents sont le même, lu dans l’autre sens.</p></div><div class="idea"><p>Tous les équivalents « d’ordre 1 » disent la même chose : près de 0, la courbe se confond avec sa tangente. Pour 1 − cos <i>x</i>, la tangente en 0 est horizontale (le terme d’ordre 1 est nul), et il faut descendre à l’ordre 2 : la courbe ressemble à une parabole. Voilà pourquoi cet équivalent est en <i>x</i>².</p></div><div class="ex"><p>Vérification numérique en <i>x</i> = 0,01 : e<sup>0,01</sup> − 1 ≈ 0,010050 et ln(1,01) ≈ 0,009950. Les deux valent <i>x</i> à 0,5 % près, l’un un peu au-dessus, l’autre un peu en dessous.</p></div>'},
 {kind:'Méthode',h:'Calculer une limite avec les équivalents',p:'<b>Quand :</b> forme 0/0 en 0 avec sin, ln(1 + …), e<sup>…</sup> − 1 ou 1 − cos. <b>Pourquoi ça marche :</b> si f ~ g, alors f = g · (f/g) avec f/g → 1 : dans un <b>produit</b> ou un <b>quotient</b>, remplacer f par g ne change pas la limite. <b>Comment :</b> vérifie que ce qui est à l’intérieur tend vers 0 (u = 3<i>x</i>, u = <i>x</i>², …), remplace chaque facteur par son équivalent avec ce u, simplifie, puis passe à la limite.',
  demo:{enonce:`Calculer lim<sub>x→0</sub> ${F('ln(1 + 2<i>x</i>)','sin(5<i>x</i>)')}.`,
   etapes:[
    {f:'En 0 : ln 1 / sin 0 = 0/0',w:'Forme indéterminée.'},
    {f:'u = 2<i>x</i> → 0, donc ln(1 + 2<i>x</i>) ~ 2<i>x</i>',w:'ln(1 + u) ~ u avec u = 2<i>x</i>.'},
    {f:'v = 5<i>x</i> → 0, donc sin(5<i>x</i>) ~ 5<i>x</i>',w:'sin v ~ v avec v = 5<i>x</i>.'},
    {f:`${F('ln(1 + 2<i>x</i>)','sin(5<i>x</i>)')} ~ ${F('2<i>x</i>','5<i>x</i>')} = ${F('2','5')}`,w:'Le haut et le bas sont des facteurs : on a le droit de les remplacer.'}],
   conclusion:'La limite vaut 2/5.'},
  note:'Jamais dans une somme : sin <i>x</i> − <i>x</i> n’est pas « équivalent à 0 ».'},
 {h:'Utilise sin x ~ x',p:`Calcule lim<sub>x→0</sub> ${F('sin(3<i>x</i>)','<i>x</i>')}.`,lab:'L =',ans:3,
  why:'Quand x → 0, 3x → 0, donc sin(3x) ~ 3x. Le quotient se comporte comme 3x/x = 3.'},
 {h:'Utilise 1 − cos x ~ x²/2',p:`Calcule lim<sub>x→0</sub> ${F('1 − cos(2<i>x</i>)','<i>x</i>²')}.`,lab:'L =',ans:2,
  why:'1 − cos(2x) ~ (2x)²/2 = 2x². Le quotient tend vers 2x²/x² = 2.'},
 {kind:'Défi',h:'Combiner les équivalents',p:`Calcule lim<sub>x→0</sub> ${F('e<sup><i>x</i>²</sup> − 1','<i>x</i> · sin(4<i>x</i>)')}.`,lab:'L =',ans:.25,tol:1e-9,
  why:'En haut, eᵘ − 1 ~ u avec u = x² : ~ x². En bas, sin(4x) ~ 4x, donc x·sin(4x) ~ 4x². Limite : x²/(4x²) = 1/4.',
  note:'On peut remplacer un <b>facteur</b> par son équivalent, jamais un terme d’une somme : sin x − x n’est pas équivalent à 0.'},
 {kind:'Méthode',h:'Changement de variable dans une limite',p:'<b>Quand :</b> la même expression revient plusieurs fois, ou une limite en +∞ cache une limite connue en 0, comme sin(1/<i>x</i>). <b>Pourquoi ça marche :</b> si <i>u</i>(<i>x</i>) → <i>b</i> quand <i>x</i> → <i>a</i>, et si g(u) → <i>L</i> quand u → <i>b</i>, alors g(<i>u</i>(<i>x</i>)) → <i>L</i>. <b>Comment :</b> pose u, trouve vers quoi il tend, réécris toute l’expression avec u seul, puis calcule la nouvelle limite.',
  demo:{enonce:'Calculer lim<sub>x→+∞</sub> <i>x</i> sin(1/<i>x</i>).',
   etapes:[
    {f:'Forme ∞ · 0',w:'<i>x</i> → +∞ et sin(1/<i>x</i>) → sin 0 = 0.'},
    {f:'On pose u = 1/<i>x</i> : u → 0⁺ et <i>x</i> = 1/u',w:'On choisit u pour que la limite devienne une limite en 0 qu’on connaît.'},
    {f:`<i>x</i> sin(1/<i>x</i>) = ${F('sin u','u')}`,w:'Toute l’expression s’écrit avec u.'},
    {f:'sin u ~ u, donc (sin u)/u → 1',w:'L’équivalent connu en 0.'}],
   conclusion:'La limite vaut 1.'}},
 {h:'À toi',p:'Calcule lim<sub>x→+∞</sub> <i>x</i> ln(1 + 3/<i>x</i>).',lab:'L =',ans:3,
  why:'Avec u = 3/x → 0⁺, x = 3/u : x ln(1 + 3/x) = 3 ln(1 + u)/u. Or ln(1 + u) ~ u, donc la limite vaut 3.'},
 {kind:'Récapitulatif',h:'Ce qu’il faut retenir : limites de fonctions',p:'<div class="keep"><ul><li><b>lim<sub>x→a</sub> f(x) = <i>L</i></b> : f(x) aussi proche de <i>L</i> qu’on veut pour <i>x</i> assez proche de <i>a</i>, <i>x</i> ≠ <i>a</i>. La limite existe si et seulement si les limites <b>à gauche</b> et <b>à droite</b> existent et sont égales.</li><li><b>Première étape</b> : remplacer. Un nombre : fini. <i>k</i>/0 avec <i>k</i> ≠ 0 : ±∞, chercher le signe du dénominateur (0⁺ ou 0⁻), souvent côté par côté. Forme indéterminée (0/0, ∞/∞, 0 · ∞, ∞ − ∞, 1<sup>∞</sup>) : transformer.</li><li><b>0/0 avec des polynômes</b> : factoriser par (<i>x</i> − <i>a</i>) et simplifier. <b>0/0 avec une racine</b> : multiplier par le conjugué.</li><li><b>À l’infini</b> : terme dominant en facteur ; pour un quotient de polynômes, comparer les degrés. Limite finie <i>L</i> ⇒ asymptote horizontale <i>y</i> = <i>L</i>. Limite infinie en <i>a</i> ⇒ asymptote verticale <i>x</i> = <i>a</i>.</li><li><b>Croissances comparées</b> en +∞ : eˣ l’emporte sur <i>x</i>ⁿ, qui l’emporte sur ln <i>x</i> : <i>x</i>ⁿ/eˣ → 0 et (ln <i>x</i>)/<i>x</i>ᵃ → 0 ; en 0⁺, <i>x</i> ln <i>x</i> → 0.</li><li><b>Équivalents en 0</b> : sin <i>x</i> ~ <i>x</i>, ln(1 + <i>x</i>) ~ <i>x</i>, eˣ − 1 ~ <i>x</i>, 1 − cos <i>x</i> ~ <i>x</i>²/2 ; valables avec u(x) → 0 à la place de <i>x</i>. On remplace un <b>facteur</b>, jamais un terme d’une somme.</li><li><b>Changement de variable</b> u = 1/<i>x</i> (ou autre) pour ramener une limite en ∞ à une limite connue en 0.</li></ul></div>'},
 {kind:'Problème',h:'La flèche d’un pont en arc',
  p:'Un pont suit un arc de cercle de rayon <i>R</i> = 40 m, qui intercepte un angle au centre θ (en radians). L’arc mesure <i>R</i>θ, la corde qui joint ses extrémités mesure 2<i>R</i> sin(θ/2), et la <b>flèche</b> (hauteur de l’arc au-dessus de la corde) vaut <i>h</i> = <i>R</i>(1 − cos(θ/2)). Pour un arc très plat, θ est petit : on utilise les équivalents.',
  fig:(()=>{ const P=plane({x:[-4,4],y:[-2.8,2],h:220,grid:false,axes:false}), a=rad(50), ex=4*Math.sin(a), ey=-2.5+4*Math.cos(a);
    P.curve(t=>4*Math.sin(t),t=>-2.5+4*Math.cos(t),-a,a,{c:'var(--accent)',w:3}).seg(-ex,ey,ex,ey,{c:'var(--spark)',w:2})
     .seg(0,-2.5,-ex,ey,{c:'var(--muted)',w:1.2,dash:true}).seg(0,-2.5,ex,ey,{c:'var(--muted)',w:1.2,dash:true}).seg(0,ey,0,1.5,{c:'var(--math)',w:2.5})
     .dot(0,-2.5,{r:3,c:'var(--ink)'}).text(0,-2.5,'θ',{a:'middle',dy:-14}).text(0,.8,'h',{dx:6,c:'var(--math)'}).text(1.6,ey,'corde',{dy:16,c:'var(--spark)'}).text(2.2,1.2,'arc Rθ',{c:'var(--accent)'}); return P.svg(); })(),
  parts:[
   {q:'a) Que vaut la limite de corde/arc = 2<i>R</i> sin(θ/2)/(<i>R</i>θ) quand θ → 0&nbsp;?',lab:'L =',ans:1,hint:'sin <i>u</i> ~ <i>u</i> avec <i>u</i> = θ/2.',why:'2R sin(θ/2) ~ 2R · θ/2 = Rθ, donc le quotient tend vers 1 : pour un arc plat, la corde et l’arc ont presque la même longueur.'},
   {q:'b) Avec <i>R</i> = 40 m, que vaut lim <i>h</i>/θ² quand θ → 0&nbsp;?',lab:'L =',unit:'m',ans:5,hint:'1 − cos <i>u</i> ~ <i>u</i>²/2 avec <i>u</i> = θ/2.',why:'h = R(1 − cos(θ/2)) ~ R(θ/2)²/2 = Rθ²/8. Donc h/θ² → R/8 = 40/8 = 5 m.'},
   {q:'c) Pour θ = 0,1 rad, estime la flèche <i>h</i> avec cet équivalent, en cm.',lab:'h ≈',unit:'cm',ans:5,tol:.011,hint:'<i>h</i> ≈ 5θ² (en m).',why:'h ≈ 5 · 0,1² = 0,05 m = 5 cm. La valeur exacte 40(1 − cos 0,05) ≈ 4,999 cm confirme l’approximation.'},
  ],
  sol:'Quand θ → 0, u = θ/2 → 0, donc sin u ~ u et 1 − cos u ~ u²/2.<br>Corde : 2R sin(θ/2) ~ Rθ, donc corde/arc → 1.<br>Flèche : h = R(1 − cos(θ/2)) ~ R · (θ/2)²/2 = Rθ²/8. Avec R = 40 m, h ~ 5θ², donc h/θ² → 5 m.<br>Pour θ = 0,1 : h ≈ 5 · 0,01 = 0,05 m = 5 cm. L’arc mesure alors 4 m : un arc de 4 m sur un cercle de 40 m ne s’élève que de 5 cm au-dessus de sa corde.<br>La flèche est un infiniment petit d’ordre 2 en θ, alors que l’arc et la corde sont d’ordre 1.'},
 {kind:'Problème',h:'Quatre limites, un piège',
  p:'Les équivalents marchent aussi en +∞ : si <i>u</i>(<i>x</i>) → 0, on peut remplacer sin <i>u</i> par <i>u</i>, e<sup><i>u</i></sup> − 1 par <i>u</i>, etc. On calcule trois limites en repérant les facteurs à remplacer. Puis on examine le raisonnement d’un élève qui a utilisé les équivalents trop vite.',
  parts:[
   {q:`a) Calcule lim<sub>x→0</sub> ${F('ln(1 + 3<i>x</i>) · sin(2<i>x</i>)','1 − cos <i>x</i>')}.`,lab:'L =',ans:12,hint:'Remplace chacun des trois facteurs par son équivalent.',why:'ln(1 + 3x) ~ 3x, sin(2x) ~ 2x, 1 − cos x ~ x²/2. Le quotient ~ 6x²/(x²/2) = 12.'},
   {q:'b) Calcule lim<sub>x→+∞</sub> <i>x</i>²(1 − cos(1/<i>x</i>)).',lab:'L =',ans:.5,tol:1e-9,hint:'Pose <i>u</i> = 1/<i>x</i>, qui tend vers 0.',why:'1 − cos(1/x) ~ (1/x)²/2 = 1/(2x²). Donc x² · 1/(2x²) = 1/2.'},
   {q:'c) Calcule lim<sub>x→+∞</sub> <i>x</i>(e<sup>2/<i>x</i></sup> − 1).',lab:'L =',ans:2,hint:'Forme ∞ · 0. Avec <i>u</i> = 2/<i>x</i> → 0, e<sup><i>u</i></sup> − 1 ~ <i>u</i>.',why:'e<sup>2/x</sup> − 1 ~ 2/x, donc x · 2/x = 2.'},
   {q:'d) Un élève écrit : « e<sup><i>x</i></sup> − 1 ~ <i>x</i>, donc (e<sup><i>x</i></sup> − 1 − <i>x</i>)/<i>x</i>² ~ (<i>x</i> − <i>x</i>)/<i>x</i>² = 0 ». Qu’en penses-tu&nbsp;?',opts:['C’est juste : la limite vaut 0','C’est faux, car e<sup><i>x</i></sup> − 1 n’est pas équivalent à <i>x</i>','C’est juste, mais la limite vaut +∞','C’est faux : il a remplacé un terme d’une somme. L’équivalent ne dit rien de e<sup><i>x</i></sup> − 1 − <i>x</i> (la vraie limite vaut 1/2)'],ans:3,hint:'Relis la règle : on remplace un facteur, jamais un terme d’une somme.',why:'eˣ − 1 ~ x est vrai, mais eˣ − 1 − x est une différence de deux quantités équivalentes : son comportement dépend du terme suivant (x²/2). Numériquement, en x = 0,001, le quotient vaut environ 0,5002.'},
  ],
  sol:'a) Trois facteurs, trois équivalents : ln(1 + 3x) ~ 3x, sin 2x ~ 2x, 1 − cos x ~ x²/2. Limite : 6x²/(x²/2) = 12.<br>b) Avec u = 1/x → 0⁺ : 1 − cos u ~ u²/2, donc x²(1 − cos(1/x)) ~ x² · 1/(2x²) → 1/2.<br>c) Avec u = 2/x → 0 : eᵘ − 1 ~ u, donc x(e<sup>2/x</sup> − 1) ~ x · 2/x = 2.<br>d) L’élève remplace un terme d’une somme : eˣ − 1 − x est la différence de deux quantités équivalentes, elle est « plus petite » que chacune et les équivalents d’ordre 1 ne la voient pas. Il faut un développement plus fin (eˣ = 1 + x + x²/2 + …), qui donne la limite 1/2.'},
]},

{subj:'an1', sem:'aut', id:'an1-derivee', h:'Continuité et dérivabilité', p:'Continuité et prolongement, la dérivée comme limite du taux d’accroissement, et les règles de dérivation.', steps:[
 {kind:'Théorie',h:'Continuité',p:'<p>Quand on trace <i>y</i> = <i>x</i>² ou <i>y</i> = sin <i>x</i>, le crayon ne quitte pas la feuille. Quand on trace la fonction « partie entière », il saute à chaque entier. La continuité est la traduction mathématique de « sans saut ».</p><div class="def"><p><i>f</i>, définie autour de <i>a</i>, est <b>continue en <i>a</i></b> si <b>lim<sub>x→a</sub> f(x) = f(a)</b> : la limite existe <b>et</b> vaut la valeur de la fonction. Elle est <b>continue sur un intervalle</b> si elle l’est en chaque point. Si <i>f</i> n’est pas définie en <i>a</i> mais y a une limite finie <i>L</i>, on la <b>prolonge par continuité</b> en posant f(a) = L : la fonction prolongée est continue en <i>a</i>.</p></div><div class="idea"><p>Trois choses peuvent casser la continuité en <i>a</i> : la fonction n’y est pas définie (un trou), elle y est définie mais la limite n’existe pas (un saut : limites à gauche et à droite différentes), ou la limite existe mais ne vaut pas f(a) (un point déplacé). Les fonctions usuelles (polynômes, fractions rationnelles, racines, sin, cos, exp, ln, |<i>x</i>|) sont continues partout où elles sont définies, et les sommes, produits, quotients et composées de fonctions continues le restent.</p></div><div class="ex"><p>f(x) = (sin <i>x</i>)/<i>x</i> n’est pas définie en 0 (la figure), mais sin <i>x</i> ~ <i>x</i> donne f(x) → 1. En posant f(0) = 1, on bouche le trou : la fonction prolongée est continue sur ℝ. Autre exemple : (<i>x</i>² − 9)/(<i>x</i> − 3) = <i>x</i> + 3 pour <i>x</i> ≠ 3 se prolonge par f(3) = 6.</p></div><div class="warn"><p>Un prolongement n’est possible que si la limite est <b>finie</b> : 1/<i>x</i> n’a pas de prolongement continu en 0. Et une fonction peut être définie en un point sans y être continue : la définition exige que la limite soit égale à f(a), pas seulement qu’elle existe.</p></div>',
  fig:(()=>{ const P=plane({x:[-10,10],y:[-.5,1.3],h:150,grid:false,lx:5}); P.fn(x=>Math.abs(x)<1e-9?1:Math.sin(x)/x).circ(0,1,.25,{c:'var(--accent)',w:2,fill:'var(--surface)',fo:1}).text(0,1,'sin x / x → 1',{dx:12,dy:-6}); return P.svg(); })(),
  note:'Sur la figure, le cercle vide en (0 ; 1) marque le trou que le prolongement vient boucher.'},
 {kind:'Théorie',h:'Ce que garantit la continuité : les valeurs intermédiaires',p:'<p>À 8 h, il fait 5 °C ; à midi, 15 °C. Y a-t-il eu un instant où il faisait exactement 10 °C ? Oui, parce que la température ne saute pas. Ce raisonnement « évident » est un théorème, et il repose entièrement sur la continuité.</p><div class="thm"><p><b>Théorème des valeurs intermédiaires.</b> Si <i>f</i> est continue sur [<i>a</i> ; <i>b</i>], alors pour tout nombre <i>k</i> compris entre f(a) et f(b), il existe au moins un <i>c</i> ∈ [<i>a</i> ; <i>b</i>] tel que <b>f(c) = k</b>. Cas particulier : si f(a) et f(b) sont de signes contraires, <i>f</i> s’annule au moins une fois entre <i>a</i> et <i>b</i>.</p></div><div class="why"><p>Idée : la courbe part d’un côté de la droite <i>y</i> = <i>k</i> et arrive de l’autre côté sans lever le crayon ; elle doit donc traverser la droite. La preuve rigoureuse coupe l’intervalle en deux, garde la moitié où le changement de signe a lieu, et recommence : les intervalles rétrécissent vers un point <i>c</i> où f(c) = k, grâce aux propriétés de ℝ.</p></div><div class="ex"><p>f(x) = <i>x</i>³ + <i>x</i> − 1 est continue, f(0) = −1 &lt; 0 et f(1) = 1 &gt; 0 : l’équation <i>x</i>³ + <i>x</i> − 1 = 0 a une solution dans ]0 ; 1[. En coupant : f(0,5) = −0,375 &lt; 0, donc la solution est dans ]0,5 ; 1[ ; f(0,75) ≈ 0,172 &gt; 0, donc dans ]0,5 ; 0,75[. On la localise aussi précisément qu’on veut (elle vaut ≈ 0,6823).</p></div><div class="warn"><p>Sans continuité, le théorème tombe : la fonction qui vaut −1 pour <i>x</i> &lt; 0 et 1 pour <i>x</i> ≥ 0 change de signe sans jamais s’annuler. Et le théorème donne l’<b>existence</b> d’un <i>c</i>, pas son unicité : il peut y en avoir plusieurs. Pour l’unicité, il faut en plus que <i>f</i> soit strictement monotone.</p></div>'},
 {kind:'Méthode',h:'Continuité d’une fonction définie par morceaux',p:'<b>Quand :</b> <i>f</i> a une formule à gauche d’un point <i>a</i> et une autre à droite. Chaque formule est continue sur son morceau ; seul le point de raccord pose question. <b>Pourquoi ça marche :</b> la limite en <i>a</i> existe si et seulement si les limites à gauche et à droite sont égales, et la continuité demande en plus qu’elles valent f(<i>a</i>). <b>Comment :</b> calcule f(<i>a</i>) avec la bonne formule, la limite de l’autre côté, et écris leur égalité.',
  demo:{enonce:'f(x) = <i>ax</i> + 1 si <i>x</i> &lt; 2 et f(x) = <i>x</i>² − 1 si <i>x</i> ≥ 2. Pour quelle valeur de <i>a</i> la fonction est-elle continue en 2&nbsp;?',
   etapes:[
    {f:'f(2) = 2² − 1 = 3',w:'En <i>x</i> = 2, c’est la seconde formule qui s’applique (<i>x</i> ≥ 2). Elle donne aussi la limite à droite.'},
    {f:'lim<sub>x→2⁻</sub> f(x) = 2<i>a</i> + 1',w:'À gauche, on prend la formule <i>ax</i> + 1, continue, et on remplace <i>x</i> par 2.'},
    {f:'2<i>a</i> + 1 = 3 ⇔ <i>a</i> = 1',w:'Les deux côtés doivent se rejoindre en f(2).'}],
   conclusion:'Pour <i>a</i> = 1, <i>f</i> est continue en 2 (et donc partout).'},
  note:'Pour la <b>dérivabilité</b> au raccord, on demande en plus que les pentes de gauche et de droite soient égales (dérivée de chaque formule au point <i>a</i>).'},
 {kind:'Pratique',h:'Recolle les morceaux',p:'f(x) = <i>x</i>² + 1 si <i>x</i> ≤ 1 et f(x) = <i>kx</i> − 1 si <i>x</i> &gt; 1. Règle <i>k</i> pour que <i>f</i> soit continue en 1.',
  params:[{id:'k',l:'k',min:-2,max:5,step:.5,v:1}],
  draw:v=>{ const P=plane({x:[-2.5,3.5],y:[-2,6],h:280,lab:1}); P.fn(x=>x*x+1,{from:-2.5,to:1}).fn(x=>v.k*x-1,{from:1,to:3.5,c:'var(--spark)'});
    P.dot(1,2,{r:5,c:'var(--accent)'}); if(v.k!==3) P.circ(1,v.k-1,.09,{c:'var(--spark)',w:2,fill:'var(--surface)',fo:1}); return P.svg(); },
  info:v=>`Limite à gauche : f(1) = 2 · limite à droite : ${fmt(v.k)} − 1 = ${fmt(v.k-1)}`,
  ok:v=>v.k===3,why:'À gauche, f(1) = 1² + 1 = 2. À droite, kx − 1 → k − 1. Continuité : k − 1 = 2, donc k = 3.'},
 {h:'Prolonger',p:`Par quelle valeur faut-il prolonger f(x) = ${F('<i>x</i>² − 9','<i>x</i> − 3')} en <i>x</i> = 3&nbsp;?`,lab:'f(3) =',ans:6,
  why:'Pour x ≠ 3, f(x) = x + 3, qui tend vers 6. On pose f(3) = 6.'},
 {kind:'Théorie',h:'La dérivée, limite des sécantes',p:'<p>Quelle est la pente d’une courbe en un point ? Une droite a une pente, une courbe en change sans arrêt. Pour la mesurer en un point A, on prend un second point B sur la courbe, on calcule la pente de la droite AB, puis on fait glisser B vers A.</p><div class="def"><p>Le <b>taux d’accroissement</b> de <i>f</i> entre <i>a</i> et <i>a</i> + <i>h</i> est <b>(f(a + h) − f(a))/h</b> : c’est la pente de la <b>sécante</b> qui joint les points d’abscisses <i>a</i> et <i>a</i> + <i>h</i>. Si ce taux a une limite finie quand <i>h</i> → 0, <i>f</i> est <b>dérivable en <i>a</i></b> et cette limite est le <b>nombre dérivé</b> <b>f′(a) = lim<sub>h→0</sub> (f(a + h) − f(a))/h</b> (lire « f prime de a »). La droite passant par A de pente f′(a) est la <b>tangente</b>.</p></div><div class="idea"><p>Sur la figure, la sécante (jaune) tourne autour de A quand <i>h</i> diminue, et se stabilise sur la tangente (pointillé vert). La tangente est la droite qui « colle » le mieux à la courbe en A : vue de très près, la courbe ressemble à sa tangente. f′(a) mesure donc la pente de la courbe en A, c’est-à-dire la vitesse à laquelle <i>f</i> varie à cet endroit.</p></div><div class="ex"><p>Pour f(x) = <i>x</i>² en <i>a</i> = 1 : f(1 + <i>h</i>) − f(1) = (1 + <i>h</i>)² − 1 = 2<i>h</i> + <i>h</i>², et le taux vaut 2 + <i>h</i>. Avec <i>h</i> = 1 : pente 3 ; <i>h</i> = 0,5 : 2,5 ; <i>h</i> = 0,1 : 2,1. La limite est 2 : f′(1) = 2, la tangente en (1 ; 1) a pour pente 2. En général, f′(a) = 2<i>a</i>.</p></div><div class="warn"><p>On ne peut pas poser <i>h</i> = 0 dans le taux : ce serait 0/0. La dérivée est une <b>limite</b>, pas une valeur. C’est pourquoi il faut toujours simplifier le taux avant de faire tendre <i>h</i> vers 0.</p></div>',
  params:[{id:'a',l:'a',min:-2,max:2,step:.5,v:1},{id:'h',l:'h',min:-2,max:2,step:.25,v:1.5}],
  draw:v=>{ const f=x=>x*x, P=plane({x:[-4.5,4.5],y:[-1.5,8],h:300,lab:2}); P.fn(f);
    P.fn(x=>f(v.a)+2*v.a*(x-v.a),{c:'var(--ok)',w:2,dash:true});
    if(v.h!==0) P.fn(x=>f(v.a)+(2*v.a+v.h)*(x-v.a),{c:'var(--spark)',w:2.5}).dot(v.a+v.h,f(v.a+v.h),{r:5,c:'var(--spark)'});
    P.dot(v.a,f(v.a),{r:6,c:'var(--ink)',l:'A'}); return P.svg(); },
  info:v=>v.h===0?`h = 0 : on ne peut pas diviser par 0, on passe à la limite. Tangente de pente f′(a) = 2a = ${fmt(2*v.a)}.`:`Taux : ((a + h)² − a²)/h = 2a + h = ${fmt(2*v.a+v.h)} · tangente (pointillé) : 2a = ${fmt(2*v.a)}`},
 {kind:'Méthode',h:'Dériver avec la définition',p:'<b>Quand :</b> on demande f′(<i>a</i>) « par la définition », ou on ne connaît pas encore de règle pour <i>f</i>. <b>Pourquoi ça marche :</b> le taux (f(<i>a</i> + <i>h</i>) − f(<i>a</i>))/<i>h</i> est une forme 0/0 quand <i>h</i> → 0. En simplifiant, on fait apparaître un facteur <i>h</i> au numérateur qui se simplifie avec celui du bas. <b>Comment :</b> écris f(<i>a</i> + <i>h</i>) − f(<i>a</i>), développe ou réduis au même dénominateur, mets <i>h</i> en facteur, simplifie, puis fais <i>h</i> → 0.',
  demo:{enonce:'Calculer f′(2) pour f(x) = 1/<i>x</i>, avec la définition.',
   etapes:[
    {f:`f(2 + <i>h</i>) − f(2) = ${F('1','2 + <i>h</i>')} − ${F('1','2')} = ${F('2 − (2 + <i>h</i>)','2(2 + <i>h</i>)')} = ${F('−<i>h</i>','2(2 + <i>h</i>)')}`,w:'On réduit au même dénominateur : le facteur <i>h</i> apparaît en haut.'},
    {f:`Taux = ${F('−<i>h</i>','2(2 + <i>h</i>) · <i>h</i>')} = ${F('−1','2(2 + <i>h</i>)')}`,w:'On divise par <i>h</i> ≠ 0 et on simplifie.'},
    {f:'→ −1/(2 · 2) = −1/4 quand <i>h</i> → 0',w:'Plus d’indétermination : on remplace <i>h</i> par 0.'}],
   conclusion:'f′(2) = −1/4, ce qui confirme (1/<i>x</i>)′ = −1/<i>x</i>².'},
  note:'Pour une puissance, développe : (<i>a</i> + <i>h</i>)² = <i>a</i>² + 2<i>ah</i> + <i>h</i>² et (<i>a</i> + <i>h</i>)³ = <i>a</i>³ + 3<i>a</i>²<i>h</i> + 3<i>ah</i>² + <i>h</i>³.'},
 {h:'Par la définition',p:'Pour f(x) = <i>x</i>³, le taux en <i>a</i> = 2 vaut ((2 + h)³ − 8)/h. Calcule sa limite f′(2).',lab:'f′(2) =',ans:12,
  why:'(2 + h)³ − 8 = 12h + 6h² + h³. Divisé par h : 12 + 6h + h² → 12.'},
 {kind:'Théorie',h:'La dérivée comme vitesse et comme approximation',p:'<p>f′(a) est une pente. Mais c’est aussi une vitesse, un taux de croissance, un coefficient d’approximation : la même notion sous des habits différents. Les reconnaître fait toute la force du calcul différentiel.</p><div class="idea"><p>Si <i>x</i>(<i>t</i>) est la position d’un mobile à l’instant <i>t</i>, le taux (<i>x</i>(<i>t</i> + <i>h</i>) − <i>x</i>(<i>t</i>))/<i>h</i> est la <b>vitesse moyenne</b> entre <i>t</i> et <i>t</i> + <i>h</i>, et sa limite <i>x</i>′(<i>t</i>) est la <b>vitesse instantanée</b>, celle du compteur. De même, f′(a) &gt; 0 signifie que <i>f</i> est en train d’augmenter en <i>a</i>, f′(a) &lt; 0 qu’elle diminue, et |f′(a)| dit à quelle vitesse.</p></div><div class="prop"><p><b>Approximation affine</b> : si <i>f</i> est dérivable en <i>a</i>, alors pour <i>h</i> petit, <b>f(a + h) ≈ f(a) + f′(a) · h</b>. Autrement dit, la courbe se confond avec sa tangente près de A, et l’erreur commise devient négligeable devant <i>h</i> quand <i>h</i> → 0.</p></div><div class="why"><p>Par définition, (f(a + h) − f(a))/h → f′(a). Donc f(a + h) − f(a) = h · (f′(a) + ε(h)) avec ε(h) → 0. L’erreur h · ε(h) est « petite devant h » : elle tend vers 0 plus vite que <i>h</i>. C’est exactement ce qui fait de la tangente la meilleure droite d’approximation.</p></div><div class="ex"><p>√<i>x</i> en <i>a</i> = 16 : f(16) = 4 et f′(x) = 1/(2√<i>x</i>), donc f′(16) = 1/8. Alors √16,5 ≈ 4 + 0,5/8 = 4,0625. La valeur exacte est 4,06202… : erreur de 0,0005. Et une chute libre <i>x</i>(<i>t</i>) = 5<i>t</i>² (en m) a pour vitesse <i>x</i>′(<i>t</i>) = 10<i>t</i> : 30 m/s après 3 s.</p></div><div class="warn"><p>L’approximation n’est bonne que pour <i>h</i> petit : avec <i>h</i> = 20, √36 ≈ 4 + 20/8 = 6,5 au lieu de 6. Plus on s’éloigne de <i>a</i>, plus la courbe se détache de sa tangente.</p></div>'},
 {kind:'Théorie',h:'Dérivable ⇒ continue, pas l’inverse',p:'<p>Continuité et dérivabilité sont deux niveaux de « régularité » d’une courbe : pas de saut, puis pas d’angle. L’un entraîne l’autre, mais pas dans les deux sens.</p><div class="thm"><p>Si <i>f</i> est <b>dérivable en <i>a</i></b>, alors <i>f</i> est <b>continue en <i>a</i></b>. La réciproque est fausse : une fonction peut être continue en <i>a</i> sans y être dérivable.</p></div><div class="why"><p>f(a + h) − f(a) = <i>h</i> · (f(a + h) − f(a))/<i>h</i>. Quand <i>h</i> → 0, le premier facteur tend vers 0 et le second vers f′(a), un nombre fini : le produit tend vers 0 · f′(a) = 0. Donc f(a + h) → f(a), ce qui est la continuité en <i>a</i>. L’argument utilise que f′(a) est fini : c’est là que la dérivabilité intervient.</p></div><div class="ex"><p>Contre-exemple pour la réciproque : f(x) = |<i>x</i>| est continue en 0, mais son taux en 0 vaut |<i>h</i>|/<i>h</i>, soit 1 pour <i>h</i> &gt; 0 et −1 pour <i>h</i> &lt; 0. Les limites à droite et à gauche diffèrent : pas de limite, pas de dérivée. La courbe a un <b>point anguleux</b> en 0, avec deux demi-tangentes de pentes 1 et −1 (la figure). Autre cas : √<i>x</i> en 0 a un taux √<i>h</i>/<i>h</i> = 1/√<i>h</i> → +∞ : tangente verticale, pas de dérivée.</p></div><div class="warn"><p>Pour vérifier la dérivabilité au point de raccord d’une fonction par morceaux, il faut d’abord la continuité (sinon c’est perdu d’avance), puis l’égalité des pentes à gauche et à droite. L’une sans l’autre ne suffit pas.</p></div>',
  fig:(()=>{ const P=plane({x:[-3,3],y:[-1,3],w:280,lab:1}); P.fn(Math.abs).seg(0,0,2.6,2.6,{c:'var(--spark)',w:2,dash:true}).seg(0,0,-2.6,2.6,{c:'var(--math)',w:2,dash:true})
    .text(2,1.2,'pente 1',{c:'var(--spark)'}).text(-2.9,1.2,'pente −1',{c:'var(--math)'}).dot(0,0,{r:5}); return P.svg(); })(),
  note:'Un <b>point anguleux</b> a deux demi-tangentes différentes : la fonction n’y est pas dérivable.'},
 {kind:'Théorie',h:'Règles de dérivation',p:'<p>Calculer chaque dérivée avec la définition serait interminable. Heureusement, dériver une somme, un produit, un quotient ou une composée se ramène aux dérivées des morceaux, par quatre règles.</p><div class="prop"><p>Si <i>f</i> et <i>g</i> sont dérivables : <b>(f + g)′ = f′ + g′</b>, <b>(<i>k</i>f)′ = <i>k</i>f′</b>, <b>(fg)′ = f′g + fg′</b>, <b>(f/g)′ = (f′g − fg′)/g²</b> où g ≠ 0, et pour la composée (<b>règle de chaîne</b>) <b>(f ∘ g)′(x) = f′(g(x)) · g′(x)</b> : on dérive l’extérieur en gardant l’intérieur, puis on multiplie par la dérivée de l’intérieur.</p></div><div class="why"><p>Pour le produit : f(a + h)g(a + h) − f(a)g(a) = [f(a + h) − f(a)]g(a + h) + f(a)[g(a + h) − g(a)], en ajoutant et retranchant f(a)g(a + h). Divisé par <i>h</i>, le premier crochet tend vers f′(a) tandis que g(a + h) → g(a) par continuité ; le second donne f(a)g′(a). D’où f′g + fg′. Pour la chaîne : une variation <i>h</i> de <i>x</i> fait varier g d’environ g′(x) · <i>h</i>, puis f d’environ f′(g(x)) fois cette quantité : les taux se multiplient.</p></div><div class="ex"><p>(<i>x</i>² sin <i>x</i>)′ = 2<i>x</i> sin <i>x</i> + <i>x</i>² cos <i>x</i>. (sin(3<i>x</i>))′ = cos(3<i>x</i>) · 3. ((<i>x</i> + 1)/(<i>x</i> − 1))′ = (1 · (<i>x</i> − 1) − (<i>x</i> + 1) · 1)/(<i>x</i> − 1)² = −2/(<i>x</i> − 1)². Contrôle du produit avec f = g = <i>x</i> : (<i>x</i>²)′ = 1 · <i>x</i> + <i>x</i> · 1 = 2<i>x</i> ✓.</p></div><div class="warn"><p>(fg)′ n’est <b>pas</b> f′g′ : avec f = g = <i>x</i>, f′g′ = 1 alors que (<i>x</i>²)′ = 2<i>x</i>. Dans le quotient, l’ordre compte : f′g − fg′, le numérateur dérivé en premier. Et l’oubli de la dérivée de l’intérieur dans une composée est l’erreur la plus fréquente.</p></div>',
  note:'Les dérivées des briques de base (puissances, sin, cos, exp, ln) sont à l’étape suivante.'},
 {kind:'Théorie',h:'Les dérivées à connaître',p:'<p>Les règles de dérivation combinent des briques. Il faut connaître la dérivée de chaque brique, et savoir d’où elle vient pour ne pas la confondre avec une autre.</p><div class="prop"><p>Pour tout réel <i>n</i> : <b>(<i>x</i>ⁿ)′ = <i>n</i><i>x</i>ⁿ⁻¹</b>, ce qui couvre (1/<i>x</i>)′ = −1/<i>x</i>² et (√<i>x</i>)′ = 1/(2√<i>x</i>). <b>(sin <i>x</i>)′ = cos <i>x</i></b>, <b>(cos <i>x</i>)′ = −sin <i>x</i></b>, <b>(tan <i>x</i>)′ = 1 + tan² <i>x</i> = 1/cos² <i>x</i></b>. <b>(eˣ)′ = eˣ</b> et <b>(ln <i>x</i>)′ = 1/<i>x</i></b>. Une constante a pour dérivée 0.</p></div><div class="why"><p>(<i>x</i>²)′ = 2<i>x</i> et (<i>x</i>³)′ = 3<i>x</i>² viennent du développement de (<i>a</i> + <i>h</i>)ⁿ : le terme en <i>h</i> est <i>n</i><i>a</i>ⁿ⁻¹<i>h</i>. Pour sin : (sin(<i>a</i> + <i>h</i>) − sin <i>a</i>)/<i>h</i> = sin <i>a</i> · (cos <i>h</i> − 1)/<i>h</i> + cos <i>a</i> · (sin <i>h</i>)/<i>h</i>, et les équivalents donnent 0 et 1, donc cos <i>a</i>. Pour exp : (e<sup>a+h</sup> − eᵃ)/<i>h</i> = eᵃ(e<sup>h</sup> − 1)/<i>h</i> → eᵃ · 1 grâce à e<sup>h</sup> − 1 ~ <i>h</i> : l’exponentielle est sa propre dérivée. Pour ln : si <i>y</i> = ln <i>x</i>, alors e<sup>y</sup> = <i>x</i>, et dériver les deux côtés par la règle de chaîne donne e<sup>y</sup> · <i>y</i>′ = 1, soit <i>y</i>′ = 1/<i>x</i>.</p></div><div class="ex"><p>(<i>x</i>⁵)′ = 5<i>x</i>⁴ ; (<i>x</i><sup>−3</sup>)′ = −3<i>x</i><sup>−4</sup> ; (<i>x</i><sup>1/2</sup>)′ = (1/2)<i>x</i><sup>−1/2</sup> = 1/(2√<i>x</i>). Avec la chaîne : (e<sup>3x</sup>)′ = 3e<sup>3x</sup>, (ln(<i>x</i>² + 1))′ = 2<i>x</i>/(<i>x</i>² + 1), (cos(<i>x</i>²))′ = −2<i>x</i> sin(<i>x</i>²).</p></div><div class="warn"><p>Le signe de (cos <i>x</i>)′ = −sin <i>x</i> s’oublie souvent : cos décroît juste après 0, sa dérivée y est négative. Et (eˣ)′ = eˣ, mais (<i>x</i>ⁿ)′ fait descendre l’exposant : ne traite pas 2ˣ comme <i>x</i>² (on a (2ˣ)′ = 2ˣ ln 2).</p></div>',
  fig:tab([['f(x)','f′(x)'],['xⁿ','n xⁿ⁻¹'],['1/x','−1/x²'],['√x','1/(2√x)'],['sin x','cos x'],['cos x','−sin x'],['tan x','1 + tan² x'],['eˣ','eˣ'],['ln x','1/x']])},
 {kind:'Méthode',h:'Dériver une expression composée',p:'<b>Quand :</b> la fonction est construite à partir de fonctions simples par produit, quotient ou composition. <b>Pourquoi ça marche :</b> chaque règle découle de la définition par le taux ; il suffit d’appliquer la bonne règle à la bonne étape. <b>Comment :</b> repère l’opération « la plus extérieure » (produit, quotient ou composée), nomme <i>u</i> et <i>v</i>, dérive chacun séparément (avec la règle de chaîne si c’est une composée : on dérive l’extérieur, puis on multiplie par la dérivée de l’intérieur), assemble, puis factorise.',
  demo:{enonce:`Dériver f(x) = ${F('e<sup>3<i>x</i></sup>','<i>x</i>² + 1')}.`,
   etapes:[
    {f:'C’est un quotient u/v avec u = e<sup>3<i>x</i></sup> et v = <i>x</i>² + 1',w:'L’opération extérieure est la division.'},
    {f:'u′ = 3e<sup>3<i>x</i></sup>',w:'u est une composée e<sup>g(x)</sup> avec g(x) = 3<i>x</i> : (e<sup>g</sup>)′ = g′ e<sup>g</sup> = 3e<sup>3<i>x</i></sup>.'},
    {f:'v′ = 2<i>x</i>',w:'Dérivée d’un polynôme.'},
    {f:`f′(x) = ${F('3e<sup>3<i>x</i></sup>(<i>x</i>² + 1) − e<sup>3<i>x</i></sup> · 2<i>x</i>','(<i>x</i>² + 1)²')}`,w:'Règle du quotient (u′v − uv′)/v².'},
    {f:`= ${F('e<sup>3<i>x</i></sup>(3<i>x</i>² − 2<i>x</i> + 3)','(<i>x</i>² + 1)²')}`,w:'On factorise e<sup>3<i>x</i></sup> : la forme factorisée sert ensuite à étudier le signe.'}],
   conclusion:'f′(x) = e<sup>3<i>x</i></sup>(3<i>x</i>² − 2<i>x</i> + 3)/(<i>x</i>² + 1)².'},
  note:'Dérivées utiles des composées : (u<sup>n</sup>)′ = n u′ u<sup>n−1</sup>, (√u)′ = u′/(2√u), (e<sup>u</sup>)′ = u′ e<sup>u</sup>, (ln u)′ = u′/u, (sin u)′ = u′ cos u.'},
 {h:'Un produit',p:'Quelle est la dérivée de f(x) = <i>x</i>² sin <i>x</i>&nbsp;?',opts:['2x cos x','2x sin x + x² cos x','2x sin x − x² cos x','x² cos x'],ans:1,
  why:'Règle du produit avec u = x² et v = sin x : u′v + uv′ = 2x sin x + x² cos x.'},
 {h:'Une composée',p:'Soit f(x) = √(<i>x</i>² + 9). Calcule f′(4).',lab:'f′(4) =',ans:.8,tol:1e-9,
  why:'Règle de chaîne avec u = x² + 9 : f′(x) = u′/(2√u) = 2x/(2√(x² + 9)) = x/√(x² + 9). En 4 : 4/√25 = 4/5 = 0,8.'},
 {kind:'Défi',h:'Un quotient',p:`Soit f(x) = ${F('<i>x</i>² + 1','<i>x</i> − 2')}. Calcule f′(3).`,lab:'f′(3) =',ans:-4,
  why:'f′(x) = (2x(x − 2) − (x² + 1))/(x − 2)² = (x² − 4x − 1)/(x − 2)². En 3 : (9 − 12 − 1)/1 = −4.'},
 {kind:'Méthode',h:'L’équation de la tangente',p:'<b>Quand :</b> on demande la tangente au graphe de <i>f</i> au point d’abscisse <i>a</i>, ou une approximation de <i>f</i> près de <i>a</i>. <b>Pourquoi ça marche :</b> la tangente passe par le point (<i>a</i> ; f(<i>a</i>)) et a pour pente f′(<i>a</i>). Une droite de pente <i>m</i> passant par (<i>a</i> ; <i>b</i>) s’écrit <i>y</i> = <i>b</i> + <i>m</i>(<i>x</i> − <i>a</i>). <b>Comment :</b> calcule f(<i>a</i>), puis f′(<i>a</i>), et écris <b><i>y</i> = f(<i>a</i>) + f′(<i>a</i>)(<i>x</i> − <i>a</i>)</b>.',
  demo:{enonce:'Tangente au graphe de f(x) = <i>x</i>³ au point d’abscisse 1.',
   etapes:[
    {f:'f(1) = 1',w:'Le point de contact est (1 ; 1).'},
    {f:'f′(x) = 3<i>x</i>², donc f′(1) = 3',w:'La pente de la tangente.'},
    {f:'<i>y</i> = 1 + 3(<i>x</i> − 1) = 3<i>x</i> − 2',w:'On remplace dans la formule et on développe.'}],
   conclusion:'La tangente est <i>y</i> = 3<i>x</i> − 2. Elle coupe l’axe O<i>x</i> en <i>x</i> = 2/3.'}},
 {h:'Où coupe la tangente&nbsp;?',p:'La tangente au graphe de f(x) = <i>x</i>² au point d’abscisse 3 coupe l’axe O<i>x</i>. En quelle abscisse&nbsp;?',lab:'x =',ans:1.5,tol:1e-9,
  why:'f(3) = 9 et f′(3) = 6 : y = 9 + 6(x − 3) = 6x − 9. Elle coupe Ox pour 6x − 9 = 0, soit x = 1,5.'},
 {kind:'Récapitulatif',h:'Ce qu’il faut retenir : continuité et dérivée',p:'<div class="keep"><ul><li><b>Continue en <i>a</i></b> : lim<sub>x→a</sub> f(x) = f(a). <b>Prolongement par continuité</b> : si la limite <i>L</i> existe et est finie, poser f(a) = L. Fonction par morceaux : égaler la limite de chaque côté à f(a).</li><li><b>Valeurs intermédiaires</b> : <i>f</i> continue sur [<i>a</i> ; <i>b</i>] prend toute valeur entre f(a) et f(b) ; un changement de signe garantit un zéro.</li><li><b>Dérivée</b> : f′(a) = lim<sub>h→0</sub> (f(a + h) − f(a))/h, pente de la tangente, vitesse instantanée. Approximation : f(a + h) ≈ f(a) + f′(a)h.</li><li><b>Dérivable ⇒ continue</b> ; réciproque fausse (|<i>x</i>| en 0 : point anguleux). Au raccord : continuité, puis égalité des pentes.</li><li><b>Règles</b> : (f + g)′ = f′ + g′ ; (fg)′ = f′g + fg′ ; (f/g)′ = (f′g − fg′)/g² ; (f ∘ g)′ = f′(g) · g′. Donc (uⁿ)′ = n u′uⁿ⁻¹, (e<sup>u</sup>)′ = u′e<sup>u</sup>, (ln u)′ = u′/u, (√u)′ = u′/(2√u).</li><li><b>Dérivées de base</b> : (xⁿ)′ = nxⁿ⁻¹, (sin)′ = cos, (cos)′ = −sin, (eˣ)′ = eˣ, (ln x)′ = 1/x.</li><li><b>Tangente en <i>a</i></b> : <i>y</i> = f(a) + f′(a)(<i>x</i> − <i>a</i>).</li></ul></div>'},
 {kind:'Problème',h:'Raccorder une voie ferrée',
  p:'Une voie ferrée suit la courbe <i>y</i> = <i>x</i>² pour <i>x</i> ≤ 1 (unités en km), puis continue en ligne droite <i>y</i> = <i>ax</i> + <i>b</i> pour <i>x</i> &gt; 1. Pour que les rails ne soient pas coupés, le raccord doit être <b>continu</b>. Pour éviter un choc latéral, il ne doit pas faire d’angle : la fonction doit être <b>dérivable</b> en 1.',
  fig:(()=>{ const P=plane({x:[-1.5,3],y:[-1,5],h:240,lab:1}); P.fn(x=>x*x,{from:-1.5,to:1}).fn(x=>2*x-1,{from:1,to:3,c:'var(--spark)'}).dot(1,1,{r:5,c:'var(--ink)',l:'raccord'}); return P.svg(); })(),
  parts:[
   {q:'a) Quelle condition impose la continuité en 1&nbsp;?',opts:['<i>a</i> = 1','<i>b</i> = 1','<i>a</i> + <i>b</i> = 1','<i>a</i> + <i>b</i> = 2'],ans:2,hint:'Compare la limite à droite <i>a</i> · 1 + <i>b</i> avec f(1).',why:'f(1) = 1² = 1 et la limite à droite vaut a + b. Continuité : a + b = 1.'},
   {q:'b) La dérivabilité en 1 impose l’égalité des pentes à gauche et à droite. Que vaut <i>a</i>&nbsp;?',lab:'a =',ans:2,hint:'À gauche, la pente est la dérivée de <i>x</i>² en 1. À droite, c’est la pente de la droite.',why:'(x²)′ = 2x vaut 2 en 1. La droite a pour pente a. Donc a = 2.'},
   {q:'c) Que vaut alors <i>b</i>&nbsp;?',lab:'b =',ans:-1,hint:'Utilise la condition de continuité.',why:'a + b = 1 avec a = 2 donne b = −1.'},
   {q:'d) La partie droite de la voie, prolongée, coupe l’axe O<i>x</i>. En quelle abscisse&nbsp;?',lab:'x =',unit:'km',ans:.5,tol:1e-9,hint:'Résous 2<i>x</i> − 1 = 0.',why:'2x − 1 = 0 ⇔ x = 0,5. C’est aussi là que la tangente à y = x² en 1 coupe l’axe : la droite est cette tangente.'},
  ],
  sol:'Continuité en 1 : f(1) = 1 et lim<sub>x→1⁺</sub> (ax + b) = a + b, donc a + b = 1.<br>Dérivabilité : à gauche, le taux (f(1 + h) − f(1))/h = 2 + h → 2 ; à droite, il vaut a. Donc a = 2.<br>Puis b = 1 − a = −1. La droite est y = 2x − 1, qui coupe Ox en x = 0,5.<br>C’est exactement la tangente à la parabole au point (1 ; 1) : un raccord sans angle prolonge la courbe par sa tangente.<br>(Il reste un saut de courbure, car f″ passe de 2 à 0 : en vrai, on intercale une courbe de transition.)'},
 {kind:'Problème',h:'Prolonger, puis dériver',
  p:`On considère f(x) = ${F('1 − cos <i>x</i>','<i>x</i>')} pour <i>x</i> ≠ 0. Elle n’est pas définie en 0. On veut la prolonger par continuité, vérifier que le prolongement est dérivable en 0, trouver sa tangente, puis calculer une dérivée ailleurs avec les règles.`,
  fig:(()=>{ const P=plane({x:[-7,7],y:[-1,1],h:160,grid:false,lx:2,ly:.5}); P.fn(x=>Math.abs(x)<1e-9?0:(1-Math.cos(x))/x).fn(x=>x/2,{from:-2,to:2,c:'var(--spark)',w:2,dash:true}).dot(0,0,{r:4,c:'var(--ink)'}); return P.svg(); })(),
  parts:[
   {q:'a) Par quelle valeur faut-il prolonger <i>f</i> en 0&nbsp;?',lab:'f(0) =',ans:0,hint:'1 − cos <i>x</i> ~ <i>x</i>²/2.',why:'f(x) ~ (x²/2)/x = x/2 → 0. On pose f(0) = 0.'},
   {q:'b) Avec f(0) = 0, calcule f′(0) à l’aide du taux d’accroissement.',lab:'f′(0) =',ans:.5,tol:1e-9,hint:'Le taux vaut (f(<i>h</i>) − 0)/<i>h</i> = (1 − cos <i>h</i>)/<i>h</i>².',why:'(1 − cos h)/h² ~ (h²/2)/h² = 1/2. Donc f′(0) = 1/2.'},
   {q:'c) Quelle est la tangente au graphe en 0&nbsp;?',opts:['<i>y</i> = 0','<i>y</i> = <i>x</i>','<i>y</i> = 2<i>x</i>','<i>y</i> = <i>x</i>/2'],ans:3,hint:'<i>y</i> = f(0) + f′(0)(<i>x</i> − 0).',why:'y = 0 + (1/2)x = x/2.'},
   {q:'d) Calcule f′(π), arrondi au centième.',lab:'f′(π) ≈',ans:-2/Math.PI**2,tol:.006,hint:'Règle du quotient avec <i>u</i> = 1 − cos <i>x</i> et <i>v</i> = <i>x</i>.',why:'f′(x) = (x sin x − (1 − cos x))/x². En π : (0 − 2)/π² = −2/π² ≈ −0,20.'},
  ],
  sol:'Comme 1 − cos x ~ x²/2 en 0, f(x) ~ x/2 → 0 : on prolonge par f(0) = 0, et f devient continue en 0.<br>Taux en 0 : (f(h) − f(0))/h = (1 − cos h)/h² → 1/2. Donc f est dérivable en 0 et f′(0) = 1/2.<br>La tangente en 0 est y = x/2.<br>Pour x ≠ 0, la règle du quotient donne f′(x) = (x sin x − (1 − cos x))/x².<br>En π : sin π = 0 et cos π = −1, donc f′(π) = −2/π² ≈ −0,20.'},
]},

/* ===================== APPLICATIONS ET INTÉGRALES ===================== */
{subj:'an1', sem:'pri', id:'an1-etude', h:'Extrema et étude de fonction', p:'Trouver les extrema, lire la convexité, repérer les asymptotes, et mener une étude complète.', steps:[
 {kind:'Théorie',h:'Extrema et tangente horizontale',p:'<p>Quand une fonction modélise un coût, une hauteur ou un bénéfice, on veut savoir où elle est la plus grande ou la plus petite. Il faut d’abord dire précisément ce que « plus grand » veut dire, puis trouver un moyen de repérer ces points sans tout calculer.</p><div class="def"><p><i>f</i> a un <b>maximum local</b> en <i>a</i> s’il existe un intervalle ouvert autour de <i>a</i> sur lequel f(x) ≤ f(a) ; un <b>minimum local</b> si f(x) ≥ f(a) près de <i>a</i>. On dit <b>extremum</b> pour l’un ou l’autre. L’extremum est <b>global</b> si l’inégalité vaut sur tout le domaine.</p></div><div class="thm"><p>Si <i>f</i> est dérivable en un point <b>intérieur</b> <i>a</i> où elle a un extremum local, alors <b>f′(a) = 0</b> : la tangente y est horizontale.</p></div><div class="why"><p>Au maximum, f(a + h) − f(a) ≤ 0 pour <i>h</i> petit. Pour <i>h</i> &gt; 0, le taux (f(a + h) − f(a))/h est donc ≤ 0, et sa limite f′(a) aussi. Pour <i>h</i> &lt; 0, le taux est ≥ 0, donc f′(a) ≥ 0. Les deux ensemble donnent f′(a) = 0.</p></div><div class="ex"><p>Déplace le point sur f(x) = <i>x</i>³ − 3<i>x</i>. f′(x) = 3<i>x</i>² − 3 s’annule en −1 et en 1. En −1, f(−1) = 2 dépasse les valeurs voisines (f(−1,5) = 1,125 et f(−0,5) = 1,375) : maximum local. En 1, f(1) = −2 : minimum local. Aucun n’est global, car f(x) → ±∞ aux deux bouts.</p></div><div class="warn"><p>La réciproque est fausse : f′(a) = 0 n’impose pas un extremum. Et en une borne d’un intervalle fermé, un extremum peut exister sans que f′ s’annule.</p></div>',
  params:[{id:'a',l:'a',min:-2.5,max:2.5,step:.25,v:1.5}],
  draw:v=>{ const f=x=>x**3-3*x, m=3*v.a*v.a-3, P=plane({x:[-3,3],y:[-4,4],lab:1}); P.fn(f).fn(x=>f(v.a)+m*(x-v.a),{c:'var(--spark)',w:2}).dot(v.a,f(v.a),{r:6,c:'var(--ink)'}); return P.svg(); },
  info:v=>`f′(${fmt(v.a)}) = 3a² − 3 = ${fmt(3*v.a*v.a-3,4)}`+(v.a===-1?' : maximum local':v.a===1?' : minimum local':'')},
 {kind:'Théorie',h:'Monotonie et signe de la dérivée',p:'<p>La condition f′(a) = 0 fournit des candidats. Pour savoir lesquels sont des maxima, des minima ou rien du tout, il faut connaître le sens de variation de <i>f</i> de part et d’autre : c’est le signe de f′ qui le donne.</p><div class="thm"><p>Soit <i>f</i> dérivable sur un <b>intervalle</b> I. Si <b>f′ &gt; 0</b> sur I (sauf peut-être en des points isolés où f′ = 0), <i>f</i> est <b>strictement croissante</b> sur I ; si <b>f′ &lt; 0</b>, elle est strictement décroissante ; si f′ = 0 partout, elle est constante.</p></div><div class="why"><p>L’argument clé est le théorème des accroissements finis : entre deux points <i>x</i>₁ &lt; <i>x</i>₂ de I, il existe un point <i>c</i> où la tangente est parallèle à la corde, soit f(x₂) − f(x₁) = f′(c)(x₂ − x₁). Si f′ &gt; 0, le membre de droite est positif, donc f(x₂) &gt; f(x₁). En mots : une pente toujours positive fait toujours monter.</p></div><div class="idea"><p>D’où la règle des extrema : si f′ passe de + à − en <i>a</i>, <i>f</i> monte puis descend, donc f(a) est un maximum local ; de − à +, c’est un minimum local ; si f′ s’annule sans changer de signe, <i>f</i> continue dans le même sens et il n’y a pas d’extremum.</p></div><div class="ex"><p>f(x) = <i>x</i>³ − 3<i>x</i> : f′(x) = 3(<i>x</i> − 1)(<i>x</i> + 1) est positive sur ]−∞ ; −1[, négative sur ]−1 ; 1[, positive sur ]1 ; +∞[. Donc <i>f</i> croît jusqu’à f(−1) = 2, décroît jusqu’à f(1) = −2, puis croît de nouveau : maximum local en −1, minimum local en 1.</p></div><div class="warn"><p>La règle vaut sur un intervalle. f(x) = −1/<i>x</i> a f′(x) = 1/<i>x</i>² &gt; 0, et pourtant f(−1) = 1 &gt; f(1) = −1 : elle est croissante sur ]−∞ ; 0[ et sur ]0 ; +∞[ séparément, pas sur leur réunion.</p></div>'},
 {kind:'Méthode',h:'Trouver les extrema locaux',p:'<b>Quand :</b> on cherche les maxima et minima d’une fonction dérivable sur un intervalle ouvert. <b>Pourquoi ça marche :</b> un extremum intérieur impose f′ = 0, mais ce n’est pas suffisant. Si f′ passe de + à −, <i>f</i> monte puis descend : c’est un maximum. De − à + : un minimum. <b>Comment :</b> calcule f′, factorise-la, trouve ses zéros, dresse le tableau de signes de f′ et lis les changements de signe.',
  demo:{enonce:'Extrema locaux de f(x) = 2<i>x</i>³ − 3<i>x</i>² − 12<i>x</i>.',
   etapes:[
    {f:'f′(x) = 6<i>x</i>² − 6<i>x</i> − 12 = 6(<i>x</i>² − <i>x</i> − 2) = 6(<i>x</i> − 2)(<i>x</i> + 1)',w:'On factorise pour lire le signe : racine évidente −1, produit des racines −2, donc l’autre est 2.'},
    {f:'f′ &gt; 0 sur ]−∞ ; −1[, f′ &lt; 0 sur ]−1 ; 2[, f′ &gt; 0 sur ]2 ; +∞[',w:'Trinôme de coefficient 6 &gt; 0 : positif à l’extérieur des racines.'},
    {f:'En −1, f′ passe de + à − : maximum local f(−1) = −2 − 3 + 12 = 7',w:'<i>f</i> croît puis décroît.'},
    {f:'En 2, f′ passe de − à + : minimum local f(2) = 16 − 12 − 24 = −20',w:'<i>f</i> décroît puis croît.'}],
   conclusion:'Maximum local 7 en <i>x</i> = −1, minimum local −20 en <i>x</i> = 2.'}},
 {kind:'Pratique',h:'Trouve le maximum local',p:'Place le point au maximum local de f(x) = <i>x</i>³ − 3<i>x</i>.',
  params:[{id:'a',l:'a',min:-2.5,max:2.5,step:.25,v:.5}],
  draw:v=>{ const f=x=>x**3-3*x, m=3*v.a*v.a-3, P=plane({x:[-3,3],y:[-4,4],lab:1}); P.fn(f).fn(x=>f(v.a)+m*(x-v.a),{c:'var(--spark)',w:2}).dot(v.a,f(v.a),{r:6,c:'var(--ink)'}); return P.svg(); },
  info:v=>`f′(a) = ${fmt(3*v.a*v.a-3,4)}`,
  ok:v=>v.a===-1,why:'f′(x) = 3x² − 3 = 3(x − 1)(x + 1) s’annule en ±1. f′ passe de + à − en −1 : maximum local f(−1) = 2. (En 1, minimum local.)'},
 {h:'Condition suffisante&nbsp;?',p:'f(x) = <i>x</i>³ vérifie f′(0) = 0. Que peut-on dire en 0&nbsp;?',opts:['0 est un minimum local','0 est un maximum local','0 n’est pas un extremum : f′ ne change pas de signe','f n’est pas dérivable en 0'],ans:2,
  why:'f′(x) = 3x² ≥ 0 : f est croissante, f(x) &lt; 0 à gauche et &gt; 0 à droite. f′(a) = 0 est nécessaire, pas suffisant : il faut un changement de signe de f′.'},
 {kind:'Théorie',h:'Extremum global : le rôle des bornes',p:'<p>Sur un intervalle fermé, une fonction peut atteindre sa plus grande valeur à une extrémité, là où la tangente n’a aucune raison d’être horizontale. Chercher seulement les zéros de f′ ne suffit donc plus pour un extremum global.</p><div class="thm"><p><b>Théorème des bornes atteintes.</b> Si <i>f</i> est <b>continue</b> sur un <b>segment</b> [<i>a</i> ; <i>b</i>], elle y possède un maximum global et un minimum global : il existe des points de [<i>a</i> ; <i>b</i>] où elle atteint sa plus grande et sa plus petite valeur.</p></div><div class="idea"><p>Où se trouve ce maximum ? Soit en un point intérieur, et alors f′ y vaut 0 si <i>f</i> est dérivable (première étape), soit en <i>a</i> ou en <i>b</i>. La liste des candidats est donc courte : les points critiques intérieurs et les deux bornes. Il suffit de calculer <i>f</i> en chacun et de comparer, sans même faire de tableau de signes.</p></div><div class="ex"><p>f(x) = <i>x</i>² sur [−1 ; 3] : f′(x) = 2<i>x</i> s’annule en 0. Candidats : f(−1) = 1, f(0) = 0, f(3) = 9. Le minimum global vaut 0 (en 0, un point critique) et le maximum global vaut 9 (en 3, une borne où f′(3) = 6 ≠ 0).</p></div><div class="warn"><p>Les deux hypothèses comptent. Sur l’intervalle ouvert ]0 ; 1[, f(x) = <i>x</i> n’a ni maximum ni minimum : elle s’approche de 1 sans l’atteindre. Et sur [−1 ; 1], la fonction discontinue qui vaut 1/<i>x</i> pour <i>x</i> ≠ 0 et 0 en 0 n’a pas de maximum : elle n’est même pas bornée.</p></div>'},
 {kind:'Méthode',h:'Extremum global sur un segment',p:'<b>Quand :</b> on cherche la plus grande ou la plus petite valeur de <i>f</i> continue sur un intervalle fermé [<i>a</i> ; <i>b</i>]. <b>Pourquoi ça marche :</b> une fonction continue sur un segment atteint son maximum et son minimum. Ils sont soit en un point intérieur où f′ = 0, soit en une borne, où f′ n’a pas besoin de s’annuler. <b>Comment :</b> trouve les zéros de f′ dans ]<i>a</i> ; <i>b</i>[, calcule <i>f</i> en ces points et aux deux bornes, puis compare.',
  demo:{enonce:'Maximum et minimum de f(x) = <i>x</i>³ − 3<i>x</i> sur [0 ; 3].',
   etapes:[
    {f:'f′(x) = 3(<i>x</i> − 1)(<i>x</i> + 1) : seul <i>x</i> = 1 est dans ]0 ; 3[',w:'−1 est hors de l’intervalle, on l’écarte.'},
    {f:'f(1) = −2',w:'Valeur au point critique.'},
    {f:'f(0) = 0 et f(3) = 27 − 9 = 18',w:'Valeurs aux bornes : on ne les oublie jamais.'},
    {f:'On compare −2, 0 et 18',w:'Le plus grand est le maximum, le plus petit le minimum.'}],
   conclusion:'Sur [0 ; 3], le maximum vaut 18 (en 3) et le minimum −2 (en 1). Le maximum est atteint à une borne, où f′(3) = 24 ≠ 0.'}},
 {h:'Le minimum sur un segment',p:'Quelle est la plus petite valeur de f(x) = <i>x</i>³ − 3<i>x</i> sur [−3 ; 2]&nbsp;?',lab:'min =',ans:-18,
  why:'Points critiques ±1 : f(−1) = 2, f(1) = −2. Bornes : f(−3) = −27 + 9 = −18, f(2) = 8 − 6 = 2. Le minimum vaut −18, atteint à la borne −3.'},
 {kind:'Théorie',h:'Variations et convexité',p:'<p>Deux courbes peuvent monter de la même façon tout en ayant des formes très différentes : l’une se creuse vers le haut comme un bol, l’autre s’arrondit comme une colline. Le signe de f′ dit si la courbe monte ; il faut un second outil pour dire comment elle tourne.</p><div class="def"><p><i>f</i> est <b>convexe</b> sur un intervalle si sa courbe est tournée vers le haut : elle reste au-dessus de chacune de ses tangentes. Elle est <b>concave</b> si elle est tournée vers le bas, au-dessous de ses tangentes. Pour <i>f</i> deux fois dérivable : <b>f″ &gt; 0 ⇒ convexe</b> et <b>f″ &lt; 0 ⇒ concave</b>. Un <b>point d’inflexion</b> est un point où la courbe change de courbure, c’est-à-dire où f″ change de signe.</p></div><div class="why"><p>f″ est la dérivée de f′. Si f″ &gt; 0, la pente f′ augmente : en avançant, la tangente se redresse, et la courbe se relève au-dessus d’elle. Si f″ &lt; 0, la pente diminue et la courbe plonge sous sa tangente.</p></div><div class="ex"><p>f(x) = <i>x</i>³ − 3<i>x</i> : f′(x) = 3<i>x</i>² − 3 et f″(x) = 6<i>x</i>. f″ &lt; 0 pour <i>x</i> &lt; 0 : <i>f</i> est concave (partie gauche de la figure) ; f″ &gt; 0 pour <i>x</i> &gt; 0 : convexe (partie droite). En 0, f″ change de signe : (0 ; 0) est un point d’inflexion, où la tangente <i>y</i> = −3<i>x</i> traverse la courbe. Le tableau réunit les deux signes.</p></div><div class="warn"><p>Ne confonds pas les deux lectures : f′ dit si la courbe <b>monte ou descend</b>, f″ si elle <b>tourne vers le haut ou vers le bas</b>. Sur ]−1 ; 0[, <i>f</i> décroît et est concave ; sur ]0 ; 1[, elle décroît encore, mais elle est convexe.</p></div>',
  fig:(()=>{ const P=plane({x:[-3,3],y:[-4,4],w:280,lab:1}); P.fn(x=>x**3-3*x,{from:-3,to:0,c:'var(--math)'}).fn(x=>x**3-3*x,{from:0,to:3,c:'var(--spark)'}).dot(0,0,{r:5,c:'var(--ink)',l:'inflexion'})
    .text(-2.9,-3,'concave',{c:'var(--math)'}).text(1.2,3,'convexe',{c:'var(--spark)'}); return P.svg(); })()+
   tab([['<i>x</i>','−∞','','−1','','0','','1','','+∞'],['f′','','+','0','−','','−','0','+',''],['f″','','−','','−','0','+','','+',''],['f','','↗','2','↘','0','↘','−2','↗','']])},
 {kind:'Méthode',h:'Convexité et points d’inflexion',p:'<b>Quand :</b> on demande où la courbe est tournée vers le haut ou vers le bas, ou ses points d’inflexion. <b>Pourquoi ça marche :</b> f″ est la dérivée de f′, donc son signe dit si la pente augmente (f″ &gt; 0, convexe) ou diminue (f″ &lt; 0, concave). Un point d’inflexion est un changement de courbure, donc un changement de signe de f″. <b>Comment :</b> dérive deux fois, factorise f″, dresse son tableau de signes, et garde les zéros où le signe change.',
  demo:{enonce:'Convexité de f(x) = <i>x</i>⁴ − 6<i>x</i>².',
   etapes:[
    {f:'f′(x) = 4<i>x</i>³ − 12<i>x</i>, puis f″(x) = 12<i>x</i>² − 12 = 12(<i>x</i> − 1)(<i>x</i> + 1)',w:'On dérive deux fois et on factorise.'},
    {f:'f″ &gt; 0 sur ]−∞ ; −1[ et ]1 ; +∞[, f″ &lt; 0 sur ]−1 ; 1[',w:'Signe d’un trinôme de coefficient 12 &gt; 0.'},
    {f:'<i>f</i> est convexe sur ]−∞ ; −1] et sur [1 ; +∞[, concave sur [−1 ; 1]',w:'On traduit le signe de f″.'},
    {f:'f″ change de signe en −1 et en 1 : f(±1) = 1 − 6 = −5',w:'On calcule l’ordonnée pour situer les points.'}],
   conclusion:'Deux points d’inflexion : (−1 ; −5) et (1 ; −5).'},
  note:'f″(<i>a</i>) = 0 ne suffit pas : pour f(x) = <i>x</i>⁴, f″(0) = 0 mais f″ = 12<i>x</i>² ne change pas de signe, il n’y a pas d’inflexion.'},
 {h:'Point d’inflexion',p:'Pour f(x) = <i>x</i>³ − 6<i>x</i>² + 9<i>x</i> + 1, quelle est l’abscisse du point d’inflexion&nbsp;?',lab:'x =',ans:2,
  why:'f′(x) = 3x² − 12x + 9, f″(x) = 6x − 12. f″ s’annule et change de signe en x = 2.'},
 {kind:'Théorie',h:'Asymptotes',p:'<p>Loin de l’origine, ou près d’une valeur interdite, une courbe peut ressembler de plus en plus à une droite. Repérer ces droites donne l’allure du graphe avant même de calculer des points.</p><div class="def"><p>La droite <i>x</i> = <i>a</i> est une <b>asymptote verticale</b> si f(x) → ±∞ quand <i>x</i> → <i>a</i> (d’un côté au moins). La droite <i>y</i> = <i>mx</i> + <i>p</i> est une <b>asymptote oblique</b> en +∞ (ou en −∞) si <b>f(x) − (mx + p) → 0</b> : l’écart vertical entre la courbe et la droite tend vers 0. Pour <i>m</i> = 0, c’est une asymptote horizontale.</p></div><div class="prop"><p>Si l’asymptote oblique existe, alors <b><i>m</i> = lim f(x)/<i>x</i></b> et <b><i>p</i> = lim (f(x) − <i>mx</i>)</b>.</p></div><div class="why"><p>Écris f(x) = <i>mx</i> + <i>p</i> + ε(x) avec ε(x) → 0. Alors f(x)/<i>x</i> = <i>m</i> + <i>p</i>/<i>x</i> + ε(x)/<i>x</i> → <i>m</i>, puis f(x) − <i>mx</i> = <i>p</i> + ε(x) → <i>p</i>. Si l’une des deux limites est infinie ou n’existe pas, il n’y a pas d’asymptote oblique.</p></div><div class="ex"><p>f(x) = (<i>x</i>² + 1)/(<i>x</i> − 1). En 1, le numérateur vaut 2 et le dénominateur tend vers 0 : asymptote verticale <i>x</i> = 1. En ±∞ : f(x)/<i>x</i> = (<i>x</i>² + 1)/(<i>x</i>² − <i>x</i>) → 1, puis f(x) − <i>x</i> = (<i>x</i> + 1)/(<i>x</i> − 1) → 1. L’asymptote est <i>y</i> = <i>x</i> + 1, ce que confirme l’écriture f(x) = <i>x</i> + 1 + 2/(<i>x</i> − 1).</p></div><div class="warn"><p>Un <i>m</i> fini ne suffit pas : pour f(x) = <i>x</i> + √<i>x</i>, f(x)/<i>x</i> → 1, mais f(x) − <i>x</i> = √<i>x</i> → +∞ : pas d’asymptote oblique.</p></div>',
  fig:(()=>{ const f=x=>(x*x+1)/(x-1), P=plane({x:[-5,7],y:[-6,10],w:280,lab:2}); P.seg(1,-6,1,10,{c:'var(--muted)',w:1.5,dash:true}).fn(x=>x+1,{c:'var(--ok)',w:1.5,dash:true})
    .fn(f,{from:-5,to:.95}).fn(f,{from:1.05,to:7}).text(-4.8,-3,'y = x + 1',{c:'var(--ok)'}).text(1,9,'x = 1',{dx:6,c:'var(--muted)'}); return P.svg(); })()},
 {kind:'Méthode',h:'Division de polynômes et asymptote oblique',p:'<b>Quand :</b> f est une fraction dont le numérateur a exactement un degré de plus que le dénominateur. <b>Pourquoi ça marche :</b> la division donne f(x) = <i>mx</i> + <i>p</i> + R(x)/D(x) avec un reste R de degré plus petit que D, donc R/D → 0 : la courbe se rapproche de la droite <i>y</i> = <i>mx</i> + <i>p</i>. <b>Comment :</b> divise le terme de plus haut degré du haut par celui du bas, multiplie, soustrais, et recommence jusqu’à ce que le reste soit de degré trop petit.',
  demo:{enonce:`Asymptote oblique de f(x) = ${F('<i>x</i>² + 3<i>x</i> + 5','<i>x</i> + 1')}.`,
   etapes:[
    {f:'<i>x</i>² ÷ <i>x</i> = <i>x</i> ; <i>x</i>(<i>x</i> + 1) = <i>x</i>² + <i>x</i> ; reste (<i>x</i>² + 3<i>x</i> + 5) − (<i>x</i>² + <i>x</i>) = 2<i>x</i> + 5',w:'On élimine le terme en <i>x</i>².'},
    {f:'2<i>x</i> ÷ <i>x</i> = 2 ; 2(<i>x</i> + 1) = 2<i>x</i> + 2 ; reste (2<i>x</i> + 5) − (2<i>x</i> + 2) = 3',w:'On élimine le terme en <i>x</i>. Le reste 3 est de degré 0 : on s’arrête.'},
    {f:'<i>x</i>² + 3<i>x</i> + 5 = (<i>x</i> + 1)(<i>x</i> + 2) + 3, donc f(x) = <i>x</i> + 2 + 3/(<i>x</i> + 1)',w:'Contrôle : (<i>x</i> + 1)(<i>x</i> + 2) + 3 = <i>x</i>² + 3<i>x</i> + 5 ✓.'},
    {f:'3/(<i>x</i> + 1) → 0 en ±∞',w:'L’écart entre la courbe et la droite tend vers 0.'}],
   conclusion:'L’asymptote oblique est <i>y</i> = <i>x</i> + 2. Le signe de 3/(<i>x</i> + 1) dit en plus que la courbe est au-dessus en +∞ et en dessous en −∞.'},
  note:'Autre voie, valable pour toute fonction : <i>m</i> = lim f(x)/<i>x</i>, puis <i>p</i> = lim (f(x) − <i>mx</i>).'},
 {h:'Trouve l’asymptote oblique',p:`Quelle est l’asymptote oblique de f(x) = ${F('2<i>x</i>² − 3<i>x</i> + 4','<i>x</i> + 1')}&nbsp;?`,opts:['y = 2x − 3','y = 2x + 5','y = 2x − 5','y = 2x + 9'],ans:2,
  why:'Division : 2x² − 3x + 4 = (x + 1)(2x − 5) + 9. Donc f(x) = 2x − 5 + 9/(x + 1), et 9/(x + 1) → 0.'},
 {kind:'Méthode',h:'La démarche d’une étude de fonction',p:'<b>Quand :</b> on demande d’« étudier » <i>f</i>, de tracer son graphe ou de trouver ses extrema globaux. <b>Pourquoi cet ordre :</b> chaque étape prépare la suivante, et le tableau de variations final rassemble tout. <b>Comment :</b> 1) domaine de définition ; 2) symétries éventuelles (paire, impaire) ; 3) limites aux bornes du domaine et asymptotes ; 4) dérivée factorisée et son signe ; 5) tableau de variations avec les valeurs des extrema ; 6) si besoin, f″ pour la convexité.',
  demo:{enonce:`Étudier f(x) = ${F('<i>x</i>','<i>x</i>² + 1')}.`,
   etapes:[
    {f:'Domaine : ℝ',w:'<i>x</i>² + 1 ≥ 1 ne s’annule jamais.'},
    {f:'f(−x) = −f(x) : <i>f</i> est impaire',w:'Le graphe est symétrique par rapport à l’origine : on pourrait se limiter à <i>x</i> ≥ 0.'},
    {f:'En ±∞ : degré 1 en haut, 2 en bas, donc f(x) → 0',w:'Terme dominant. Asymptote horizontale <i>y</i> = 0.'},
    {f:`f′(x) = ${F('(<i>x</i>² + 1) − 2<i>x</i>²','(<i>x</i>² + 1)²')} = ${F('(1 − <i>x</i>)(1 + <i>x</i>)','(<i>x</i>² + 1)²')}`,w:'Règle du quotient, puis factorisation de 1 − <i>x</i>².'},
    {f:'f′ &lt; 0 sur ]−∞ ; −1[, f′ &gt; 0 sur ]−1 ; 1[, f′ &lt; 0 sur ]1 ; +∞[',w:'Le dénominateur est positif : le signe est celui de 1 − <i>x</i>².'},
    {f:'f décroît de 0 à f(−1) = −1/2, croît jusqu’à f(1) = 1/2, puis décroît vers 0',w:'Tableau de variations, avec les limites aux bouts.'}],
   conclusion:'Maximum global 1/2 en <i>x</i> = 1, minimum global −1/2 en <i>x</i> = −1 : ils sont globaux car <i>f</i> ne dépasse jamais ces valeurs, même aux bouts.'}},
 {kind:'Défi',h:'Étude complète',p:'Étudie f(x) = (ln <i>x</i>)/<i>x</i> sur ]0 ; +∞[. Quelle est la valeur de son maximum global, arrondie au centième&nbsp;?',lab:'max ≈',ans:1/Math.E,tol:.006,
  fig:(()=>{ const P=plane({x:[-.5,10],y:[-1.5,1],h:180,lab:2,grid:false}); P.fn(x=>Math.log(x)/x,{from:.25,to:10}).seg(Math.E,0,Math.E,1/Math.E,{c:'var(--muted)',w:1.5,dash:true}); return P.svg(); })(),
  why:'f′(x) = (1 − ln x)/x² : positive si x &lt; e, négative si x &gt; e. Maximum en x = e, de valeur 1/e ≈ 0,37. (f → −∞ en 0⁺ et f → 0 en +∞.)'},
 {kind:'Méthode',h:'Résoudre un problème d’optimisation',p:'<b>Quand :</b> on cherche la meilleure valeur d’une grandeur (aire, coût, longueur) sous une contrainte. <b>Pourquoi ça marche :</b> la contrainte permet d’exprimer la grandeur en fonction d’une seule variable ; on étudie alors une fonction comme d’habitude. <b>Comment :</b> nomme les variables, écris la grandeur et la contrainte, élimine une variable, précise l’intervalle permis, puis cherche l’extremum global avec f′.',
  demo:{enonce:'On clôture un enclos rectangulaire de 50 m² contre un mur : la clôture ne couvre que trois côtés. Quelle longueur minimale de clôture faut-il&nbsp;?',
   etapes:[
    {f:'Soit <i>x</i> la longueur des deux côtés perpendiculaires au mur, <i>y</i> celle du côté parallèle. Contrainte : <i>xy</i> = 50',w:'On nomme les inconnues et on écrit la contrainte.'},
    {f:'Clôture : L = 2<i>x</i> + <i>y</i> = 2<i>x</i> + 50/<i>x</i>, pour <i>x</i> &gt; 0',w:'On élimine <i>y</i> = 50/<i>x</i> : il ne reste qu’une variable.'},
    {f:'L′(x) = 2 − 50/<i>x</i>² = 0 ⇔ <i>x</i>² = 25 ⇔ <i>x</i> = 5',w:'On garde la solution positive.'},
    {f:'L′ &lt; 0 sur ]0 ; 5[ et L′ &gt; 0 sur ]5 ; +∞[',w:'L décroît puis croît : c’est un minimum global sur ]0 ; +∞[.'},
    {f:'L(5) = 10 + 10 = 20, et <i>y</i> = 10',w:'On calcule la valeur optimale et la dimension restante.'}],
   conclusion:'Il faut au minimum 20 m de clôture, avec un enclos de 5 m sur 10 m.'}},
 {h:'À toi',p:'Quelle est la plus petite valeur de f(x) = <i>x</i> + 9/<i>x</i> pour <i>x</i> &gt; 0&nbsp;?',lab:'min =',ans:6,
  why:'f′(x) = 1 − 9/x² s’annule en x = 3 (x &gt; 0), négative avant et positive après. Minimum f(3) = 3 + 3 = 6.'},
 {kind:'Récapitulatif',h:'Ce qu’il faut retenir : extrema et étude de fonction',p:'<div class="keep"><ul><li><b>Extremum local</b> en <i>a</i> : f(x) ≤ f(a) (maximum) ou f(x) ≥ f(a) (minimum) près de <i>a</i> ; <b>global</b> si c’est vrai sur tout le domaine.</li><li>En un point <b>intérieur</b> où <i>f</i> est dérivable, un extremum impose <b>f′(a) = 0</b>. C’est nécessaire, pas suffisant (<i>x</i>³ en 0).</li><li><b>Signe de f′</b> sur un intervalle : f′ &gt; 0 ⇒ croissante, f′ &lt; 0 ⇒ décroissante. f′ passe de + à − : maximum ; de − à + : minimum ; pas de changement de signe : pas d’extremum.</li><li><b>Sur un segment</b>, <i>f</i> continue atteint un maximum et un minimum globaux : compare <i>f</i> aux points critiques intérieurs <b>et</b> aux bornes.</li><li><b>Signe de f″</b> : f″ &gt; 0 convexe (au-dessus des tangentes), f″ &lt; 0 concave. <b>Inflexion</b> là où f″ change de signe ; f″(a) = 0 seul ne suffit pas.</li><li><b>Asymptotes</b> : verticale <i>x</i> = <i>a</i> si f → ±∞ en <i>a</i> ; oblique <i>y</i> = <i>mx</i> + <i>p</i> avec <i>m</i> = lim f(x)/<i>x</i> et <i>p</i> = lim (f(x) − <i>mx</i>), ou par <b>division de polynômes</b> quand le degré du haut dépasse de 1.</li><li><b>Étude complète</b> : domaine, symétries, limites et asymptotes, f′ factorisée et son signe, tableau de variations, puis f″ si besoin.</li><li><b>Optimisation</b> : nommer les variables, écrire la grandeur et la contrainte, éliminer une variable, fixer l’intervalle, chercher l’extremum global.</li></ul></div>'},
 {kind:'Problème',h:'La canette la plus économique',
  p:'Une canette cylindrique doit contenir <i>V</i> = 330 cm³. Pour économiser l’aluminium, on veut minimiser sa surface totale : le fond, le couvercle et la paroi. On note <i>r</i> le rayon et <i>h</i> la hauteur, en cm. On cherche les dimensions optimales.',
  parts:[
   {q:'a) Exprime la surface en fonction de <i>r</i> seul.',opts:['S(r) = πr² + 330/r','S(r) = 2πr² + 660/r','S(r) = 2πr² + 330/r','S(r) = 2πr · 330'],ans:1,hint:'Le volume impose <i>h</i> = 330/(π<i>r</i>²). La paroi déroulée est un rectangle de côtés 2π<i>r</i> et <i>h</i>.',why:'Fond et couvercle : 2πr². Paroi : 2πr · h = 2πr · 330/(πr²) = 660/r.'},
   {q:'b) Pour quel rayon la surface est-elle minimale&nbsp;? Arrondis au centième.',lab:'r ≈',unit:'cm',ans:Math.cbrt(330/(2*Math.PI)),tol:.006,hint:'Résous S′(<i>r</i>) = 4π<i>r</i> − 660/<i>r</i>² = 0.',why:'4πr³ = 660 ⇔ r³ = 165/π ⇔ r ≈ 3,74 cm. S′ &lt; 0 avant et S′ &gt; 0 après : c’est un minimum.'},
   {q:'c) Que vaut alors le rapport <i>h</i>/<i>r</i>&nbsp;?',lab:'h/r =',ans:2,hint:'Au minimum, π<i>r</i>³ = 165 = <i>V</i>/2. Remplace dans <i>h</i> = <i>V</i>/(π<i>r</i>²).',why:'h = V/(πr²) = 2πr³/(πr²) = 2r. La hauteur égale le diamètre.'},
   {q:'d) Quelle est la surface minimale&nbsp;? Arrondis au cm².',lab:'S ≈',unit:'cm²',ans:6*Math.PI*Math.cbrt(330/(2*Math.PI))**2,tol:.5,hint:'Avec <i>h</i> = 2<i>r</i>, S = 2π<i>r</i>² + 2π<i>r</i> · 2<i>r</i>.',why:'S = 6πr² ≈ 6π · 3,745² ≈ 264 cm².'},
  ],
  sol:'Le volume donne h = 330/(πr²). Surface : S(r) = 2πr² + 2πrh = 2πr² + 660/r, pour r &gt; 0.<br>S′(r) = 4πr − 660/r² = (4πr³ − 660)/r². Elle s’annule pour r³ = 165/π, soit r ≈ 3,74 cm.<br>S′ &lt; 0 avant, S′ &gt; 0 après, et S → +∞ en 0⁺ et en +∞ : c’est le minimum global.<br>Alors h = 330/(πr²) = 2r ≈ 7,49 cm : la canette optimale est aussi haute que large.<br>S<sub>min</sub> = 6πr² ≈ 264 cm². (Les vraies canettes sont plus hautes : la prise en main et l’épaisseur du fond comptent aussi.)'},
 {kind:'Problème',h:'Étude complète d’une fraction',
  p:`On étudie f(x) = ${F('<i>x</i>² + 3','<i>x</i> − 1')} sur ℝ \\ {1}. On cherche ses asymptotes et ses extrema. On veut ensuite savoir pour quelles valeurs de <i>k</i> l’équation f(x) = <i>k</i> a des solutions.`,
  fig:(()=>{ const f=x=>(x*x+3)/(x-1), P=plane({x:[-6,8],y:[-8,14],w:300,lab:2}); P.seg(1,-8,1,14,{c:'var(--muted)',w:1.5,dash:true}).fn(x=>x+1,{c:'var(--ok)',w:1.5,dash:true})
    .fn(f,{from:-6,to:.8}).fn(f,{from:1.25,to:8}).dot(-1,-2,{r:4,c:'var(--ink)'}).dot(3,6,{r:4,c:'var(--ink)'}); return P.svg(); })(),
  parts:[
   {q:'a) Quelle est l’asymptote oblique&nbsp;?',opts:['<i>y</i> = <i>x</i>','<i>y</i> = <i>x</i> − 1','<i>y</i> = <i>x</i> + 1','<i>y</i> = <i>x</i> + 4'],ans:2,hint:'Divise <i>x</i>² + 3 par <i>x</i> − 1.',why:'x² + 3 = (x − 1)(x + 1) + 4, donc f(x) = x + 1 + 4/(x − 1), et 4/(x − 1) → 0.'},
   {q:'b) En quelle abscisse <i>f</i> a-t-elle un minimum local&nbsp;?',lab:'x =',ans:3,hint:'f′(<i>x</i>) = 1 − 4/(<i>x</i> − 1)². Où s’annule-t-elle, et comment change son signe&nbsp;?',why:'f′(x) = 0 ⇔ (x − 1)² = 4 ⇔ x = 3 ou x = −1. En 3, f′ passe de − à + : minimum local f(3) = 12/2 = 6.'},
   {q:'c) Quelle est la valeur du maximum local&nbsp;?',lab:'f =',ans:-2,hint:'Calcule f en l’autre zéro de f′.',why:'En x = −1, f′ passe de + à − : maximum local f(−1) = 4/(−2) = −2.'},
   {q:'d) Pour quelles valeurs de <i>k</i> l’équation f(x) = <i>k</i> n’a-t-elle aucune solution&nbsp;?',opts:[']−2 ; 6[','[−2 ; 6]',']−∞ ; −2[ ∪ ]6 ; +∞[','Aucune : <i>f</i> prend toutes les valeurs'],ans:0,hint:'Lis le tableau de variations sur chacun des deux intervalles ]−∞ ; 1[ et ]1 ; +∞[.',why:'Sur ]−∞ ; 1[, f monte jusqu’à −2 puis redescend vers −∞ : elle prend les valeurs de ]−∞ ; −2]. Sur ]1 ; +∞[, elle descend de +∞ à 6 puis remonte : valeurs [6 ; +∞[. Rien entre −2 et 6.'},
  ],
  sol:'Division : f(x) = x + 1 + 4/(x − 1). Asymptote verticale x = 1 (f → −∞ en 1⁻, +∞ en 1⁺) et oblique y = x + 1 en ±∞.<br>f′(x) = 1 − 4/(x − 1)² = ((x − 3)(x + 1))/(x − 1)², du signe de (x − 3)(x + 1).<br>Variations : f croît sur ]−∞ ; −1], décroît sur [−1 ; 1[ et sur ]1 ; 3], croît sur [3 ; +∞[.<br>Maximum local f(−1) = −2, minimum local f(3) = 6. Le maximum local est plus petit que le minimum local : ces extrema ne sont pas globaux.<br>Image : ]−∞ ; −2] ∪ [6 ; +∞[. L’équation f(x) = k n’a aucune solution si k ∈ ]−2 ; 6[, une seule si k = −2 ou k = 6, deux sinon.<br>f″(x) = 8/(x − 1)³ : f est concave à gauche de 1 et convexe à droite, sans point d’inflexion.'},
]},

{subj:'an1', sem:'pri', id:'an1-arcs', h:'Arcs paramétrés', p:'Une courbe décrite par un point qui bouge : vitesse, tangente, points singuliers, le folium de Descartes et le limaçon de Pascal.', steps:[
 {kind:'Théorie',h:'Un point qui bouge : l’arc paramétré',p:'<p>Le graphe d’une fonction <i>y</i> = f(x) ne peut ni revenir en arrière ni se recouper : à chaque <i>x</i> correspond un seul point. Or la trajectoire d’une valve de vélo, d’une planète ou d’un ballon fait des boucles et des pointes. Pour la décrire, on suit le point au cours du temps.</p><div class="def"><p>Un <b>arc paramétré</b> est une application γ qui, à chaque valeur du <b>paramètre</b> <i>t</i> d’un intervalle I, associe un point du plan : <b>γ(t) = (x(t) ; y(t))</b> (lire « gamma de t »). Les fonctions <i>x</i> et <i>y</i> sont les <b>coordonnées</b> de l’arc ; l’ensemble des points obtenus est sa <b>trace</b>.</p></div><div class="idea"><p>Pense à <i>t</i> comme au temps : γ(t) est la position d’un mobile à l’instant <i>t</i>. Le même dessin peut être parcouru de plusieurs façons (plus vite, plus lentement, en sens inverse) : l’arc contient plus d’information que la trace, il dit aussi comment on la parcourt.</p></div><div class="ex"><p>γ(t) = (<i>t</i>² − 1 ; <i>t</i>³ − 3<i>t</i>). En <i>t</i> = 0 : (−1 ; 0) ; en <i>t</i> = 1 : (0 ; −2) ; en <i>t</i> = −1 : (0 ; 2). En <i>t</i> = √3 comme en <i>t</i> = −√3, on trouve (3 − 1 ; 3√3 − 3√3) = (2 ; 0) : la courbe passe deux fois par ce point, elle se recoupe (la figure). Aucun graphe de fonction ne peut faire ça.</p></div><div class="warn"><p>Ne confonds pas <i>t</i> avec l’abscisse : ici l’abscisse vaut <i>x</i>(<i>t</i>) = <i>t</i>² − 1, pas <i>t</i>. Le cercle γ(t) = (cos <i>t</i> ; sin <i>t</i>) en est un autre exemple : <i>t</i> est un angle, et le point fait un tour quand <i>t</i> va de 0 à 2π.</p></div>',
  fig:(()=>{ const P=plane({x:[-1.6,3.6],y:[-3.2,3.2],w:300,lab:1}); P.curve(t=>t*t-1,t=>t**3-3*t,-2.1,2.1)
    .dot(-1,0,{r:4,c:'var(--ink)',l:'t = 0'}).dot(0,-2,{r:4,c:'var(--ink)',l:'t = 1'}).dot(0,2,{r:4,c:'var(--ink)',l:'t = −1'}).dot(2,0,{r:5,c:'var(--spark)',l:'t = ±√3'}); return P.svg(); })()},
 {kind:'Théorie',h:'Vitesse et tangente',p:'<p>Quand le point γ(t) se déplace, on veut savoir dans quelle direction il va et à quelle vitesse. Comme pour une fonction, on regarde le déplacement entre <i>t</i> et <i>t</i> + <i>h</i>, on le divise par <i>h</i>, puis on fait tendre <i>h</i> vers 0.</p><div class="def"><p>Si <i>x</i> et <i>y</i> sont dérivables, le <b>vecteur vitesse</b> en <i>t</i> est <b>γ′(t) = (x′(t) ; y′(t))</b>, limite de (γ(t + h) − γ(t))/h. Sa longueur <b>|γ′(t)| = √(x′(t)² + y′(t)²)</b> est la <b>vitesse</b> (scalaire). Si γ′(t) ≠ (0 ; 0), le point est <b>régulier</b> et γ′(t) <b>dirige la tangente</b> ; si γ′(t) = (0 ; 0), le point est <b>singulier</b>.</p></div><div class="idea"><p>Le vecteur (γ(t + h) − γ(t))/h va de γ(t) vers un point voisin de la courbe : il porte une corde. Quand <i>h</i> → 0, la corde devient la tangente. Si x′(t) ≠ 0, la pente de cette tangente vaut <b>y′(t)/x′(t)</b>.</p></div><div class="ex"><p>La <b>cycloïde</b> <i>x</i> = <i>t</i> − sin <i>t</i>, <i>y</i> = 1 − cos <i>t</i> est la trajectoire d’un point d’une roue de rayon 1 qui roule. γ′(t) = (1 − cos <i>t</i> ; sin <i>t</i>). En <i>t</i> = 90° (π/2) : γ′ = (1 ; 1), vitesse √2 ≈ 1,41, tangente de pente 1. En <i>t</i> = 180° (π), au sommet de l’arche : γ′ = (2 ; 0), vitesse 2, tangente horizontale.</p></div><div class="warn"><p>En <i>t</i> = 0 et en <i>t</i> = 360°, γ′ = (0 ; 0) : le point s’arrête un instant au contact du sol. La vitesse ne donne alors aucune direction, et la courbe y forme une <b>pointe</b>. Un point singulier est un endroit où il faut se méfier : la courbe peut y faire une pointe ou un angle.</p></div>',
  params:[{id:'t',l:'t',min:0,max:720,step:15,v:90,u:'°'}],
  draw:v=>{ const t=rad(v.t), P=plane({x:[-.6,13.2],y:[-1.3,3.6],lab:2,step:1}); P.curve(s=>s-Math.sin(s),s=>1-Math.cos(s),0,4*Math.PI);
    const x=t-Math.sin(t), y=1-Math.cos(t); P.circ(t,1,1,{c:'var(--muted)',w:1.2}).arrow(x,y,x+1-Math.cos(t),y+Math.sin(t),{c:'var(--spark)',w:3}).dot(x,y,{r:5,c:'var(--ink)'}); return P.svg(); },
  info:v=>{ const t=rad(v.t), vx=1-Math.cos(t), vy=Math.sin(t); return `γ′(t) = (1 − cos t ; sin t) = (${fmt(vx)} ; ${fmt(vy)}) · vitesse ${fmt(Math.hypot(vx,vy))}`; }},
 {kind:'Méthode',h:'Vitesse, tangentes et points singuliers',p:'<b>Quand :</b> on étudie un arc γ(<i>t</i>) = (<i>x</i>(<i>t</i>) ; <i>y</i>(<i>t</i>)). <b>Pourquoi ça marche :</b> le vecteur γ′(<i>t</i>) dirige la tangente. Si <i>x</i>′ ≠ 0, sa pente vaut <b><i>y</i>′/<i>x</i>′</b>. <b>Comment :</b> dérive chaque coordonnée. <i>y</i>′ = 0 avec <i>x</i>′ ≠ 0 donne une tangente <b>horizontale</b> ; <i>x</i>′ = 0 avec <i>y</i>′ ≠ 0 une tangente <b>verticale</b> ; <i>x</i>′ = <i>y</i>′ = 0 <b>en même temps</b> un point <b>singulier</b>.',
  demo:{enonce:'Étudier les tangentes de γ(<i>t</i>) = (<i>t</i>² − 1 ; <i>t</i>³ − 3<i>t</i>).',
   etapes:[
    {f:'γ′(<i>t</i>) = (2<i>t</i> ; 3<i>t</i>² − 3) = (2<i>t</i> ; 3(<i>t</i> − 1)(<i>t</i> + 1))',w:'On dérive chaque coordonnée et on factorise.'},
    {f:'<i>x</i>′ = 0 ⇔ <i>t</i> = 0, et alors <i>y</i>′ = −3 ≠ 0 : tangente verticale en γ(0) = (−1 ; 0)',w:'Une seule coordonnée de la vitesse est nulle.'},
    {f:'<i>y</i>′ = 0 ⇔ <i>t</i> = ±1, et <i>x</i>′ = ±2 ≠ 0 : tangentes horizontales en γ(1) = (0 ; −2) et γ(−1) = (0 ; 2)',w:'Même raisonnement pour <i>y</i>′.'},
    {f:'<i>x</i>′ et <i>y</i>′ ne s’annulent jamais ensemble',w:'Les zéros de <i>x</i>′ (0) et de <i>y</i>′ (±1) sont différents.'}],
   conclusion:'L’arc n’a pas de point singulier. Ailleurs, la pente de la tangente vaut <i>y</i>′/<i>x</i>′ = 3(<i>t</i>² − 1)/(2<i>t</i>).'}},
 {kind:'Pratique',h:'Trouve un point singulier',p:'Place le point sur un point singulier de la cycloïde, avec 0° &lt; <i>t</i> &lt; 720°.',
  params:[{id:'t',l:'t',min:0,max:720,step:15,v:90,u:'°'}],
  draw:v=>{ const t=rad(v.t), P=plane({x:[-.6,13.2],y:[-1.3,3.6],lab:2,step:1}); P.curve(s=>s-Math.sin(s),s=>1-Math.cos(s),0,4*Math.PI);
    const x=t-Math.sin(t), y=1-Math.cos(t); P.arrow(x,y,x+1-Math.cos(t),y+Math.sin(t),{c:'var(--spark)',w:3}).dot(x,y,{r:5,c:'var(--ink)'}); return P.svg(); },
  info:v=>`|γ′(t)| = ${fmt(Math.hypot(1-Math.cos(rad(v.t)),Math.sin(rad(v.t))))}`,
  ok:v=>v.t===360,why:'γ′(t) = 0 demande 1 − cos t = 0 et sin t = 0, soit t = 0°, 360°, 720°… Entre les deux bornes : t = 360°. La courbe y forme un point de rebroussement.'},
 {h:'Calcule',p:'Pour γ(t) = (<i>t</i>² − 2<i>t</i> ; <i>t</i>³ − 3<i>t</i>), pour quelle valeur de <i>t</i> le point est-il singulier&nbsp;?',lab:'t =',ans:1,
  why:'x′(t) = 2t − 2 s’annule en t = 1 seulement, et y′(1) = 3·1² − 3 = 0. Les deux s’annulent ensemble en t = 1.'},
 {kind:'Méthode',h:'L’équation de la tangente à un arc',p:'<b>Quand :</b> on veut la droite tangente en un point régulier γ(<i>t</i>₀), par exemple pour trouver où elle coupe les axes. <b>Pourquoi ça marche :</b> elle passe par γ(<i>t</i>₀) et a la direction γ′(<i>t</i>₀). <b>Comment :</b> écris-la sous forme paramétrique (<i>x</i> ; <i>y</i>) = γ(<i>t</i>₀) + <i>s</i> · γ′(<i>t</i>₀), ou, si <i>x</i>′(<i>t</i>₀) ≠ 0, sous la forme <i>y</i> = <i>y</i>₀ + <i>m</i>(<i>x</i> − <i>x</i>₀) avec la pente <i>m</i> = <i>y</i>′/<i>x</i>′.',
  demo:{enonce:'Tangente à γ(<i>t</i>) = (<i>t</i>² ; <i>t</i>³) en <i>t</i> = 1, et son intersection avec O<i>x</i>.',
   etapes:[
    {f:'γ(1) = (1 ; 1) et γ′(<i>t</i>) = (2<i>t</i> ; 3<i>t</i>²), donc γ′(1) = (2 ; 3)',w:'Le point et le vecteur directeur.'},
    {f:'Pente <i>m</i> = 3/2',w:'<i>x</i>′(1) = 2 ≠ 0, la pente existe.'},
    {f:'<i>y</i> = 1 + (3/2)(<i>x</i> − 1) = 1,5<i>x</i> − 0,5',w:'Droite de pente <i>m</i> passant par (1 ; 1).'},
    {f:'<i>y</i> = 0 ⇔ <i>x</i> = 1/3',w:'On cherche le point d’ordonnée nulle.'}],
   conclusion:'La tangente <i>y</i> = 1,5<i>x</i> − 0,5 coupe O<i>x</i> en <i>x</i> = 1/3.'}},
 {h:'À toi',p:'Pour γ(<i>t</i>) = (2<i>t</i> ; <i>t</i>²), la tangente en <i>t</i> = 2 coupe l’axe O<i>x</i>. En quelle abscisse&nbsp;?',lab:'x =',ans:2,
  why:'γ(2) = (4 ; 4) et γ′(2) = (2 ; 4), pente 2. Tangente : y = 4 + 2(x − 4) = 2x − 4, qui s’annule en x = 2.'},
 {kind:'Théorie',h:'Le folium de Descartes',p:'<p>Le folium (« feuille » en latin) est une courbe qui a à la fois une boucle, un point double et une asymptote. Son équation cartésienne <i>x</i>³ + <i>y</i>³ = 3<i>axy</i> est difficile à exploiter ; sa version paramétrée permet de la parcourir pas à pas.</p><div class="def"><p>Pour <i>a</i> &gt; 0 : <b><i>x</i>(t) = 3<i>at</i>/(1 + <i>t</i>³)</b>, <b><i>y</i>(t) = 3<i>at</i>²/(1 + <i>t</i>³)</b>, <i>t</i> ≠ −1. On l’obtient en coupant la courbe par la droite <i>y</i> = <i>tx</i> : le paramètre <i>t</i> est la pente de la droite qui joint l’origine au point.</p></div><div class="idea"><p>Pour <i>t</i> ≥ 0, le point part de l’origine (<i>t</i> = 0), monte dans le premier quadrant, passe au sommet en <i>t</i> = 1 et revient vers l’origine quand <i>t</i> → +∞ : c’est la boucle. Remplacer <i>t</i> par 1/<i>t</i> échange <i>x</i> et <i>y</i>, donc la boucle est symétrique par rapport à <i>y</i> = <i>x</i>. Quand <i>t</i> → −1, le dénominateur 1 + <i>t</i>³ tend vers 0 et le point file à l’infini, le long de l’asymptote <b><i>x</i> + <i>y</i> + <i>a</i> = 0</b>.</p></div><div class="ex"><p>Avec <i>a</i> = 1,5 et <i>t</i> = 1 : <i>x</i> = <i>y</i> = 4,5/2 = 2,25, le sommet de la boucle. Avec <i>t</i> = 2 : <i>x</i> = 9/9 = 1 et <i>y</i> = 18/9 = 2. Pour l’asymptote : 1 + <i>t</i>³ = (1 + <i>t</i>)(1 − <i>t</i> + <i>t</i>²), donc <i>x</i> + <i>y</i> = 3<i>at</i>/(1 − <i>t</i> + <i>t</i>²), qui tend vers −3<i>a</i>/3 = −<i>a</i> quand <i>t</i> → −1.</p></div><div class="warn"><p>L’origine n’est pas un point singulier : la courbe y passe en <i>t</i> = 0 et y revient quand <i>t</i> → ±∞, avec deux tangentes différentes. C’est un <b>point double</b>, comme un carrefour, où la vitesse ne s’annule pas.</p></div>',
  params:[{id:'a',l:'a',min:.5,max:2,step:.5,v:1.5},{id:'t',l:'t',min:0,max:4,step:.2,v:.6}],
  draw:v=>{ const a=v.a, X=t=>3*a*t/(1+t**3), Y=t=>3*a*t*t/(1+t**3), P=plane({x:[-4,4],y:[-4,4],lab:2});
    P.fn(x=>-x-a,{c:'var(--muted)',w:1.5,dash:true});
    P.curve(s=>X(Math.tan(s)),s=>Y(Math.tan(s)),0,Math.PI/2-.005,{n:400}).curve(X,Y,-.97,0).curve(s=>X(-1/s),s=>Y(-1/s),.02,.97);
    const t=v.t, d=(1+t**3)**2, vx=3*a*(1-2*t**3)/d, vy=3*a*(2*t-t**4)/d;
    P.arrow(X(t),Y(t),X(t)+vx/2,Y(t)+vy/2,{c:'var(--spark)',w:2.5}).dot(X(t),Y(t),{r:5,c:'var(--ink)'}); return P.svg(); },
  info:v=>{ const a=v.a,t=v.t,d=1+t**3; return `γ(${fmt(t,1)}) = (${fmt(3*a*t/d)} ; ${fmt(3*a*t*t/d)})`+(t===1?' : sommet de la boucle, sur la droite y = x':''); },
  note:'La vitesse vaut γ′(t) = 3a/(1 + t³)² · (1 − 2t³ ; 2t − t⁴). Elle ne s’annule jamais : le folium n’a pas de point singulier, l’origine est un <b>point double</b>.'},
 {h:'Tangente au sommet',p:'Au point du folium obtenu pour <i>t</i> = 1, quelle est la pente de la tangente&nbsp;?',opts:['1','0','−1','La tangente est verticale'],ans:2,
  why:'En t = 1 : x′ = 3a(1 − 2)/4 = −3a/4 et y′ = 3a(2 − 1)/4 = 3a/4. Pente y′/x′ = −1, perpendiculaire à l’axe de symétrie y = x.'},
 {kind:'Théorie',h:'Repérer un point par un angle et une distance',p:'<p>Pour décrire une courbe qui tourne autour de l’origine (une spirale, une fleur, un limaçon), il est souvent plus simple de dire « dans quelle direction » et « à quelle distance » que de donner <i>x</i> et <i>y</i>.</p><div class="def"><p>Les <b>coordonnées polaires</b> (<i>r</i> ; θ) d’un point M sont la distance <i>r</i> = OM et l’angle θ entre l’axe O<i>x</i> et la demi-droite OM. On repasse aux coordonnées cartésiennes par <b><i>x</i> = <i>r</i> cos θ</b> et <b><i>y</i> = <i>r</i> sin θ</b>. Une <b>courbe polaire</b> <i>r</i> = f(θ) est l’arc paramétré γ(θ) = (f(θ) cos θ ; f(θ) sin θ).</p></div><div class="idea"><p>Imagine un phare à l’origine dont le faisceau tourne : pour chaque angle θ, on place le point sur le faisceau, à la distance f(θ). Si f(θ) est négatif, le point se retrouve à la distance |f(θ)| dans la direction opposée, θ + π. Et la courbe passe par l’origine chaque fois que f(θ) = 0.</p></div><div class="ex"><p><i>r</i> = 2 donne le cercle de centre O et de rayon 2. <i>r</i> = 2 cos θ donne <i>x</i> = 2 cos²θ et <i>y</i> = 2 cos θ sin θ ; on vérifie <i>x</i>² + <i>y</i>² = 4 cos²θ = 2<i>x</i>, soit (<i>x</i> − 1)² + <i>y</i>² = 1 : le cercle de centre (1 ; 0) et de rayon 1. Pour θ = π/3, <i>r</i> = 1 et le point est (0,5 ; √3/2 ≈ 0,866).</p></div><div class="warn"><p>Dans les formules, les angles se mesurent en radians : θ = π correspond à 180°. Et un même point a plusieurs écritures polaires, car θ et θ + 2π désignent la même direction.</p></div>'},
 {kind:'Théorie',h:'Le limaçon de Pascal',p:'<p>Le limaçon est la courbe polaire <b><i>r</i> = <i>b</i> + <i>a</i> cos θ</b> (avec <i>a</i> &gt; 0 et <i>b</i> ≥ 0), soit <i>x</i> = (<i>b</i> + <i>a</i> cos θ) cos θ et <i>y</i> = (<i>b</i> + <i>a</i> cos θ) sin θ. Une seule formule, et pourtant quatre formes très différentes selon le rapport <i>b</i>/<i>a</i>.</p><div class="idea"><p>Quand θ fait un tour, la distance <i>r</i> oscille entre <i>b</i> + <i>a</i> (en θ = 0, à droite) et <i>b</i> − <i>a</i> (en θ = π, à gauche). Tout dépend du signe de <i>b</i> − <i>a</i>. Si <i>b</i> &lt; <i>a</i>, <i>r</i> devient négatif autour de θ = π : le point passe de l’autre côté de l’origine et trace une <b>boucle intérieure</b>. Si <i>b</i> = <i>a</i>, <i>r</i> s’annule juste en θ = π : c’est la <b>cardioïde</b>, avec une pointe à l’origine. Si <i>a</i> &lt; <i>b</i> &lt; 2<i>a</i>, <i>r</i> reste positif mais la courbe se creuse d’une <b>fossette</b> ; dès <i>b</i> ≥ 2<i>a</i>, c’est un ovale <b>convexe</b>.</p></div><div class="ex"><p>Avec <i>a</i> = 3 et <i>b</i> = 1 : <i>r</i> = 1 + 3 cos θ vaut 4 en θ = 0 et −2 en θ = π. Il s’annule quand cos θ = −1/3, pour deux angles (θ ≈ 109,5° et θ ≈ 250,5°) : la courbe traverse deux fois l’origine, d’où la boucle intérieure. Avec <i>a</i> = <i>b</i> = 1 : <i>r</i> = 1 + cos θ ≥ 0 ne s’annule qu’en θ = π, la cardioïde.</p></div><div class="warn"><p>Passer par l’origine ne suffit pas à faire une pointe : dans la boucle intérieure, la courbe traverse l’origine avec une vitesse non nulle. La pointe de la cardioïde vient de ce que <i>r</i> et <i>r</i>′ s’y annulent en même temps.</p></div>',
  params:[{id:'a',l:'a',min:.5,max:3,step:.5,v:2},{id:'b',l:'b',min:0,max:4,step:.5,v:1}],
  draw:v=>{ const r=t=>v.b+v.a*Math.cos(t), P=plane({x:[-5,7.5],y:[-5.5,5.5],lab:2}); P.curve(t=>r(t)*Math.cos(t),t=>r(t)*Math.sin(t),0,2*Math.PI,{n:360}).dot(0,0,{r:4,c:'var(--ink)'}); return P.svg(); },
  info:v=>{ const a=v.a,b=v.b; return b===0?'b = 0 : r = a cos θ, un cercle de diamètre a.':b<a?'b &lt; a : r s’annule deux fois, d’où une <b>boucle intérieure</b>.':b===a?'b = a : <b>cardioïde</b>, point singulier à l’origine.':b<2*a?'a &lt; b &lt; 2a : limaçon à <b>fossette</b>.':'b ≥ 2a : ovale <b>convexe</b>.'; }},
 {kind:'Méthode',h:'Courbe polaire : passages par l’origine',p:'<b>Quand :</b> la courbe est donnée par <i>r</i> = f(θ). <b>Pourquoi ça marche :</b> le point (<i>r</i> cos θ ; <i>r</i> sin θ) est l’origine exactement quand <i>r</i> = 0. On a aussi |γ′(θ)|² = <i>r</i>′² + <i>r</i>² : un point est singulier si <i>r</i> = 0 et <i>r</i>′ = 0 en même temps. <b>Comment :</b> résous f(θ) = 0 sur [0 ; 2π[. Pour cos θ = <i>c</i> (avec −1 &lt; <i>c</i> &lt; 1), il y a deux solutions θ₀ et 2π − θ₀ ; pour sin θ = <i>c</i>, θ₀ et π − θ₀. Lis θ₀ sur le cercle trigonométrique.',
  demo:{enonce:'Passages par l’origine de <i>r</i> = 1 − 2 sin θ, θ ∈ [0 ; 2π[.',
   etapes:[
    {f:'<i>r</i> = 0 ⇔ sin θ = 1/2',w:'On isole la fonction trigonométrique.'},
    {f:'sin(π/6) = 1/2, donc θ = π/6 ou θ = π − π/6 = 5π/6',w:'Deux angles ont le même sinus : θ₀ et son symétrique par rapport à l’axe vertical.'},
    {f:'<i>r</i>′ = −2 cos θ vaut −√3 et √3 en ces angles, non nul',w:'Les passages ne sont pas des points singuliers : la courbe traverse l’origine dans la direction θ.'}],
   conclusion:'La courbe passe deux fois par l’origine, pour θ = π/6 et θ = 5π/6, ce qui forme une boucle.'},
  note:'Valeurs à connaître : cos(π/3) = sin(π/6) = 1/2, cos(π/6) = sin(π/3) = √3/2, cos(2π/3) = −1/2.'},
 {kind:'Pratique',h:'Fabrique une cardioïde',p:'Avec <i>a</i> = 2, règle <i>b</i> pour que la courbe ait un point singulier (une pointe).',
  params:[{id:'b',l:'b',min:0,max:4,step:.5,v:3}],
  draw:v=>{ const r=t=>v.b+2*Math.cos(t), P=plane({x:[-5,7.5],y:[-5.5,5.5],lab:2}); P.curve(t=>r(t)*Math.cos(t),t=>r(t)*Math.sin(t),0,2*Math.PI,{n:360}).dot(0,0,{r:4,c:'var(--ink)'}); return P.svg(); },
  ok:v=>v.b===2,why:'|γ′(θ)|² = r′² + r². Il est nul si r = 0 et r′ = −a sin θ = 0, donc θ = π et b − a = 0. Avec a = 2 : b = 2, la cardioïde r = 2(1 + cos θ).'},
 {kind:'Défi',h:'Passages par l’origine',p:'Pour <i>r</i> = 1 + 2 cos θ, combien de fois la courbe passe-t-elle par l’origine quand θ parcourt [0 ; 2π[&nbsp;?',ans:2,
  why:'r = 0 ⇔ cos θ = −1/2 ⇔ θ = 2π/3 ou 4π/3. Deux passages, ce qui ferme la boucle intérieure (b = 1 &lt; a = 2).'},
 {kind:'Méthode',h:'Éliminer le paramètre',p:'<b>Quand :</b> on veut reconnaître la forme d’un arc paramétré (droite, parabole, cercle) par une équation en <i>x</i> et <i>y</i> seulement. <b>Pourquoi ça marche :</b> si l’on peut exprimer <i>t</i> en fonction de <i>x</i>, on le remplace dans <i>y</i>(<i>t</i>) : chaque point de l’arc vérifie alors la nouvelle équation. <b>Comment :</b> isole <i>t</i> dans l’équation la plus simple, puis remplace dans l’autre. Avec cos <i>t</i> et sin <i>t</i>, utilise plutôt cos²<i>t</i> + sin²<i>t</i> = 1.',
  demo:{enonce:'Équation cartésienne de γ(<i>t</i>) = (<i>t</i> + 1 ; <i>t</i>² − 2<i>t</i>).',
   etapes:[
    {f:'<i>x</i> = <i>t</i> + 1 ⇔ <i>t</i> = <i>x</i> − 1',w:'La première coordonnée est affine en <i>t</i> : facile à inverser.'},
    {f:'<i>y</i> = (<i>x</i> − 1)² − 2(<i>x</i> − 1)',w:'On remplace <i>t</i> dans <i>y</i>(<i>t</i>).'},
    {f:'<i>y</i> = <i>x</i>² − 2<i>x</i> + 1 − 2<i>x</i> + 2 = <i>x</i>² − 4<i>x</i> + 3',w:'On développe et on réduit.'}],
   conclusion:'L’arc est la parabole <i>y</i> = <i>x</i>² − 4<i>x</i> + 3. Pour (3 cos <i>t</i> ; 3 sin <i>t</i>), on trouverait <i>x</i>² + <i>y</i>² = 9 : un cercle.'}},
 {h:'Quelle courbe&nbsp;?',p:'Quelle est l’équation cartésienne de γ(<i>t</i>) = (2<i>t</i> ; 4<i>t</i> − <i>t</i>²)&nbsp;?',opts:['<i>y</i> = 4<i>x</i> − <i>x</i>²','<i>y</i> = 2<i>x</i> − <i>x</i>²/2','<i>y</i> = <i>x</i>/2 − <i>x</i>²/4','<i>y</i> = 2<i>x</i> − <i>x</i>²/4'],ans:3,
  why:'t = x/2, donc y = 4 · x/2 − (x/2)² = 2x − x²/4 : une parabole tournée vers le bas.'},
 {kind:'Récapitulatif',h:'Ce qu’il faut retenir : arcs paramétrés',p:'<div class="keep"><ul><li><b>Arc paramétré</b> γ(t) = (x(t) ; y(t)) : un point qui bouge avec le paramètre <i>t</i>. La trace peut se recouper, revenir en arrière, faire des pointes.</li><li><b>Vitesse</b> γ′(t) = (x′(t) ; y′(t)), de longueur |γ′(t)| = √(x′² + y′²). Si γ′(t) ≠ 0, elle dirige la tangente, de pente <b>y′/x′</b> quand x′ ≠ 0.</li><li><b>Tangente horizontale</b> : y′ = 0 et x′ ≠ 0. <b>Verticale</b> : x′ = 0 et y′ ≠ 0. <b>Point singulier</b> : x′ = y′ = 0 en même temps (souvent une pointe).</li><li><b>Équation de la tangente</b> en γ(t₀) : (x ; y) = γ(t₀) + s · γ′(t₀), ou y = y₀ + m(x − x₀) avec m = y′(t₀)/x′(t₀).</li><li><b>Point double</b> : la courbe passe deux fois au même endroit pour deux valeurs du paramètre (folium à l’origine), sans que la vitesse s’annule.</li><li><b>Coordonnées polaires</b> : x = r cos θ, y = r sin θ. La courbe r = f(θ) passe par l’origine quand f(θ) = 0 ; |γ′|² = r′² + r², donc point singulier si r = r′ = 0.</li><li><b>Limaçon</b> r = b + a cos θ : boucle intérieure si b &lt; a, cardioïde si b = a, fossette si a &lt; b &lt; 2a, ovale convexe si b ≥ 2a.</li><li><b>Éliminer le paramètre</b> : isoler <i>t</i> et le remplacer, ou utiliser cos²t + sin²t = 1, pour reconnaître droite, parabole ou cercle.</li></ul></div>'},
 {kind:'Problème',h:'La trajectoire d’un ballon',
  p:'Un ballon est lancé depuis le sol. Sa position (en m) au temps <i>t</i> (en s) est <b>γ(<i>t</i>) = (20<i>t</i> ; 15<i>t</i> − 5<i>t</i>²)</b>, de <i>t</i> = 0 jusqu’à l’instant où il retombe. On étudie la trajectoire avec le vecteur vitesse.',
  params:[{id:'t',l:'t',min:0,max:3,step:.25,v:.5,u:' s'}],
  draw:v=>{ const P=plane({x:[-4,64],y:[-3,14],w:320,grid:false,lx:10,ly:5}); P.curve(s=>20*s,s=>15*s-5*s*s,0,3);
    const x=20*v.t, y=15*v.t-5*v.t*v.t; P.arrow(x,y,x+20*.4,y+(15-10*v.t)*.4,{c:'var(--spark)',w:2.5}).dot(x,y,{r:5,c:'var(--ink)'}); return P.svg(); },
  info:v=>`γ(${fmt(v.t)}) = (${fmt(20*v.t)} ; ${fmt(15*v.t-5*v.t*v.t)}) · γ′(t) = (20 ; ${fmt(15-10*v.t)})`,
  parts:[
   {q:'a) À quel instant le ballon retombe-t-il au sol&nbsp;?',lab:'t =',unit:'s',ans:3,hint:'Résous <i>y</i>(<i>t</i>) = 0 avec <i>t</i> &gt; 0.',why:'15t − 5t² = 5t(3 − t) = 0 ⇔ t = 0 ou t = 3. Il retombe en t = 3 s.'},
   {q:'b) À quelle distance du point de lancer&nbsp;?',lab:'x =',unit:'m',ans:60,hint:'Calcule <i>x</i>(3).',why:'x(3) = 20 · 3 = 60 m.'},
   {q:'c) Quelle est la pente de la tangente à la trajectoire en <i>t</i> = 1&nbsp;?',lab:'pente =',ans:.25,tol:1e-9,hint:'La pente vaut <i>y</i>′(<i>t</i>)/<i>x</i>′(<i>t</i>).',why:'γ′(t) = (20 ; 15 − 10t). En t = 1 : (20 ; 5), pente 5/20 = 0,25.'},
   {q:'d) Quelle est la hauteur maximale atteinte&nbsp;?',lab:'y =',unit:'m',ans:11.25,tol:1e-9,hint:'Au sommet, la tangente est horizontale : <i>y</i>′(<i>t</i>) = 0.',why:'y′(t) = 15 − 10t = 0 ⇔ t = 1,5 s. y(1,5) = 22,5 − 11,25 = 11,25 m.'},
  ],
  sol:'y(t) = 5t(3 − t) s’annule en t = 3 s : le ballon retombe à x(3) = 60 m.<br>Vitesse : γ′(t) = (20 ; 15 − 10t). Elle ne s’annule jamais (x′ = 20), donc la trajectoire n’a pas de point singulier.<br>Pente de la tangente : (15 − 10t)/20. En t = 1, elle vaut 0,25.<br>La tangente est horizontale quand y′(t) = 0, soit t = 1,5 s : sommet (30 ; 11,25).<br>En éliminant t (t = x/20), on trouve y = 0,75x − x²/80 : la trajectoire est une parabole.'},
 {kind:'Problème',h:'L’échelle qui glisse',
  p:'L’<b>astroïde</b> est l’arc γ(<i>t</i>) = (cos³ <i>t</i> ; sin³ <i>t</i>), <i>t</i> ∈ [0 ; 2π[. Elle a la forme d’une étoile à quatre pointes. On cherche ses points singuliers, puis on découvre une propriété surprenante de ses tangentes. Déplace le point avec le curseur.',
  params:[{id:'t',l:'t',min:0,max:90,step:5,v:35,u:'°'}],
  draw:v=>{ const t=rad(v.t), P=plane({x:[-1.3,1.3],y:[-1.3,1.3],w:300,step:.5,lab:1}); P.curve(s=>Math.cos(s)**3,s=>Math.sin(s)**3,0,2*Math.PI,{n:400});
    P.seg(Math.cos(t),0,0,Math.sin(t),{c:'var(--spark)',w:2.5}).dot(Math.cos(t),0,{r:4,c:'var(--spark)',l:'A'}).dot(0,Math.sin(t),{r:4,c:'var(--spark)',l:'B'}).dot(Math.cos(t)**3,Math.sin(t)**3,{r:5,c:'var(--ink)'}); return P.svg(); },
  info:v=>{ const t=rad(v.t); return `A = (${fmt(Math.cos(t))} ; 0), B = (0 ; ${fmt(Math.sin(t))}) · AB = ${fmt(Math.hypot(Math.cos(t),Math.sin(t)))}`; },
  parts:[
   {q:'a) Combien l’astroïde a-t-elle de points singuliers sur [0 ; 2π[&nbsp;?',ans:4,hint:'Calcule γ′(<i>t</i>) et mets 3 sin <i>t</i> cos <i>t</i> en facteur.',why:'γ′(t) = (−3cos²t sin t ; 3sin²t cos t) = 3 sin t cos t (−cos t ; sin t). Il est nul ssi sin t cos t = 0 : t = 0, π/2, π, 3π/2. Ce sont les quatre pointes.'},
   {q:'b) Quelle est la pente de la tangente en <i>t</i> = π/3&nbsp;? Arrondis au centième.',lab:'pente ≈',ans:-Math.sqrt(3),tol:.006,hint:'La pente vaut <i>y</i>′/<i>x</i>′ ; simplifie avant de remplacer.',why:'y′/x′ = 3sin²t cos t/(−3cos²t sin t) = −tan t. En π/3 : −√3 ≈ −1,73.'},
   {q:'c) En <i>t</i> = π/3, la tangente coupe O<i>x</i> en A et O<i>y</i> en B. Calcule la longueur AB.',lab:'AB =',ans:1,tol:1e-6,hint:'La tangente passe par (cos³ <i>t</i> ; sin³ <i>t</i>) avec la direction (−cos <i>t</i> ; sin <i>t</i>). Cherche où <i>y</i> = 0, puis où <i>x</i> = 0.',why:'On trouve A = (cos t ; 0) et B = (0 ; sin t), donc AB = √(cos²t + sin²t) = 1. En π/3 : A = (0,5 ; 0), B = (0 ; 0,866).'},
   {q:'d) Que montre ce calcul, fait pour un <i>t</i> quelconque de ]0 ; π/2[&nbsp;?',opts:['Le segment AB rétrécit vers les pointes','Le segment AB garde la longueur 1 : c’est une échelle de longueur 1 qui glisse contre un mur, et l’astroïde est tangente à toutes ses positions','Le segment AB passe toujours par l’origine','Le segment AB est toujours parallèle à <i>y</i> = −<i>x</i>'],ans:1,hint:'Le calcul de c) ne dépend pas de la valeur π/3.',why:'Pour tout t, A = (cos t ; 0) et B = (0 ; sin t) : AB = 1. L’astroïde est l’enveloppe des positions d’une échelle de longueur 1 qui glisse entre le sol et le mur.'},
  ],
  sol:'γ′(t) = 3 sin t cos t (−cos t ; sin t). Il s’annule pour t = 0, π/2, π, 3π/2 : quatre points singuliers, les pointes.<br>Ailleurs, la tangente a la direction (−cos t ; sin t) et la pente −tan t (−√3 en π/3).<br>Tangente : (x ; y) = (cos³t − s cos t ; sin³t + s sin t). y = 0 pour s = −sin²t, d’où x = cos³t + sin²t cos t = cos t. x = 0 pour s = cos²t, d’où y = sin t.<br>Donc A = (cos t ; 0), B = (0 ; sin t), et AB = 1 pour tout t.<br>Interprétation : une échelle de longueur 1 qui glisse le long d’un mur touche toujours l’astroïde. La courbe est l’enveloppe de ces segments.'},
]},

{subj:'an1', sem:'pri', id:'an1-riemann', h:'Sommes de Riemann et théorème fondamental', p:'Encadrer une aire par des rectangles, définir l’intégrale, puis la relier à la dérivée.', steps:[
 {kind:'Théorie',h:'Sommes inférieures et supérieures',p:'<p>L’aire d’un rectangle ou d’un triangle se calcule avec une formule. Mais quelle est l’aire de la région sous la parabole <i>y</i> = <i>x</i>², entre 0 et 2 ? Aucune formule de géométrie ne la donne. L’idée est de l’approcher par des rectangles, dont on connaît l’aire, puis de raffiner le découpage.</p><div class="def"><p>On coupe [<i>a</i> ; <i>b</i>] en <i>n</i> morceaux de même largeur <b>Δ<i>x</i> = (<i>b</i> − <i>a</i>)/<i>n</i></b> (lire « delta x » : la lettre Δ note une petite différence). Sur chaque morceau, on pose un rectangle dont la hauteur est le <b>minimum</b> de <i>f</i> sur ce morceau : la somme de leurs aires est la <b>somme inférieure</b> <i>sₙ</i>. Avec le <b>maximum</b>, on obtient la <b>somme supérieure</b> <i>Sₙ</i>.</p></div><div class="idea"><p>Les rectangles bas restent sous la courbe, les hauts la dépassent : <b><i>sₙ</i> ≤ aire ≤ <i>Sₙ</i></b>. Plus <i>n</i> est grand, plus les rectangles épousent la courbe, et plus l’encadrement se resserre. Bouge le curseur : l’écart <i>Sₙ</i> − <i>sₙ</i> fond.</p></div><div class="ex"><p>f(x) = <i>x</i>² sur [0 ; 2] avec <i>n</i> = 2 : Δ<i>x</i> = 1, morceaux [0 ; 1] et [1 ; 2]. <i>f</i> croît, donc son minimum est au bord gauche et son maximum au bord droit : <i>s</i>₂ = 1 · (0 + 1) = 1 et <i>S</i>₂ = 1 · (1 + 4) = 5. Avec <i>n</i> = 4 (Δ<i>x</i> = 0,5) : <i>s</i>₄ = 0,5 · (0 + 0,25 + 1 + 2,25) = 1,75 et <i>S</i>₄ = 0,5 · (0,25 + 1 + 2,25 + 4) = 3,75. L’aire est entre 1,75 et 3,75 ; on verra qu’elle vaut 8/3 ≈ 2,67.</p></div><div class="warn"><p>Le maximum sur un morceau n’est pas toujours à un bord : si <i>f</i> monte puis redescend sur ce morceau, il est au sommet. La règle « bord gauche ou bord droit » ne vaut que pour une fonction monotone.</p></div>',
  params:[{id:'n',l:'n',min:1,max:40,v:4}],
  draw:v=>{ const f=x=>x*x, d=2/v.n, P=plane({x:[-.3,2.3],y:[-.4,4.3],h:260,step:.5,lab:1});
    for(let k=0;k<v.n;k++){ P.rect(k*d,0,d,f((k+1)*d),{fill:'var(--spark)',fo:.3,c:'var(--spark)',w:1}); P.rect(k*d,0,d,f(k*d),{fill:'var(--math)',fo:.5,c:'var(--math)',w:1}); }
    P.fn(f,{from:0,to:2.1}); return P.svg(); },
  info:v=>{ const d=2/v.n; let s=0,S=0; for(let k=0;k<v.n;k++){ s+=d*(k*d)**2; S+=d*((k+1)*d)**2; } return `sₙ ≈ ${fmt(s,4)} ≤ 8/3 ≈ 2,6667 ≤ Sₙ ≈ ${fmt(S,4)} · écart Sₙ − sₙ = ${fmt(S-s,4)}`; }},
 {kind:'Méthode',h:'Calculer une somme de Riemann à la main',p:'<b>Quand :</b> on demande <i>sₙ</i> ou <i>Sₙ</i> pour un <i>n</i> donné. <b>Pourquoi ça marche :</b> chaque rectangle a pour aire largeur × hauteur. Si <i>f</i> est <b>croissante</b>, son minimum sur un morceau est au bord gauche et son maximum au bord droit ; si elle est <b>décroissante</b>, c’est l’inverse. <b>Comment :</b> calcule Δ<i>x</i> = (<i>b</i> − <i>a</i>)/<i>n</i>, liste les bords des morceaux, choisis le bon bord selon la monotonie, puis Δ<i>x</i> × (somme des hauteurs).',
  demo:{enonce:'f(x) = 1 + <i>x</i> sur [0 ; 2], avec <i>n</i> = 4. Calculer <i>s</i>₄ et <i>S</i>₄.',
   etapes:[
    {f:'Δ<i>x</i> = (2 − 0)/4 = 0,5 ; bords : 0 ; 0,5 ; 1 ; 1,5 ; 2',w:'Quatre morceaux de même largeur.'},
    {f:'<i>f</i> est croissante : minimum au bord gauche, maximum au bord droit',w:'Le choix du bord dépend de la monotonie.'},
    {f:'<i>s</i>₄ = 0,5 · (f(0) + f(0,5) + f(1) + f(1,5)) = 0,5 · (1 + 1,5 + 2 + 2,5) = 3,5',w:'Bords gauches 0 ; 0,5 ; 1 ; 1,5.'},
    {f:'<i>S</i>₄ = 0,5 · (f(0,5) + f(1) + f(1,5) + f(2)) = 0,5 · (1,5 + 2 + 2,5 + 3) = 4,5',w:'Bords droits 0,5 ; 1 ; 1,5 ; 2.'}],
   conclusion:'3,5 ≤ aire ≤ 4,5. L’aire exacte (un trapèze) vaut 4.'}},
 {h:'Une somme inférieure',p:'Calcule la somme inférieure <i>s</i>₄ de f(x) = <i>x</i> sur [0 ; 1].',lab:'s₄ =',ans:.375,tol:1e-9,
  why:'Δx = 1/4 et f croissante : on prend les bords gauches 0, 1/4, 2/4, 3/4. s₄ = (1/4)(0 + 1/4 + 1/2 + 3/4) = (1/4)(3/2) = 3/8 = 0,375.'},
 {kind:'Théorie',h:'L’intégrale de Riemann',p:'<p>Les sommes inférieures encadrent l’aire par en dessous, les supérieures par au-dessus. Si les deux se rejoignent quand on raffine le découpage, il ne reste qu’un seul nombre possible pour l’aire : c’est lui qu’on appelle l’intégrale.</p><div class="def"><p><i>f</i>, bornée sur [<i>a</i> ; <i>b</i>], est <b>intégrable</b> (au sens de Riemann) si le sup des sommes inférieures (la plus petite valeur qui les dépasse toutes) est égal à l’inf des sommes supérieures (la plus grande valeur qui reste sous toutes). Cette valeur commune est l’<b>intégrale</b> de <i>f</i> de <i>a</i> à <i>b</i>, notée <b>∫ₐᵇ f(x) dx</b>.</p></div><div class="blk" data-t="La notation"><p>Le signe ∫ est un S allongé, pour « somme » : il rappelle la somme des f(x) · Δ<i>x</i>. <i>a</i> et <i>b</i> sont les <b>bornes</b>, f(x) est la hauteur des rectangles et d<i>x</i> rappelle leur largeur Δ<i>x</i>, devenue infiniment petite. La variable est muette : ∫ₐᵇ f(x) d<i>x</i> = ∫ₐᵇ f(t) d<i>t</i>.</p></div><div class="thm"><p>Toute fonction <b>continue</b> sur [<i>a</i> ; <i>b</i>], et toute fonction <b>monotone</b> sur [<i>a</i> ; <i>b</i>], est intégrable.</p></div><div class="why"><p>Pour <i>f</i> croissante, le minimum d’un morceau est le maximum du morceau précédent : les rectangles se décalent d’un cran, et il ne reste que la différence entre le dernier et le premier (voir la note). Pour f(x) = <i>x</i> sur [0 ; 1] : <i>sₙ</i> = (<i>n</i> − 1)/(2<i>n</i>) et <i>Sₙ</i> = (<i>n</i> + 1)/(2<i>n</i>), dont l’écart 1/<i>n</i> tend vers 0. Les deux tendent vers 1/2, l’aire du triangle.</p></div><div class="warn"><p>Une fonction bornée peut ne pas être intégrable : celle qui vaut 1 sur les rationnels et 0 ailleurs a toujours <i>sₙ</i> = 0 et <i>Sₙ</i> = <i>b</i> − <i>a</i>, car chaque morceau contient des nombres des deux sortes.</p></div>',
  note:'Pour <i>f</i> croissante, les rectangles se décalent d’un cran : <b>Sₙ − sₙ = (f(b) − f(a)) · (b − a)/n</b>, qui tend vers 0.'},
 {h:'L’écart',p:'Pour f(x) = <i>x</i>² sur [0 ; 2], que vaut <i>Sₙ</i> − <i>sₙ</i>&nbsp;?',opts:['4/n','2/n','8/n²','8/n'],ans:3,
  why:'f est croissante : Sₙ − sₙ = (f(2) − f(0)) · (2 − 0)/n = 4 · 2/n = 8/n.'},
 {kind:'Pratique',h:'Assez de rectangles',p:'Trouve le <b>plus petit</b> <i>n</i> pour lequel <i>Sₙ</i> − <i>sₙ</i> &lt; 0,25 (toujours f(x) = <i>x</i>² sur [0 ; 2]).',
  params:[{id:'n',l:'n',min:1,max:40,v:5}],
  draw:v=>{ const f=x=>x*x, d=2/v.n, P=plane({x:[-.3,2.3],y:[-.4,4.3],h:260,step:.5,lab:1});
    for(let k=0;k<v.n;k++){ P.rect(k*d,0,d,f((k+1)*d),{fill:'var(--spark)',fo:.3,c:'var(--spark)',w:1}); P.rect(k*d,0,d,f(k*d),{fill:'var(--math)',fo:.5,c:'var(--math)',w:1}); }
    P.fn(f,{from:0,to:2.1}); return P.svg(); },
  info:v=>`Sₙ − sₙ = 8/${v.n} ≈ ${fmt(8/v.n,4)}`,
  ok:v=>v.n===33,why:'8/n &lt; 0,25 ⇔ n &gt; 32. Pour n = 32 l’écart vaut exactement 0,25 : il faut n = 33.'},
 {kind:'Théorie',h:'Aire signée et propriétés de l’intégrale',p:'<p>Avant de calculer des intégrales, il faut savoir comment elles se comportent : que se passe-t-il quand la courbe passe sous l’axe, quand on additionne deux fonctions, quand on coupe l’intervalle en deux ?</p><div class="idea"><p>Là où <i>f</i> est négative, les rectangles de hauteur f(x) comptent négativement : l’intégrale est une <b>aire signée</b>, l’aire au-dessus de l’axe moins l’aire au-dessous (en rouge sur la figure).</p></div><div class="prop"><p>Pour <i>f</i>, <i>g</i> intégrables et <i>k</i> réel :</p><ul><li><b>Linéarité</b> : ∫ₐᵇ (f + g) = ∫ₐᵇ f + ∫ₐᵇ g et ∫ₐᵇ kf = k ∫ₐᵇ f.</li><li><b>Relation de Chasles</b> : ∫ₐᶜ f = ∫ₐᵇ f + ∫ᵇᶜ f.</li><li><b>Positivité</b> : si f ≥ 0 sur [<i>a</i> ; <i>b</i>], alors ∫ₐᵇ f ≥ 0 ; si f ≤ g, alors ∫ₐᵇ f ≤ ∫ₐᵇ g.</li><li><b>Convention</b> : ∫<sub>b</sub><sup>a</sup> f = −∫ₐᵇ f et ∫ₐᵃ f = 0.</li></ul></div><div class="why"><p>Chaque propriété est vraie pour les sommes de rectangles, puis passe à la limite. Additionner deux fonctions additionne les hauteurs ; multiplier par <i>k</i> étire les rectangles ; couper [<i>a</i> ; <i>c</i>] en <i>b</i> sépare les rectangles en deux paquets ; des hauteurs positives donnent des aires positives.</p></div><div class="ex"><p>f(x) = <i>x</i> sur [−1 ; 2] : le triangle sous l’axe (de −1 à 0) a une aire 1/2, celui au-dessus (de 0 à 2) une aire 2. Par Chasles, ∫₋₁² <i>x</i> d<i>x</i> = −1/2 + 2 = 3/2, alors que l’aire géométrique totale vaut 1/2 + 2 = 5/2.</p></div><div class="warn"><p>Il n’y a pas de règle pour le produit : ∫ fg n’est pas (∫ f)(∫ g). Avec f = g = <i>x</i> sur [0 ; 1], ∫₀¹ <i>x</i>² d<i>x</i> = 1/3, mais (∫₀¹ <i>x</i> d<i>x</i>)² = 1/4.</p></div>',
  fig:(()=>{ const P=plane({x:[-1.5,2.5],y:[-1.3,2.4],w:280,lab:1}); P.area(x=>x,-1,0,{fill:'var(--bad)'}).area(x=>x,0,2).fn(x=>x,{from:-1.5,to:2.5}); return P.svg(); })()},
 {kind:'Théorie',h:'Le théorème fondamental',p:'<p>Calculer une intégrale avec des sommes de rectangles est long. Le théorème fondamental fait un lien inattendu entre deux problèmes : calculer une aire et calculer une dérivée. Grâce à lui, on intègre en lisant les dérivées à l’envers.</p><div class="def"><p>Pour <i>f</i> continue sur un intervalle contenant <i>a</i>, la <b>fonction aire</b> est <b>F(x) = ∫ₐˣ f(t) dt</b> : l’aire signée sous la courbe entre <i>a</i> et <i>x</i>. On écrit <i>t</i> pour la variable d’intégration, car la lettre <i>x</i> est déjà prise par la borne.</p></div><div class="thm"><p><b>Théorème fondamental.</b> Si <i>f</i> est continue, F est dérivable et <b>F′(x) = f(x)</b>.</p></div><div class="why"><p>F(x + h) − F(x) = ∫ₓ<sup>x+h</sup> f(t) dt est l’aire d’une bande très fine de largeur <i>h</i>, presque un rectangle de hauteur f(x). Donc (F(x + h) − F(x))/h ≈ f(x), et l’écart tend vers 0 avec <i>h</i> parce que <i>f</i> est continue : sur la bande, f(t) reste proche de f(x).</p></div><div class="ex"><p>Avec f(t) = 2 − <i>t</i> et <i>a</i> = 0 : pour 0 ≤ <i>x</i> ≤ 2, la région est un trapèze de bases 2 et 2 − <i>x</i> et de largeur <i>x</i>, d’aire <i>x</i>(2 + 2 − <i>x</i>)/2 = 2<i>x</i> − <i>x</i>²/2 (la courbe jaune). On a bien F′(x) = 2 − <i>x</i> = f(x). En <i>x</i> = 1 : F(1) = 1,5 et la pente de F y vaut f(1) = 1.</p></div><div class="warn"><p>La continuité compte : si <i>f</i> saute en un point, F y fait un angle et n’y est pas dérivable. Et F′ = f, pas F = f : F mesure l’aire accumulée, <i>f</i> la vitesse à laquelle elle s’accumule.</p></div>',
  params:[{id:'x',l:'x',min:0,max:4,step:.25,v:1}],
  draw:v=>{ const f=t=>2-t, P=plane({x:[-.5,4.5],y:[-2.5,2.6],lab:1});
    P.area(f,0,Math.min(v.x,2)); if(v.x>2) P.area(f,2,v.x,{fill:'var(--bad)'});
    P.fn(f,{from:0,to:4.4}).fn(t=>2*t-t*t/2,{from:0,to:4.4,c:'var(--spark)',w:2.5}).dot(v.x,2*v.x-v.x*v.x/2,{r:5,c:'var(--spark)',l:'F(x)'}); return P.svg(); },
  info:v=>`F(${fmt(v.x)}) = ${fmt(2*v.x-v.x*v.x/2,4)} · F′(x) = f(x) = ${fmt(2-v.x)}`,
  note:'L’aire sous l’axe compte négativement (en rouge). F est maximale en x = 2, là où f = F′ change de signe.'},
 {kind:'Théorie',h:'De la primitive à la valeur de l’intégrale',p:'<p>Le théorème fondamental dit que la fonction aire a pour dérivée <i>f</i>. Mais pour calculer une intégrale précise, inutile de passer par la fonction aire : n’importe quelle fonction dont la dérivée est <i>f</i> fait l’affaire.</p><div class="def"><p>Une <b>primitive</b> de <i>f</i> sur un intervalle est une fonction G telle que <b>G′ = f</b>. Par exemple, <i>x</i>³/3 est une primitive de <i>x</i>², et <i>x</i>³/3 + 5 aussi.</p></div><div class="thm"><p>Si <i>f</i> est continue sur [<i>a</i> ; <i>b</i>] et si G est une primitive de <i>f</i>, alors <b>∫ₐᵇ f(x) dx = G(b) − G(a)</b>, qu’on note <b>[G(x)]ₐᵇ</b>.</p></div><div class="why"><p>F(x) = ∫ₐˣ f et G ont la même dérivée <i>f</i>, donc (G − F)′ = 0 : sur un intervalle, G − F est une constante <i>C</i>. Alors G(b) − G(a) = (F(b) + C) − (F(a) + C) = F(b) − F(a) = ∫ₐᵇ f − 0. La constante disparaît dans la différence : c’est pourquoi n’importe quelle primitive convient.</p></div><div class="ex"><p>L’aire sous <i>y</i> = <i>x</i>² entre 0 et 2, encadrée au début entre 1,75 et 3,75 : avec G(x) = <i>x</i>³/3, ∫₀² <i>x</i>² d<i>x</i> = 8/3 − 0 = 8/3 ≈ 2,667. Trois lignes au lieu d’une infinité de rectangles.</p></div><div class="warn"><p>On calcule toujours G(<b>borne du haut</b>) − G(<b>borne du bas</b>), dans cet ordre. Et le résultat est une aire signée : ∫₀² (<i>x</i> − 2) d<i>x</i> = [<i>x</i>²/2 − 2<i>x</i>]₀² = 2 − 4 = −2, car la droite est sous l’axe.</p></div>'},
 {kind:'Méthode',h:'Calculer une intégrale avec une primitive',p:'<b>Quand :</b> on veut la valeur exacte de ∫ₐᵇ f(x) d<i>x</i> et on connaît une fonction G dont la dérivée est <i>f</i>. <b>Pourquoi ça marche :</b> c’est le théorème fondamental : ∫ₐᵇ f = G(b) − G(a). <b>Comment :</b> trouve une primitive en lisant les dérivées à l’envers ; pour une puissance, <b><i>x</i>ⁿ a pour primitive <i>x</i>ⁿ⁺¹/(<i>n</i> + 1)</b> (<i>n</i> ≠ −1), car (<i>x</i>ⁿ⁺¹)′ = (<i>n</i> + 1)<i>x</i>ⁿ. Traite chaque terme séparément, puis écris [G(x)]ₐᵇ = G(b) − G(a).',
  demo:{enonce:'Calculer ∫₀² (<i>x</i>² − <i>x</i> + 1) d<i>x</i>.',
   etapes:[
    {f:'Primitive : G(x) = <i>x</i>³/3 − <i>x</i>²/2 + <i>x</i>',w:'Terme à terme : <i>x</i>² → <i>x</i>³/3, <i>x</i> → <i>x</i>²/2, 1 → <i>x</i>.'},
    {f:'Contrôle : G′(x) = <i>x</i>² − <i>x</i> + 1 ✓',w:'Dériver la primitive détecte presque toutes les erreurs.'},
    {f:'G(2) = 8/3 − 2 + 2 = 8/3 et G(0) = 0',w:'On évalue aux deux bornes.'},
    {f:'∫₀² (<i>x</i>² − <i>x</i> + 1) d<i>x</i> = 8/3 − 0 = 8/3',w:'Borne du haut moins borne du bas.'}],
   conclusion:'L’intégrale vaut 8/3 ≈ 2,667.'}},
 {h:'Calcule l’intégrale',p:'Calcule ∫₁³ (3<i>x</i>² − 2<i>x</i>) d<i>x</i>.',ans:18,
  why:'Une primitive est x³ − x². Donc (27 − 9) − (1 − 1) = 18.'},
 {kind:'Méthode',h:'Dériver une intégrale à borne variable',p:'<b>Quand :</b> une fonction est définie par G(x) = ∫ₐ<sup>u(x)</sup> f(t) d<i>t</i>, et on ne sait pas (ou on n’a pas besoin de) calculer l’intégrale. <b>Pourquoi ça marche :</b> avec F(y) = ∫ₐʸ f(t) d<i>t</i>, on a F′ = f (théorème fondamental) et G(x) = F(u(x)). La règle de chaîne donne <b>G′(x) = f(u(x)) · u′(x)</b>. <b>Comment :</b> remplace <i>t</i> par la borne du haut dans <i>f</i>, puis multiplie par la dérivée de cette borne.',
  demo:{enonce:'H(x) = ∫₀<sup><i>x</i>³</sup> √(1 + <i>t</i>) d<i>t</i>. Calculer H′(2).',
   etapes:[
    {f:'f(t) = √(1 + <i>t</i>) et u(x) = <i>x</i>³, u′(x) = 3<i>x</i>²',w:'On repère la fonction intégrée et la borne variable.'},
    {f:'H′(x) = √(1 + <i>x</i>³) · 3<i>x</i>²',w:'f(u(x)) · u′(x).'},
    {f:'H′(2) = √9 · 12 = 36',w:'On remplace <i>x</i> par 2.'}],
   conclusion:'H′(2) = 36, sans jamais calculer l’intégrale.'}},
 {h:'Borne variable',p:'Soit G(x) = ∫₀<sup><i>x</i>²</sup> cos <i>t</i> d<i>t</i>. Que vaut G′(x)&nbsp;?',opts:['cos(x²)','2x cos(x²)','sin(x²)','2x sin(x²)'],ans:1,
  why:'G(x) = F(x²) avec F′ = cos. Par la règle de chaîne : G′(x) = cos(x²) · 2x.'},
 {kind:'Méthode',h:'Reconnaître une somme de Riemann',p:'<b>Quand :</b> on cherche la limite d’une somme de la forme (1/<i>n</i>) Σ<sub>k=1</sub><sup>n</sup> f(k/<i>n</i>). <b>Pourquoi ça marche :</b> c’est la somme des aires de <i>n</i> rectangles de largeur 1/<i>n</i> et de hauteur f(k/<i>n</i>) sur [0 ; 1]. Quand <i>n</i> → ∞, elle tend vers ∫₀¹ f(x) d<i>x</i> (pour <i>f</i> continue). <b>Comment :</b> mets 1/<i>n</i> en facteur, repère la fonction <i>f</i> appliquée à k/<i>n</i>, puis calcule l’intégrale.',
  demo:{enonce:'Calculer lim (1/<i>n</i>) Σ<sub>k=1</sub><sup>n</sup> √(k/<i>n</i>) quand <i>n</i> → ∞.',
   etapes:[
    {f:'Δ<i>x</i> = 1/<i>n</i> et les points k/<i>n</i> parcourent ]0 ; 1]',w:'On reconnaît la largeur des rectangles et leurs bords droits sur [0 ; 1].'},
    {f:'La hauteur est f(k/<i>n</i>) avec f(x) = √<i>x</i>',w:'On lit la fonction.'},
    {f:'La limite vaut ∫₀¹ √<i>x</i> d<i>x</i> = ∫₀¹ <i>x</i><sup>1/2</sup> d<i>x</i> = [(2/3)<i>x</i><sup>3/2</sup>]₀¹',w:'√<i>x</i> = <i>x</i><sup>1/2</sup> : la règle des puissances donne <i>x</i><sup>3/2</sup>/(3/2).'},
    {f:'= 2/3',w:'On évalue entre 0 et 1.'}],
   conclusion:'La somme tend vers 2/3.'}},
 {kind:'Défi',h:'Une somme devenue intégrale',p:'Calcule lim (1/<i>n</i>) Σ<sub>k=1</sub><sup>n</sup> (k/n)² quand <i>n</i> → ∞. Donne une fraction ou un arrondi au millième.',lab:'L =',ans:1/3,tol:6e-4,
  why:'C’est une somme de Riemann de f(x) = x² sur [0 ; 1] avec Δx = 1/n. Elle tend vers ∫₀¹ x² dx = 1/3.'},
 {kind:'Méthode',h:'La valeur moyenne d’une fonction',p:'<b>Quand :</b> on demande la valeur moyenne d’une grandeur qui varie (débit, concentration, température) sur une durée. <b>Pourquoi ça marche :</b> la moyenne <i>m</i> est la hauteur du rectangle de base [<i>a</i> ; <i>b</i>] qui a la même aire que la courbe : <i>m</i>(<i>b</i> − <i>a</i>) = ∫ₐᵇ f. <b>Comment :</b> calcule l’intégrale, puis divise par la longueur de l’intervalle : <b><i>m</i> = (1/(<i>b</i> − <i>a</i>)) ∫ₐᵇ f(x) d<i>x</i></b>.',
  demo:{enonce:'Valeur moyenne de f(x) = <i>x</i>² sur [0 ; 3].',
   etapes:[
    {f:'∫₀³ <i>x</i>² d<i>x</i> = [<i>x</i>³/3]₀³ = 9',w:'On calcule d’abord l’aire sous la courbe.'},
    {f:'<i>m</i> = 9/(3 − 0) = 3',w:'On divise par la longueur de l’intervalle.'}],
   conclusion:'La moyenne vaut 3 : elle est atteinte en <i>x</i> = √3, entre la plus petite valeur 0 et la plus grande 9.'}},
 {h:'Une moyenne',p:'Calcule la valeur moyenne de f(x) = 4 − <i>x</i>² sur [0 ; 2]. Donne une fraction ou un arrondi au millième.',lab:'m =',ans:8/3,tol:6e-4,
  why:'∫₀² (4 − x²) dx = [4x − x³/3]₀² = 8 − 8/3 = 16/3. Moyenne : (16/3)/2 = 8/3 ≈ 2,667.'},
 {kind:'Méthode',h:'Aire géométrique : couper aux zéros',p:'<b>Quand :</b> on demande l’aire (toujours positive) entre une courbe et l’axe O<i>x</i>, alors que la fonction change de signe. <b>Pourquoi :</b> l’intégrale compte négativement les parties sous l’axe ; elles se compensent avec celles au-dessus. <b>Comment :</b> trouve les zéros de <i>f</i> dans l’intervalle, coupe l’intégrale en ces points, calcule chaque morceau, puis additionne leurs valeurs absolues.',
  demo:{enonce:'Aire entre la courbe de f(x) = <i>x</i>² − 1 et l’axe O<i>x</i>, pour <i>x</i> ∈ [0 ; 2].',
   etapes:[
    {f:'f(x) = 0 ⇔ <i>x</i> = 1 (dans [0 ; 2]) ; f &lt; 0 sur [0 ; 1[, f &gt; 0 sur ]1 ; 2]',w:'On repère où la courbe passe sous l’axe.'},
    {f:'∫₀¹ (<i>x</i>² − 1) d<i>x</i> = [<i>x</i>³/3 − <i>x</i>]₀¹ = −2/3',w:'Morceau sous l’axe : l’intégrale est négative.'},
    {f:'∫₁² (<i>x</i>² − 1) d<i>x</i> = (8/3 − 2) − (1/3 − 1) = 4/3',w:'Morceau au-dessus de l’axe.'},
    {f:'Aire = |−2/3| + 4/3 = 2',w:'On additionne les valeurs absolues.'}],
   conclusion:'L’aire vaut 2, alors que ∫₀² (<i>x</i>² − 1) d<i>x</i> = 2/3 seulement.'}},
 {h:'Aire ou intégrale&nbsp;?',p:'Calcule l’aire entre la courbe de f(x) = <i>x</i>² − 4 et l’axe O<i>x</i>, pour <i>x</i> ∈ [0 ; 3]. Donne une fraction ou un arrondi au millième.',lab:'A =',ans:23/3,tol:6e-4,
  why:'f s’annule en 2. ∫₀² (x² − 4) dx = 8/3 − 8 = −16/3 et ∫₂³ (x² − 4) dx = (9 − 12) − (8/3 − 8) = 7/3. Aire : 16/3 + 7/3 = 23/3 ≈ 7,667.'},
 {kind:'Récapitulatif',h:'Ce qu’il faut retenir : sommes de Riemann et intégrale',p:'<div class="keep"><ul><li><b>Découpage</b> de [<i>a</i> ; <i>b</i>] en <i>n</i> morceaux de largeur Δ<i>x</i> = (<i>b</i> − <i>a</i>)/<i>n</i>. Somme inférieure <i>sₙ</i> (minimum de <i>f</i> sur chaque morceau), supérieure <i>Sₙ</i> (maximum) : <b><i>sₙ</i> ≤ aire ≤ <i>Sₙ</i></b>. Croissante : bord gauche pour <i>sₙ</i>, droit pour <i>Sₙ</i> ; décroissante : l’inverse.</li><li><b>Intégrale</b> ∫ₐᵇ f(x) d<i>x</i> : valeur commune des sommes inférieures et supérieures à la limite. Continue ou monotone ⇒ intégrable. Monotone : <i>Sₙ</i> − <i>sₙ</i> = |f(b) − f(a)| · (<i>b</i> − <i>a</i>)/<i>n</i>.</li><li><b>Aire signée</b> : les parties sous l’axe comptent négativement. Linéarité, Chasles ∫ₐᶜ = ∫ₐᵇ + ∫ᵇᶜ, positivité ; pas de règle pour un produit.</li><li><b>Théorème fondamental</b> : F(x) = ∫ₐˣ f(t) d<i>t</i> vérifie F′ = f (<i>f</i> continue). Donc <b>∫ₐᵇ f = G(b) − G(a)</b> pour toute primitive G ; <i>x</i>ⁿ a pour primitive <i>x</i>ⁿ⁺¹/(<i>n</i> + 1).</li><li><b>Borne variable</b> : (∫ₐ<sup>u(x)</sup> f(t) d<i>t</i>)′ = f(u(x)) · u′(x).</li><li><b>Somme de Riemann</b> : (1/<i>n</i>) Σ<sub>k=1</sub><sup>n</sup> f(k/<i>n</i>) → ∫₀¹ f(x) d<i>x</i>.</li><li><b>Valeur moyenne</b> : <i>m</i> = (1/(<i>b</i> − <i>a</i>)) ∫ₐᵇ f.</li><li><b>Aire géométrique</b> : couper aux zéros de <i>f</i> et additionner les valeurs absolues des morceaux.</li></ul></div>'},
 {kind:'Problème',h:'Encadrer ln 2',
  p:'Sans calculatrice, on veut encadrer ln 2 = ∫₁² d<i>x</i>/<i>x</i>. La fonction f(x) = 1/<i>x</i> est <b>décroissante</b> sur [1 ; 2] : sur chaque morceau, son minimum est au bord droit et son maximum au bord gauche. On découpe [1 ; 2] en <i>n</i> morceaux égaux.',
  params:[{id:'n',l:'n',min:1,max:20,v:4}],
  draw:v=>{ const d=1/v.n, P=plane({x:[.8,2.2],y:[-.1,1.15],h:220,step:.25,lab:1});
    for(let k=0;k<v.n;k++){ const a=1+k*d; P.rect(a,0,d,1/a,{fill:'var(--spark)',fo:.3,c:'var(--spark)',w:1}).rect(a,0,d,1/(a+d),{fill:'var(--math)',fo:.5,c:'var(--math)',w:1}); }
    P.fn(x=>1/x,{from:.9,to:2.15}); return P.svg(); },
  info:v=>{ const d=1/v.n; let s=0,S=0; for(let k=0;k<v.n;k++){ s+=d/(1+(k+1)*d); S+=d/(1+k*d); } return `sₙ ≈ ${fmt(s,4)} ≤ ln 2 ≤ Sₙ ≈ ${fmt(S,4)}`; },
  parts:[
   {q:'a) Calcule la somme inférieure <i>s</i>₄, arrondie au millième.',lab:'s₄ ≈',ans:.25*(1/1.25+1/1.5+1/1.75+1/2),tol:6e-4,hint:'Δ<i>x</i> = 1/4. Prends les bords droits 1,25 ; 1,5 ; 1,75 ; 2.',why:'s₄ = (1/4)(4/5 + 2/3 + 4/7 + 1/2) ≈ (1/4) · 2,5381 ≈ 0,635.'},
   {q:'b) Calcule la somme supérieure <i>S</i>₄, arrondie au millième.',lab:'S₄ ≈',ans:.25*(1+1/1.25+1/1.5+1/1.75),tol:6e-4,hint:'Cette fois, les bords gauches 1 ; 1,25 ; 1,5 ; 1,75.',why:'S₄ = (1/4)(1 + 4/5 + 2/3 + 4/7) ≈ 0,760. Donc 0,634 &lt; ln 2 &lt; 0,760.'},
   {q:'c) L’écart <i>Sₙ</i> − <i>sₙ</i> vaut <i>c</i>/<i>n</i>. Que vaut <i>c</i>&nbsp;?',lab:'c =',ans:.5,tol:1e-9,hint:'Pour une fonction monotone, les rectangles se décalent d’un cran : seul le premier et le dernier comptent.',why:'Sₙ − sₙ = |f(1) − f(2)| · (2 − 1)/n = (1 − 1/2)/n = 0,5/n.'},
   {q:'d) Quel est le plus petit <i>n</i> qui garantit <i>Sₙ</i> − <i>sₙ</i> &lt; 0,01&nbsp;?',lab:'n =',ans:51,hint:'Résous 0,5/<i>n</i> &lt; 0,01. Attention au cas d’égalité.',why:'0,5/n &lt; 0,01 ⇔ n &gt; 50. Pour n = 50 l’écart vaut exactement 0,01 : il faut n = 51.'},
  ],
  sol:'f(x) = 1/x décroît sur [1 ; 2] : la somme inférieure utilise les bords droits, la supérieure les bords gauches.<br>Avec n = 4 : s₄ = (1/4)(4/5 + 2/3 + 4/7 + 1/2) ≈ 0,6345 et S₄ = (1/4)(1 + 4/5 + 2/3 + 4/7) ≈ 0,7595.<br>Donc 0,634 &lt; ln 2 &lt; 0,760 (en fait ln 2 ≈ 0,6931).<br>En général, Sₙ − sₙ = (f(1) − f(2))/n = 1/(2n), qui tend vers 0 : f est intégrable.<br>Pour garantir un écart &lt; 0,01, il faut 1/(2n) &lt; 0,01, soit n ≥ 51.'},
 {kind:'Problème',h:'Le volume d’une citerne',
  p:'Une citerne reçoit de l’eau avec un débit <b>d(t) = 6<i>t</i> − <i>t</i>²</b> (en L/min), où <i>t</i> est en minutes, pour <i>t</i> ∈ [0 ; 10]. Quand d(t) &lt; 0, la citerne se vide. Le volume ajouté depuis <i>t</i> = 0 vaut V(x) = ∫₀ˣ d(t) d<i>t</i>. On utilise le théorème fondamental pour étudier V.',
  params:[{id:'x',l:'x',min:0,max:10,step:.5,v:2,u:' min'}],
  draw:v=>{ const d=t=>6*t-t*t, P=plane({x:[-.5,10.5],y:[-17,40],w:320,h:260,grid:false,lx:2,ly:10});
    P.area(d,0,Math.min(v.x,6)); if(v.x>6) P.area(d,6,v.x,{fill:'var(--bad)'});
    P.fn(d,{from:0,to:10}).fn(t=>3*t*t-t**3/3,{from:0,to:10,c:'var(--spark)',w:2.5}).dot(v.x,3*v.x*v.x-v.x**3/3,{r:5,c:'var(--spark)',l:'V(x)'}); return P.svg(); },
  info:v=>`d(${fmt(v.x)}) = ${fmt(6*v.x-v.x*v.x)} L/min · V(${fmt(v.x)}) = ${fmt(3*v.x*v.x-v.x**3/3)} L`,
  parts:[
   {q:'a) À quel instant le volume ajouté V est-il maximal, et pourquoi&nbsp;?',opts:['En <i>t</i> = 3, car le débit y est maximal','En <i>t</i> = 6, car V′ = d passe de positif à négatif','En <i>t</i> = 10, car c’est la fin de l’intervalle','En <i>t</i> = 0, car V(0) = 0'],ans:1,hint:'Par le théorème fondamental, V′ = d. Étudie le signe de d.',why:'V′(t) = d(t) = t(6 − t) est positif sur ]0 ; 6[ et négatif sur ]6 ; 10]. V croît puis décroît : maximum en t = 6. En t = 3, c’est V′ qui est maximal, pas V.'},
   {q:'b) Que vaut ce volume maximal V(6)&nbsp;?',lab:'V(6) =',unit:'L',ans:36,hint:'Une primitive de 6<i>t</i> − <i>t</i>² est 3<i>t</i>² − <i>t</i>³/3.',why:'V(6) = 3 · 36 − 216/3 = 108 − 72 = 36 L.'},
   {q:'c) À quel instant la citerne retrouve-t-elle son volume de départ&nbsp;?',lab:'t =',unit:'min',ans:9,hint:'Résous V(<i>x</i>) = 0 avec <i>x</i> &gt; 0 et factorise <i>x</i>².',why:'V(x) = 3x² − x³/3 = x²(3 − x/3) = 0 ⇔ x = 9 min. Les 36 L entrés ont été vidés entre 6 et 9 minutes.'},
   {q:'d) Quel est le débit moyen sur [0 ; 6]&nbsp;?',lab:'d̄ =',unit:'L/min',ans:6,hint:'La moyenne d’une fonction sur [<i>a</i> ; <i>b</i>] vaut (1/(<i>b</i> − <i>a</i>)) ∫ₐᵇ.',why:'36 L en 6 minutes : 36/6 = 6 L/min, alors que le débit maximal (en t = 3) vaut 9 L/min.'},
  ],
  sol:'Par le théorème fondamental, V est dérivable et V′ = d, puisque d est continue.<br>d(t) = t(6 − t) &gt; 0 sur ]0 ; 6[ et &lt; 0 sur ]6 ; 10] : V croît sur [0 ; 6], décroît ensuite. Maximum en t = 6.<br>Avec la primitive 3t² − t³/3 : V(6) = 108 − 72 = 36 L.<br>V(x) = x²(3 − x/3) s’annule en x = 9 : à 9 min, la citerne a retrouvé son niveau initial. À 10 min, V(10) = 300 − 1000/3 ≈ −33,3 L, elle est sous son niveau de départ.<br>Débit moyen sur [0 ; 6] : V(6)/6 = 6 L/min.'},
]},

{subj:'an1', sem:'pri', id:'an1-primitives', h:'Recherche de primitives', p:'Les primitives à connaître, puis les deux grandes techniques : substitution et intégration par parties.', steps:[
 {kind:'Théorie',h:'Une famille de primitives',p:'<p>Dériver, on sait le faire. Le problème inverse est plus difficile et plus utile : connaissant la vitesse, retrouver la position ; connaissant <i>f</i>, trouver une fonction dont <i>f</i> est la dérivée. C’est la clé du calcul des intégrales, grâce au théorème fondamental.</p><div class="def"><p><i>F</i> est une <b>primitive</b> de <i>f</i> sur un intervalle I si <b>F′(x) = f(x)</b> pour tout <i>x</i> de I. On note toutes les primitives à la fois <b>∫ f(x) dx = F(x) + C</b>, où <i>C</i> est une constante quelconque : c’est une <b>intégrale indéfinie</b>, sans bornes.</p></div><div class="why"><p>Si <i>F</i> est une primitive, F + C en est une autre, car la dérivée d’une constante est nulle. Inversement, si <i>F</i> et <i>G</i> sont deux primitives, (G − F)′ = f − f = 0 sur l’intervalle, donc G − F est constante. Il n’y a donc pas d’autres primitives que les F + C.</p></div><div class="ex"><p>f(x) = 2<i>x</i> : <i>x</i>² est une primitive, comme <i>x</i>² + 1 ou <i>x</i>² − 3. Sur la figure, toutes ces courbes sont décalées verticalement : elles ont la même pente en chaque <i>x</i>. Si l’on impose F(2) = 1, alors 4 + C = 1, donc C = −3 et F(x) = <i>x</i>² − 3 : une condition fixe la constante.</p></div><div class="warn"><p>« Deux primitives diffèrent d’une constante » n’est vrai que sur un <b>intervalle</b>. Sur ℝ privé de 0, la fonction qui vaut −1/<i>x</i> pour <i>x</i> &lt; 0 et −1/<i>x</i> + 5 pour <i>x</i> &gt; 0 est aussi une primitive de 1/<i>x</i>², avec une constante différente de chaque côté.</p></div>',
  params:[{id:'C',l:'C',min:-3,max:3,step:.5,v:0}],
  draw:v=>{ const P=plane({x:[-3,3],y:[-4,6],h:300,lab:1}); for(let c=-3;c<=3;c++) P.fn(x=>x*x+c,{c:'var(--line)',w:1.5});
    P.fn(x=>x*x+v.C).dot(1,3,{c:'var(--bad)',l:'(1 ; 3)'}); return P.svg(); },
  info:v=>`F(x) = x² + ${fmt(v.C)} · F(1) = ${fmt(1+v.C)}`},
 {kind:'Pratique',h:'Passe par le point',p:'Choisis <i>C</i> pour que la primitive <i>x</i>² + <i>C</i> de 2<i>x</i> passe par (1 ; 3).',
  params:[{id:'C',l:'C',min:-3,max:3,step:.5,v:-1}],
  draw:v=>{ const P=plane({x:[-3,3],y:[-4,6],h:300,lab:1}); P.fn(x=>x*x+v.C).dot(1,3,{c:'var(--bad)',l:'(1 ; 3)'}); return P.svg(); },
  info:v=>`F(1) = ${fmt(1+v.C)}`,
  ok:v=>v.C===2,why:'F(1) = 1 + C = 3, donc C = 2 et F(x) = x² + 2.'},
 {kind:'Théorie',h:'Le tableau de base',p:'<p>Chaque formule de dérivation, lue de droite à gauche, donne une primitive. Le tableau ci-dessous rassemble celles qu’il faut connaître par cœur : toutes les techniques du chapitre consistent à ramener un calcul à l’une de ces lignes.</p><div class="why"><p>Chaque ligne se vérifie en dérivant la colonne de droite. (<i>x</i>ⁿ⁺¹/(<i>n</i> + 1))′ = (<i>n</i> + 1)<i>x</i>ⁿ/(<i>n</i> + 1) = <i>x</i>ⁿ. (sin <i>x</i>)′ = cos <i>x</i>, et (−cos <i>x</i>)′ = sin <i>x</i> : d’où le signe moins. (tan <i>x</i>)′ = 1/cos² <i>x</i>, (arctan <i>x</i>)′ = 1/(1 + <i>x</i>²) et (arcsin <i>x</i>)′ = 1/√(1 − <i>x</i>²) viennent des dérivées des fonctions réciproques.</p></div><div class="blk" data-t="Pourquoi ln|x|"><p>La formule des puissances échoue pour <i>n</i> = −1 : elle diviserait par 0. La primitive de 1/<i>x</i> est le logarithme. Pour <i>x</i> &gt; 0, (ln <i>x</i>)′ = 1/<i>x</i>. Pour <i>x</i> &lt; 0, ln <i>x</i> n’existe pas, mais (ln(−<i>x</i>))′ = −1/(−<i>x</i>) = 1/<i>x</i>. Les deux cas s’écrivent ensemble ln|<i>x</i>|.</p></div><div class="ex"><p>∫ <i>x</i>⁵ d<i>x</i> = <i>x</i>⁶/6 + C. ∫ √<i>x</i> d<i>x</i> = ∫ <i>x</i><sup>1/2</sup> d<i>x</i> = <i>x</i><sup>3/2</sup>/(3/2) + C = (2/3)<i>x</i>√<i>x</i> + C. ∫ d<i>x</i>/<i>x</i>³ = ∫ <i>x</i>⁻³ d<i>x</i> = <i>x</i>⁻²/(−2) + C = −1/(2<i>x</i>²) + C ; contrôle : (−<i>x</i>⁻²/2)′ = <i>x</i>⁻³ ✓.</p></div><div class="warn"><p>La formule des puissances s’applique à <i>x</i>ⁿ, pas à la puissance d’autre chose : ∫ (2<i>x</i> + 1)² d<i>x</i> n’est pas (2<i>x</i> + 1)³/3, dont la dérivée vaut 2(2<i>x</i> + 1)² à cause de la règle de chaîne. On verra plus loin comment corriger ce facteur.</p></div>',
  fig:tab([['f(x)','primitive F(x)'],['xⁿ (n ≠ −1)','xⁿ⁺¹/(n + 1)'],['1/x','ln|x|'],['eˣ','eˣ'],['cos x','sin x'],['sin x','−cos x'],['1/cos² x','tan x'],['1/(1 + x²)','arctan x'],['1/√(1 − x²)','arcsin x']]),
  note:'N’oublie pas le <b>+ C</b>, et le signe moins de −cos x.'},
 {kind:'Méthode',h:'Linéarité : intégrer terme à terme',p:'<b>Quand :</b> la fonction est une somme de termes du tableau, chacun multiplié par une constante. <b>Pourquoi ça marche :</b> la dérivée d’une somme est la somme des dérivées et (<i>k</i>F)′ = <i>k</i>F′. Donc <b>∫ (<i>a</i>f + <i>b</i>g) = <i>a</i>∫ f + <i>b</i>∫ g</b>. <b>Comment :</b> réécris chaque terme sous une forme du tableau (1/<i>x</i>² = <i>x</i>⁻², √<i>x</i> = <i>x</i><sup>1/2</sup>), sors les constantes, intègre chaque terme, ajoute un seul + C, puis vérifie en dérivant.',
  demo:{enonce:'Calculer ∫ (4<i>x</i>³ − 6/<i>x</i>² + 2 cos <i>x</i>) d<i>x</i>.',
   etapes:[
    {f:'6/<i>x</i>² = 6<i>x</i>⁻²',w:'On écrit le terme comme une puissance pour utiliser <i>x</i>ⁿ → <i>x</i>ⁿ⁺¹/(<i>n</i> + 1).'},
    {f:'∫ 4<i>x</i>³ d<i>x</i> = <i>x</i>⁴ ; ∫ 6<i>x</i>⁻² d<i>x</i> = 6 · <i>x</i>⁻¹/(−1) = −6/<i>x</i> ; ∫ 2 cos <i>x</i> d<i>x</i> = 2 sin <i>x</i>',w:'Chaque terme séparément, constante sortie.'},
    {f:'∫ (…) d<i>x</i> = <i>x</i>⁴ + 6/<i>x</i> + 2 sin <i>x</i> + C',w:'Attention au signe : on soustrait −6/<i>x</i>, ce qui donne +6/<i>x</i>.'},
    {f:'Contrôle : (<i>x</i>⁴ + 6/<i>x</i> + 2 sin <i>x</i>)′ = 4<i>x</i>³ − 6/<i>x</i>² + 2 cos <i>x</i> ✓',w:'On redérive.'}],
   conclusion:'Une primitive est <i>x</i>⁴ + 6/<i>x</i> + 2 sin <i>x</i>.'},
  note:'Il n’y a <b>pas</b> de règle simple pour un produit : ∫ <i>x</i> eˣ d<i>x</i> n’est pas (<i>x</i>²/2) eˣ. Les produits demandent la substitution ou les parties.'},
 {h:'Applique le tableau',p:'Une primitive de 3<i>x</i>² − 4/<i>x</i> + eˣ est…',opts:['6x + 4/x² + eˣ','x³ − 4 ln|x| + eˣ','x³ − 4/x² + eˣ','x³ + 4 ln|x| + eˣ'],ans:1,
  why:'On intègre terme à terme : x³, puis −4 ln|x|, puis eˣ. Vérifie en dérivant : 3x² − 4/x + eˣ.'},
 {kind:'Méthode',h:'Composée avec ax + b',p:'<b>Quand :</b> une fonction du tableau est appliquée à <i>ax</i> + <i>b</i>, comme cos(3<i>x</i> − 1) ou e<sup>−2<i>x</i></sup>. <b>Pourquoi ça marche :</b> par la règle de chaîne, (F(<i>ax</i> + <i>b</i>))′ = <i>a</i> f(<i>ax</i> + <i>b</i>) : il y a un facteur <i>a</i> en trop, qu’on compense en divisant. <b>Comment :</b> si F est une primitive de <i>f</i>, alors <b>∫ f(<i>ax</i> + <i>b</i>) d<i>x</i> = F(<i>ax</i> + <i>b</i>)/<i>a</i> + C</b>.',
  demo:{enonce:'Calculer ∫ e<sup>−2<i>x</i></sup> d<i>x</i> et ∫ cos(3<i>x</i> − 1) d<i>x</i>.',
   etapes:[
    {f:'e<sup>−2<i>x</i></sup> = f(−2<i>x</i>) avec f = exp, <i>a</i> = −2',w:'On repère la fonction et le coefficient de <i>x</i>.'},
    {f:'∫ e<sup>−2<i>x</i></sup> d<i>x</i> = e<sup>−2<i>x</i></sup>/(−2) + C = −e<sup>−2<i>x</i></sup>/2 + C',w:'On divise par <i>a</i> = −2.'},
    {f:'∫ cos(3<i>x</i> − 1) d<i>x</i> = sin(3<i>x</i> − 1)/3 + C',w:'Primitive de cos : sin, puis division par <i>a</i> = 3.'},
    {f:'Contrôle : (sin(3<i>x</i> − 1)/3)′ = 3 cos(3<i>x</i> − 1)/3 = cos(3<i>x</i> − 1) ✓',w:'La dérivée redonne bien la fonction.'}],
   conclusion:'En particulier, ∫ e<sup>−<i>t</i></sup> d<i>t</i> = −e<sup>−<i>t</i></sup> + C.'}},
 {h:'À toi',p:'Calcule ∫₀¹ e<sup>2<i>x</i></sup> d<i>x</i>, arrondi au millième.',ans:(Math.E**2-1)/2,tol:6e-4,
  why:'Une primitive est e<sup>2x</sup>/2. Donc (e² − 1)/2 ≈ 3,195.'},
 {kind:'Théorie',h:'Substitution',p:'<p>Le tableau ne suffit plus pour ∫ 2<i>x</i> cos(<i>x</i>²) d<i>x</i> : c’est un produit, et cos y est appliqué à <i>x</i>², pas à <i>x</i>. Pourtant on y reconnaît la dérivée d’une composée. La substitution consiste à repérer ce motif.</p><div class="thm"><p>Si F est une primitive de <i>f</i> et si <i>g</i> est dérivable (à dérivée continue), alors <b>∫ f(g(x)) g′(x) dx = F(g(x)) + C</b>. Pour une intégrale définie : <b>∫ₐᵇ f(g(x)) g′(x) dx = ∫<sub>g(a)</sub><sup>g(b)</sup> f(u) du</b>.</p></div><div class="why"><p>C’est la règle de chaîne lue à l’envers : (F(g(x)))′ = F′(g(x)) · g′(x) = f(g(x)) g′(x).</p></div><div class="blk" data-t="La notation du"><p>On pose <i>u</i> = g(x). En écrivant d<i>u</i>/d<i>x</i> = g′(x) comme une fraction, on obtient <b>d<i>u</i> = g′(x) d<i>x</i></b>. Ce n’est pas une vraie division, mais un raccourci qui donne toujours le bon résultat : le bloc g′(x) d<i>x</i> de l’intégrale se remplace par d<i>u</i>, et tout s’écrit avec <i>u</i>.</p></div><div class="ex"><p>∫ 2<i>x</i> cos(<i>x</i>²) d<i>x</i> : avec <i>u</i> = <i>x</i>², d<i>u</i> = 2<i>x</i> d<i>x</i>, l’intégrale devient ∫ cos <i>u</i> d<i>u</i> = sin <i>u</i> + C = sin(<i>x</i>²) + C. Contrôle : (sin(<i>x</i>²))′ = 2<i>x</i> cos(<i>x</i>²) ✓. Version définie : quand <i>x</i> va de 0 à √(π/2), <i>u</i> va de 0 à π/2, donc ∫₀<sup>√(π/2)</sup> 2<i>x</i> cos(<i>x</i>²) d<i>x</i> = ∫₀<sup>π/2</sup> cos <i>u</i> d<i>u</i> = 1.</p></div><div class="warn"><p>Le facteur g′(x) doit être présent, au moins à une constante près : ∫ cos(<i>x</i>²) d<i>x</i>, sans le 2<i>x</i>, ne se calcule pas ainsi (elle n’a même pas de primitive qui s’écrive avec les fonctions usuelles).</p></div>',
  note:'Dans une intégrale définie, change aussi les bornes : <i>x</i> = <i>a</i> devient <i>u</i> = g(a).'},
 {kind:'Méthode',h:'Faire une substitution',p:'<b>Quand :</b> on voit une fonction de g(x), multipliée par g′(x) à une constante près. <b>Pourquoi ça marche :</b> c’est la règle de chaîne lue à l’envers : (F(g(x)))′ = f(g(x)) g′(x). <b>Comment :</b> pose u = g(x), calcule du = g′(x) d<i>x</i>, exprime tout avec u (ajuste la constante), change les bornes, intègre en u.',
  demo:{enonce:'Calculer ∫₀¹ <i>x</i>² (<i>x</i>³ + 1)⁴ d<i>x</i>.',
   etapes:[
    {f:'u = <i>x</i>³ + 1, du = 3<i>x</i>² d<i>x</i>, donc <i>x</i>² d<i>x</i> = du/3',w:'L’intérieur de la puissance est <i>x</i>³ + 1, et sa dérivée 3<i>x</i>² est là à un facteur 3 près.'},
    {f:'<i>x</i> = 0 → u = 1 ; <i>x</i> = 1 → u = 2',w:'On change les bornes pour ne plus revenir à <i>x</i>.'},
    {f:'∫₁² u⁴ du/3 = (1/3)[u⁵/5]₁² = (1/3)(32 − 1)/5',w:'Une simple puissance en u.'},
    {f:'= 31/15',w:'On simplifie.'}],
   conclusion:'L’intégrale vaut 31/15 ≈ 2,067.'}},
 {h:'À toi',p:'Calcule ∫₀¹ <i>x</i> e<sup><i>x</i>²</sup> d<i>x</i>, arrondi au millième.',ans:(Math.E-1)/2,tol:6e-4,
  why:'u = x², du = 2x dx, bornes 0 et 1 : (1/2)∫₀¹ eᵘ du = (e − 1)/2 ≈ 0,859.'},
 {kind:'Méthode',h:'Reconnaître u′/u et u′uⁿ',p:'<b>Quand :</b> le numérateur est (à une constante près) la dérivée du dénominateur, ou un facteur est la dérivée de ce qui est élevé à une puissance. <b>Pourquoi ça marche :</b> (ln|u|)′ = u′/u et (u<sup>n+1</sup>)′ = (n + 1) u′ uⁿ. <b>Comment :</b> dérive le « bloc » suspect et compare : <b>∫ u′/u = ln|u| + C</b> et <b>∫ u′ uⁿ = u<sup>n+1</sup>/(n + 1) + C</b> (n ≠ −1). Ajuste la constante si besoin.',
  demo:{enonce:'Calculer ∫ (2<i>x</i> + 3)/(<i>x</i>² + 3<i>x</i> + 1) d<i>x</i> et ∫ cos <i>x</i> sin² <i>x</i> d<i>x</i>.',
   etapes:[
    {f:'(<i>x</i>² + 3<i>x</i> + 1)′ = 2<i>x</i> + 3 : c’est le numérateur',w:'On dérive le dénominateur et on le compare au numérateur.'},
    {f:'∫ (2<i>x</i> + 3)/(<i>x</i>² + 3<i>x</i> + 1) d<i>x</i> = ln|<i>x</i>² + 3<i>x</i> + 1| + C',w:'Forme u′/u.'},
    {f:'cos <i>x</i> sin² <i>x</i> = u′ u² avec u = sin <i>x</i>',w:'Le facteur cos <i>x</i> est la dérivée de sin <i>x</i>.'},
    {f:'∫ cos <i>x</i> sin² <i>x</i> d<i>x</i> = sin³ <i>x</i>/3 + C',w:'Forme u′uⁿ avec n = 2.'}],
   conclusion:'Contrôle : (sin³ <i>x</i>/3)′ = 3 cos <i>x</i> sin² <i>x</i>/3 = cos <i>x</i> sin² <i>x</i> ✓.'},
  note:'S’il manque une constante, on la crée : <i>x</i>/(<i>x</i>² + 1) = (1/2) · 2<i>x</i>/(<i>x</i>² + 1).'},
 {h:'Reconnais la forme',p:'∫ tan <i>x</i> d<i>x</i> = ∫ sin <i>x</i>/cos <i>x</i> d<i>x</i> vaut…',opts:['ln|cos x| + C','1/cos² x + C','−ln|sin x| + C','−ln|cos x| + C'],ans:3,
  why:'Avec u = cos x, du = −sin x dx : ∫ −du/u = −ln|u| + C = −ln|cos x| + C.'},
 {h:'Un logarithme caché',p:`Calcule ∫₀¹ ${F('<i>x</i>','<i>x</i>² + 1')} d<i>x</i>, arrondi au millième.`,ans:Math.log(2)/2,tol:6e-4,
  why:'x/(x² + 1) = (1/2) · 2x/(x² + 1), de la forme u′/u. Primitive : (1/2) ln(x² + 1). De 0 à 1 : (ln 2)/2 ≈ 0,347.'},
 {kind:'Théorie',h:'Intégration par parties',p:'<p>Pour ∫ <i>x</i> eˣ d<i>x</i>, aucune substitution ne marche : <i>x</i> n’est pas la dérivée de ce qu’il y a dans l’exponentielle. Il faut une règle pour certains produits ; elle vient de la dérivée d’un produit.</p><div class="thm"><p><b>Intégration par parties.</b> Si <i>u</i> et <i>v</i> sont dérivables à dérivées continues : <b>∫ u v′ dx = u v − ∫ u′ v dx</b>, et sur un segment <b>∫ₐᵇ u v′ dx = [u v]ₐᵇ − ∫ₐᵇ u′ v dx</b>.</p></div><div class="why"><p>(uv)′ = u′v + uv′, donc uv′ = (uv)′ − u′v. On intègre les deux membres : une primitive de (uv)′ est uv, d’où la formule. Elle ne calcule rien toute seule : elle <b>échange</b> une intégrale contre une autre.</p></div><div class="idea"><p>L’échange est gagnant si <i>u</i> se simplifie en dérivant (un polynôme perd un degré, ln <i>x</i> devient 1/<i>x</i>) tandis que <i>v</i>′ s’intègre sans se compliquer (eˣ, sin <i>x</i>, cos <i>x</i>).</p></div><div class="ex"><p>∫ <i>x</i> eˣ d<i>x</i> : <i>u</i> = <i>x</i> (<i>u</i>′ = 1) et <i>v</i>′ = eˣ (<i>v</i> = eˣ). Alors ∫ <i>x</i> eˣ d<i>x</i> = <i>x</i> eˣ − ∫ eˣ d<i>x</i> = (<i>x</i> − 1) eˣ + C. Contrôle : ((<i>x</i> − 1)eˣ)′ = eˣ + (<i>x</i> − 1)eˣ = <i>x</i> eˣ ✓. Sur [0 ; 1] : [(<i>x</i> − 1)eˣ]₀¹ = 0 − (−1) = 1.</p></div><div class="warn"><p>Le mauvais choix fait empirer le calcul : <i>u</i> = eˣ et <i>v</i>′ = <i>x</i> donnent ∫ <i>x</i> eˣ d<i>x</i> = (<i>x</i>²/2)eˣ − ∫ (<i>x</i>²/2)eˣ d<i>x</i>, avec un degré de plus qu’au départ.</p></div>',
  note:'Astuce : ∫ ln x dx = ∫ 1 · ln x dx, avec v′ = 1 et u = ln x.'},
 {kind:'Méthode',h:'Intégrer par parties',p:'<b>Quand :</b> on intègre un produit de deux fonctions de natures différentes (polynôme × exponentielle, polynôme × sin ou cos, polynôme × ln) et aucune substitution ne marche. <b>Pourquoi ça marche :</b> la formule échange ∫ u v′ contre ∫ u′ v ; si u se simplifie en dérivant, la nouvelle intégrale est plus facile. <b>Comment :</b> choisis u (à dériver) et v′ (à intégrer), écris le tableau u, u′, v′, v, applique <b>∫ u v′ = u v − ∫ u′ v</b>, et calcule la nouvelle intégrale. Ordre de choix pour u : ln, puis polynôme, puis exp ou sin, cos.',
  demo:{enonce:'Calculer ∫₀<sup>π/2</sup> <i>x</i> cos <i>x</i> d<i>x</i>.',
   etapes:[
    {f:'u = <i>x</i>, u′ = 1 ; v′ = cos <i>x</i>, v = sin <i>x</i>',w:'<i>x</i> devient 1 en dérivant ; cos <i>x</i> s’intègre facilement.'},
    {f:'∫ <i>x</i> cos <i>x</i> d<i>x</i> = <i>x</i> sin <i>x</i> − ∫ sin <i>x</i> d<i>x</i> = <i>x</i> sin <i>x</i> + cos <i>x</i> + C',w:'La nouvelle intégrale ne contient plus de produit.'},
    {f:'Contrôle : (<i>x</i> sin <i>x</i> + cos <i>x</i>)′ = sin <i>x</i> + <i>x</i> cos <i>x</i> − sin <i>x</i> = <i>x</i> cos <i>x</i> ✓',w:'Dériver confirme la primitive.'},
    {f:'[<i>x</i> sin <i>x</i> + cos <i>x</i>]₀<sup>π/2</sup> = (π/2 + 0) − (0 + 1)',w:'On évalue aux bornes.'}],
   conclusion:'L’intégrale vaut π/2 − 1 ≈ 0,571.'},
  note:'Mauvais choix : u = cos <i>x</i> et v′ = <i>x</i> donnerait ∫ (<i>x</i>²/2) sin <i>x</i>, plus compliquée qu’au départ.'},
 {h:'Le logarithme',p:'Calcule ∫₁<sup>e</sup> ln <i>x</i> d<i>x</i>.',ans:1,
  why:'Par parties : ∫ ln x dx = x ln x − ∫ x · (1/x) dx = x ln x − x. De 1 à e : (e − e) − (0 − 1) = 1.'},
 {kind:'Défi',h:'Par parties, encore',p:'Calcule ∫₀<sup>π</sup> <i>x</i> sin <i>x</i> d<i>x</i>, arrondi au centième.',ans:Math.PI,tol:.006,
  why:'u = x, v′ = sin x, v = −cos x : ∫ x sin x dx = −x cos x + sin x. De 0 à π : (−π · (−1) + 0) − 0 = π ≈ 3,14.'},
 {kind:'Méthode',h:'Plusieurs intégrations par parties',p:'<b>Quand :</b> le polynôme est de degré 2 ou plus, comme <i>x</i>² eˣ, ou le produit mélange exponentielle et sinus. <b>Pourquoi ça marche :</b> chaque intégration par parties fait baisser le degré du polynôme de 1. Avec eˣ sin <i>x</i>, l’intégrale de départ réapparaît : on obtient une équation qu’on résout. <b>Comment :</b> enchaîne les parties en dérivant toujours le polynôme ; garde bien les signes avec des parenthèses.',
  demo:{enonce:'Calculer ∫ <i>x</i>² eˣ d<i>x</i>.',
   etapes:[
    {f:'u = <i>x</i>², v′ = eˣ : ∫ <i>x</i>² eˣ d<i>x</i> = <i>x</i>² eˣ − ∫ 2<i>x</i> eˣ d<i>x</i>',w:'Premier passage : le degré passe de 2 à 1.'},
    {f:'u = 2<i>x</i>, v′ = eˣ : ∫ 2<i>x</i> eˣ d<i>x</i> = 2<i>x</i> eˣ − ∫ 2eˣ d<i>x</i> = 2<i>x</i> eˣ − 2eˣ',w:'Second passage : le degré passe à 0.'},
    {f:'∫ <i>x</i>² eˣ d<i>x</i> = <i>x</i>² eˣ − (2<i>x</i> eˣ − 2eˣ) + C',w:'On remplace, avec des parenthèses pour ne pas perdre le signe.'},
    {f:'= (<i>x</i>² − 2<i>x</i> + 2) eˣ + C',w:'On factorise eˣ.'}],
   conclusion:'Contrôle : ((<i>x</i>² − 2<i>x</i> + 2)eˣ)′ = (2<i>x</i> − 2)eˣ + (<i>x</i>² − 2<i>x</i> + 2)eˣ = <i>x</i>² eˣ ✓.'}},
 {h:'Deux fois par parties',p:'Calcule ∫₀¹ <i>x</i>² eˣ d<i>x</i>, arrondi au millième.',ans:Math.E-2,tol:6e-4,
  why:'Avec la primitive (x² − 2x + 2)eˣ : (1 − 2 + 2)e − 2 = e − 2 ≈ 0,718.'},
 {kind:'Méthode',h:'Décomposer en fractions simples',p:'<b>Quand :</b> on intègre une fraction 1/((<i>x</i> − <i>a</i>)(<i>x</i> − <i>b</i>)), ou plus généralement P/Q avec deg P &lt; deg Q et Q factorisé en facteurs distincts du premier degré. <b>Pourquoi ça marche :</b> une telle fraction s’écrit A/(<i>x</i> − <i>a</i>) + B/(<i>x</i> − <i>b</i>), et chaque morceau s’intègre en ln. <b>Comment :</b> factorise le dénominateur, écris la décomposition avec A et B inconnus, réduis au même dénominateur et identifie (ou remplace <i>x</i> par <i>a</i> puis par <i>b</i>), puis intègre.',
  demo:{enonce:`Calculer ∫ ${F('1','<i>x</i>² − 1')} d<i>x</i>.`,
   etapes:[
    {f:'<i>x</i>² − 1 = (<i>x</i> − 1)(<i>x</i> + 1)',w:'On factorise le dénominateur.'},
    {f:`${F('1','(<i>x</i> − 1)(<i>x</i> + 1)')} = ${F('A','<i>x</i> − 1')} + ${F('B','<i>x</i> + 1')}, soit 1 = A(<i>x</i> + 1) + B(<i>x</i> − 1)`,w:'On multiplie les deux membres par (<i>x</i> − 1)(<i>x</i> + 1).'},
    {f:'<i>x</i> = 1 : 1 = 2A, A = 1/2 ; <i>x</i> = −1 : 1 = −2B, B = −1/2',w:'Chaque valeur annule l’un des termes et isole une inconnue.'},
    {f:'∫ = (1/2) ln|<i>x</i> − 1| − (1/2) ln|<i>x</i> + 1| + C',w:'∫ d<i>x</i>/(<i>x</i> − <i>a</i>) = ln|<i>x</i> − <i>a</i>|.'}],
   conclusion:'∫ d<i>x</i>/(<i>x</i>² − 1) = (1/2) ln|(<i>x</i> − 1)/(<i>x</i> + 1)| + C.'},
  note:'Si le degré du numérateur est au moins celui du dénominateur, commence par une division de polynômes.'},
 {h:'À toi',p:`Calcule ∫₂³ ${F('1','<i>x</i>(<i>x</i> − 1)')} d<i>x</i>, arrondi au millième.`,ans:Math.log(4/3),tol:6e-4,
  why:'1/(x(x − 1)) = 1/(x − 1) − 1/x. Primitive : ln|x − 1| − ln|x|. De 2 à 3 : (ln 2 − ln 3) − (0 − ln 2) = 2 ln 2 − ln 3 = ln(4/3) ≈ 0,288.'},
 {kind:'Récapitulatif',h:'Ce qu’il faut retenir : primitives',p:'<div class="keep"><ul><li><b>Primitive</b> : F′ = f sur un intervalle. Toutes les primitives sont F + C ; une condition F(x₀) = y₀ fixe <i>C</i>. Contrôle toujours en dérivant.</li><li><b>Tableau</b> : <i>x</i>ⁿ → <i>x</i>ⁿ⁺¹/(<i>n</i> + 1) (<i>n</i> ≠ −1), 1/<i>x</i> → ln|<i>x</i>|, eˣ → eˣ, cos → sin, sin → −cos, 1/cos² → tan, 1/(1 + <i>x</i>²) → arctan, 1/√(1 − <i>x</i>²) → arcsin. Écrire √<i>x</i> = <i>x</i><sup>1/2</sup>, 1/<i>x</i>² = <i>x</i>⁻².</li><li><b>Linéarité</b> : on intègre terme à terme et on sort les constantes ; pas de règle pour un produit.</li><li><b>Composée avec <i>ax</i> + <i>b</i></b> : ∫ f(<i>ax</i> + <i>b</i>) d<i>x</i> = F(<i>ax</i> + <i>b</i>)/<i>a</i> + C.</li><li><b>Substitution</b> : ∫ f(g(x)) g′(x) d<i>x</i> = F(g(x)) + C ; poser <i>u</i> = g(x), d<i>u</i> = g′(x) d<i>x</i>, et changer les bornes. Cas fréquents : ∫ u′/u = ln|u| + C, ∫ u′uⁿ = uⁿ⁺¹/(<i>n</i> + 1) + C.</li><li><b>Par parties</b> : ∫ u v′ = u v − ∫ u′ v. Choisir pour <i>u</i> : ln, puis polynôme, puis exp, sin, cos. Répéter pour <i>x</i>² eˣ ; pour eˣ sin <i>x</i>, l’intégrale revient : résoudre l’équation.</li><li><b>Fractions simples</b> : 1/((<i>x</i> − <i>a</i>)(<i>x</i> − <i>b</i>)) = A/(<i>x</i> − <i>a</i>) + B/(<i>x</i> − <i>b</i>), puis des ln ; diviser d’abord si le degré du haut est trop grand.</li></ul></div>'},
 {kind:'Problème',h:'L’exposition à un médicament',
  p:'Après une prise de médicament, la concentration dans le sang vaut <b>c(t) = <i>t</i> e<sup>−<i>t</i></sup></b> (en mg/L), où <i>t</i> est en heures. L’« aire sous la courbe » ∫₀² c(t) d<i>t</i> mesure l’exposition au médicament pendant les deux premières heures. On la calcule par parties.',
  fig:(()=>{ const P=plane({x:[-.3,5],y:[-.05,.45],h:180,grid:false,lx:1,ly:.1}); P.area(t=>t*Math.exp(-t),0,2).fn(t=>t*Math.exp(-t),{from:0,to:5}).dot(1,Math.exp(-1),{r:4,c:'var(--ink)'}); return P.svg(); })(),
  parts:[
   {q:'a) Quelle est une primitive de <i>t</i> e<sup>−<i>t</i></sup>&nbsp;?',opts:['(<i>t</i> − 1) e<sup>−<i>t</i></sup>','(1 − <i>t</i>) e<sup>−<i>t</i></sup>','−(<i>t</i> + 1) e<sup>−<i>t</i></sup>','−<i>t</i> e<sup>−<i>t</i></sup>'],ans:2,hint:'Par parties avec <i>u</i> = <i>t</i> et <i>v</i>′ = e<sup>−<i>t</i></sup>, donc <i>v</i> = −e<sup>−<i>t</i></sup>. Vérifie en dérivant.',why:'∫ t e<sup>−t</sup> dt = −t e<sup>−t</sup> + ∫ e<sup>−t</sup> dt = −t e<sup>−t</sup> − e<sup>−t</sup> = −(t + 1) e<sup>−t</sup>. (1 − t) e<sup>−t</sup> est la dérivée de c, pas sa primitive.'},
   {q:'b) Calcule ∫₀² c(t) d<i>t</i>, arrondi au millième.',lab:'≈',unit:'mg·h/L',ans:1-3*Math.exp(-2),tol:6e-4,hint:'Évalue −(<i>t</i> + 1) e<sup>−<i>t</i></sup> en 2 et en 0.',why:'[−(t + 1)e<sup>−t</sup>]₀² = −3e<sup>−2</sup> + 1 ≈ 0,594.'},
   {q:'c) À quel instant la concentration est-elle maximale&nbsp;?',lab:'t =',unit:'h',ans:1,hint:'Annule c′(t) = (1 − <i>t</i>) e<sup>−<i>t</i></sup>.',why:'c′(t) = (1 − t)e<sup>−t</sup> est positive avant 1 et négative après : maximum en t = 1 h, c(1) = 1/e ≈ 0,37 mg/L.'},
   {q:'d) Quelle est la concentration moyenne sur les deux premières heures&nbsp;? Arrondis au millième.',lab:'c̄ ≈',unit:'mg/L',ans:(1-3*Math.exp(-2))/2,tol:6e-4,hint:'Moyenne = intégrale divisée par la durée.',why:'(1 − 3e<sup>−2</sup>)/2 ≈ 0,297 mg/L.'},
  ],
  sol:'Par parties, avec u = t et v′ = e<sup>−t</sup> (u′ = 1, v = −e<sup>−t</sup>) : ∫ t e<sup>−t</sup> dt = −t e<sup>−t</sup> + ∫ e<sup>−t</sup> dt = −(t + 1) e<sup>−t</sup> + C.<br>On vérifie : (−(t + 1)e<sup>−t</sup>)′ = −e<sup>−t</sup> + (t + 1)e<sup>−t</sup> = t e<sup>−t</sup>.<br>∫₀² t e<sup>−t</sup> dt = [−(t + 1)e<sup>−t</sup>]₀² = 1 − 3e<sup>−2</sup> ≈ 0,594 mg·h/L.<br>c′(t) = (1 − t)e<sup>−t</sup> : la concentration culmine en t = 1 h à 1/e ≈ 0,368 mg/L.<br>La moyenne sur [0 ; 2] vaut (1 − 3e<sup>−2</sup>)/2 ≈ 0,297 mg/L.'},
 {kind:'Problème',h:'Une oscillation amortie',
  p:'Le déplacement d’un ressort amorti vaut e<sup>−<i>x</i></sup> sin <i>x</i>. On veut l’aire de la première bosse, <b>I = ∫₀<sup>π</sup> e<sup>−<i>x</i></sup> sin <i>x</i> d<i>x</i></b>. Une seule intégration par parties ne suffit pas : il en faut deux, et l’intégrale cherchée réapparaît. On compare ensuite avec la deuxième bosse.',
  fig:(()=>{ const f=x=>Math.exp(-x)*Math.sin(x), P=plane({x:[-.3,6.6],y:[-.1,.4],h:160,grid:false,lx:1,ly:.1}); P.area(f,0,Math.PI).area(f,Math.PI,2*Math.PI,{fill:'var(--bad)'}).fn(f,{from:0,to:6.5}); return P.svg(); })(),
  parts:[
   {q:'a) Une première intégration par parties, avec <i>u</i> = sin <i>x</i> et <i>v</i>′ = e<sup>−<i>x</i></sup>, donne ∫ e<sup>−<i>x</i></sup> sin <i>x</i> d<i>x</i> = …',opts:['−e<sup>−<i>x</i></sup> sin <i>x</i> + ∫ e<sup>−<i>x</i></sup> cos <i>x</i> d<i>x</i>','e<sup>−<i>x</i></sup> sin <i>x</i> − ∫ e<sup>−<i>x</i></sup> cos <i>x</i> d<i>x</i>','−e<sup>−<i>x</i></sup> cos <i>x</i> − ∫ e<sup>−<i>x</i></sup> sin <i>x</i> d<i>x</i>','−e<sup>−<i>x</i></sup> sin <i>x</i> − ∫ e<sup>−<i>x</i></sup> cos <i>x</i> d<i>x</i>'],ans:0,hint:'<i>v</i> = −e<sup>−<i>x</i></sup>, <i>u</i>′ = cos <i>x</i>. Attention aux deux signes moins.',why:'uv − ∫ u′v = −e<sup>−x</sup> sin x − ∫ cos x · (−e<sup>−x</sup>) dx = −e<sup>−x</sup> sin x + ∫ e<sup>−x</sup> cos x dx.'},
   {q:'b) Une seconde intégration par parties donne I = [−e<sup>−<i>x</i></sup>(sin <i>x</i> + cos <i>x</i>)]₀<sup>π</sup> − I. Que fait-on&nbsp;?',opts:['On a tourné en rond : il faut une autre méthode','On en déduit I = 0','On passe I à gauche : 2I = [−e<sup>−<i>x</i></sup>(sin <i>x</i> + cos <i>x</i>)]₀<sup>π</sup>','On recommence une troisième fois'],ans:2,hint:'I est un nombre inconnu qui apparaît des deux côtés d’une égalité.',why:'C’est une équation en I : 2I = [−e<sup>−x</sup>(sin x + cos x)]₀<sup>π</sup> = e<sup>−π</sup> + 1.'},
   {q:'c) Que vaut I&nbsp;? Arrondis au millième.',lab:'I ≈',ans:(1+Math.exp(-Math.PI))/2,tol:6e-4,hint:'En π : sin π + cos π = −1. En 0 : sin 0 + cos 0 = 1.',why:'2I = e<sup>−π</sup> · 1 − (−1) = 1 + e<sup>−π</sup>, donc I = (1 + e<sup>−π</sup>)/2 ≈ 0,522.'},
   {q:'d) La deuxième bosse, sur [π ; 2π], est sous l’axe. Que vaut le rapport |∫<sub>π</sub><sup>2π</sup> e<sup>−<i>x</i></sup> sin <i>x</i> d<i>x</i>| / I&nbsp;? Arrondis au millième.',lab:'rapport ≈',ans:Math.exp(-Math.PI),tol:6e-4,hint:'Utilise la primitive F(x) = −e<sup>−<i>x</i></sup>(sin <i>x</i> + cos <i>x</i>)/2 entre π et 2π.',why:'∫<sub>π</sub><sup>2π</sup> = F(2π) − F(π) = −(e<sup>−2π</sup> + e<sup>−π</sup>)/2 = −e<sup>−π</sup>(1 + e<sup>−π</sup>)/2 = −e<sup>−π</sup> I. Le rapport vaut e<sup>−π</sup> ≈ 0,043.'},
  ],
  sol:'1re IPP (u = sin x, v′ = e<sup>−x</sup>) : ∫ e<sup>−x</sup> sin x dx = −e<sup>−x</sup> sin x + ∫ e<sup>−x</sup> cos x dx.<br>2e IPP (u = cos x, v′ = e<sup>−x</sup>) : ∫ e<sup>−x</sup> cos x dx = −e<sup>−x</sup> cos x − ∫ e<sup>−x</sup> sin x dx.<br>En reportant : ∫ e<sup>−x</sup> sin x dx = −e<sup>−x</sup>(sin x + cos x) − ∫ e<sup>−x</sup> sin x dx, d’où la primitive F(x) = −e<sup>−x</sup>(sin x + cos x)/2.<br>I = F(π) − F(0) = e<sup>−π</sup>/2 + 1/2 = (1 + e<sup>−π</sup>)/2 ≈ 0,522.<br>Sur [π ; 2π] : F(2π) − F(π) = −e<sup>−π</sup>(1 + e<sup>−π</sup>)/2 = −e<sup>−π</sup> I.<br>Chaque bosse est e<sup>−π</sup> ≈ 0,043 fois la précédente, au signe près : l’amortissement est très rapide.'},
]},

{subj:'an1', sem:'pri', id:'an1-applications', h:'Applications de l’intégrale', p:'Aires entre courbes, volumes de révolution, longueurs d’arc et aires de surfaces de révolution.', steps:[
 {kind:'Théorie',h:'Aire entre deux courbes',p:'<p>L’intégrale ∫ₐᵇ f mesure l’aire entre une courbe et l’axe. Souvent, la région qui nous intéresse est coincée entre deux courbes : un champ entre une route et une rivière, la zone entre deux profils. Il suffit d’adapter la hauteur des rectangles.</p><div class="blk" data-t="L’idée de tout le chapitre"><p>Pour mesurer une grandeur (aire, volume, longueur), on la <b>découpe</b> en tranches fines d’épaisseur d<i>x</i>, on <b>approche</b> chaque tranche par une forme simple, puis on <b>somme</b> avec une intégrale. Toutes les formules de ce chapitre viennent de là.</p></div><div class="prop"><p>Si <b>f ≥ g</b> sur [<i>a</i> ; <i>b</i>], l’aire de la région comprise entre les deux courbes vaut <b>A = ∫ₐᵇ (f(x) − g(x)) dx</b>.</p></div><div class="why"><p>Une tranche verticale en <i>x</i> est presque un rectangle de largeur d<i>x</i> et de hauteur f(x) − g(x), la distance entre la courbe du haut et celle du bas. Cela reste vrai même si les deux courbes passent sous l’axe : seule leur différence compte.</p></div><div class="ex"><p>Entre <i>y</i> = <i>kx</i> et <i>y</i> = <i>x</i>² (avec <i>k</i> &gt; 0) : <i>kx</i> = <i>x</i>² ⇔ <i>x</i> = 0 ou <i>x</i> = <i>k</i>, et la droite est au-dessus entre les deux (en <i>x</i> = <i>k</i>/2 : <i>k</i>²/2 &gt; <i>k</i>²/4). A = ∫₀ᵏ (<i>kx</i> − <i>x</i>²) d<i>x</i> = <i>k</i>³/2 − <i>k</i>³/3 = <i>k</i>³/6. Pour <i>k</i> = 3 : A = 27/6 = 4,5.</p></div><div class="warn"><p>Si les courbes se croisent dans l’intervalle, les rôles du haut et du bas s’échangent : coupe aux points d’intersection et calcule chaque morceau avec la bonne différence, sinon les parts se compensent.</p></div>',
  params:[{id:'k',l:'k',min:.5,max:3,step:.5,v:3}],
  draw:v=>{ const k=v.k, P=plane({x:[-.5,3.5],y:[-.5,9.5],h:300,lab:1,step:1}); const pts=[];
    for(let i=0;i<=60;i++){ const x=k*i/60; pts.push([x,k*x]); } for(let i=60;i>=0;i--){ const x=k*i/60; pts.push([x,x*x]); }
    P.poly(pts,{fill:'var(--accent)',fo:.25,c:null}).fn(x=>x*x,{from:-.5,to:3.2}).fn(x=>k*x,{c:'var(--spark)',w:2.5}); return P.svg(); },
  info:v=>`A = ∫₀ᵏ (kx − x²) dx = k³/6 = ${fmt(v.k**3/6,4)}`},
 {kind:'Pratique',h:'Règle l’aire',p:'Choisis <i>k</i> pour que l’aire entre <i>y</i> = <i>kx</i> et <i>y</i> = <i>x</i>² vaille 4/3.',
  params:[{id:'k',l:'k',min:.5,max:3,step:.5,v:1}],
  draw:v=>{ const k=v.k, P=plane({x:[-.5,3.5],y:[-.5,9.5],h:300,lab:1,step:1}); const pts=[];
    for(let i=0;i<=60;i++){ const x=k*i/60; pts.push([x,k*x]); } for(let i=60;i>=0;i--){ const x=k*i/60; pts.push([x,x*x]); }
    P.poly(pts,{fill:'var(--accent)',fo:.25,c:null}).fn(x=>x*x,{from:-.5,to:3.2}).fn(x=>k*x,{c:'var(--spark)',w:2.5}); return P.svg(); },
  info:v=>`A = ${fmt(v.k**3/6,4)}`,
  ok:v=>v.k===2,why:'k³/6 = 4/3 ⇔ k³ = 8 ⇔ k = 2.'},
 {kind:'Méthode',h:'Calculer l’aire entre deux courbes',p:'<b>Quand :</b> on demande l’aire de la région fermée entre deux graphes. <b>Pourquoi ça marche :</b> sur une tranche verticale, la hauteur de la région est (courbe du haut) − (courbe du bas) ; on somme ces hauteurs avec l’intégrale. <b>Comment :</b> 1) résous f(x) = g(x) pour trouver les bornes ; 2) teste une valeur entre les bornes pour savoir qui est au-dessus ; 3) intègre (haut − bas).',
  demo:{enonce:'Aire entre <i>y</i> = <i>x</i>² et <i>y</i> = 2<i>x</i> + 3.',
   etapes:[
    {f:'<i>x</i>² = 2<i>x</i> + 3 ⇔ <i>x</i>² − 2<i>x</i> − 3 = 0 ⇔ (<i>x</i> − 3)(<i>x</i> + 1) = 0',w:'Les points d’intersection donnent les bornes : −1 et 3.'},
    {f:'En <i>x</i> = 0 : 2 · 0 + 3 = 3 &gt; 0² : la droite est au-dessus',w:'Une seule valeur test suffit, car les courbes ne se croisent pas entre −1 et 3.'},
    {f:'A = ∫₋₁³ (2<i>x</i> + 3 − <i>x</i>²) d<i>x</i> = [<i>x</i>² + 3<i>x</i> − <i>x</i>³/3]₋₁³',w:'Haut moins bas, entre les bornes.'},
    {f:'= (9 + 9 − 9) − (1 − 3 + 1/3) = 9 + 5/3 = 32/3',w:'On évalue soigneusement la borne négative.'}],
   conclusion:'L’aire vaut 32/3 ≈ 10,67.'}},
 {h:'Calcule une aire',p:'Calcule l’aire comprise entre <i>y</i> = 4 − <i>x</i>² et <i>y</i> = <i>x</i> + 2.',ans:4.5,tol:1e-9,
  why:'4 − x² = x + 2 ⇔ x² + x − 2 = 0 ⇔ x = −2 ou 1. A = ∫₋₂¹ (2 − x − x²) dx = [2x − x²/2 − x³/3]₋₂¹ = 7/6 + 10/3 = 9/2.'},
 {kind:'Théorie',h:'Volume de révolution',p:'<p>Un vase, un cône, une sphère, un ballon de rugby : beaucoup de solides s’obtiennent en faisant tourner une courbe autour d’un axe. Leur volume se calcule avec la même idée que l’aire : découper en tranches.</p><div class="def"><p>On fait tourner autour de l’axe O<i>x</i> la région sous le graphe de <i>f</i> ≥ 0, pour <i>x</i> ∈ [<i>a</i> ; <i>b</i>]. On obtient un <b>solide de révolution</b>, de volume <b>V = π ∫ₐᵇ f(x)² dx</b>.</p></div><div class="why"><p>Coupe le solide perpendiculairement à l’axe, à l’abscisse <i>x</i> : la section est un <b>disque</b> de rayon f(x), d’aire π f(x)². Une tranche d’épaisseur d<i>x</i> est presque un cylindre aplati, de volume π f(x)² d<i>x</i>. On somme ces volumes avec l’intégrale. Sur la figure, chaque segment vertical est le diamètre d’un de ces disques.</p></div><div class="ex"><p>Le cône de rayon <i>R</i> et de hauteur <i>h</i> : on fait tourner le segment <i>y</i> = <i>Rx</i>/<i>h</i>, <i>x</i> ∈ [0 ; <i>h</i>]. V = π ∫₀ʰ <i>R</i>²<i>x</i>²/<i>h</i>² d<i>x</i> = (π<i>R</i>²/<i>h</i>²) · <i>h</i>³/3 = π<i>R</i>²<i>h</i>/3 : on retrouve la formule connue. Avec <i>R</i> = 3 et <i>h</i> = 4 : V = 12π ≈ 37,7.</p></div><div class="warn"><p>C’est l’<b>aire</b> du disque qui compte : on intègre f(x)², pas f(x). Et pour un anneau (région entre deux courbes f ≥ g ≥ 0), on retire le trou : V = π ∫ₐᵇ (f² − g²) d<i>x</i>, et non π ∫ₐᵇ (f − g)² d<i>x</i>.</p></div>',
  fig:(()=>{ const P=plane({x:[-.5,4.5],y:[-2.5,2.5],w:300,lab:1}); P.fn(Math.sqrt,{from:0,to:4}).fn(x=>-Math.sqrt(x),{from:0,to:4,c:'var(--accent)',dash:true,w:2});
    [1,2,3,4].forEach(x=>P.seg(x,-Math.sqrt(x),x,Math.sqrt(x),{c:'var(--spark)',w:2})); P.text(2.2,1.9,'y = √x'); return P.svg(); })(),
  note:'La sphère de rayon <i>R</i> s’obtient avec f(x) = √(R² − x²) : π ∫₋ᴿᴿ (R² − x²) dx = 4πR³/3.'},
 {kind:'Méthode',h:'Calculer un volume de révolution',p:'<b>Quand :</b> un solide est obtenu en faisant tourner le graphe de <i>f</i> ≥ 0 autour de O<i>x</i> (cône, sphère, vase, seau). <b>Pourquoi ça marche :</b> une tranche d’épaisseur d<i>x</i> est un disque de rayon f(x), de volume π f(x)² d<i>x</i>. <b>Comment :</b> identifie le rayon f(x) et l’intervalle, élève f au carré <b>avant</b> d’intégrer, puis calcule V = π ∫ₐᵇ f(x)² d<i>x</i>.',
  demo:{enonce:'On fait tourner <i>y</i> = 1/<i>x</i>, <i>x</i> ∈ [1 ; 3], autour de O<i>x</i>. Calculer le volume.',
   etapes:[
    {f:'Rayon f(x) = 1/<i>x</i>, donc f(x)² = 1/<i>x</i>² = <i>x</i>⁻²',w:'On élève au carré : c’est l’aire du disque qui compte.'},
    {f:'V = π ∫₁³ <i>x</i>⁻² d<i>x</i> = π [−1/<i>x</i>]₁³',w:'Primitive de <i>x</i>⁻² : <i>x</i>⁻¹/(−1).'},
    {f:'= π(−1/3 + 1) = 2π/3',w:'On évalue aux bornes.'}],
   conclusion:'V = 2π/3 ≈ 2,09.'},
  note:'Erreur classique : écrire π (∫ f)² au lieu de π ∫ f². Le carré porte sur f, à l’intérieur de l’intégrale.'},
 {h:'Le paraboloïde',p:'On fait tourner <i>y</i> = √<i>x</i>, <i>x</i> ∈ [0 ; 4], autour de O<i>x</i>. Calcule le volume, arrondi au centième.',ans:8*Math.PI,tol:.006,
  why:'V = π ∫₀⁴ (√x)² dx = π ∫₀⁴ x dx = π · 16/2 = 8π ≈ 25,13.'},
 {kind:'Théorie',h:'Longueur d’arc',p:'<p>Quelle est la longueur d’un câble suspendu, d’une route en lacets, d’une arche de cycloïde ? Pour un segment, Pythagore répond. Pour une courbe, on la remplace par une ligne brisée de petits segments, puis on passe à la limite.</p><div class="thm"><p>Si <i>f</i> a une dérivée continue sur [<i>a</i> ; <i>b</i>], la longueur de son graphe vaut <b>L = ∫ₐᵇ √(1 + f′(x)²) dx</b>. Pour un arc paramétré γ(t) = (x(t) ; y(t)), <i>t</i> ∈ [<i>t</i>₀ ; <i>t</i>₁] : <b>L = ∫ √(x′(t)² + y′(t)²) dt</b>.</p></div><div class="why"><p>Entre <i>x</i> et <i>x</i> + d<i>x</i>, la courbe est presque un segment qui avance de d<i>x</i> et monte de d<i>y</i> ≈ f′(x) d<i>x</i>. Par Pythagore, sa longueur vaut √(d<i>x</i>² + d<i>y</i>²) = √(1 + f′(x)²) d<i>x</i>. Pour un arc, pendant d<i>t</i>, le point avance de <i>x</i>′ d<i>t</i> horizontalement et de <i>y</i>′ d<i>t</i> verticalement : longueur |γ′(t)| d<i>t</i>, la vitesse multipliée par la durée.</p></div><div class="ex"><p>Le cercle (<i>R</i> cos <i>t</i> ; <i>R</i> sin <i>t</i>), <i>t</i> ∈ [0 ; 2π] : <i>x</i>′² + <i>y</i>′² = <i>R</i>²(sin²<i>t</i> + cos²<i>t</i>) = <i>R</i>², donc L = ∫₀<sup>2π</sup> <i>R</i> d<i>t</i> = 2π<i>R</i>, le périmètre attendu. Pour un graphe, f(x) = <i>x</i><sup>3/2</sup> donne 1 + f′² = 1 + 9<i>x</i>/4, une racine qu’on sait intégrer.</p></div><div class="warn"><p>La racine de 1 + f′² se simplifie rarement : pour la plupart des fonctions (même <i>x</i>²), l’intégrale demande des techniques plus avancées ou un calcul approché. Les exercices sont choisis pour que la racine se simplifie.</p></div>',
  note:'Contrôle : pour f(x) = mx, on trouve (b − a)√(1 + m²), la longueur du segment.'},
 {kind:'Méthode',h:'Calculer la longueur d’un graphe',p:'<b>Quand :</b> on demande la longueur de la courbe <i>y</i> = f(x) entre <i>a</i> et <i>b</i>. <b>Pourquoi ça marche :</b> un petit morceau de courbe est presque un segment de côtés d<i>x</i> et f′(x) d<i>x</i>, donc de longueur √(1 + f′(x)²) d<i>x</i> (Pythagore). <b>Comment :</b> calcule f′, puis 1 + f′², simplifie la racine si possible, et intègre. Les exercices sont choisis pour que la racine se simplifie ou devienne une composée avec <i>ax</i> + <i>b</i>.',
  demo:{enonce:'Longueur du graphe de f(x) = <i>x</i><sup>3/2</sup> pour <i>x</i> ∈ [0 ; 4/3].',
   etapes:[
    {f:'f′(x) = (3/2)<i>x</i><sup>1/2</sup>, donc 1 + f′(x)² = 1 + 9<i>x</i>/4',w:'Le carré de √<i>x</i> est <i>x</i> : la racine disparaît.'},
    {f:'L = ∫₀<sup>4/3</sup> (1 + 9<i>x</i>/4)<sup>1/2</sup> d<i>x</i>',w:'Formule de la longueur.'},
    {f:'Primitive : (1 + 9<i>x</i>/4)<sup>3/2</sup>/(3/2) ÷ (9/4) = (8/27)(1 + 9<i>x</i>/4)<sup>3/2</sup>',w:'Composée avec <i>ax</i> + <i>b</i> : on divise par <i>a</i> = 9/4.'},
    {f:'L = (8/27)(4<sup>3/2</sup> − 1) = (8/27) · 7 = 56/27',w:'En 4/3 : 1 + 3 = 4, et 4<sup>3/2</sup> = 8.'}],
   conclusion:'L = 56/27 ≈ 2,074.'}},
 {h:'Une longueur exacte',p:'Calcule la longueur du graphe de f(x) = (2/3)<i>x</i><sup>3/2</sup> pour <i>x</i> ∈ [0 ; 3]. Donne une fraction ou un arrondi au millième.',lab:'L =',ans:14/3,tol:6e-4,
  why:'f′(x) = √x, donc √(1 + f′²) = √(1 + x). L = [(2/3)(1 + x)<sup>3/2</sup>]₀³ = (2/3)(8 − 1) = 14/3 ≈ 4,667.'},
 {kind:'Méthode',h:'Longueur d’un arc paramétré',p:'<b>Quand :</b> la courbe est donnée par γ(<i>t</i>) = (<i>x</i>(<i>t</i>) ; <i>y</i>(<i>t</i>)), <i>t</i> ∈ [<i>t</i>₀ ; <i>t</i>₁] (trajectoire, cycloïde). <b>Pourquoi ça marche :</b> pendant d<i>t</i>, le point parcourt environ |γ′(<i>t</i>)| d<i>t</i> : longueur = intégrale de la vitesse. <b>Comment :</b> calcule <i>x</i>′² + <i>y</i>′², factorise pour sortir un carré de la racine (attention à son signe sur l’intervalle), puis intègre L = ∫ √(<i>x</i>′² + <i>y</i>′²) d<i>t</i>.',
  demo:{enonce:'Longueur de γ(<i>t</i>) = (<i>t</i>² ; <i>t</i>³) pour <i>t</i> ∈ [0 ; 1].',
   etapes:[
    {f:'<i>x</i>′ = 2<i>t</i>, <i>y</i>′ = 3<i>t</i>² ; <i>x</i>′² + <i>y</i>′² = 4<i>t</i>² + 9<i>t</i>⁴ = <i>t</i>²(4 + 9<i>t</i>²)',w:'On met le carré <i>t</i>² en facteur.'},
    {f:'√(<i>t</i>²(4 + 9<i>t</i>²)) = <i>t</i> √(4 + 9<i>t</i>²), car <i>t</i> ≥ 0',w:'√(<i>t</i>²) = |<i>t</i>| = <i>t</i> sur [0 ; 1].'},
    {f:'∫ <i>t</i>(4 + 9<i>t</i>²)<sup>1/2</sup> d<i>t</i> = (1/18) ∫ 18<i>t</i>(4 + 9<i>t</i>²)<sup>1/2</sup> d<i>t</i> = (1/27)(4 + 9<i>t</i>²)<sup>3/2</sup>',w:'Forme u′u<sup>n</sup> avec u = 4 + 9<i>t</i>² et u′ = 18<i>t</i>.'},
    {f:'L = (1/27)(13<sup>3/2</sup> − 4<sup>3/2</sup>) = (13√13 − 8)/27',w:'On évalue entre 0 et 1.'}],
   conclusion:'L ≈ 1,440.'}},
 {h:'À toi',p:'Calcule la longueur de γ(<i>t</i>) = (<i>t</i>² ; (2/3)<i>t</i>³) pour <i>t</i> ∈ [0 ; 1], arrondie au millième.',lab:'L ≈',ans:2/3*(2*Math.SQRT2-1),tol:6e-4,
  why:'x′² + y′² = 4t² + 4t⁴ = 4t²(1 + t²), donc |γ′| = 2t√(1 + t²). Primitive : (2/3)(1 + t²)<sup>3/2</sup>. L = (2/3)(2√2 − 1) ≈ 1,219.'},
 {kind:'Théorie',h:'Aire d’une surface de révolution',p:'<p>Pour peindre un abat-jour ou fabriquer une coque, il faut l’aire de la surface, pas le volume. On découpe encore en tranches, mais cette fois chaque tranche est une fine bande, comme un ruban enroulé autour de l’axe.</p><div class="thm"><p>Si <i>f</i> ≥ 0 a une dérivée continue sur [<i>a</i> ; <i>b</i>], la surface engendrée par la rotation de son graphe autour de O<i>x</i> a pour aire (sans les disques des extrémités) <b>S = 2π ∫ₐᵇ f(x) √(1 + f′(x)²) dx</b>.</p></div><div class="why"><p>Un petit bout de courbe, de longueur d<i>s</i> = √(1 + f′²) d<i>x</i> (étape précédente), tourne sur un cercle de rayon f(x), de circonférence 2π f(x). Il balaie une bande presque cylindrique d’aire 2π f(x) d<i>s</i> : circonférence × largeur. On somme ces bandes.</p></div><div class="ex"><p>Le cylindre : f(x) = <i>R</i> sur [0 ; <i>h</i>], f′ = 0, donc S = 2π ∫₀ʰ <i>R</i> d<i>x</i> = 2π<i>Rh</i>, l’aire du rectangle obtenu en déroulant la paroi. La sphère de rayon <i>R</i> : f(x) = √(<i>R</i>² − <i>x</i>²), et f √(1 + f′²) = <i>R</i> (voir la note), donc S = 2π<i>R</i> · 2<i>R</i> = 4π<i>R</i>².</p></div><div class="warn"><p>Ne remplace pas d<i>s</i> par d<i>x</i> : 2π ∫ f d<i>x</i> sous-estime l’aire dès que la courbe est inclinée. Pour le segment <i>y</i> = 2<i>x</i> sur [0 ; 1], il donnerait 2π au lieu de 2π√5 ≈ 14,05.</p></div>',
  note:'Pour la sphère, f(x)√(1 + f′(x)²) = R tout le long : S = 2π · R · 2R = 4πR².'},
 {kind:'Méthode',h:'Calculer l’aire d’une surface de révolution',p:'<b>Quand :</b> on demande l’aire de la surface (sans les disques des extrémités) balayée par le graphe de <i>f</i> ≥ 0 tournant autour de O<i>x</i>. <b>Pourquoi ça marche :</b> un petit bout d’arc de longueur √(1 + f′²) d<i>x</i> décrit une bande de rayon f(x), de longueur 2π f(x). <b>Comment :</b> calcule f′, puis le produit f(x)√(1 + f′(x)²), simplifie-le en un seul radical si possible, et intègre S = 2π ∫ₐᵇ f √(1 + f′²) d<i>x</i>.',
  demo:{enonce:'Aire de la surface obtenue en faisant tourner <i>y</i> = √<i>x</i>, <i>x</i> ∈ [0 ; 2], autour de O<i>x</i>.',
   etapes:[
    {f:'f′(x) = 1/(2√<i>x</i>), donc 1 + f′² = 1 + 1/(4<i>x</i>)',w:'On prépare la racine.'},
    {f:'f √(1 + f′²) = √<i>x</i> · √(1 + 1/(4<i>x</i>)) = √(<i>x</i> + 1/4)',w:'On regroupe sous une seule racine : <i>x</i>(1 + 1/(4<i>x</i>)) = <i>x</i> + 1/4.'},
    {f:'S = 2π ∫₀² (<i>x</i> + 1/4)<sup>1/2</sup> d<i>x</i> = 2π · (2/3)[(<i>x</i> + 1/4)<sup>3/2</sup>]₀²',w:'Composée avec <i>x</i> + 1/4 (ici <i>a</i> = 1).'},
    {f:'= (4π/3)((9/4)<sup>3/2</sup> − (1/4)<sup>3/2</sup>) = (4π/3)(27/8 − 1/8) = 13π/3',w:'(9/4)<sup>3/2</sup> = (3/2)³ et (1/4)<sup>3/2</sup> = (1/2)³.'}],
   conclusion:'S = 13π/3 ≈ 13,61.'}},
 {kind:'Défi',h:'L’aire d’un cône',p:'On fait tourner le segment <i>y</i> = <i>x</i>, <i>x</i> ∈ [0 ; 1], autour de O<i>x</i>. Calcule l’aire de la surface obtenue, arrondie au centième.',ans:Math.SQRT2*Math.PI,tol:.006,
  why:'f′ = 1 : S = 2π ∫₀¹ x√2 dx = 2π√2 · 1/2 = π√2 ≈ 4,44. C’est bien πrℓ avec r = 1 et ℓ = √2.'},
 {kind:'Récapitulatif',h:'Ce qu’il faut retenir : applications de l’intégrale',p:'<div class="keep"><ul><li><b>Méthode générale</b> : découper en tranches d’épaisseur d<i>x</i>, approcher chaque tranche par une forme simple (rectangle, disque, segment, bande), sommer avec une intégrale.</li><li><b>Aire entre deux courbes</b> : A = ∫ₐᵇ (haut − bas) d<i>x</i>. Bornes : résoudre f(x) = g(x) ; une valeur test dit qui est au-dessus ; couper aux croisements.</li><li><b>Volume de révolution</b> autour de O<i>x</i> : V = π ∫ₐᵇ f(x)² d<i>x</i> (le carré à l’intérieur) ; pour un anneau, π ∫ (f² − g²). Contrôle : cône π<i>R</i>²<i>h</i>/3, sphère 4π<i>R</i>³/3.</li><li><b>Longueur d’un graphe</b> : L = ∫ₐᵇ √(1 + f′(x)²) d<i>x</i>. <b>Longueur d’un arc</b> : L = ∫ √(x′(t)² + y′(t)²) d<i>t</i> = ∫ |γ′(t)| d<i>t</i> ; sortir un carré de la racine avec sa valeur absolue.</li><li><b>Aire d’une surface de révolution</b> : S = 2π ∫ₐᵇ f(x) √(1 + f′(x)²) d<i>x</i>. Contrôle : cylindre 2π<i>Rh</i>, sphère 4π<i>R</i>², cône π<i>r</i>ℓ.</li><li>Pour simplifier les racines : regrouper sous un seul radical, reconnaître une composée avec <i>ax</i> + <i>b</i> ou une forme u′uⁿ.</li></ul></div>'},
 {kind:'Problème',h:'La contenance d’un seau',
  p:'Un seau a la forme d’un tronc de cône : rayon 10 cm au fond, 15 cm en haut, hauteur 30 cm. On le voit comme le solide obtenu en faisant tourner autour de l’axe O<i>x</i> le segment <i>y</i> = r(<i>x</i>), <i>x</i> ∈ [0 ; 30], où <i>x</i> est la hauteur mesurée depuis le fond (en cm).',
  fig:(()=>{ const P=plane({x:[-3,34],y:[-17,17],w:300,grid:false,lx:10,ly:5}); P.poly([[0,10],[30,15],[30,-15],[0,-10]],{fill:'var(--sci)',fo:.15,c:'var(--muted)',w:1.2,dash:true});
    P.seg(0,10,30,15,{c:'var(--accent)',w:3}).seg(13,-(10+13/6),13,10+13/6,{c:'var(--spark)',w:2}).text(13,12.5,'eau',{a:'middle',dy:-10,c:'var(--spark)'}).text(20,13.5,'y = r(x)',{dy:-10,c:'var(--accent)'}); return P.svg(); })(),
  parts:[
   {q:'a) Quelle est la fonction r&nbsp;?',opts:['r(<i>x</i>) = 10 + <i>x</i>/2','r(<i>x</i>) = 15 − <i>x</i>/6','r(<i>x</i>) = 10 + 5<i>x</i>','r(<i>x</i>) = 10 + <i>x</i>/6'],ans:3,hint:'r est affine, avec r(0) = 10 et r(30) = 15.',why:'La pente vaut (15 − 10)/30 = 1/6, donc r(x) = 10 + x/6.'},
   {q:'b) Quelle est la contenance du seau, en litres&nbsp;? Arrondis au centième.',lab:'V ≈',unit:'L',ans:4.75*Math.PI,tol:.006,hint:'V = π ∫₀³⁰ (10 + <i>x</i>/6)² d<i>x</i>. Une primitive de (10 + <i>x</i>/6)² est 2(10 + <i>x</i>/6)³. Et 1 L = 1000 cm³.',why:'V = 2π(15³ − 10³) = 2π · 2375 = 4750π ≈ 14 923 cm³ ≈ 14,92 L.'},
   {q:'c) Tu verses 5 L d’eau. Jusqu’à quelle hauteur monte-t-elle&nbsp;? Arrondis au dixième.',lab:'h ≈',unit:'cm',ans:6*(Math.cbrt(1000+2500/Math.PI)-10),tol:.06,hint:'Résous π ∫₀ʰ r(<i>x</i>)² d<i>x</i> = 5000, soit 2π((10 + <i>h</i>/6)³ − 1000) = 5000.',why:'(10 + h/6)³ = 1000 + 2500/π ≈ 1795,8, donc 10 + h/6 ≈ 12,155 et h ≈ 12,9 cm.'},
  ],
  sol:'r est affine : r(x) = 10 + x/6. Chaque tranche à la hauteur x est un disque d’aire π r(x)².<br>V = π ∫₀³⁰ (10 + x/6)² dx = π [2(10 + x/6)³]₀³⁰ = 2π(3375 − 1000) = 4750π ≈ 14 923 cm³, soit 14,92 L.<br>(Contrôle avec la formule du tronc de cône πh(R² + Rr + r²)/3 = 10π(225 + 150 + 100) = 4750π.)<br>Pour 5 L : 2π((10 + h/6)³ − 1000) = 5000 ⇔ (10 + h/6)³ = 1000 + 2500/π ≈ 1795,8 ⇔ h ≈ 12,9 cm.<br>Le tiers du volume occupe moins de la moitié de la hauteur, car le seau s’élargit vers le haut.'},
 {kind:'Problème',h:'Le caillou dans le pneu',
  p:'Un petit caillou est coincé dans le pneu d’une roue de rayon <i>R</i>. Quand la roue roule sans glisser, il décrit une cycloïde : <b>γ(<i>t</i>) = (<i>R</i>(<i>t</i> − sin <i>t</i>) ; <i>R</i>(1 − cos <i>t</i>))</b>. Pendant un tour de roue (<i>t</i> de 0 à 2π), le vélo avance de 2π<i>R</i>. On veut la distance réellement parcourue par le caillou.',
  fig:(()=>{ const P=plane({x:[-.5,6.8],y:[-.3,2.4],w:320,grid:false,lx:1,ly:1}); P.curve(t=>t-Math.sin(t),t=>1-Math.cos(t),0,2*Math.PI,{c:'var(--accent)',w:2.5});
    const t=2; P.circ(t,1,1,{c:'var(--muted)',w:1.2}).seg(-.5,0,6.8,0,{c:'var(--muted)',w:1.5}).dot(t-Math.sin(t),1-Math.cos(t),{r:5,c:'var(--ink)'}); return P.svg(); })(),
  parts:[
   {q:'a) Que vaut |γ′(<i>t</i>)|²&nbsp;?',opts:['<i>R</i>²(1 − cos <i>t</i>)²','2<i>R</i>²','<i>R</i>²(2 − 2 cos <i>t</i>) = 4<i>R</i>² sin²(<i>t</i>/2)','<i>R</i>²(2 + 2 cos <i>t</i>)'],ans:2,hint:'γ′(<i>t</i>) = (<i>R</i>(1 − cos <i>t</i>) ; <i>R</i> sin <i>t</i>). Développe, puis utilise 1 − cos <i>t</i> = 2 sin²(<i>t</i>/2).',why:'R²((1 − cos t)² + sin²t) = R²(1 − 2cos t + cos²t + sin²t) = R²(2 − 2cos t) = 4R² sin²(t/2).'},
   {q:'b) Pour <i>R</i> = 1, quelle est la longueur d’une arche (<i>t</i> de 0 à 2π)&nbsp;?',lab:'L =',ans:8,tol:1e-6,hint:'Sur [0 ; 2π], sin(<i>t</i>/2) ≥ 0, donc |γ′(<i>t</i>)| = 2 sin(<i>t</i>/2).',why:'L = ∫₀<sup>2π</sup> 2 sin(t/2) dt = [−4 cos(t/2)]₀<sup>2π</sup> = 4 + 4 = 8.'},
   {q:'c) Pour une roue de rayon <i>R</i> = 0,35 m, quelle distance le caillou parcourt-il pendant un tour&nbsp;?',lab:'L =',unit:'m',ans:2.8,tol:1e-6,hint:'Toutes les longueurs sont multipliées par <i>R</i>.',why:'L = 8R = 8 · 0,35 = 2,8 m.'},
   {q:'d) Quel est le rapport entre cette distance et l’avancée du vélo&nbsp;? Arrondis au centième.',lab:'rapport ≈',ans:4/Math.PI,tol:.006,hint:'Le vélo avance de 2π<i>R</i>.',why:'8R/(2πR) = 4/π ≈ 1,27. Le caillou parcourt 27 % de chemin en plus, quel que soit le rayon.'},
  ],
  sol:'γ′(t) = R(1 − cos t ; sin t), donc |γ′(t)|² = R²(2 − 2cos t) = 4R² sin²(t/2).<br>Sur [0 ; 2π], t/2 ∈ [0 ; π] et sin(t/2) ≥ 0 : |γ′(t)| = 2R sin(t/2), sans valeur absolue.<br>L = ∫₀<sup>2π</sup> 2R sin(t/2) dt = 2R [−2 cos(t/2)]₀<sup>2π</sup> = 2R(2 + 2) = 8R.<br>Pour R = 0,35 m : L = 2,8 m, contre 2πR ≈ 2,20 m pour le vélo.<br>Le rapport 8/(2π) = 4/π ≈ 1,27 ne dépend pas de R. En t = 0 et t = 2π, la vitesse du caillou est nulle : il touche le sol sans glisser, c’est un point de rebroussement.'},
]},
);
})();
